D[7841] = {[1]="Message to the Wildhammer",[2]={{14738}},[3]={{14738}},[4]=44,[5]=48,[6]=178,[8]={"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.","","You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands."},[10]={{{2692,nil,0},{2691,nil,0},{2694,nil,0},{2693,nil,0}}},[17]=47,[22]=7842,[23]=8}
D[7842] = {[1]="Another Message to the Wildhammer",[2]={{14738}},[3]={{14738}},[4]=44,[5]=48,[6]=178,[8]={"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.","","Gryphons are known to inhabit every region of the Hinterlands."},[10]={[3]={{4589,nil,0}}},[13]={7841},[17]=47,[22]=7843}
D[7843] = {[1]="The Final Message to the Wildhammer",[2]={{14738}},[3]={{14738}},[4]=44,[5]=50,[6]=178,[8]={"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.","","Beware of angry Wildhammer dwarves and unruly members of the Alliance."},[11]=19036,[13]={7842},[17]=47,[23]=2,[24]=2}
D[7844] = {[1]="Cannibalistic Cousins",[2]={{14739}},[3]={{14739}},[4]=44,[5]=48,[6]=178,[8]={"Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete.","","Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands."},[10]={{{4466,nil,0},{4467,nil,0}}},[17]=47,[23]=8}
D[7845] = {[1]="Kidnapped Elder Torntusk!",[2]={{14736}},[3]={{14757}},[4]=46,[5]=51,[6]=178,[8]={"Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.","","You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."},[17]=47,[22]=7846,[23]=8}
D[7846] = {[1]="Recover the Key!",[2]={{14757}},[3]={{14757}},[4]=46,[5]=51,[6]=178,[8]={"Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key."},[10]={[3]={{19064,nil,0}}},[13]={7845},[17]=47,[22]=7847}
D[7847] = {[1]="Return to Primal Torntusk",[2]={{14757}},[3]={{14736}},[4]=46,[5]=51,[6]=178,[8]={"Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue."},[13]={7846},[17]=47}
D[7848] = {[1]="Attunement to the Core",[2]={{14387}},[3]={{14387}},[4]=55,[5]=60,[8]={"Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."},[10]={[3]={{18412,nil,0}}},[17]=2717,[23]=64}
D[7849] = {[1]="Separation Anxiety",[2]={{14741}},[3]={{14741}},[4]=46,[5]=50,[6]=178,[8]={"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.","","Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple."},[10]={[3]={{19069,nil,0},{19070,nil,0}}},[17]=47,[23]=8}
D[7850] = {[1]="Dark Vessels",[2]={{14736}},[3]={{14736}},[4]=46,[5]=50,[6]=178,[8]={"Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete."},[10]={[3]={{19071,nil,0}}},[17]=47,[23]=8}
D[7861] = {[1]="Wanted: Vile Priestess Hexx and Her Minions",[2]={nil,{179913}},[3]={{14736}},[4]=46,[5]=51,[6]=178,[8]={"You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.","","Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands."},[10]={{{7995,nil,0},{2648,nil,0}}},[17]=47,[23]=8}
D[7862] = {[1]="Job Opening: Guard Captain of Revantusk Village",[2]={nil,{179913}},[3]={{14736}},[4]=46,[5]=51,[6]=178,[8]={"You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.","","Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands."},[10]={{{2643,nil,0},{2645,nil,0},{2646,nil,0},{2647,nil,0}}},[17]=47,[23]=8}
