D[25] = {"Stillstand am Steinkrallenpfad",{"Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splintertreeposten.","","Erkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.","","Kehrt zu Mastok Wrilehiss im Splintertreeposten in Ashenvale zurück."}}
D[26] = {"Eine wertvolle Lektion",{"Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade."}}
D[27] = {"Eine wertvolle Lektion",{"Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade."}}
D[28] = {"Prüfung des Sees",{"Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.","","Ihr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."}}
D[29] = {"Prüfung des Sees",{"Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.","","Ihr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."}}
D[30] = {"Prüfung des Seelöwen",{"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.","","Formt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.","","Bringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade."}}
D[31] = {"Wassergestalt",{"Kehrt nach Thunder Bluff zurück und zeigt Turak Runetotem den Anhänger des Seelöwen."}}
D[32] = {"Aufstieg der Silithid",{"Bringt den Bericht nach Orgrimmar zu Zilzibin Drumlore."}}
D[33] = {"Wölfe an der Grenze",{"Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch."}}
D[34] = {"Ein ungebetener Gast",{"Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis."}}
D[35] = {"Weitere Sorgen",{"Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht."}}
D[36] = {"Westfall-Eintopf",{"Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert."}}
D[37] = {"Suche nach den vermissten Wachen",{"Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht."}}
