D[172] = {"Die Kinderwoche",{"Benutzt die Pfeife des orcischen Waisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen."}}
D[173] = {"Worgs in den Wäldern",{"Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler."}}
D[174] = {"Der Blick zu den Sternen",{"Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt."}}
D[175] = {"Der Blick zu den Sternen",{"Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern."}}
D[176] = {"GESUCHT: \"Hogger\"",{"Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnoll-Klaue zu Marshal Dughan."}}
D[177] = {"Der Blick zu den Sternen",{"Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain."}}
D[178] = {"Wiederbeschaffung für Theocritus",{"Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier."}}
D[179] = {"Zwergenausstatter",{"Sten Stoutarm hätte gern 8 Stücke zähes Wolfsfleisch."}}
D[180] = {"GESUCHT: Lieutenant Fangor",{"Tötet Lieutenant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück."}}
D[181] = {"Der Blick zu den Sternen",{"Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain."}}
D[182] = {"Die Trollhöhle",{"Grelin Whitebeard möchte, dass Ihr 14 Trollwelpen der Frostmane tötet."}}
D[183] = {"Der Eberjäger",{"Talin Keeneye möchte, dass Ihr 12 kleine Klippeneber tötet."}}
D[184] = {"Furlbrows Urkunde",{"Bringt Furlbrows Besitzurkunde zu Bauer Furlbrow."}}
D[185] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 junge Schlingendorntiger tötet."}}
D[186] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet."}}
D[187] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet."}}
D[188] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt."}}
D[189] = {"Ohren der Bloodscalp",{"Verschafft Euch 15 Ohren der Bloodscalp und bringt sie Kebok in Booty Bay."}}
D[190] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 junge Panther tötet."}}
D[191] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Panther tötet."}}
D[192] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Schattentatzenpanther tötet."}}
D[193] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr ihm den Fangzahn von Bhag'thera bringt."}}
D[194] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary möchte, dass Ihr 10 Schlingendornraptoren tötet."}}
D[195] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary möchte, dass Ihr 10 Schmetterschwanzraptoren tötet."}}
D[196] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary möchte, dass Ihr 10 Dschungelpirscher tötet."}}
D[197] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary möchte, dass Ihr Tethis tötet, einen schwer fassbaren, gefährlichen Raptoren des Schlingendorntals."}}
D[198] = {"Vorräte für den Gefreiten Thorsen",{"Liefert die verschiedenen Goblin-Vorräte bei dem Gefreiten Thorsen ab."}}
D[199] = {"Eine dunkle Bedrohung",{"Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt."}}
D[200] = {"Buchmacher Herod",{"Findet Buchhalter Herods Aufzeichnungen."}}
D[201] = {"Untersuchung des Lagers",{"Lokalisiert das Jägerlager und teilt dann Krazek in Booty Bay mit, wo es sich befindet."}}
D[202] = {"Colonel Kurzen",{"Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Lieutenant Doren."}}
