D[206] = {"Mai'Zoth",{"Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager."}}
D[207] = {"Das Geheimnis um Kurzen",{"Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück."}}
D[208] = {"Großwildjagd",{"Hemet Nesingwary möchte, dass Ihr ihm den Kopf von König Bangalash, dem großen weißen Tiger, bringt."}}
D[209] = {"Hauer der Skullsplitter",{"Besorgt 18 Hauer der Skullsplitter und bringt sie zu Kebok."}}
D[210] = {"Kochen mit Krazek",{"Bringt Krazeks Spezialtopf zu Krazek, dem Goblin."}}
D[211] = {"Weh dir, Andorhal",{"Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Valorfist auf der Chillwindspitze in den westlichen Pestländern."}}
D[212] = {"Eine kalte Mahlzeit",{"Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.","","<Um diese Aufgabe erfolgreich abschließen zu können, dürft Ihr Euren Geist nicht freigeben.>"}}
D[213] = {"Feindliche Übernahme",{"Beschafft 8 gerommelte Kristalle und bringt sie nach Booty Bay zu Kebok."}}
D[214] = {"Rote Seidenkopftücher",{"Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt."}}
D[215] = {"Geheimnisse im Dschungel",{"Sprecht im Rebellenlager mit Lieutenant Doren."}}
D[216] = {"Hart auf hart",{"Schaltet 12 Rächer der Distelfelle und 12 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Distelfelllager. Wenn das erledigt ist, kehrt zu Karang Amakkar in den Zoram'gar-Außenposten in Ashenvale zurück."}}
D[217] = {"Verteidigung der Länder des Königs",{"Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Captain Rugelfuss im südlichen Wachturm Bericht."}}
D[218] = {"Das gestohlene Tagebuch",{"Grelin Whitebeard möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft."}}
D[219] = {"Vermisst",{"Beschützt Corporal Keeshan auf dem Rückweg ins Rotkammgebirge."}}
D[220] = {"Ruf des Wassers",{"Bringt die Phiole mit reinstem Wasser in das Brachland zu Islen Waterseer."}}
D[221] = {"Worgs in den Wäldern",{"Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler."}}
D[222] = {"Worgs in den Wäldern",{"Tötet für Calor aus Dunkelhain einige Worgs, und zwar 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler."}}
D[223] = {"Worgs in den Wäldern",{"Bringt Calors Notiz zu Jonathan Carevin."}}
D[224] = {"Verteidigung der Länder des Königs",{"Gebirgsjäger Cobbleflint vom südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher tötet."}}
D[225] = {"Das verwitterte Grab",{"Sprecht in Dunkelhain mit Sirra Von'Indi."}}
D[226] = {"Wölfe auf den Fersen",{"Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück."}}
D[227] = {"Morgan Ladimore",{"Sprecht in Dunkelhain mit Kommandantin Althea Ebonlocke."}}
D[228] = {"Mor'Ladim",{"Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Ebonlocke."}}
D[229] = {"Die überlebende Tochter",{"Sprecht in Dunkelhain mit Behüterin Sarah Ladimore."}}
D[230] = {"Svens Lager",{"Bringt das Buch von Svens Hof zu Sven."}}
D[231] = {"Die Liebe einer Tochter",{"Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab."}}
D[232] = {"Kurierdienst für Apothekerin Zinge",{"Bringt die Bestellung nach Undercity zu Alessandro Luca."}}
D[233] = {"Postbeförderung im Coldridgetal",{"Liefert den Stapel Briefe bei Talin Keeneye ab."}}
D[234] = {"Postbeförderung im Coldridgetal",{"Liefert den Brief bei Grelin Whitebeard ab."}}
D[235] = {"Die Jagd in Ashenvale",{"Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale."}}
D[237] = {"Verteidigung der Länder des Königs",{"Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet."}}
D[238] = {"Kurierdienst für Apothekerin Zinge",{"Bringt das Feldprobenset nach Undercity zu Apothekerin Zinge."}}
D[239] = {"Hilfe für die Weststromgarnison",{"Begebt Euch zur Weststromgarnison und sprecht mit Deputy Rainer."}}
D[240] = {"Rückkehr zu Jitters",{"Kehrt mit den schwärzlichen Krebsküchlein zu Jitters zurück."}}
D[243] = {"Auf ins Feld",{"Sprecht in Gadgetzan mit Chefingenieur Bilgewhizzle über eine Kraftquelle für das Testset."}}
D[244] = {"Eindringende Gnolle",{"Erstattet Deputy Feldon Bericht."}}
D[245] = {"Gefahr auf acht Beinen",{"Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald."}}
D[246] = {"Einschätzung der Gefahr",{"Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain."}}
D[247] = {"Die Jagd ist abgeschlossen"}
D[248] = {"Weitere Beobachtungen",{"Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.","","Findet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab."}}
D[249] = {"Morganth",{"Besiegt Morganth.","","Bringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn."}}
D[250] = {"Eine dunkle Bedrohung",{"Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben."}}
D[251] = {"Übersetzung von Calvinius' Notiz",{"Bringt den Brief an Ello zu Sirra Von'Indi."}}
D[252] = {"Übersetzung für Ello",{"Bringt Lord Ello Ebonlocke den übersetzten Brief."}}
D[253] = {"Braut des Einbalsamierers",{"Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Ebonlocke zurück."}}
D[254] = {"Graben in der Erde"}
D[255] = {"Söldner",{"Magistrat Bluntnose aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten."}}
D[256] = {"GESUCHT: Chok'sul",{"Tötet Chok'sul und bringt Magistrat Bluntnose seinen Kopf."}}
D[257] = {"Das Prahlen eines Jägers",{"Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}}
D[258] = {"Die Herausforderung eines Jägers",{"Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}}
D[261] = {"Auf dem Scharlachroten Pfad",{"Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück."}}
D[262] = {"Die Schattengestalt",{"Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain."}}
D[263] = {"Verteidigung der Länder des Königs",{"Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet."}}
D[264] = {"Bis dass der Tod uns scheidet",{"Legt Clarices Anhänger auf Yurivs Grab in Silberwald."}}
D[265] = {"Die Schattensuche geht weiter",{"Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben."}}
D[266] = {"Nachforschungen im Gasthaus",{"Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt."}}
D[267] = {"Die Bedrohung durch die Troggs",{"Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne."}}
D[268] = {"Rückkehr zu Sven",{"Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück."}}
D[269] = {"Auf der Suche nach Weisheit",{"Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch."}}
D[270] = {"Die verlorene Flotte",{"Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow."}}
D[271] = {"Vyrins Rache",{"Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk."}}
D[272] = {"Prüfung des Seelöwen",{"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.","","Formt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.","","Bringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade."}}
D[273] = {"Nachschub für die Ausgrabungsstätte",{"Sprecht mit Huldar."}}
D[274] = {"Eine dunkle Bedrohung",{"Ashlan Stonesmirk möchte, dass Ihr zum Chefingenieur Hinderweir zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt."}}
D[275] = {"Schwärendes Land",{"Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}}
D[276] = {"Stapfende Pfoten",{"Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}}
D[277] = {"Feuer-Tabu",{"Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine."}}
D[278] = {"Eine dunkle Bedrohung",{"Chefingenieur Hinderweir möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt."}}
D[279] = {"Klauen aus der Tiefe",{"Tötet 12 Murlocs der Blaukiemen.","","Erschlagt Gobbler und nehmt Euch seinen Kopf.","","Bringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil"}}
D[280] = {"Eine dunkle Bedrohung",{"Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern."}}
D[281] = {"Waren-Wiederbeschaffung",{"Durchsucht die Kisten und Fässer in den Murloclagern an der Küste."}}
D[282] = {"Senirs Beobachtungen",{"Sprecht mit Gebirgsjäger Thalos."}}
D[283] = {"Eine dunkle Bedrohung",{"Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten."}}
D[284] = {"Die Suche geht weiter",{"Sucht nach der Menethil-Statuette."}}
D[285] = {"Suche in weiteren Hütten",{"Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette."}}
D[286] = {"Rückgabe der Statuette",{"Bringt Karl Boran die Menethil-Statuette."}}
D[287] = {"Höhle der Frostmane",{"Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos."}}
D[288] = {"Die Dritte Flotte",{"Spendiert dem ersten Maat Fitzsimmons einen Krug Met."}}
D[289] = {"Die verfluchte Crew",{"Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil."}}
D[290] = {"Brechen des Fluchs",{"Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.","","Verwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen."}}
D[291] = {"Die Berichte",{"Überbringt Senator Barin Redstone in Ironforge Senirs Bericht."}}
D[292] = {"Das Auge von Paleth",{"Bringt Glorin Steelbrow das verfluchte Auge von Paleth."}}
D[293] = {"Die Reinigung des Auges",{"Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind."}}
D[294] = {"Ormers Rache",{"Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet."}}
D[295] = {"Ormers Rache",{"Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt."}}
D[296] = {"Ormers Rache",{"Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt."}}
D[297] = {"Götzen sammeln",{"Bringt Magmar Fellhew 8 verzierte Steingötzen."}}
D[298] = {"Bericht über den Fortschritt der Ausgrabungen",{"Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar."}}
D[299] = {"Enthüllung der Vergangenheit",{"Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru."}}
D[301] = {"Meldung in Ironforge",{"Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike."}}
D[302] = {"Pulver für Ironband",{"Sprecht in Thelsamar mit Jern Hornhelm."}}
D[303] = {"Der Dunkeleisenkrieg",{"Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet."}}
D[304] = {"Eine grausige Aufgabe",{"Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr."}}
D[305] = {"Auf der Suche nach dem Ausgrabungstrupp",{"Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt."}}
D[306] = {"Auf der Suche nach dem Ausgrabungstrupp",{"Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück."}}
D[307] = {"Schmutzige Pfoten",{"Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.","","Kehrt dann zu Gebirgsjäger Stormpike zurück."}}
D[308] = {"Jarvens Ablenkung"}
D[309] = {"Beschützen der Fracht",{"Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis."}}
D[310] = {"Bittere Rivalen",{"Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu."}}
D[311] = {"Rückkehr zu Marleth",{"Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier."}}
D[312] = {"Tundra MacGranns gestohlene Vorräte",{"Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten."}}
D[313] = {"Der altgediente Bau",{"Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear."}}
D[314] = {"Die Herde beschützen",{"Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt."}}
D[315] = {"Das Perfekte Starkbier",{"Bringt Rejold Gerstenbräu in Brewnall 6 Schimmerkräuter."}}
D[317] = {"Vorräte für Jetsteam",{"Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab."}}
D[318] = {"Immerschimmer",{"Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer."}}
D[319] = {"Ein Gefallen für etwas Immerschimmer",{"Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück."}}
D[320] = {"Rückkehr zu Bellowfiz",{"Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer."}}
D[321] = {"Lichtgeschmiedetes Eisen",{"Durchsucht das Wrack der FLYING OSPREY im Sumpfland."}}
D[322] = {"Gesegnete Waffe",{"Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken."}}
D[323] = {"Bewährungsprobe",{"Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück."}}
D[324] = {"Die verlorenen Blöcke",{"Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück."}}
D[325] = {"Bewaffnet und bereit",{"Bringt Morbents Bann zu Sven im Dämmerwald."}}
D[328] = {"Der versteckte Schlüssel",{"Verwendet den kleinen Messingschlüssel, um Buchhalter Herods Geldkassette zu öffnen."}}
D[329] = {"Der entlarvte Spion",{"Bringt die schlammverschmierte Notiz zu Lieutenant Doren im Rebellen-Lager."}}
D[330] = {"Patrouillen-Pläne",{"Sprecht mit Corporal Sethman."}}
D[331] = {"Meldung bei Doren",{"Sprecht mit Lieutenant Doren."}}
D[332] = {"Weinladen-Werbung",{"Geht zum Weingut Gallina und gebt Suzetta Gallina den Wein-Gutschein, um eine kostenlose Flasche Wein zu erhalten."}}
D[333] = {"Harlan braucht Nachschub",{"Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema Schneider Harlan Bagleys Kleidungs-Auftrag."}}
D[334] = {"Eine Lieferung für Thurman",{"Geht zum Konfektionsgeschäft Larson im Magierviertel von Stormwind und gebt Thurman Schneider sein Nähkästchen."}}
D[335] = {"Ein nobles Bräu",{"Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt."}}
D[336] = {"Ein nobles Bräu",{"Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier."}}
D[337] = {"Ein altes Geschichtsbuch",{"Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück."}}
D[338] = {"Die Grünen Hügel des Schlingendorntals",{"Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals”. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück."}}
