D[2440] = {"Die Platinscheiben",{"Bringt den Belohnungsgutschein zu Bena Winterhoof nach Thunder Bluff."}}
D[2458] = {"Undercover",{"Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.","","Sobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.","","Es ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert."}}
D[2459] = {"Ferocitas der Traumfresser",{"Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet."}}
D[2460] = {"Der Shattered-Gruß",{"Führt Shenthul gegenüber den Shattered-Gruß aus."}}
D[2478] = {"Mission: möglich, aber nicht sehr wahrscheinlich",{"Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.","","Eliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben."}}
D[2479] = {"Hinotts Hilfe",{"Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.","","Um nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!"}}
D[2480] = {"Hinotts Hilfe",{"Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen."}}
D[2498] = {"Rückkehr zu Denalan",{"Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht."}}
D[2499] = {"Grimmeiche",{"Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt."}}
D[2500] = {"Reagenzien-Suche im Ödland",{"Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar."}}
D[2501] = {"Reagenzien-Suche im Ödland II",{"Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Healtouch in Thelsamar."}}
D[2518] = {"Tränen des Mondes",{"Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt."}}
D[2519] = {"Der Tempel des Mondes",{"Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht."}}
D[2520] = {"Sathrahs Opferung",{"Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt."}}
D[2521] = {"Ein Dienst für Kum'isha",{"Falls Ihr auf Euren Reisen durch die verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler.","","Doch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.","","Ihr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt."}}
D[2522] = {"Kum'ishas Bemühungen",{"Findet eine fehlerlose Draenethystsphäre und bringt sie Kum'isha dem Sammler."}}
D[2523] = {"Verderbte Liedblume"}
