D[3523] = {"Geißel der Niederungen",{"Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."}}
D[3524] = {"An Land gespült",{"Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück."}}
D[3525] = {"Ausschalten des Götzen",{"Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.","","Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."}}
D[3526] = {"Goblin-Ingenieurskunst",{"Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}}
D[3527] = {"Die Prophezeiung von Mosh'aru",{"Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris."}}
D[3528] = {"Der Gott Hakkar",{"Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."}}
D[3541] = {"Lieferung an Jes'rimon",{"Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar."}}
D[3542] = {"Lieferung an Andron Gant",{"Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity."}}
D[3561] = {"Lieferung für Erzmagier Xylem",{"Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara."}}
D[3562] = {"Magathas Bezahlung für Jediga",{"Bringt Magathas Notiz zu Jediga in Azshara."}}
D[3563] = {"Jes'rimons Bezahlung für Jediga",{"Bringt Jes'rimons Notiz zu Jediga in Azshara."}}
D[3564] = {"Androns Bezahlung für Jediga",{"Bringt Androns Notiz zu Jediga in Azshara."}}
D[3565] = {"Xylems Bezahlung für Jediga",{"Bringt Xylems Notiz zu Jediga in Azshara."}}
D[3566] = {"Erhebt Euch, Obsidion!",{"Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion."}}
D[3567] = {"An die Spitze"}
D[3568] = {"Verbreitete Verderbnis",{"Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Cuely zurück."}}
D[3569] = {"Verbreitete Verderbnis",{"Gebt Cuelys Elixier Thersa Windsong in Undercity."}}
D[3570] = {"Verbreitete Verderbnis"}
D[3601] = {"Kim'jael, fürwahr!",{"Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück."}}
D[3602] = {"Azsharit",{"Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.","","Kehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[3621] = {"Die Herstellung von Teufelsbann",{"Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal."}}
D[3625] = {"Verzauberte Azsharit-Teufelswaffe",{"Wartet, bis Galvan die Waffen fertig geschmiedet hat."}}
D[3626] = {"Rückkehr in die verwüsteten Lande",{"Kehrt zum Gefallenen Helden der Horde zurück."}}
D[3627] = {"Das zerbrochene Amulett vereinen",{"Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.","","Denkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise ..."}}
D[3628] = {"Ihr seid Rakh'likh, Dämon",{"Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt."}}
D[3629] = {"Goblin-Ingenieurskunst",{"Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}}
