D[3639] = {"Zeigt Eure Arbeit",{"Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprocketspring nach Gadgetzan."}}
D[3640] = {"Der Schwur der Geheimhaltung",{"Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Overspark in Ironforge sprechen."}}
D[3641] = {"Zeigt Eure Arbeit",{"Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Overspark in Ironforge."}}
