D[3761] = {"Un'Goro-Erde",{"Bringt 20 Un'Goro-Erdproben zu Ghede in Thunder Bluff."}}
D[3762] = {"Erzdruide Runetotem helfen",{"Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem."}}
D[3763] = {"Erzdruide Staghelm helfen",{"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}}
D[3764] = {"Un'Goro-Erde",{"Bringt 20 Un'Goro-Erdproben zu Jenal in Darnassus."}}
D[3765] = {"Verderbnis in der Fremde",{"Reist zu Gershala Nightwhisper in Auberdine."}}
D[3781] = {"Morgenkornforschung",{"Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus."}}
D[3782] = {"Morgenkornforschung",{"Bringt den Samenkorngutschein zu Bashana Runetotem in Thunder Bluff."}}
