D[3804] = {"Morgenkorn nach Thunder Bluff"}
D[3821] = {"Schreckensfels",{"Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist."}}
D[3822] = {"Krom'Grul",{"Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels."}}
D[3823] = {"Die Feuermagenoger auslöschen",{"Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid."}}
D[3824] = {"Gor'tesh der Schläger-Lord",{"Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück."}}
D[3825] = {"Ogerkopf auf einem Pfahl = Party",{"Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen."}}
D[3841] = {"Waise sucht Zuhause",{"Sprecht mit Quentin in Tausend Nadeln."}}
D[3842] = {"Kurz vor dem Schlüpfen",{"Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln."}}
D[3843] = {"Das neueste Mitglied der Familie",{"Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei."}}
D[3844] = {"Es ist für jeden ein Geheimnis",{"Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte."}}
D[3845] = {"Es ist für jeden ein Geheimnis",{"Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer."}}
D[3861] = {"GLUCK!",{"Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt."}}
D[3881] = {"Rettungsexpedition",{"Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater."}}
D[3882] = {"Knochenklappern",{"Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater."}}
D[3883] = {"Eine fremdartige Ökologie",{"Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.","","Bringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater."}}
D[3884] = {"Willidens Tagebuch",{"Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater."}}
D[3901] = {"Klappernde Skelette",{"Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid."}}
D[3902] = {"Beutesuche in Deathknell",{"Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück."}}
D[3903] = {"Milly Osworth",{"Sprecht mit Milly Osworth."}}
D[3904] = {"Millys Ernte",{"Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain."}}
D[3905] = {"Traubenliste",{"Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain."}}
D[3906] = {"Disharmonie der Flamme",{"Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt."}}
D[3907] = {"Disharmonie des Feuers",{"Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart."}}
D[3908] = {"Es ist für jeden ein Geheimnis",{"Bringt Linkens Schwert zu Donova Snowden in Winterspring."}}
D[3909] = {"Das Videre-Elixier",{"Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück."}}
D[3912] = {"Treffen am Grab",{"Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."}}
D[3913] = {"Grabesstille",{"Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat."}}
D[3914] = {"Linkens Schwert",{"Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab."}}
D[3921] = {"Wenikee Boltbucket",{"Bringt das zerbrochene Samophlang zu Wenikee Boltbucket."}}
D[3922] = {"Nugget-Patronen",{"Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland."}}
D[3923] = {"Rilli Greasygob",{"Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob."}}
D[3924] = {"Samophlang-Handbuch",{"Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob."}}
D[3941] = {"Die Hilfe des Gnoms",{"Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf."}}
D[3942] = {"Linkens Andenken",{"Sucht Eridan Bluewind im südlichen Teil des Teufelswalds."}}
D[3961] = {"Linkens Abenteuer",{"Bringt das Silbertotem von Aquementas zu Linken in Marshals Zuflucht."}}
D[3962] = {"Allein ist es gefährlich",{"Begebt Euch zum Feuerfedergrat südlich von Marshals Zuflucht.","","Sucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle."}}
D[3981] = {"Kommandant Gor'shak",{"Sucht Kommandant Gor'shak in den Blackrocktiefen.","","Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen."}}
D[3982] = {"Was ist los?",{"Verteidigt Gor'shak."}}
D[4001] = {"Was ist los?",{"Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.","","Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten."}}
D[4002] = {"Das östliche Königreich",{"Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen."}}
D[4003] = {"Die königliche Rettung",{"Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber."}}
D[4004] = {"Ist die Prinzessin gerettet?",{"Kehrt zu Thrall zurück!"}}
D[4005] = {"Aquementas",{"Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.","","Benutzt das Buch von Aquor, um Aquementas zu beschwören.","","Wenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück."}}
D[4021] = {"Gegenangriff!",{"Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads."}}
D[4022] = {"Eine Kostprobe der Flamme",{"Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windblade erhalten habt."}}
D[4023] = {"Eine Kostprobe der Flamme",{"Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.","","Ihr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid."}}
D[4024] = {"Eine Kostprobe der Flamme",{"Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.","","Ihr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.","","Bringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück."}}
D[4041] = {"Das Videre-Elixier"}
D[4061] = {"Aufstieg der Maschinen",{"Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.","","Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter."}}
D[4062] = {"Aufstieg der Maschinen",{"Bringt die Elementarsplitterprobe zu Lotwil Veriatus.","","Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert."}}
D[4063] = {"Aufstieg der Maschinen",{"Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt."}}
D[4081] = {"SOFORT TÖTEN: Dunkeleisenzwerge",{"Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!","","Kriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[4082] = {"SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge",{"Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!","","Kriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[4083] = {"Der spektrale Kelch"}
D[4084] = {"Silberherz",{"Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald."}}
