D[4181] = {"Goblin-Ingenieurskunst",{"Wenn Ihr mehr über die Goblin-Ingenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan."}}
D[4182] = {"Drachkin-Bedrohung",{"Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist."}}
D[4183] = {"Die wahren Meister",{"Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus."}}
D[4184] = {"Die wahren Meister",{"Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.","","Bolvar residiert in der Burg Stormwind."}}
D[4185] = {"Die wahren Meister",{"Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon."}}
D[4186] = {"Die wahren Meister",{"Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus."}}
D[4201] = {"Der Liebestrank",{"Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen."}}
