D[4222] = {"Verderbte Windblüte"}
D[4223] = {"Die wahren Meister",{"Sprecht mit Marshal Maxwell in der brennenden Steppe."}}
D[4224] = {"Die wahren Meister",{"Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.","","Ihr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen."}}
D[4241] = {"Marshal Windsor",{"Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.","","Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."}}
D[4242] = {"Verlorene Hoffnung",{"Überbringt Marshal Maxwell die schlechten Neuigkeiten."}}
D[4243] = {"Chasing A-Me 01",{"Sucht im Un'Goro Krater nach A-Me 01."}}
