D[4245] = {"Chasing A-Me 01",{"Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater."}}
D[4261] = {"Alter Geist",{"Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Forest Song, im Osten von Ashenvale."}}
D[4262] = {"Übermeister Pyron",{"Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.","","Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?"}}
D[4263] = {"Incendius!",{"Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!"}}
D[4264] = {"Eine zusammengeknüllte Notiz",{"Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung."}}
D[4265] = {"Flucht aus dem Schwarmbau",{"Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.","","Kehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."}}
D[4266] = {"Der Empfang eines Helden",{"Sprecht mit Shandris Feathermoon in der Festung Feathermoon."}}
D[4267] = {"Aufstieg der Silithid",{"Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus."}}
D[4281] = {"Thalanaar-Lieferung",{"Bringt das nicht ausgelieferte Paket zu Falfindel Waywarder in Thalanaar."}}
D[4282] = {"Ein Funken Hoffnung",{"Holt Marshal Windsors verloren gegangene Informationen zurück.","","Marshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden."}}
D[4283] = {"FÜNFZIG! Jawoll!",{"Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet."}}
