D[4740] = {"GESUCHT: Gurgelbacke!",{"Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.","","Informiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod."}}
D[4741] = {"Wilde Wächter",{"Trull Failbane im Teufelswald möchte, dass Ihr in Winterspring 13 mondbestrahlte Eulenbestien jagt."}}
D[4742] = {"Siegel des Aufstiegs",{"Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.","","Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten."}}
D[4743] = {"Siegel des Aufstiegs",{"Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.","","In genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!"}}
D[4761] = {"Thundris Windwirker",{"Sprecht mit Thundris Windwirker in Auberdine."}}
D[4762] = {"Der Cliffspring",{"Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe.","","Kehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück."}}
D[4763] = {"Die verderbten Schwarzfelle",{"Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.","","Holt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.","","Mischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.","","Nehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine."}}
D[4764] = {"Doomriggers Schnalle",{"Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle."}}
D[4765] = {"Lieferung an Ridgewell",{"Bringt Ridgewells Kiste zu Remington Ridgewell nach Stormwind."}}
D[4766] = {"Mayara Brightwing",{"Sprecht mit Mayara Brightwing in der brennenden Steppe."}}
D[4767] = {"Windreiter",{"Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen."}}
D[4768] = {"Die Darkstone-Schrifttafel",{"Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel."}}
D[4769] = {"Vivian Lagrave und die Darkstone-Schrifttafel",{"Sprecht mit Schattenmagierin Vivian Lagrave."}}
D[4770] = {"Auf der Heimreise",{"Begleitet Pao'ka Swiftmountain aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Firemane."}}
D[4771] = {"Dämmerungstrickfalle",{"Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück."}}
D[4781] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt Xizk Goodstitch im Schlingendorntal einen Goldbarren."}}
D[4782] = {"Komponenten für die verzauberte Goldblutrobe",{"Kehrt zu Menara Voidrender im Brachland zurück."}}
D[4783] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt Menara Voidrender im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein."}}
D[4784] = {"Komponenten für die verzauberte Goldblutrobe",{"Bringt Menara Voidrender im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter."}}
D[4785] = {"Feiner Goldfaden"}
D[4786] = {"Die fertig gestellte Robe",{"Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr."}}
D[4787] = {"Das uralte Ei",{"Bringt das uralte Ei zu Yeh'kinya nach Tanaris."}}
D[4788] = {"Die letzten Schrifttafeln",{"Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru."}}
