D[4808] = {"Felnok Steelspring",{"Gebt Felnok Steelspring Tinkees Brief."}}
D[4809] = {"Hörner der Eiswindschimären",{"Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre."}}
D[4810] = {"Rückkehr zu Tinkee",{"Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen."}}
D[4811] = {"Der rote Kristall",{"Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}}
D[4812] = {"Wenn das Wasser fließt",{"Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste."}}
D[4813] = {"Die Fragmente im Inneren",{"Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}}
D[4821] = {"Fremdartiges Ei",{"Bringt Hagar Lightninghoof am Freiwindposten das fremdartige Ei."}}
D[4822] = {"Lecker Eis",{"Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Skippis Eiscreme' zu bevorzugen."}}
D[4841] = {"Befriedung der Zentauren",{"Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Longhorn am Freiwindposten zurück."}}
D[4842] = {"Sonderbare Quellen",{"Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr."}}
D[4861] = {"Wütende Wildekin",{"Findet Jaron Stoneshapers ruiniertes Lager samt dessen Vorräte im südlichen Winterspring."}}
D[4862] = {"Be-Öh-Es-Eh",{"Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler.","","Logischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden."}}
D[4863] = {"Wütende Wildekin",{"Sucht Jaron Stoneshapers zerstörten Wagen."}}
D[4864] = {"Wütende Wildekin",{"Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.","","Bringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett."}}
D[4865] = {"Wilde Schlange",{"Berichtet Motega Firemane von Euren Entdeckungen."}}
D[4866] = {"Muttermilch",{"Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann."}}
D[4867] = {"Urok Schreckensbote",{"Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh."}}
D[4881] = {"Auftragsmordplan",{"Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten."}}
D[4882] = {"Geheimnisse bewachen",{"Bringt Trull Failbane beim Blutgiftposten das blaugefiederte Amulett."}}
D[4883] = {"Geheimnisse bewahren",{"Bringt Nara Wildmane das blaugefiederte Amulett."}}
D[4901] = {"Wächter des Altars",{"Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund."}}
D[4902] = {"Wildekin von Elune",{"Sprecht mit Erzdruide Fandral Staghelm in Darnassus."}}
D[4903] = {"Befehl des Kriegsherrn",{"Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt."}}
D[4904] = {"Endlich frei",{"Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide."}}
D[4906] = {"Weitere Verderbnis",{"Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[4907] = {"Tinkee Steamboil",{"Sprecht mit Tinkee Steamboil."}}
D[4921] = {"In der Schlacht vermisst",{"Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück."}}
D[4941] = {"Eitriggs Weisheit",{"Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat.","","Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt."}}
D[4961] = {"Die Säuberung der Kugel von Orahil",{"Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}}
D[4962] = {"Splitter eines Teufelshundes",{"Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin."}}
D[4963] = {"Splitter einer Höllenbestie",{"Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd."}}
D[4964] = {"Die fertig gestellte Kugel von Dar'Orahil",{"Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr."}}
D[4965] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Voidrender im Brachland."}}
D[4966] = {"Kanati Greycloud schützen",{"Beschützt Kanati Greycloud vor den Angriffen der Zentauren."}}
D[4967] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Voidrender im Brachland."}}
D[4968] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Voidrender im Brachland."}}
D[4969] = {"Wissen der Kugel von Orahil",{"Sprecht mit Menara Voidrender im Brachland."}}
D[4970] = {"Frostsäblerverpflegung",{"Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterspring."}}
D[4971] = {"Eine Frage der Zeit",{"Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.","","Tötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern."}}
D[4972] = {"Tempus fugit",{"Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück."}}
D[4973] = {"Tempus fugit",{"Sucht 5 Andorhal-Uhren in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den Westlichen Pestländern."}}
D[4974] = {"Für die Horde!",{"Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück."}}
D[4975] = {"Die fertig gestellte Kugel von Noh'Orahil",{"Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr."}}
D[4976] = {"Ablieferung der gesäuberten Kugel",{"Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland."}}
D[4981] = {"Agentin Bijou",{"Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist."}}
D[4982] = {"Bijous Habseligkeiten",{"Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben."}}
D[4983] = {"Bijous Aufklärungsbericht",{"Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath."}}
D[4984] = {"Die Tierwelt leidet auch",{"Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}}
D[4985] = {"Die Tierwelt leidet auch",{"Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}}
D[4986] = {"Glyphenverzierter Eichenast",{"Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe."}}
D[4987] = {"Glyphenverzierter Eichenast",{"Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Thunder Bluff bringt. Bittet einen der Druiden dort um Hilfe."}}
D[5001] = {"Bijous Habseligkeiten",{"Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!"}}
D[5002] = {"Nachricht an Maxwell",{"Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter."}}
D[5021] = {"Besser spät als nie",{"Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts."}}
D[5022] = {"Besser spät als nie",{"Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus."}}
D[5023] = {"Besser spät als nie",{"Wendet Euch an die königlichen Vorarbeiter von Undercity, um etwas über den Aufenthaltsort von Jeremiah Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung."}}
D[5041] = {"Vorräte für Crossroads",{"Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück."}}
