D[5043] = {"Agammagans Beweglichkeit"}
D[5044] = {"Weisheit von Agammagan"}
D[5045] = {"Steigerung des Geistes"}
D[5046] = {"Klingenhaut"}
D[5047] = {"Pip Quickwit, zu Euren Diensten!",{"Sprecht mit Malyfous Darkhammer in Everlook."}}
D[5048] = {"Emma die Nette",{"Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat."}}
D[5049] = {"Der Jammer des Jeremiah",{"Sucht Jeremiah Payson in Undercity und findet heraus, ob er tatsächlich Jeremiah Felstone ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Felstone für ihn gepackt hat."}}
D[5050] = {"Glücksbringer",{"Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück."}}
D[5051] = {"Zwei Hälften vereint",{"Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen.","","Gebt den Glücksbringer Janice Felstone auf demTeufelssteinfeld in den Westlichen Pestländern."}}
D[5052] = {"Blutsplitter von Agammagan",{"Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter.","","Sammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet."}}
D[5054] = {"Ursius von den Splitterzahnbären",{"Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Ursius tötet."}}
D[5055] = {"Brumeran von den Eiswindschimären",{"Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Brumeran tötet."}}
D[5056] = {"Shy-Rotam",{"Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Shy-Rotam besiegt."}}
D[5057] = {"Frühere Abenteuer",{"Bringt Storm Shadowhoofs Gutschein zu Melor Stonehoof in Thunder Bluff."}}
