D[5059] = {"Weggeschlossen"}
D[5060] = {"Weggeschlossen"}
D[5061] = {"Wassergestalt",{"Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen."}}
D[5062] = {"Hochheiliges Feuer",{"Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff."}}
D[5063] = {"Kappe des scharlachroten Wissenden",{"Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden.","","Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen."}}
D[5064] = {"Grimmtotemspionage",{"Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück."}}
D[5065] = {"Die verlorenen Schrifttafeln von Mosh'aru",{"Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru."}}
D[5066] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."}}
D[5067] = {"Gamaschen von Arcana",{"Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit.","","Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen."}}
D[5068] = {"Brustplatte des Blutdurstes",{"Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens.","","Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen."}}
D[5081] = {"Maxwells Mission",{"Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist."}}
D[5082] = {"Bedrohung durch die Winterfelle",{"Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt."}}
D[5083] = {"Feuerwasser der Winterfelle",{"Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring."}}
D[5084] = {"Der Verderbnis erliegen",{"Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis."}}
D[5085] = {"Geheimnisvoller Glibber",{"Berichtet Donova Snowden von Euren Entdeckungen."}}
D[5086] = {"Toxinschrecken",{"Sammelt 3 Toxinschrecken-Tröpfchen für Donova Snowden in Winterspring."}}
D[5087] = {"Läufer der Winterfelle",{"Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen."}}
D[5088] = {"Arikara",{"Erschlagt Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Firemane im Weißgipfelposten als Beweis für Eure Tat."}}
D[5089] = {"General Drakkisaths Befehl",{"Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe."}}
D[5090] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."}}
D[5091] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."}}
D[5092] = {"Den Weg räumen",{"Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.","","Kehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück."}}
D[5093] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity."}}
D[5094] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity."}}
D[5095] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity."}}
D[5096] = {"Scharlachrote Ablenkung",{"Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt.","","Lasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück."}}
D[5097] = {"Turm um Turm",{"Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.","","Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück."}}
D[5098] = {"Turm um Turm",{"Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.","","Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück."}}
D[5102] = {"General Drakkisaths Niedergang",{"Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist."}}
D[5103] = {"Heißer, feuriger Tod",{"Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!"}}
D[5121] = {"Oberhäuptling der Winterfelle",{"Donova Snowden in Winterspring möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt."}}
D[5122] = {"Das Medaillon des Glaubens"}
D[5123] = {"Das letzte Stück",{"Bringt das kunstlos geschriebene Logbuch zu Donova Snowden in Winterspring."}}
D[5124] = {"Feurige Plattenstulpen",{"Bringt Malyfous Darkhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben."}}
D[5125] = {"Aurius' Abrechnung"}
D[5126] = {"Lorax' Geschichte",{"Sprecht mit Lorax. Hört, was er zu sagen hat."}}
D[5127] = {"Die Dämonenschmiede",{"Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein.","","Ihr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden.","","Bringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring."}}
D[5128] = {"Worte des Oberhäuptlings",{"Bringt das kunstlos geschriebene Logbuch zu Kelek Skykeeper im südlichen Teil des Teufelswalds."}}
D[5141] = {"Drachenlederverarbeitung",{"Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.","","Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5142] = {"Klein-Pamela",{"Sucht Pamela Redpath."}}
D[5143] = {"Stammeslederverarbeitung",{"Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Moonhunter in Feralas.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5144] = {"Elementarlederverarbeitung",{"Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Tanner in die sengende Schlucht.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5145] = {"Drachenlederverarbeitung",{"Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Dragoneye im Ödland.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.","","Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5146] = {"Elementarlederverarbeitung",{"Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhoof in den Arathi-Bergen.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5147] = {"GESUCHT: Arnak Grimmtotem",{"Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten."}}
D[5148] = {"Stammeslederverarbeitung",{"Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.","","Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt."}}
D[5149] = {"Pamelas Puppe",{"Sucht Pamelas Puppe."}}
D[5150] = {"Dadanga ist hungrig!"}
D[5151] = {"Hyperkondensator-Dingsda",{"Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück."}}
D[5152] = {"Tante Marlene",{"Sprecht mit Marlene, südlich der Ruinen von Andorhal."}}
D[5153] = {"Ein seltsamer Historiker",{"Bringt Josephs Ehering zu Chromie."}}
D[5154] = {"Die Annalen von Darrowshire",{"Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal."}}
D[5155] = {"Streitmacht von Jaedenar",{"Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}}
D[5156] = {"Die Verderbnis überprüfen",{"Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück."}}
D[5157] = {"Verderbtes Wasser sammeln",{"Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}}
D[5158] = {"Spirituelle Hilfe suchen",{"Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer."}}
D[5159] = {"Gesäubertes Wasser wird zum Teufelswald gebracht",{"Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald."}}
D[5160] = {"Die oberste Beschützerin",{"Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe."}}
D[5161] = {"Der Zorn des blauen Drachenschwarms",{"Sprecht mit Haleh, wenn Ihr weitermachen wollt."}}
D[5162] = {"Der Zorn des blauen Drachenschwarms",{"Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal."}}
D[5163] = {"Sind wir endlich da, Yeti?",{"Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit:","","Legacki in Everlook (Winterspring)","Sprinkle in Gadgetzan (Tanaris)","Quixxil in Marshals Zuflucht (Un'Goro Krater)","","Wenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück."}}
D[5164] = {"Verzeichnis der Abtrünnigen",{"Lest das 'Verzeichnis der Abtrünnigen'."}}
D[5165] = {"Übergießen der Flammen des Schutzes",{"Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser."}}
D[5166] = {"Brustplatte des Chromatischen Drachenschwarms",{"Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:","","1 chromatischer Knochenpanzer.","","10 glänzende chromatische Schuppen.","","10 Einheiten Blut von Helden.","","10 ausgefranste Monstrositätenstickereien."}}
D[5167] = {"Beinplatten des chromatischen Widersetzers",{"Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen:","","1 chromatischer Knochenpanzer.","","10 glänzende chromatische Schuppen.","","10 Einheiten Blut von Helden.","","5 Häute des Schattens."}}
D[5168] = {"Helden von Darrowshire",{"Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath."}}
D[5181] = {"Bösewichte von Darrowshire",{"Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts."}}
D[5201] = {"Eindringlinge der Winterfelle",{"Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt."}}
D[5202] = {"Ein merkwürdiger roter Schlüssel",{"Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird."}}
D[5203] = {"Rettung aus Jaedenar",{"Bringt Arko'narin dorthin, wo Lightforge und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Moonbow im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist."}}
D[5204] = {"Vergeltung des Lichts",{"Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lightforge sucht."}}
D[5206] = {"Marodeure von Darrowshire",{"Bringt 5 widerhallende Schädel und den mystischen Kristall zu Carlin Redpath in den Östlichen Pestländern."}}
D[5210] = {"Bruder Carlin",{"Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern."}}
D[5211] = {"Verteidiger von Darrowshire",{"Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück."}}
D[5212] = {"Das Fleisch lügt nicht",{"Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt."}}
D[5213] = {"Der aktive Wirkstoff",{"Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück."}}
D[5214] = {"Der große Ezra Grimm",{"Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist."}}
D[5215] = {"Die Geißelkessel",{"Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."}}
D[5216] = {"Ziel: Teufelssteinfeld",{"Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}}
D[5217] = {"Rückkehr zum Chillwind-Lager",{"Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."}}
D[5218] = {"Der Kessel des Teufelssteinfelds"}
D[5219] = {"Ziel: Dalsons Tränenfeld",{"Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}}
