D[5526] = {"Die Splitter der Teufelsranke",{"Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade."}}
D[5527] = {"Ein Reliquiar der Reinheit",{"Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück."}}
D[5528] = {"Der Gordokgeschmackstest"}
D[5529] = {"Verseuchte Jungtiere",{"Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück."}}
D[5531] = {"Betina Bigglezink",{"Bringt die gefrorenen Eier zu Betina Bigglezink."}}
D[5533] = {"Scholomance",{"Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer."}}
D[5534] = {"Kim'jaels 'fehlende' Ausrüstung",{"Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jal in Azshara."}}
D[5535] = {"Spirituelle Unruhe",{"Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt."}}
D[5536] = {"Ein Land voller Hass",{"Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück."}}
