D[5721] = {"Die Schlacht um Darrowshire",{"Legt das Reliktbündel auf den Marktplatz von Darrowshire.","","Verhindert Davil Lightfires Tod, bis Horgus stirbt.","","Verhindert Captain Redpaths Tod, bis Redpath der Verderbte erscheint.","","Besiegt Redpath den Verderbten.","","Sprecht mit dem Geist von Josef Redpath, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause."}}
D[5722] = {"Die Suche nach dem verloren gegangenen Ranzen",{"Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen."}}
D[5723] = {"Die Kraft des Feindes wird auf die Probe gestellt",{"Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück."}}
D[5724] = {"Wiederbeschaffung des verloren gegangenen Ranzens",{"Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff."}}
D[5725] = {"Die Macht der Zerstörung...",{"Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity."}}
D[5726] = {"Verborgene Feinde",{"Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar."}}
D[5727] = {"Verborgene Feinde",{"Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück."}}
D[5728] = {"Verborgene Feinde",{"Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt."}}
D[5729] = {"Verborgene Feinde",{"Sprecht mit Neeru Fireblade in Orgrimmar."}}
D[5730] = {"Verborgene Feinde",{"Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt."}}
D[5741] = {"Szepter des Lichts",{"Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor."}}
D[5742] = {"Erlösung",{"Hört Euch an, was Tirion Fordring zu sagen hat."}}
D[5761] = {"Vernichtung der Bestie",{"Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar."}}
D[5762] = {"Hemet Nesingwary",{"Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal."}}
D[5763] = {"Jagd im Schlingendorntal",{"Bringt Roons Kodohorn zu Hemet Nesingwary ins Schlingendorntal."}}
D[5781] = {"Von vergessenen Erinnerungen",{"Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}}
D[5801] = {"Feuerfeder geschmiedet",{"Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.","","Bringt den unvollendeten Skelettschlüssel dann zum Alchimisten Arbington an der Chillwindspitze in den Westlichen Pestländern."}}
D[5802] = {"Feuerfeder geschmiedet",{"Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden.","","Bringt den unvollendeten Skelettschlüssel zu Apotheker Dithers im Bollwerk, Westliche Pestländer."}}
D[5803] = {"Arajs Skarabäus",{"Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Chillwindspitze in den westlichen Pestländern."}}
D[5804] = {"Arajs Skarabäus",{"Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Dithers im Bollwerk, in den westlichen Pestländern."}}
D[5805] = {"Willkommen!",{"Bringt Merissa Stilwell den Nordhaingeschenkgutschein."}}
D[5821] = {"Leibwache zu mieten",{"Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten."}}
D[5841] = {"Willkommen!",{"Bringt Yori Crackhelm den Coldridgetal-Geschenkgutschein."}}
D[5842] = {"Willkommen!",{"Bringt Orenthil Whisperwind den Shadowglen-Geschenkgutschein."}}
D[5843] = {"Willkommen!",{"Bringt Magga den 'Tal der Prüfungen'-Geschenkgutschein."}}
D[5844] = {"Willkommen!",{"Bringt Vorn Skyseer den 'Camp Narache'-Geschenkgutschein."}}
D[5845] = {"Von verlorener Ehre",{"Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}}
D[5846] = {"Von Liebe und Familie",{"Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte."}}
D[5847] = {"Willkommen!",{"Bringt Claire Willower den Deathknell-Geschenkgutschein."}}
D[5848] = {"Von Liebe und Familie",{"Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.","","Bringt das Gemälde zu Tirion Fordring."}}
D[5861] = {"Myranda suchen",{"Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk."}}
D[5862] = {"Scharlachrote Täuschung",{"Sprecht mit Myranda, um die scharlachrote Illusion zu erhalten. Begebt Euch nach Hearthglen, während Ihr unter dem Einfluss der scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk.","","Hearthglen liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten."}}
D[5863] = {"Das Truppenlager der Dünenbrecher",{"Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet."}}
