D[5981] = {"Tobende Riesen",{"Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt."}}
D[6001] = {"Körper und Herz",{"Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid."}}
D[6002] = {"Körper und Herz",{"Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid."}}
D[6004] = {"Offene Rechnungen",{"Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}}
D[6021] = {"Zaeldarr der Ausgestoßene",{"Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts."}}
D[6022] = {"Töten zu einem bestimmten Zweck",{"Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."}}
D[6023] = {"Offene Rechnungen",{"Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}}
D[6024] = {"Hameyas Bitte",{"Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe."}}
D[6025] = {"Offene Rechnungen",{"Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück."}}
D[6026] = {"Das ist viel verlangt",{"Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.","","Für diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden."}}
D[6027] = {"Buch der Uralten",{"Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück."}}
D[6028] = {"Der Everlook-Bericht",{"Bringt den Everlook-Bericht zu Argentumoffizier Pureheart im Chillwind-Lager in den westlichen Pestländern."}}
D[6029] = {"Der Everlook-Bericht",{"Bringt den Everlook-Bericht zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern."}}
D[6030] = {"Fürst Nicholas Zverenhoff",{"Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern."}}
D[6031] = {"Runenstoff",{"Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste."}}
D[6032] = {"Hochheiliger Stoff",{"Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste."}}
D[6041] = {"When Smokey Sings, I Get Violent",{"Reist in den Pestwald, nordwestlich der Hoffnung des Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.","","Wenn ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.","","Übrigens, Smokeys spezielles Präparat ist recht ... instabil."}}
D[6042] = {"Die kleinen Ärgernisse des Un-Lebens",{"Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid."}}
D[6061] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof."}}
D[6062] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel."}}
