D[6086] = {"Die Ausbildung des Tiers",{"Sprecht mit Belia Thundergranite in Ironforge."}}
D[6087] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof."}}
D[6088] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof."}}
D[6089] = {"Die Ausbildung des Tiers",{"Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff."}}
D[6101] = {"Die Zähmung der Bestie",{"Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6102] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6103] = {"Die Ausbildung des Tiers",{"Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus."}}
D[6121] = {"Neue Lektionen",{"Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven."}}
D[6122] = {"Die eigentliche Ursache",{"Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.","","Bringt das gefüllte Gefäß von Cliffspring Falls zu Alanndarian Nightsong nach Auberdine in Dunkelküste."}}
D[6123] = {"Das Heilmittel sammeln",{"Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann."}}
D[6124] = {"Heilung der Kranken",{"Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist."}}
D[6125] = {"Macht über Gift",{"Kehrt zu Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus zurück."}}
D[6126] = {"Neue Lektionen",{"Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven."}}
D[6127] = {"Die eigentliche Ursache",{"Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.","","Bringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runetotem in Crossroads im Brachland."}}
D[6128] = {"Das Heilmittel sammeln",{"Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runetotem in Crossroads, damit er eine Heilsalbe machen kann."}}
D[6129] = {"Heilung der Kranken",{"Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße durch Crossroads gesehen."}}
D[6130] = {"Macht über Gift",{"Kehrt zu Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff zurück."}}
D[6132] = {"Holt mich hier raus!",{"Eskortiert Melizza Brimbuzzle und sprecht anschließend mit Hornizz Brimbuzzle beim Kodofriedhdof Desolace."}}
D[6133] = {"Das Ersuchen des Waldläuferlords",{"Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge.","","Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten."}}
D[6134] = {"Geisterplasmasuche",{"Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace."}}
D[6135] = {"Dämmerschwinge, oh, wie ich Euch hasse...",{"Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller.","","Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift."}}
D[6136] = {"Der Korpulente",{"Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt."}}
D[6141] = {"Bruder Anton",{"Sprecht mit Bruder Anton in Desolace."}}
D[6142] = {"Muschelköder",{"Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Shadowprey."}}
D[6143] = {"Andere Fische zu grillen",{"Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberhexerinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Shadowprey."}}
D[6144] = {"Der Befehl",{"Reist in die Undercity und sprecht mit Varimathras."}}
D[6145] = {"Der Purpurrote Kurier",{"Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers.","","Bringt den Befehl zu Nathanos Blightcaller und wartet auf weitere Anweisungen."}}
D[6146] = {"Nathanos' List",{"Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des obersten Kreuzzüglers."}}
D[6147] = {"Kehrt zu Nathanos zurück.",{"Kehrt mit der neuen Information zu Nathanos Blightcaller zurück."}}
D[6148] = {"Das Scharlachrote Orakel Demetria",{"Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr erfolgreich wart."}}
D[6161] = {"Nehmt Rackmores Schatz!",{"Sucht Rackmores Silberschlüssel. Sucht Rackmores Goldschlüssel. Sucht und öffnet Rackmores Truhe."}}
D[6162] = {"Eines Ehemanns letzter Kampf",{"Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald."}}
D[6163] = {"Ramstein",{"Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos."}}
D[6164] = {"Augustus' Rezeptbuch",{"Bringt Augustus' Quittungsbuch zu Augustus dem Meschuggenen im Schreckenstal."}}
D[6181] = {"Eine eilige Nachricht",{"Bringt Lewis' Notiz zu Thor dem Greifenmeister."}}
D[6182] = {"Der Erste und Letzte",{"Sprecht mit Meister Mathias Shaw in der Altstadt von Stormwind. Er wohnt in der Kaserne."}}
D[6183] = {"Ehret die Toten",{"Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt."}}
D[6184] = {"Flint Shadowmore",{"Reist zur Chillwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Shadowmore."}}
D[6185] = {"Die östlichen Pestländer",{"Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze."}}
D[6186] = {"Der Blightcaller kommt",{"Kehrt nach Stormwind zurück und informiert Hochlord Bolvar Fordragon über das Schicksal von Nathanos Marris."}}
D[6187] = {"Ordnung muss wieder hergestellt werden",{"Stellt eine Armee auf und reist zu den östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Blightcaller und jeden Abschaum der Horde, der ihn beschützen mag.","","Bewahrt einen klaren Kopf, <Name>. Die Horde wird den Waldläuferlord mit dem Leben verteidigen."}}
D[6261] = {"Dungar Longdrink",{"Bringt Osrics Kiste zu Dungar Longdrink dem Greifenmeister."}}
D[6281] = {"Weiter nach Stormwind",{"Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Stormwind."}}
D[6282] = {"Harpyien drohen",{"Maggran Earthbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt."}}
D[6283] = {"Blutfuriengeschlecht",{"Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt."}}
D[6284] = {"Arachnophobie",{"Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels."}}
D[6285] = {"Zurück zu Lewis",{"Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Longdrink, dann bringt Osrics Kiste zu Lewis an der Späherkuppe."}}
D[6301] = {"Zyklus der Wiedergeburt",{"Tammra Windfield in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt."}}
D[6321] = {"Nachschub für das Grabmal",{"Bringt Podrigs Liste zu Karos Razok."}}
D[6322] = {"Michael Garrett",{"Bringt Gordons Kiste zu Michael Garret."}}
D[6323] = {"Flug nach Undercity",{"Bucht einen Fledermausritt zur Undercity bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendham in Undercity."}}
D[6324] = {"Rückkehr zu Podrig",{"Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garret und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal."}}
D[6341] = {"Die Arten von Teldrassil",{"Bringt Nessas Sammlung zu Vesprystus."}}
D[6342] = {"Flug nach Auberdine",{"Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird."}}
D[6343] = {"Rückkehr zu Nessa",{"Bringt Lairds Antwort zu Nessa Shadowsong."}}
D[6344] = {"Nessa Shadowsong",{"Sprecht mit Nessa Shadowsong."}}
D[6361] = {"Ein Bündel Bälge",{"Bringt das Bündel Bälge zu Windreitermeister Devrak in Crossroads."}}
D[6362] = {"Flug nach Thunder Bluff",{"Bucht einen Windreiter nach Thunder Bluff bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Thunder Bluff."}}
D[6363] = {"Tal der Windreitermeister",{"Bringt Ahanus Lederwaren zu Tal in Thunder Bluff."}}
D[6364] = {"Rückkehr zu Jahan",{"Bucht einen Windreiter nach Crossroads bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Hawkwing."}}
D[6365] = {"Fleisch für Orgrimmar",{"Bringt Zarghs Fleisch zu Devrak in Crossroads."}}
D[6381] = {"Neues Leben",{"Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und sprecht dann mit Tammra in Sonnenfels."}}
D[6382] = {"Die Jagd in Ashenvale",{"Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale."}}
D[6383] = {"Die Jagd in Ashenvale"}
D[6384] = {"Flug nach Orgrimmar",{"Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleisch zu Gryshka in Orgrimmar."}}
D[6385] = {"Doras der Windreitermeister",{"Bringt Gryshkas Brief zu Doras in Orgrimmar."}}
D[6386] = {"Kehrt nach Crossroads zurück",{"Bucht einen Windreiter nach Crossroads bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh in Crossroads."}}
D[6387] = {"Ehrenstudenten",{"Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Bringt die Ehrenhacken zu Gryth Thurden in Ironforge."}}
D[6389] = {"Eine Plage komme über Euch",{"Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück."}}
D[6390] = {"Eine Plage komme über Euch",{"Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück."}}
D[6391] = {"Flug nach Ironforge",{"Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge."}}
D[6392] = {"Rückkehr zu Brock",{"Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar."}}
D[6393] = {"Krieg der Elementare",{"Bringt 10 Pyrophore zu Tsunaman in Sonnenfels."}}
D[6394] = {"Thazz'rils Hacke",{"Bringt Thazz'rils Hacke zu Großknecht Thazz'ril."}}
D[6395] = {"Marlas letzter Wunsch",{"Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück."}}
D[6401] = {"Kaya lebt",{"Teilt Tammra Windfield, die in Sonnenfels lebt, die gute Nachricht mit."}}
D[6402] = {"Treffen in Stormwind",{"Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert."}}
D[6403] = {"Die große Maskerade",{"Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!"}}
D[6421] = {"Steinschlagklamm",{"Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann."}}
D[6441] = {"Satyrhörner",{"Sammelt für Pixel im Splintertreeposten 16 Satyrhörner."}}
D[6442] = {"Die Naga am Zoramstrand",{"Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen."}}
D[6461] = {"Blutfresser",{"Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet."}}
D[6462] = {"Troll-Glücksbringer",{"Bringt Mitsuwa im Zoram'gar-Außenposten 8 Troll-Glücksbringer."}}
D[6481] = {"Der Irdene erhebt sich",{"Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück."}}
D[6482] = {"Freiheit für Ruul",{"Begleitet Ruul und sprecht dann mit Yama Snowhoof im Splintertreeposten."}}
D[6501] = {"Das Großdrachenauge",{"Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert."}}
D[6502] = {"Drachenfeueramulett",{"Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze."}}
D[6503] = {"Die Kundschafter von Ashenvale",{"Tötet 9 Kundschafter von Ashenvale und kehrt dann zu Kuray'bin im Splintertreeaußenposten zurück."}}
D[6504] = {"Die verlorenen Seiten",{"Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen."}}
D[6521] = {"Eine unheilige Allianz",{"Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity."}}
D[6522] = {"Eine unheilige Allianz",{"Bringt die kleine Rolle zu Varimathras nach Undercity."}}
D[6523] = {"Schützt Kaya",{"Begleitet Kaya Flathoof zum Camp Aparaje und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6541] = {"Meldung bei Kadrak",{"Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."}}
D[6542] = {"Meldung bei Kadrak",{"Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."}}
D[6543] = {"Die Warsongberichte",{"Bringt die Warsongberichte dem Warsongspäher, dem Warsongläufer und der Warsongvorhut. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands."}}
D[6544] = {"Toreks Angriff",{"Eskortiert Torek bei seinem Angriff auf den Außenposten der Silverwing und Duriel Moonfire. Erstattet dann Ertog Ragetusk im Splintertreeposten Bericht."}}
D[6545] = {"Warsongläufer-Update"}
D[6546] = {"Warsongvorhut-Update"}
D[6547] = {"Warsongspäher-Update"}
D[6548] = {"Rächt mein Dorf",{"Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6561] = {"Blackfathom-Schurkerei",{"Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff."}}
D[6562] = {"Ärger in der Tiefe",{"Sprecht in Ashenvale mit Je'neu Sancrea."}}
D[6563] = {"Die Essenz von Aku'mai",{"Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale."}}
D[6564] = {"Treue zu den Alten Göttern",{"Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale."}}
D[6565] = {"Treue zu den Alten Göttern",{"Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück."}}
D[6566] = {"Was der Wind erzählt",{"Hört Thrall zu."}}
D[6567] = {"Der Champion der Horde",{"Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab."}}
D[6568] = {"Nachricht von Rexxar",{"Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht."}}
D[6569] = {"Oculus-Illusionen",{"Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[6570] = {"Aschenschwinge",{"Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge."}}
D[6571] = {"Warsongnachschub",{"Tragt den Warsongnachschub zusammen: Warsongsägeblätter, Holzfäller-Seil, Warsongöl und die Warsongaxtlieferung für Locke Okarr im Splintertreeposten."}}
D[6581] = {"Warsongsägeblätter"}
D[6582] = {"Die Prüfung der Schädel, Scryer",{"Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.","","Ihr wisst, dass Scryer in Winterspring zu finden ist."}}
D[6583] = {"Die Prüfung der Schädel, Somnus",{"Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück."}}
D[6584] = {"Die Prüfung der Schädel, Chronalis",{"Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge."}}
D[6585] = {"Die Prüfung der Schädel, Axtroz",{"Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück."}}
D[6601] = {"Aufstieg...",{"Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist."}}
D[6602] = {"Blut des schwarzen Großdrachen-Helden",{"Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar."}}
D[6603] = {"Probleme in Winterspring",{"Findet Donova Snowden bei den Thermalquellen in Winterspring."}}
D[6604] = {"Wütende Wildekin",{"Sprecht mit Jaron Stoneshaper in Starfall."}}
D[6605] = {"Eine seltsame Person",{"Sprecht im Teufelswald mit Winna Hazzard."}}
D[6606] = {"Ein bisschen Glück",{"Sprecht in Everlook mit Hexendoktorin Mau'ari."}}
D[6607] = {"Nat Pagle, Extremangler",{"Nat Pagle möchte, dass Ihr folgende Fische fangt:","","Nebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.","","Einen Sar'theris-Barsch vom Sar'theris-Strand in Desolace.","","Feralas-Ahi aus dem Verdantis in Feralas.","","Blauwimpel von der ungezähmten Küste im Schlingendorntal.","","Kehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!"}}
D[6608] = {"Ihr zu gut",{"Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht."}}
D[6609] = {"Ich hab nix mehr!",{"Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!"}}
D[6610] = {"Muschelette Surprise",{"Dirge Quikcleave möchte, dass Ihr folgende Dinge besorgt:","","12 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.","","10 Stück scharfes Muschelfleisch. Die findet Ihr natürlich in Muscheln!","","20 Stück Alteraclochkäse. Begebt Euch zu einer Käserei!","","Sammelt all diese Gegenstände und kehrt dann zu Dirge zurück."}}
D[6611] = {"Ab mit Euch nach Gadgetzan!",{"Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere."}}
D[6612] = {"Ich kenne einen Typen...",{"Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere."}}
D[6621] = {"König der Fäulnisklauen",{"Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar."}}
D[6622] = {"Triage",{"Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.","","Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt."}}
D[6623] = {"Traumachirurg der Horde",{"Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt."}}
D[6624] = {"Triage",{"Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.","","Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt."}}
D[6625] = {"Traumachirurg der Allianz",{"Reist nach Theramore in den Marschen von Dustwallow und sprecht mit Doktor Gustaf van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt."}}
D[6626] = {"Ein Hort des Bösen",{"Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück."}}
D[6627] = {"Test der Lehre",{"Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid."}}
D[6628] = {"Test der Lehre",{"Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid."}}
D[6629] = {"Tötet Grundig Finsterwolke",{"Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6641] = {"Vorsha die Peitscherin",{"Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.","","Wenn Ihr erfolgreich gewesen seid, kehrt zum Zoram'garposten zurück und informiert den Warsongläufer über den Tod von Vorsha der Peitscherin."}}
D[6642] = {"Gunst der Bruderschaft, Dunkeleisenerz"}
D[6643] = {"Gunst der Bruderschaft, Feuerkern"}
D[6644] = {"Gunst der Bruderschaft, Lavakern"}
D[6645] = {"Gunst der Bruderschaft, Kernhäute"}
D[6646] = {"Gunst der Bruderschaft, Blut des Berges"}
D[6661] = {"Tiefenbahn-Ratten-Razzia",{"Fangt mit Hilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid."}}
D[6662] = {"Mein Bruder Nipsy...",{"Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Stormwind."}}
D[6681] = {"Das Anwesen, Ravenholdt",{"Bringt das Ravenholdt-Siegel zu Fahrad im Ravenholdt-Anwesen, das versteckt in den Hügeln von Hillsbrad liegt.","","Unterwegs wird man Eure Schlauheit testen. Seid darauf gefasst."}}
D[6701] = {"Syndikatsembleme"}
D[6721] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6722] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar."}}
D[6741] = {"Mehr Beute!"}
D[6761] = {"Die neue Grenze",{"Sprecht mit Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus."}}
D[6762] = {"Rabine Saturna",{"Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt."}}
D[6781] = {"Mehr Rüstungsfetzen"}
D[6801] = {"Lokholar der Eislord"}
D[6804] = {"Vergiftetes Wasser",{"Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara."}}
D[6805] = {"Stürmer und Rumpler",{"Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück."}}
D[6821] = {"Auge des Glutsehers",{"Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara."}}
D[6822] = {"Der geschmolzene Kern",{"Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück."}}
D[6823] = {"Agent von Hydraxis",{"Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara."}}
D[6824] = {"Hände des Feindes",{"Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara."}}
D[6825] = {"Ruf der Lüfte - Guses Luftflotte"}
D[6826] = {"Ruf der Lüfte - Jeztors Luftflotte"}
D[6827] = {"Ruf der Lüfte - Mulvericks Luftflotte"}
D[6844] = {"Umber, Archivar",{"Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nighthaven in Moonglade."}}
D[6845] = {"Enthüllung von Geheimnissen der Vergangenheit",{"Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade."}}
D[6846] = {"Der Angriff soll beginnen!"}
D[6847] = {"Meister Rysons Allsehendes Auge",{"Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.","","Seid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!"}}
D[6848] = {"Meister Rysons Allsehendes Auge",{"Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.","","Seid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!"}}
D[6861] = {"Zinfizzlex's tragbare Schreddereinheit",{"Meisteringenieur Zinfizzlex möchte, dass Ihr ihm Folgendes bringt:","","*30 Thoriumbarren.","","*50 Mithrilbarren.","","*75 Eisenbarren.","","*1 Dampfsäge."}}
D[6862] = {"Zinfizzlex's tragbare Schreddereinheit",{"Meisteringenieur Zinfizzlex möchte, dass Ihr ihm Folgendes bringt:","","*30 Thoriumbarren.","","*50 Mithrilbarren.","","*75 Eisenbarren.","","*1 Dampfsäge."}}
