D[6901] = {"Startet den Angriff!"}
D[6921] = {"Inmitten der Ruinen",{"Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}}
D[6922] = {"Baron Aquanis",{"Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}}
