D[6961] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[6962] = {"Leckereien für Altvater Winter",{"Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Orgrimmar."}}
D[6963] = {"Gestohlene Winterhauch-Leckereien",{"Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird."}}
D[6964] = {"Der Anlass für die Feiertage",{"Sprecht mit Sagorne Crestrider im Tal der Weisheit von Orgrimmar über das Winterhauchfest."}}
D[6981] = {"Der leuchtende Splitter",{"Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.","","Liefert dann den Splitter ab, wie Ihr angewiesen wurdet."}}
D[6982] = {"Coldtooth-Vorräte",{"Bringt 5 Coldtooth-Vorräte zum Rüstmeister der Allianz in Dun Baldar."}}
D[6983] = {"So was Gemeines...",{"Sucht die gestohlenen Leckereien und bringt sie zu Kaymard Copperpinch nach Orgrimmar. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten der Arathi-Berge befindet."}}
D[6984] = {"Ein Dankeschön von Kokelwälder!",{"Sprecht mit Altvater Winter in Orgrimmar."}}
D[6985] = {"Irondeep-Vorräte",{"Bringt 10 Irondeep-Vorräte zum Rüstmeister der Horde in die Burg Frostwolf."}}
D[7001] = {"Verwaiste Ställe",{"Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden."}}
D[7002] = {"Widderledernes Zaumzeug"}
D[7003] = {"Geschrumpfte Riesen",{"Benutzt Zorbins Super-Schrumpfer um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin Fandazzle 15 Schrumpf-Überreste von diesen Riesen. Ihr findet Ihn bei den Docks, an der vergessenen Küste in Feralas."}}
D[7021] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[7022] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Ironforge."}}
D[7023] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Ironforge."}}
D[7024] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[7025] = {"Leckereien für Altvater Winter",{"Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Ironforge."}}
D[7026] = {"Widderzaumzeug"}
D[7027] = {"Verwaiste Ställe",{"Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Stormpike Zähmungshalsband um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden."}}
D[7028] = {"Dunkles Böses",{"Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace."}}
D[7029] = {"Schlangenzunges Verderbnis",{"Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.","","Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.","","Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück."}}
D[7041] = {"Schlangenzunges Verderbnis",{"Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.","","Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.","","Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück."}}
D[7042] = {"Gestohlene Winterhauch-Leckereien",{"Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird."}}
D[7043] = {"So was Gemeines...",{"Sucht die gestohlenen Leckereien und bringt sie zu Wulmort Jinglepocket nach Ironforge. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten der Arathi-Berge befindet."}}
D[7044] = {"Legenden von Maraudon",{"Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.","","Findet einen Weg, um mit Celebras zu sprechen."}}
D[7045] = {"Ein Dankeschön von Kokelwälder!",{"Sprecht mit Altvater Winter in Ironforge."}}
D[7046] = {"Das Szepter von Celebras",{"Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.","","Sprecht mit ihm, nachdem das Ritual vollendet ist."}}
D[7061] = {"Das Winterhauchfest",{"Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Cairne Bloodhoof in Thunder Bluff."}}
D[7062] = {"Der Anlass für die Feiertage",{"Sprecht mit dem Historiker Karnik in der Forscherliga von Ironforge über das Winterhauchfest."}}
D[7063] = {"Das Winterhauchfest",{"Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, dann bringt es zu König Magni Bronzebeard nach Ironforge."}}
D[7064] = {"Verderbnis von Erde und Samenkorn",{"Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück."}}
D[7065] = {"Verderbnis von Erde und Samenkorn",{"Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück."}}
D[7066] = {"Samenkorn des Lebens",{"Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens."}}
D[7067] = {"Die Anweisungen des Pariahs",{"Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."}}
D[7068] = {"Schattensplitter",{"Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar."}}
D[7070] = {"Schattensplitter",{"Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow."}}
D[7081] = {"Die Friedhöfe im Alteractal",{"Erobert einen Friedhof und kehrt zu Sergeant Durgen Stormpike im Alteracgebirge zurück."}}
D[7082] = {"Die Friedhöfe von Alterac",{"Erobert einen Friedhof und kehrt zu Corporal Teeka Bloodsnarl im Alteracgebirge zurück."}}
D[7101] = {"Türme und Bunker",{"Erobert einen gegnerischen Turm und kehrt anschließend zu Corporal Teeka Bloodsnarl in Frostwolf zurück."}}
D[7102] = {"Türme und Bunker",{"Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Sergeant Durgen Stormpike im Alteracgebirge zurück."}}
D[7121] = {"Der Rüstmeister",{"Sprecht mit dem Rüstmeister der Stormpike."}}
D[7122] = {"Mine besetzen",{"Erobert eine Mine, die die Stormpike noch nicht kontrollieren, und kehrt dann zu Sergeant Durgen Stormpike im Alteracgebirge zurück."}}
D[7123] = {"Sprecht mit unserem Rüstmeister",{"Sprecht mit dem Rüstmeister der Frostwolf."}}
D[7124] = {"Eine Mine besetzen",{"Erobert eine Mine und kehrt zu Corporal Teeka Bloodsnarl im Alteracgebirge zurück."}}
D[7141] = {"Die Schlacht um Alterac",{"Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Stonehewer im Alteracgebirge zurück."}}
D[7142] = {"Die Schlacht um Alterac",{"Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Stormpike. Kehrt anschließend zu Voggah Deathgrip im Alteracgebirge zurück."}}
D[7161] = {"Flaggenjagd",{"Begebt euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt und findet das Banner der Frostwolf. Bringt anschließend Kriegsmeister Laggrond das Banner."}}
D[7162] = {"Flaggenjagd",{"Begebt euch in die Icewinghöhle südwestlich von Dun Baldar und findet das Banner der Stormpike. Bringt anschließend Lieutenant Haggerdin im Alteracgebirge das Banner."}}
