D[7165] = {"Verdiente Ehrerbietung"}
D[7166] = {"Legendäre Helden"}
D[7167] = {"Das Auge der Führung"}
D[7168] = {"Aufstieg und Anerkennung"}
D[7169] = {"Ehre innerhalb der Garde"}
D[7170] = {"Verdiente Ehrerbietung"}
D[7171] = {"Legendäre Helden"}
D[7172] = {"Das Auge der Führung"}
D[7181] = {"Die Legende von Korrak",{"Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden.","","Begebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Kriegsmeister Laggrond zurück."}}
D[7201] = {"Das letzte Element",{"Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat."}}
D[7202] = {"Korrak der Blutrünstige",{"Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden.","","Begebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Lieutenant Haggerdin zurück."}}
D[7221] = {"Sprecht mit Ausgrabungsleiter Stonehewer",{"Sprecht mit Ausgrabungsleiter Stonehewer in der Garnison von Dun Baldar."}}
D[7222] = {"Sprecht mit Voggah Deathgrip",{"Sprecht mit Voggah in Burg Frostwolf."}}
D[7223] = {"Rüstungsfetzen",{"Bringt Murgot Deepforge in Dun Baldar 20 Rüstungsfetzen."}}
D[7224] = {"Beutezug im Feindesland",{"Bringt 20 Rüstungsfetzen zu Schmied Regzar in Frostwolf."}}
D[7241] = {"Die Verteidigung von Frostwolf",{"Reist ins Alteractal im Vorgebirge von Hillsbrad. Sucht dort Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwolf."}}
D[7261] = {"Die hoheitliche Anordnung",{"Reist ins Alteractal im Vorgebirge von Hillsbrad. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.","","Für den Ruhm von Bronzebeard!"}}
D[7281] = {"Bruderliebe",{"Begebt euch ins Gebiet der Stormpike und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[7282] = {"Bruderliebe",{"Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[7301] = {"Gefallene Himmelsstürmer",{"Begebt Euch ins Frostwolf Territorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt."}}
D[7302] = {"Gefallene Himmelsstürmer",{"Findet heraus was aus Schwadronskommandant Guse, Schwadronskommandant Jeztor, und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück."}}
D[7321] = {"Milde Schildkrötensuppe",{"Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Christoph Jeffcoat in Tarrens Mühle."}}
D[7341] = {"Ein fairer Handel"}
D[7342] = {"Pfeile sind was für Memmen"}
D[7361] = {"Die Gunst der Dunkelspeere",{"Ihr wurdet beauftragt gegnerische Nachtelfenspieler im Alteractal zu töten.","","Tötet einen Nachtelfen und bringt einen abgeschlagenen Nachtelfenkopf zu Najak Hexxen in Burg Frostwolf."}}
D[7362] = {"Verbündeter der Tauren",{"Ihr wurdet beauftragt gegnerische Gnomspieler im Alteractal zu töten.","","Tötet einen Gnom und bringt ein Büschel Gnomhaar zu Ravak Grimmtotem in Burg Frostwolf."}}
D[7363] = {"Die menschliche Existenz",{"Ihr wurdet beauftragt gegnerische Menschenspieler im Alteractal zu töten.","","Tötet einen Menschen und bringt dessen Knochensplitter zu Kommandant Louis Philips (er bewegt sich zwischen den Frontlinien und Burg Frostwolf hin und her).","","Die Heilung für die menschliche Existenz ist zum Greifen nahe!"}}
D[7364] = {"Gnomeregan Kopfgeld",{"Ihr wurdet beauftragt gegnerische Taurenspieler im Alteractal zu töten.","","Tötet einen Tauren und bringt dessen Taurenhuf zu Dirk Schwindel in Dun Baldar."}}
D[7365] = {"Hirschhaupts Requiem",{"Ihr wurdet beauftragt gegnerische Trollspieler im Alteractal zu töten.","","Tötet einen Troll und bringt Athramanis in Dun Baldar etwas Trollmojo der Dunkelspeere."}}
D[7366] = {"Die Gnade des Erzbischofs",{"Ihr wurdet beauftragt gegnerische Verlassenen-Spieler im Alteractal zu töten.","","Tötet einen Verlassenen und bringt dessen Herz zu Kommandant Karl Philips (er bewegt sich zwischen dem Sägewerk und der Mine hin und her)."}}
D[7367] = {"Die Gefahr bannen",{"Findet den Sprengmeister der Frostwolf und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Stormpike zurück."}}
D[7368] = {"Die Gefahr bannen",{"Findet den Sprengmeister der Stormpike und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Frostwolf zurück."}}
D[7381] = {"Korraks Rückkehr",{"Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.","","Bringt Korraks Schädel zu Kriegsmeister Laggrond auf Burg Frostwolf."}}
D[7382] = {"Korrak der Unsterbliche",{"Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.","","Bringt Korraks Schädel zu Leutnant Haggerdin in Dun Baldar."}}
D[7383] = {"Krone der Erde",{"Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar."}}
D[7385] = {"Eine Gallone Blut"}
D[7386] = {"Haufenweise Kristalle"}
D[7401] = {"GESUCHT: Zwerge!",{"Ihr wurdet damit beauftragt, alle feindlichen Zwergenspieler im Alteractal zu töten.","","Tötet einen Zwerg und schneidet ihm sein Rückgrat heraus. Bringt anschließend das Zwergenrückgrat zu Unteroffizierin Yazra Murrblut in Burg Frostwolf."}}
D[7402] = {"GESUCHT: ORCS!",{"Ihr wurdet damit beauftragt, alle feindlichen orcischen Spieler im Alteractal zu töten.","","Tötet einen Orc und bringt seinen Zahn zurück zu Korporal Noreg Sturmlanze in Dun Baldar."}}
