D[7701] = {"GESUCHT: Vorarbeiter Maltorius",{"Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.","","Tötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Ausguck Captain Lolo Longstriker in der sengenden Schlucht für eine Belohnung."}}
D[7703] = {"Die offene Rechnung der Gordok",{"Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.","","Kromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat."}}
D[7704] = {"Schau dir die Größe an!",{"Bringt das Kissen von Zimmermädchen Kissenquetscher zu Evonice Sootsmoker in der sengenden Schlucht."}}
D[7721] = {"Treibstoff fürs Schrumpfen",{"Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks."}}
D[7722] = {"Was zum Fluxus?!",{"Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht."}}
D[7723] = {"Verdammt seien diese fetten Finger",{"Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet.","","Die Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück."}}
D[7724] = {"Feurige Bedrohung!",{"Hansel Heavyhands möchte, dass Ihr 20 große Lavaspinnen in der sengenden Schlucht tötet.","","Die großen Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der segenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück."}}
D[7725] = {"Und wieder unter den geschrumpften Riesen",{"Benutzt Zorbins Super-Schrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt 10 Schrumpf-Überreste, die auf den kleineren handlicheren Riesen liegen zu Zorbin Fandazzle am Dock der Vergessenen Küste in Feralas."}}
D[7726] = {"Neuer Treibstoff fürs Schrumpfen",{"Sammelt 6 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks."}}
D[7727] = {"Incendosaurier? Was-auch-immer-Saurier?",{"Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet.","","Die Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der segenden Schlucht.","","Sobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Heavyhands in der sengenden Schlucht zurück."}}
D[7728] = {"GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr",{"Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht.","","Die einzigen Informationen die Ihr habt sind: Die Schmiedewindform is ein SCHMIEDEwerkzeug welches von SCHMIEDEN verwendet wird und das Ausguck-Handfernrohr ist ein unverzichtbares Werkzeug für SPÄHPOSTEN."}}
D[7729] = {"STELLE ZU VERGEBEN: Erledige die Konkurrenz",{"Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[7730] = {"Zukk'ash-Plage",{"Bringt Hadoken Swiftstrider im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer."}}
D[7731] = {"Zornstachel",{"Besiegt Zornstachel in der verwundenen Tiefe und bringt seine Drüsen zu Hadoken Swiftstrider im Camp Mojache in Feralas zurück."}}
D[7732] = {"Bericht über die Zukk'ash",{"Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Drumlore. Er wohnt in der Gasse von Orgrimmar."}}
D[7733] = {"Beste Qualität",{"Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge."}}
D[7734] = {"Beste Qualität",{"Bringt Jangdor Swiftstrider im Camp Mojache in Feralas 10 Wutschrammyetibälge."}}
D[7735] = {"Makelloser Yetibalg",{"Bringt Pratt McGrubben in der Festung Feathermoon den makellosen Yetibalg."}}
D[7736] = {"Nachschub an feurigem Fluxus: Königsblut"}
D[7737] = {"Erlangte Anerkennung"}
D[7738] = {"Perfekter Yetibalg",{"Bringt Jangdor Swiftstrider im Camp Mojache in Feralas den makellosen Yetibalg."}}
D[7761] = {"Blackhands Befehl",{"Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.","","Dem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen."}}
D[7781] = {"Der Herrscher von Blackrock",{"Bringt Hochlord Bolvar Fordragon in Stormwind den Kopf von Nefarian."}}
D[7782] = {"Der Herrscher von Blackrock",{"Reist in nach Stormwind in das Tal der Helden und sprecht mit Feldmarschall Afrasiabi."}}
D[7783] = {"Der Herrscher von Blackrock",{"Bringt Thrall in Orgrimmar den Kopf von Nefarian."}}
D[7784] = {"Der Herrscher von Blackrock",{"Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch."}}
D[7785] = {"Untersuchung des Gefäßes",{"Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian."}}
D[7786] = {"Donneraan der Windsucher",{"Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen."}}
D[7787] = {"Donnerzorn erwache!",{"Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge."}}
D[7788] = {"Besiegt die Eindringlinge!",{"Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück."}}
D[7789] = {"Bezwingt die Eindringlinge der Silverwing",{"Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück."}}
