D[8053] = {"Symbole der Macht: Die Armschützer des Freidenkers",{"Bringt urzeitliche Hakkaribindungen zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8054] = {"Symbole der Macht: Der Gürtel des Freidenkers",{"Bringt einen urzeitlichen Hakkarischal zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.","","Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8055] = {"Symbole der Macht: Die Brustplatte des Freidenkers",{"Bringt einen urzeitlichen Hakkariwappenrock zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.","","Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8056] = {"Symbole der Macht: Die Armschienen des Weissagers",{"Bringt urzeitliche Hakkariarmsplinte zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8057] = {"Symbole der Macht: Die Haruspexarmschienen",{"Bringt eine urzeitliche Hakkaristütze zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8058] = {"Symbole der Macht: Die Armschützer des Vollstreckers",{"Bringt urzeitliche Hakkariarmsplinte zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8059] = {"Symbole der Macht: Die Handlappen des Besessenen",{"Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Al'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8060] = {"Symbole der Macht: Die Handlappen des Illusionisten",{"Bringt urzeitliche Hakkaribindungen zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Al'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8061] = {"Symbole der Macht: Die Handlappen des Glaubenshüters",{"Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Al'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal."}}
D[8062] = {"Symbole der Macht: Die Armschienen des Raubtiers",{"Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Urzeitliche Hakkaribindungen. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.","","Falthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal."}}
