D[8304] = {"Liebste Natalia",{"Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr die Bewohner von Bronzebeards Lager befragt. Das Lager befindet sich südlich von Burg Cenarius.","","Kehrt zu Kommandant Mar'alith zurück, wenn Ihr die benötigten Informationen gesammelt habt."}}
D[8305] = {"Lang Vergessenes",{"Sucht die Kristallträne und blickt in ihr Innerstes."}}
D[8306] = {"Der Schlund des Wahnsinns",{"Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet.","","Sprecht noch einmal mit den Zwergen in Bronzebeards Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch.","","Und <Name>, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\""}}
D[8307] = {"Wüstenrezept",{"Haltet beim Lager der Twilight-Hammer westlich von Burg Cenarius nach Informationen zum Zubereiten von Sandwurmfleisch Ausschau."}}
D[8308] = {"Der verlorene Brief von Brann Bronzebeard",{"Liefert Brann Bronzebeards verlorenen Brief in Bronzebeards Lager im südlichen Silithus ab."}}
D[8309] = {"Glyphenjagd",{"Rutgar Glyphshaper in Bronzebeards Lager in Silithus möchte, dass Ihr in den Bau des Ashischwarms, Bau des Zoraschwarms und Bau des Regalschwarms eindringt und dort Abpausbilder von den glyphenverzierten Kristallen anfertigt.","","Benutzt das Abschriftenset für Geologen, um Abpausbilder der uralten Glyphen herzustellen. Kehrt nach Abschluss der Aufgabe zu Rutgar Glyphshaper zurück."}}
D[8310] = {"Knackt den Kode",{"Frankal Stonebridge in Bronzebeards Lager möchte, dass Ihr ihm jeweils ein Silithidengehirn des Zoraschwarms, Ashischwarms und des Regalschwarms bringt. Kehrt nach der Erfüllung Eurer Aufgabe zu Frankal zurück."}}
D[8311] = {"Schlotternachtssüßigkeiten für Jesper!",{"Sprecht mit den Gastwirten in Stormwind, Ironforge und Darnassus, sowie mit Talvash del Kissel in Ironforge. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.","","Kehrt zu Jesper ins Waisenhaus von Stormwind mit einem Marzipan aus Darnassus, einer Kaugummikugel aus Gnomeregan, Nugat aus Stormwind und einem Pfefferminzbonbon aus Ironforge zurück."}}
D[8312] = {"Schlotternachtssüßigkeiten für Spoops!",{"Sprecht mit den Gastwirten in Orgrimmar, Undercity und Thunder Bluff, sowie mit Kali Remik in Sen'jin. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.","","Kehrt zu Spoops ins Waisenhaus von Orgrimmar mit einem Marzipan aus Thunder Bluff, einer Kaugummikugel der Darkspear, Nugat aus Orgrimmar und einem Pfefferminzbonbon aus Undercity zurück."}}
D[8313] = {"Geteiltes Wissen",{"Bringt die ausgerissene Rezeptseite zu Calandrath ins Gasthaus der Burg Cenarius."}}
D[8314] = {"Des Rätsels Lösung",{"Rutgar Glyphshaper in Bronzebeards Lager möchte, dass Ihr Geologin Larksbane auf Burg Cenarius in Silithus das glyphenverzierte Kristallprisma bringt."}}
D[8315] = {"Die Anrufung",{"Geologin Larksbane auf Burg Cenarius in Silithus möchte, dass Ihr ihr den Kristallentriegelungsmechanismus vom Abgesandten der Qiraji beschafft.","","Nehmt die Glyphen der Anrufung, begebt Euch zu den Knochen von Grakkarond südlich von Burg Cenarius und zeichnet sie dort in den Sand. Sollte der Abgesandte der Qiraji erscheinen, tötet ihn und nehmt den Kristallentriegelungsmechanismus an Euch. Kehrt anschließend zu Geologin Larksbane zurück.","","Für diese Aufgabe werdet Ihr eine kleine Armee benötigen, <Name>!"}}
D[8316] = {"Kriegsausrüstung"}
D[8317] = {"Küchengehilfe",{"Calandrath von der Burg Cenarius braucht 10 geräucherte Wüstenknödel."}}
D[8318] = {"Geheime Nachrichten",{"Bringt Bor Wildmane auf Burg Cenarius 10 verschlüsselte Texte der Twilight."}}
D[8319] = {"Verschlüsselte Texte der Twilight"}
D[8320] = {"Geolords der Twilight",{"Tötet 10 Geolords der Twilight und kehrt anschließend zu Huum Wildmane auf Burg Cenarius zurück."}}
D[8321] = {"Vyral der Üble",{"Bringt Vyrals Siegelring zu Huum Wildmane auf Burg Cenarius."}}
D[8322] = {"Faule Eier",{"Werft die faulen Eier in den großen Braukessel im Gasthaus von Southshore."}}
D[8323] = {"Wahrer Glauben",{"Ortell der Einsiedler möchte, dass Ihr ihm 10 verschlüsselte Texte der Twilight beschafft."}}
D[8324] = {"Fester Glauben"}
