D[8332] = {"Fürsten des Rates",{"Bringt Aurel Goldleaf auf Burg Cenarius 1 großen glänzenden Splitter und 3 abyssische Wappen."}}
D[8333] = {"Das Standesmedallion"}
D[8341] = {"Lords des Rates",{"Bringt Aurel Goldleaf auf Burg Cenarius 5 große glänzende Splitter und 3 abyssische Siegel."}}
D[8342] = {"Herrschaftsring der Twilight"}
D[8343] = {"Goldleafs Entdeckung",{"Sprecht mit Aurel Goldleaf auf Burg Cenarius."}}
D[8348] = {"Siegel der Fürsten",{"Bringt Bor Wildmane auf Burg Cenarius das abyssische Siegel."}}
D[8349] = {"Bor Wildmane",{"Sprecht mit Bor Wildmane auf Burg Cenarius."}}
D[8351] = {"Bor möchte Euch sprechen",{"Sprecht mit Bor Wildmane auf Burg Cenarius."}}
D[8352] = {"Szepter des Rates",{"Bringt Huum Wildmane auf Burg Cenarius ein abyssisches Szepter."}}
D[8353] = {"Hühnchengegacker für ein Pfefferminzbonbon",{"Spielt Gastwirt Firebrew ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Ironforge geben!"}}
D[8354] = {"Hühnchengegacker für ein Pfefferminzbonbon",{"Spielt Gastwirt Norman ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Undercity geben!"}}
D[8355] = {"Kaugummikugelexpress",{"Ahmt für Talvash del Kissel einen Zug nach und er wird Euch dafür eine Kaugummikugel aus Gnomeregan geben!"}}
D[8356] = {"Muskelspiel für Nugat",{"Ihr müsst vor Gastwirtin Allison angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Stormwind gibt!"}}
D[8357] = {"Tanzen für Marzipan",{"Tanzt für Gastwirtin Saelienne und Ihr werdet im Gegenzug etwas von dem Marzipan aus Darnassus bekommen!"}}
D[8358] = {"Kaugummikugelexpress",{"Ahmt für Kali Remik einen Zug nach und er wird Euch dafür eine Kaugummikugel der Darkspear geben!"}}
D[8359] = {"Muskelspiel für Nugat",{"Ihr müsst vor Gastwirtin Gryshka angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Stormwind gibt!"}}
D[8360] = {"Tanzen für Marzipan",{"Tanzt für Gastwirtin Pala und Ihr werdet im Gegenzug etwas von dem Marzipan aus Thunder Bluff bekommen!"}}
D[8361] = {"Abyssische Kontakte",{"Bor Wildmane auf Burg Cenarius in Silithus möchte, dass Ihr einen abyssischen Templer vernichtet und ihm dessen abyssisches Wappen als Beweis für Eure Tat bringt."}}
