D[8365] = {"Piratenhüte Ahoy!",{"Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin nach Steamwheedle in Tanaris."}}
D[8366] = {"Gaunerei und Erpressung im Südmeer",{"Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten."}}
D[8367] = {"Große Ehre",{"Bring je 3 Ehrenabzeichen des Alteractals, des Arathibeckens und der Warsongschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8368] = {"Schlacht der Warsongschlucht",{"Bringt 3 Ehrenabzeichen der Warsong zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
