D[8370] = {"Eroberung des Arathibeckens",{"Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8371] = {"Gemeinsames Bestreben",{"Bringt 3 Ehrenabzeichen des Alteractals, 3 Ehrenabzeichen des Arathibeckens und 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder."}}
D[8372] = {"Kampf um die Warsongschlucht",{"Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder."}}
D[8373] = {"Die Kraft der Pinie",{"Verwendet einen Stinkbombenreiniger, um alle Stinkbomben der Verlassenen zu vernichten, die hier in Southshore losgelassen wurden. Kehrt zu Sergeant Hartman in Southshore zurück, wenn Ihr fertig seid."}}
