D[8446] = {"Eingehüllt in Alpträume",{"Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann.","","Vielleicht kann Euch ein Druide von großer Macht weiterhelfen."}}
D[8447] = {"Legenden erwachen",{"Wartet, bis Bewahrer Remulos in Moonglade den von Alpträumen eingehüllten Gegenstand gereinigt hat."}}
D[8460] = {"Verbündeter der Holzschlundfeste",{"Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt."}}
D[8461] = {"Totenwaldfelle des Nordens",{"Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück."}}
D[8462] = {"Sprecht mit Nafien",{"Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache."}}
D[8464] = {"Aktivität der Winterfelle",{"Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich genau außerhalb des Eingangs zur Holzschlundfeste in Winterspring."}}
D[8465] = {"Sprecht mit Salfa",{"Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterspring. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht."}}
D[8466] = {"Federn für Grazle"}
D[8467] = {"Federn für Nafien"}
D[8469] = {"Perlen für Salfa"}
D[8470] = {"Ritualtotem der Totenwaldfelle",{"Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist."}}
D[8471] = {"Ritualtotem der Winterfelle",{"Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist."}}
D[8481] = {"Die Wurzel alles Bösen",{"Stellt die Fackel zur Dämonenbeschwörung im Eingang der Höhle des Oberhäuptlings der Winterfelle, im Lager der Winterfellfurbolgs auf. Besiegt den Dämon und erlangt die Essenz von Xandivious für Gorn Einauge in der Holzschlundfeste."}}
D[8484] = {"Das Bemühen um Frieden",{"Bringt das Friedensangebot der Holzschlundfeste zu König Magni Bronzebeard in Ironforge."}}
D[8485] = {"Das Bemühen um Frieden",{"Bringt das Friedensangebot der Holzschlundfeste zu Thrall in Orgrimmar."}}
D[8492] = {"Die Allianz braucht Kupferbarren!",{"Bringt 20 Kupferbarren zu Sergeant Stonebrow im Militärviertel in Ironforge."}}
D[8493] = {"Die Allianz braucht mehr Kupferbarren!",{"Bringt 20 Kupferbarren zu Sergeant Stonebrow beim Landeplatz in Dun Morogh."}}
D[8494] = {"Die Allianz braucht Eisenbarren!",{"Bringt 20 Eisenbarren zu Corporal Carnes im Militärviertel in Ironforge."}}
D[8495] = {"Die Allianz braucht mehr Eisenbarren!",{"Bringt 20 Eisenbarren zu Corporal Carnes beim Landeplatz in Dun Morogh."}}
D[8496] = {"Verbände für den Feldeinsatz",{"Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können."}}
D[8497] = {"Wüstenüberlebenspaket",{"Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können."}}
D[8498] = {"Schlachtordnungen der Twilight",{"Beschafft Euch die Schlachtordnungen der Twilight und bringt sie zu Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch den taktischen Einsatz X, um diese Aufgabe abschließen zu können."}}
D[8499] = {"Die Allianz braucht Thoriumbarren!",{"Bringt 20 Thoriumbarren zu Dame Twinbraid im Militärviertel in Ironforge."}}
D[8500] = {"Die Allianz braucht mehr Thoriumbarren!",{"Bringt 20 Thoriumbarren zu Dame Twinbraid beim Landeplatz in Dun Morogh."}}
D[8501] = {"Ziel: Stecher des Ashischwarms",{"Tötet 30 Stecher des Ashischwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XII, um diese Aufgabe abschließen zu können."}}
D[8502] = {"Ziel: Arbeiter des Ashischwarms",{"Tötet 30 Arbeiter des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz III, um diese Aufgabe abschließen zu können."}}
D[8503] = {"Die Allianz braucht Würgetang!",{"Bringt 20 Stück Würgetang zu dem Gefreiten Draxlegauge im Militärviertel in Ironforge."}}
D[8504] = {"Die Allianz braucht mehr Würgetang!",{"Bringt 20 Stück Würgetang zu dem Gefreiten Draxlegauge beim Landeplatz in Dun Morogh."}}
D[8505] = {"Die Allianz braucht lila Lotus!",{"Bringt 20 lila Lotus zu Meister Nightsong im Militärviertel in Ironforge."}}
D[8506] = {"Die Allianz braucht mehr lila Lotus!",{"Bringt 20 lila Lotus zu Meister Nightsong beim Landeplatz in Dun Morogh."}}
D[8507] = {"Felddienst",{"Erstattet am Posten der Ironforgebrigade beim Zoraschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie von Captain Blackanvil unterzeichnen und kehrt zu Windrufer Kaldon auf Burg Cenarius in Silithus zurück.","","Hinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Ironforgebrigade wird Euch für den PvP-Kampf markieren."}}
D[8508] = {"Felddienstpapiere"}
D[8509] = {"Die Allianz braucht Arthas' Tränen!",{"Bringt 20 Arthas' Tränen zu Sergeant Major Germaine im Militärviertel in Ironforge."}}
D[8510] = {"Die Allianz braucht mehr Arthas' Tränen!",{"Bringt 20 Arthas' Tränen zu Sergeant Major Germaine beim Landeplatz in Dun Morogh."}}
D[8511] = {"Die Allianz braucht leichtes Leder!",{"Bringt 10 Einheiten leichtes Leder zu Bonnie Stoneflayer im Militärviertel in Ironforge."}}
D[8512] = {"Die Allianz braucht mehr leichtes Leder!",{"Bringt 10 Einheiten leichtes Leder zu Bonnie Stoneflayer beim Landeplatz in Dun Morogh."}}
D[8513] = {"Die Allianz braucht mittleres Leder!",{"Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter im Militärviertel in Ironforge."}}
D[8514] = {"Die Allianz braucht mehr mittleres Leder!",{"Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter beim Landeplatz in Dun Morogh."}}
D[8515] = {"Die Allianz braucht dickes Leder!",{"Bringt 10 Einheiten dickes Leder zu Marta Finespindle im Militärviertel in Ironforge."}}
D[8516] = {"Die Allianz braucht mehr dickes Leder!",{"Bringt 10 Einheiten dickes Leder zu Marta Finespindle beim Landeplatz in Dun Morogh."}}
D[8517] = {"Die Allianz braucht Leinenverbände!",{"Bringt 20 Leinenverbände zu Schildwache Silversky im Militärviertel in Ironforge."}}
D[8518] = {"Die Allianz braucht mehr Leinenverbände!",{"Bringt 20 Leinenverbände zu Schildwache Silversky beim Landeplatz in Dun Morogh."}}
D[8519] = {"Eine Spielfigur auf dem Schachbrett der Ewigkeit",{"Lernt so viel Ihr könnt über die Vergangenheit, sprecht dann mit Anachronos in den Höhlen der Zeit in Tanaris."}}
D[8520] = {"Die Allianz braucht Seidenverbände!",{"Bringt 20 Seidenverbände zu Schwester Stonefield im Militärviertel in Ironforge."}}
