D[8660] = {"Fußlappen des Verdammnisrufers",{"Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Nacht, 5 Tonskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus."}}
D[8661] = {"Roben des Verdammnisrufers",{"Bringt die Hülle des alten Gottes, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Kristallskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus."}}
D[8662] = {"Reif des Verdammnisrufers",{"Bringt Vek'nilashs Reif, 2 Götzen des Todes, 5 Silberskarabäen und 5 Knochenskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus."}}
D[8663] = {"Beinkleider des Verdammnisrufers",{"Bringt die Haut des großen Sandwurms, 2 Götzen der Wiedergeburt, 5 Goldskarabäen und 5 Tonskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus."}}
D[8664] = {"Mantel des Verdammnisrufers",{"Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Weisen, 5 Bronzeskarabäen und 5 Knochenskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus."}}
D[8665] = {"Stiefel der Genesis",{"Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Silberskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus."}}
