D[8728] = {"Die gute und die schlechte Nachricht",{"Narain Soothfancy in Tanaris möchte, dass Ihr ihm 20 Arkanitbarren, 10 Elementiumerz, 10 Azerothianische Diamanten und 10 blaue Saphire bringt."}}
D[8729] = {"Der Zorn von Neptulon",{"Benutzt die Arkanitboje am wirbelnden Maelstrom in der Bucht der Stürme in Azshara."}}
D[8730] = {"Nefarius' Verderbnis",{"Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen."}}
D[8731] = {"Felddienst",{"Erstattet Krug Skullsplit am Posten der Orgrimmarlegion beim Regalschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie unterzeichnen und bringt sie dann zu Windrufer Kaldon auf Burg Cenarius.","","Hinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Orgrimmarlegion wird Euch für den PvP-Kampf markieren."}}
D[8732] = {"Felddienstpapiere"}
D[8733] = {"Eranikus, der Tyrann des Traums",{"Reist nach Teldrassil und sucht Malfurions Agenten irgendwo außerhalb der Stadtmauern von Darnassus auf."}}
D[8734] = {"Tyrande und Remulos",{"Reist nach Moonglade und sprecht mit Bewahrer Remulos."}}
D[8735] = {"Die Verderbnis des Alptraums",{"Reist zu den vier Portalen des smaragdgrünen Traums in Azeroth und sammelt dort jeweils ein Verderbnisfragment des Alptraums ein. Kehrt zu Bewahrer Remulos in Moonglade zurück, sobald Ihr diese Aufgabe erfüllt habt."}}
D[8736] = {"Der Alptraum offenbart sich",{"Verteidigt Nighthaven gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande."}}
D[8737] = {"Azurblauer Templer",{"Beschwört und vernichtet einen azurblauen Templer. Erstattet anschließend Bericht bei Bor Wildmane auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz I, um diese Aufgabe abschließen zu können."}}
D[8738] = {"Späherbericht des Regalschwarms",{"Setzt Euch mit dem cenarischen Späher Landion innerhalb des Regalschwarmbaus in Verbindung und bringt den Späherbericht des Regalschwarms zu Windruferin Proudhorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VII, um diese Aufgabe abschließen zu können."}}
D[8739] = {"Späherbericht des Ashischwarms",{"Setzt Euch mit der cenarischen Späherin Jalia innerhalb des Ashischwarmbaus in Verbindung und bringt den Späherbericht des Ashischwarms zu Windruferin Proudhorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VIII, um diese Aufgabe abschließen zu können."}}
D[8740] = {"Marodeure der Twilight",{"Tötet den Marodeur der Twilight Morna und 5 Marodeure der Twilight. Erstattet anschließend Bericht bei Windruferin Proudhorn. Ihr benötigt auch den taktischen Einsatz IX, um diese Aufgabe abschließen zu können."}}
D[8741] = {"Der Held kehrt zurück",{"Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit."}}
