D[8777] = {"Ziel: Einbuddler des Regalschwarms",{"Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können."}}
D[8778] = {"Die Ironforgebrigade braucht Sprengstoff!",{"Bringt Arkanist Nozzlespring nahe des Zoraschwarmbaus in Silithus 6 Öle des Feuerbrandes, 5 Einheiten Goblin-Raketentreibstoff und 10 Einheiten dichtes Sprengpulver. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können."}}
D[8779] = {"Magische Materialien",{"Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und einen gewaltigen Smaragd zu Geologin Larksbane auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können."}}
D[8780] = {"Rüstungssets für den Feldeinsatz",{"Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau in Silithus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können."}}
D[8781] = {"Waffen für den Feldeinsatz",{"Bringt 2 Mondstahlbreitschwerter zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können."}}
D[8782] = {"Uniformnachschub",{"Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können."}}
D[8783] = {"Besondere Materialien",{"Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können."}}
D[8784] = {"Geheimnisse der Qiraji",{"Bringt das uralte Qirajiartefakt zu den Drachen, die sich nahe des Tempeleingangs versteckt halten."}}
D[8785] = {"Die Orgrimmarlegion braucht Mojo!",{"Bringt Schattenpriesterin Shai nahe des Regalschwarmbaus in Silithus 6 Einheiten mächtiges Mojo, 6 Fläschchen großes Mojo und 8 Öle des Feuerbrandes. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können."}}
D[8786] = {"Waffen für den Feldeinsatz",{"Bring 3 massive Eisenäxte zu Merok Longstride im Lager der Orgrimmarlegion außerhalb des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können."}}
D[8787] = {"Rüstungssets für den Feldeinsatz",{"Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Merok Longstride nahe des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können."}}
D[8788] = {"Ein leicht geschütteltes Geschenk"}
D[8789] = {"Imperiale Qirajiwaffen",{"Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Einheiten Elementiumerz bringt."}}
D[8790] = {"Imperiale Qirajiinsignien",{"Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Einheiten Elementiumerz."}}
D[8791] = {"Der Untergang von Ossirian",{"Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus."}}
