D[8989] = {"Das rechte Stück von Lord Valthalaks Amulett",{"Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grayhoof zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."}}
D[8990] = {"Das rechte Stück von Lord Valthalaks Amulett",{"Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."}}
D[8991] = {"Das rechte Stück von Lord Valthalaks Amulett",{"Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."}}
D[8992] = {"Das rechte Stück von Lord Valthalaks Amulett",{"Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."}}
D[8993] = {"Geschenkübergabe"}
D[8994] = {"Letzte Vorbereitungen",{"Bringt Bodley im Blackrock 40 Blackrockarmschienen und ein Fläschchen mit oberster Macht."}}
D[8995] = {"Mea Culpa, Lord Valthalak",{"Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen."}}
D[8996] = {"Rückkehr zu Bodley",{"Bringt das Räuchergefäß der Beschwörung zurück zu Bodley im Blackrock."}}
D[8997] = {"Zurück zum Anfang",{"Sprecht mit Deliana am Hohen Sitz von Ironforge."}}
D[8998] = {"Zurück zum Anfang",{"Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar."}}
