D[9237] = {"Gletscherumhang",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 4 Runenstoffballen, 2 Essenzen des Wassers, 4 Einheiten Eisenweberseide und 200 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein."}}
D[9238] = {"Gletscherhandschutz",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 2 Runenstoffballen, 2 Essenzen des Wassers, 2 Einheiten Eisenweberseide und 200 Gold."}}
D[9239] = {"Gletscherhandschuhe",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 4 Runenstoffballen, 4 Essenzen des Wassers, 2 Einheiten Eisenweberseide und 200 Gold."}}
D[9240] = {"Gletscherweste",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 8 Runenstoffballen, 6 Essenzen des Wassers, 4 Einheiten Eisenweberseide und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein."}}
D[9241] = {"Polararmschienen",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 12 Einheiten verzaubertes Leder, 3 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold."}}
D[9242] = {"Polarhandschuhe",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 12 Einheiten verzaubertes Leder, 3 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold."}}
D[9243] = {"Polartunika",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 16 Einheiten verzaubertes Leder, 5 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein."}}
D[9244] = {"Eisschuppenarmschienen",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 4 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold."}}
D[9245] = {"Eisschuppenstulpen",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 5 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold."}}
D[9246] = {"Eisschuppenbrustplatte",{"Handwerker Wilhelm bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte 8 gefrorene Runen, 24 schwere Skorpidschuppen, 7 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein."}}
D[9247] = {"Der Ruf des Bewahrers",{"Bringt den Brief vom Bewahrer der Schriften zu ihm, in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9248] = {"Eine bescheidene Darbringung",{"Aurel Goldblatt auf Burg Cenarius in Silithus möchte, dass Ihr ihr 1 abyssisches Szepter bringt. Euer Ruf bei dem Zirkel des Cenarius muss außerdem wohlwollend sein."}}
D[9250] = {"Grundstab von Atiesh",{"Findet jemanden, der Euch dabei hilft, die letzten beiden Teile des Stabs zu finden und das Böse daraus zu vertreiben."}}
D[9251] = {"Atiesh, der korrumpierte Hohestab",{"Anachronos in den Höhlen der Zeit in Tanaris möchte den Stabkopf und -fuß von Atiesh."}}
D[9259] = {"Verrat am Blutsegel"}
D[9260] = {"Erforscht die Geißel von Stormwind",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren Stormwinds. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9261] = {"Erforscht die Geißel von Ironforge",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Ironforge. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9262] = {"Erforscht die Geißel von Darnassus",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Darnassus. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9263] = {"Erforscht die Geißel von Orgrimmar",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Orgrimmar. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9264] = {"Erforscht die Geißel von Thunder Bluff",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel außerhalb von Thunder Bluff. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
D[9265] = {"Erforscht die Geißel von Undercity",{"Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Undercity. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an."}}
