D[9319] = {"Licht im Dunkeln",{"Findet und berührt die Freudenfeuer innerhalb der Blackrockspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück."}}
D[9320] = {"Erheblicher Manatrank"}
D[9321] = {"Erheblicher Heiltrank"}
D[9322] = {"Glühende Feuer in Kalimdor",{"Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Un'Goro-Krater und Winterspring auf. Kehrt dann zum Flammenbewahrer zurück."}}
D[9323] = {"Glühende Feuer in den östlichen Königreichen",{"Reist zu den Lagern des Sonnenwendfests in den verwüsteten Landen, den östlichen Pestländern, dem Hinterland und der sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück."}}
D[9324] = {"Raubt die Flamme von Orgrimmar",{"Bringt die Flamme von Orgrimmar zu dem Meister der Lehren."}}
D[9325] = {"Raubt die Flamme von Thunder Bluff",{"Bringt die Flamme von Thunder Bluff zu dem Meister der Lehren."}}
