D[9362] = {"Kriegsherr Krellian",{"Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara."}}
D[9364] = {"Gespaltene Magie",{"Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück."}}
D[9365] = {"Der Lohn des Diebes"}
D[9367] = {"Das Fest des Feuers",{"Wärmt Euch an den Freudenfeuern in Stormwind, Ironforge und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte."}}
D[9368] = {"Das Fest des Feuers",{"Wärmt Euch an den Freudenfeuern in Orgrimmar, Thunder Bluff und Undercity. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte."}}
D[9386] = {"Licht im Dunkeln",{"Findet und berührt die Freudenfeuer innerhalb der Blackrockspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer."}}
D[9388] = {"Lodernde Flammen in Kalimdor",{"Sucht die Freudenfeuer in Ashenvale, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer."}}
D[9389] = {"Lodernde Flammen in den östlichen Königreichen",{"Sucht die Freudenfeuer im Vorgebirge von Hillsbrad, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer."}}
D[9415] = {"Meldung bei Marschall Bluewall",{"Sprecht mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus."}}
D[9416] = {"Meldung bei General Kirika",{"Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus."}}
D[9419] = {"Durchkämmen der Wüste",{"Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus."}}
D[9422] = {"Durchkämmen der Wüste",{"Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus."}}
D[9664] = {"Mehr Befestigungen",{"Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Whitebeard bei der Kapelle des hoffnungsvollen Lichts zurück."}}
D[9665] = {"Verstärkung der Verteidigung",{"Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des hoffnungsvollen Lichts zurück."}}
D[65593] = {"Herzen der Liebenden",{"Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten."}}
D[65597] = {"Die Bindung",{"Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Undercity zurück."}}
D[65601] = {"Liebe kann schmerzhaft sein",{"Sprecht mit Magar in Orgrimmar."}}
D[65602] = {"Alles aus Liebe",{"Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind."}}
D[65603] = {"Die Bindung",{"Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück."}}
D[65604] = {"Die Bindung",{"Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Bloodeye in Orgrimmar zurück."}}
D[65610] = {"Irgendwo anders",{"Untersucht den Fallenskysee in Ashenvale und erstattet Gan'rul Bloodeye in Orgrimmar Bericht."}}
