D[3123] = {"Probar la vasija",{"Viaja a las Tierras del Interior y localiza a los lechúcicos. Mata a 10 de ellos y utiliza la vasija de muisek para reducir y capturar a los lechúcicos caídos.","","Lleva 10 muiseks de lechúcico y la vasija de muisek al médico brujo Uzer'i a Feralas."}}
D[3124] = {"Hipogrifos muisek",{"ACaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos."}}
D[3125] = {"Dragones feéricos muisek",{"Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos."}}
D[3126] = {"Antárboles muisek",{"Mata a 3 Caminabosques deambulantes. Utiliza la vasija de muisek para reducir y capturar a los Antárboles caídos."}}
D[3127] = {"Gigantes de montaña muisek",{"Mata a 7 caminantes de la tierra o gigantes del risco. Utiliza la vasija de muisek para reducir y capturar a los gigantes de montaña caídos."}}
D[3128] = {"Materiales naturales",{"Lleva 2 troncos astillados, 6 minerales taraceados, 20 tendones elásticos y 40 fragmentos metálicos al médico brujo Uzer'i al Campamento Mojache."}}
D[3129] = {"Armas del espíritu",{"El médico brujo Uzer'i quiere que esperes mientras prepara las armas."}}
D[3130] = {"En contra de los Crestafuria",{"Preséntate ante Latronicus Lanzaluna, en el Bastión Plumaluna."}}
D[3141] = {"Loramus",{"Escucha la historia de Loramus Thalipedes."}}
D[3161] = {"Gahz'rilo",{"Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz'rilo."}}
D[3181] = {"El cuerno de la bestia",{"Lleva el cuerno enorme de Margol a la montaraz Guijarro.|n"}}
