D[3449] = {"Runas arcanas",{"Haz calcos de la Runa de Beth'Amara, la Runa de Jin'yael, la Runa de Markri y la Runa de Sael'hai. Luego ve a la isla frente a la península meridional de Azshara y avisa al piloto Xiggs Luzfusil para que recoja los calcos."}}
D[3450] = {"Un simple envío",{"Habla con Xiggs Luzfusil en Forjaz."}}
D[3451] = {"Una señal para el envío",{"Habla con Xiggs Luzfusil para que te dé una pistola de bengalas en Forjaz."}}
D[3452] = {"El soporte para la llama",{"Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento."}}
D[3453] = {"La Antorcha de Reprensión",{"Espera a que Kalaran Espada del Viento termine la Antorcha de Reprensión."}}
D[3454] = {"La Antorcha de Reprensión",{"Coge la Antorcha de Reprensión."}}
D[3461] = {"Vuelve con Tymor",{"Devuelve el juego de calco a Tymor, que está en Forjaz."}}
