D[3504] = {"Traición",{"Entrega la carta sellada a Ag'tor Puñosangre en Azshara."}}
D[3505] = {"Traición",{"Mata a 10 reivindicadores y 10 agrimensores elfos de sangre antes de buscar el campamento de Magus Rimtori. Una vez allí, busca algo que sea importante para ella, algo con lo que provocar un combate."}}
D[3506] = {"Traición",{"Destruye el cristal de enfoque arcano de Magus Rimtori y entonces mátala. Lleva su cabeza a Ag'tor Puñosangre a Azshara."}}
D[3507] = {"Traición",{"Habla con Belgrom Destrozaroca en Orgrimmar."}}
D[3508] = {"Romper el amuleto",{"Espera que Loramus acabe el hechizo de ilustración."}}
D[3509] = {"El nombre de la bestia",{"Habla con Lord Arkkoroc en Azshara. Empieza tu búsqueda en la orilla para encontrar el Templo de Arkkoran."}}
D[3510] = {"El nombre de la bestia",{"Mata a Hetaera y lleva la cabeza ensangrentada, la cabeza golpeada y la cabeza amoratada a Lord Arkkoroc."}}
D[3511] = {"El nombre de la bestia",{"Llévale el temple a Loramus Thalimedes.|n"}}
D[3512] = {"Como diría  Eranikus…",{"Viaja a la parte este de Cuna del Invierno y habla con Umbranse el Contacto Espiritual."}}
