D[3640] = {"La promesa del secreto",{"Si decides dedicarte a la ingeniería gnómica, haz clic con el botón derecho en el compromiso de secreto perpetuo y vuelve a hablar con el maestro manitas Sobrechispa en Forjaz."}}
D[3641] = {"Muestra tu trabajo",{"Lleva 6 tubos de mitril, 1 escopo y 2 objetivos de prueba al maestro manitas Sobrechispa a Forjaz."}}
D[3642] = {"La promesa del secreto",{"Si quieres convertirte en <un ingeniero/una ingeniera> gnomo, haz clic con el botón derecho del ratón en el compromiso de secreto perpetuo y vuelve a hablar con Oglethrope Obnoticus en la Bahía del Botín."}}
D[3643] = {"Muestra tu trabajo",{"Lleva 6 tubos de mitril, un escopo preciso y 2 muñecos-diana avanzados a Oglethorpe Obnoticus en la Bahía del Botín."}}
