D[3761] = {"Tierra de Un'Goro",{"Llévale 20 muestras de la tierra de Un'Goro a Ghede, que está en el Alto de los Ancestros de Cima del Trueno."}}
D[3762] = {"Ayuda al archidruida Tótem de Runa",{"Habla con el archidruida Hamuul Tótem de Runa en Cima del Trueno."}}
D[3763] = {"Ayuda al archidruida Corzocelada",{"Ve a Darnassus y habla con el archidruida Fandral Corzocelada."}}
D[3764] = {"La tierra de Un'Goro",{"Lleva 20 muestras de tierra de Un'Goro Soil a Jenal, que está en el Enclave Cenarion de Darnassus."}}
D[3765] = {"Lejana corrupción",{"Ve a ver a Gershala Susurro Nocturno en Auberdine."}}
D[3781] = {"Investigar la mañagrana",{"Lleva el vale para semillas del archidruida a Mathrengyl Garroso al Enclave Cenarion de Darnassus."}}
D[3782] = {"Investigar la mañagrana",{"Llévale este vale para semillas a Bashana Runatótem, que está en Cima del Trueno."}}
D[3783] = {"Yeti... ¿ya hemos llegado?",{"Reúne 10 pieles gruesas de yeti para Umi Risitas en Vista Eterna."}}
