D[3801] = {"El legado de los Hierro Negro",{"Habla con Franclorn Forjafina si te interesa obtener una llave de la ciudad."}}
D[3802] = {"El legado de los Hierro Negro",{"Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador.|n"}}
D[3803] = {"Mañagrana para Darnassus"}
D[3804] = {"Mañagrana para Cima del Trueno"}
D[3821] = {"Roca Machacamiedo",{"Adéntrate en Las Estepas Ardientes y averigua qué le ha ocurrido a Sha'ni Colminilludo."}}
D[3822] = {"Krom'Grul",{"Recupera la alianza de la nariz de Sha'ni de Krom'Grul y llévasela a Thal'trak en Kargath. Busca por las diferentes cuevas y minas de la Roca Machacamiedo."}}
D[3823] = {"El exterminio de los Ardentrañas",{"Mata a 15 ogros magos Pirontraña, 7 ogros Pirontraña y 7 ogros brutos Pirontraña y vuelve junto a Oralius cuando hayas acabado."}}
D[3824] = {"Gor'tesh, el Señor bruto",{"Encuentra a Gor'tesh, en el algún lugar al oeste de la Roca Machacamiedo. Mata a Gor'tesh y llévale entonces la cabeza cortada de Gor'tesh a Oralius en Las Estepas Ardientes."}}
D[3825] = {"Una cabeza ogro empalada = FIESTA",{"Coge la cabeza cortada de Gor'tesh y colócala en lo alto de la Roca Machacamiedo. Busca un montículo de tierra blanda para clavar la pica."}}
D[3841] = {"Un huérfano que busca un hogar",{"Ve a Las Mil Agujas y habla con Quentin."}}
D[3842] = {"Una corta incubación",{"Lleva 2 elixires de la entereza a Quentin a Las Mil Agujas."}}
D[3843] = {"Un nuevo miembro en la familia",{"Lleva tu huevo de duende dardo frágil a las Tierras del Interior y habla con Agnar Domabestias, pero date prisa: si tardas más de 1 hora en encontrarlo, la cría que hay en el huevo morirá."}}
D[3844] = {"Un secreto bien guardado",{"Busca alrededor del estanque alguna pista sobre a quién perteneció la balsa destrozada."}}
D[3845] = {"Un secreto bien guardado",{"Examina los objetos de la talega y devuélveselos a su propietario."}}
D[3861] = {"¡CLOQUEA!",{"Consigue comida para pollos y ve con el pollo que has conocido. Cuando lo encuentres, /dórale la píldora antes de darle la comida."}}
D[3881] = {"Expedición Salvación",{"Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro."}}
D[3882] = {"Choca esos huesos",{"Lleva 8 huesos de dinosaurio a Chispik Nilminer en el Cráter de Un'Goro."}}
D[3883] = {"Ecología alienígena",{"Utiliza el vial raspador para recoger una Muestra de pared de la colmena de uno de los criaderos Gorishi del Cráter de Un'Goro. Busca las cámaras con los huevos de larva colgantes.","","Lleva la Muestra de pared de la colmena a Hol'anyee Marshal en el Cráter de Un'Goro."}}
D[3884] = {"Diario de Williden",{"Devuelve el diario a Williden Marshal en algún lugar del Cráter de Un'Goro."}}
D[3901] = {"Sacudir esqueletos",{"Mata a 12 esqueletos armadóseos y cuando lo hayas hecho, vuelve a buscar al sacerdote de las Sombras Sarvis a Camposanto."}}
D[3902] = {"Hurgar en Camposanto",{"Busca 6 piezas de mercancías extraviadas por Camposanto y los alrededores y llévaselas al guardia de la muerte Saltain."}}
D[3903] = {"Milly Osworth",{"Habla con Milly Osworth."}}
D[3904] = {"La cosecha de Milly",{"Lleva 8 cajas de uva recogida a Milly Osworth a la Abadía de Villanorte."}}
D[3905] = {"Informe de la vendimia",{"Lleva el Informe de la vendimia al hermano Neals a la Abadía de Villanorte."}}
D[3906] = {"La discordia de las llamas",{"Ve a la cantera de la Montaña Roca Negra y ejecuta al gran maestro Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo."}}
D[3907] = {"La discordia de las llamas",{"Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón."}}
D[3908] = {"Un secreto bien guardado",{"Lleva la Espada de Linken a Donova Cubilnevado en Cuna del Invierno."}}
D[3909] = {"El Elixir de Videre",{"Busca a Gregan Vomitabrebaje en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno."}}
D[3912] = {"Encuentro en la tumba",{"Ve al cementerio a las afueras de Gadgetzan y utiliza el Elixir de Videre. Sigue las demás instrucciones de Donova para encontrar a Gaeriyan."}}
D[3913] = {"Una situación mortal",{"Resucita y busca la lápida de la que te habló Gaeriyan."}}
D[3914] = {"La Espada de Linken",{"Entrega la Espada superior a Linken en el Cráter de Un'Goro."}}
D[3921] = {"Wenikee Tuercasmil",{"Llévale el churumbele roto a Wenikee Tuercasmil."}}
D[3922] = {"Engranajes",{"Llévale 15 engranajes a Wenikee Tuercasmil en Los Baldíos."}}
D[3923] = {"Rilli Gapegajoso",{"Llévale el churumbele roto y maltrecho a Rilli Gapegajoso en Orgrimmar."}}
D[3924] = {"El manual de churumbele",{"Llévale el manual del churumbele a Rilli Gapegajoso en Orgrimmar."}}
D[3941] = {"La ayuda de una gnoma",{"Encuentra a J.D. Collie en la cueva del Refugio de Marshal."}}
D[3942] = {"Recuerdos de Linken",{"Encuentra a Eridan Vientoazul en el sur de Frondavil."}}
D[3961] = {"La aventura de Linken",{"Lleva el Tótem plateado de Aquementas a Linken, en el Refugio de Marshal."}}
D[3962] = {"Ir solo es peligroso",{"Viaja a Cresta del Penacho en Llamas, al sur del Refugio de Marshal.","","Busca a Correfuego y utiliza el Tótem para eliminar su aura protectora. Cuando le hayas derrotado, coge la Llama Dorada de la cueva."}}
D[3981] = {"Comandante Gor'shak",{"Encuentra al comandante Gor'shak en las Profundidades de Roca Negra.","","Recuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar."}}
D[3982] = {"¿Qué pasa?",{"Defiende a Gor'shak."}}
D[4001] = {"¿Qué pasa?",{"Habla con Kharan Martillo Poderoso y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar. Recuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana.|n"}}
D[4002] = {"Los Reinos del Este",{"Si aceptas la misión, habla con Thrall."}}
D[4003] = {"El rescate real",{"Mata al emperador Dagran Thaurissan para liberar a la princesa Barbabronce del hechizo."}}
D[4004] = {"¿Princesa salvada?",{"¡Vuelve junto a Thrall!"}}
D[4005] = {"Aquementas",{"Lleva el Libro de Aquor, las zarpas plateadas y el corazón de Troncoferro a Tanaris.","","Utiliza el Libro de Aquor para invocar Aquementas.","","Cuando tengas el tótem completo llévaselo a J.D. Collie en el Refugio de Marshal."}}
D[4021] = {"¡Contraataca!",{"Llévale una pieza del estandarte de Krom'zar a Regthar Portamorta, al oeste de El Cruce."}}
D[4022] = {"Un sabor a llamarada",{"Enséñale a Cyrus Therepentio la escama de Vuelo Negro que recibiste de Kalaran Espada del Viento.|n"}}
D[4023] = {"Un sabor a llamarada",{"Demuéstrale a Cyrus Therepentio lo que vales.","","Te da la impresión de que Cyrus ya sabe que no eres digno."}}
D[4024] = {"Un sabor a llamarada",{"Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar.","","Solo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia fiera.","","Llévale la esencia fiera recubierta a Cyrus Therepentio."}}
D[4041] = {"El Elixir de Videre"}
D[4061] = {"La revuelta de las máquinas",{"Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos de elemental agrietado para Hierofante Theodora Mulvadania.","","Recuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos."}}
D[4062] = {"La revuelta de las máquinas",{"Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus.","","Recuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este."}}
D[4063] = {"La revuelta de las máquinas",{"Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los gólems Furiatracadores y de los ensamblajes belisario que protegen a Argelmach. Lo sabes porque eres <un adivino/una adivina>."}}
D[4081] = {"MATAR INMEDIATAMENTE: enanos Hierro Negro",{"Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!","","El señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea."}}
D[4082] = {"MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango",{"Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!","","El señor de la guerra Dientegore quiere que mates a 10 médicos de Yunque Colérico, 10 soldados de Yunque Colérico y 10 oficiales de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea."}}
D[4083] = {"El cáliz espectral"}
D[4084] = {"Corazón de plata",{"Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil."}}
D[4101] = {"Limpiar Frondavil",{"Lleva 15 unidades de sangre ámbar a Arathandris Cielargente a Frondavil."}}
D[4102] = {"Limpiar Frondavil",{"Lleva 15 unidades de sangre ámbar a Maybess Brisafluvial a Frondavil."}}
