D[4821] = {"Un huevo extraño",{"Devuélvele el huevo extraño a Hagar Pezuña del Rayo, que está en el Poblado Viento Libre."}}
D[4822] = {"¡Quiero un heladooooo!",{"Consigue helado de fresa para tu pupilo. Parece que el favorito del muchacho es el helado de Tigule."}}
D[4841] = {"Apaciguar al centauro",{"Mata a 12 exploradores Galak, 10 retadores Galak y 6 cazavientos Galak, y después ve a ver de nuevo al vigiarrisco Cuerno Largo al Poblado Viento Libre."}}
