D[4862] = {"Bestia amaestrada",{"Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.","","Yo diría que se pueden encontrar estos huevos cerca de arañas."}}
D[4863] = {"Lechúcico salvaje iracundo",{"Encuentra el carro destrozado de Jaron Tallapiedras."}}
D[4864] = {"Lechúcico iracundo",{"Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico que robó el amuleto del que te habló Jaron.","","Lleva los Suministros de Jaron y el Amuleto de plumas azules a Jaron Tallapiedras en el refugio de Cuna del Invierno."}}
D[4865] = {"Venganza",{"Cuéntale a Motega Pirocabello lo que has descubierto."}}
D[4866] = {"La leche de la madre",{"En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti."}}
D[4867] = {"Urok Aullasino",{"Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh."}}
D[4881] = {"Complot de asesinato",{"Avisa a Kanati Nubegris, que está en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida."}}
D[4882] = {"Guardar un secreto",{"Lleva el Collar de plumas azules a Trull Fallarruina en el Puesto del Veneno."}}
D[4883] = {"Guardar un secreto",{"Lleva el Collar de plumas azules a Nara Bravacrín."}}
D[4901] = {"Guardianes del altar",{"Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Eralas Cieloámbar de Aldea Rut'theran."}}
D[4902] = {"Lechúcico de Elune",{"Habla con el archidruida Fandral Corzocelada de Darnassus."}}
D[4903] = {"La orden del Señor de la Guerra",{"Mata al alto señor Omokk, al maestro de guerra Voone y al señor supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión."}}
D[4904] = {"Al fin libre",{"Saca a Lakota Canzalvaje de Cumbre de la Nube Negra y después habla con Thalia Pielámbar, que está en el Poblado Viento Libre."}}
D[4906] = {"Más corrupción",{"Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho."}}
D[4907] = {"Tinkee Vaporino",{"Habla con Tinkee Vaporio."}}
D[4921] = {"Perdida en la batalla",{"Encuentra a la esposa de Mankrik y llévala a El Cruce."}}
D[4941] = {"La sabiduría de Eitrigg",{"Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.","","Recuerdas haber visto a Eitrigg en la Cámara de Thrall."}}
D[4961] = {"La purificación del orbe de Orahil",{"Mata al demonio del orbe y luego habla con Tabetha."}}
D[4962] = {"Fragmento de can manáfago",{"Coge el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago capturado a Menara Nadiz en Los Baldíos."}}
D[4963] = {"Fragmento de infernal",{"Coge la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal capturado a Menara Nadiz en Los Baldíos."}}
