D[4971] = {"Una cuestión de tiempo",{"Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales.","","Mata a 15 parásitos temporales y devuélvele el desplazador temporal a Chromie en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4972] = {"Contar el tiempo",{"Localiza 5 relojes de Andorhal, los encontrarás en cajas fuertes entre las ruinas de la ciudad. Cuando los tengas regresa con Chromie, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4973] = {"Contar el tiempo",{"Localiza 5 relojes de Andorhal entre las ruinas de la ciudad y llévaselos a Chromie, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4974] = {"¡Por la Horda!",{"Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar."}}
D[4975] = {"El orbe completo de Noh'Orahil",{"Espera a Menara Nadiz para completar el orbe de Noh'Orahil y vuelve entonces a hablar con ella."}}
D[4976] = {"Devolver el orbe purificado",{"Llévale el orbe infernal limpio a Menara Nadiz en Los Baldíos."}}
