D[5441] = {"Peones vagos",{"Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos."}}
D[5461] = {"El humano, Ras Levescarcha",{"Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Recuerdo de Evocación. Si lo encuentras llévaselo al magistrado Marduke."}}
D[5462] = {"El moribundo, Ras Levescarcha",{"Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Recuerdo de Evocación y cuéntale todo lo que has descubierto."}}
D[5463] = {"El Obsequio de Menethil",{"Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Recuerdo de Evocación en suelo no consagrado."}}
D[5464] = {"El Obsequio de Menethil",{"Lleva las Memorias del Vínculo del Alma a Leonid Barthalomew a las Tierras de la Peste del Este."}}
D[5465] = {"Memorias del Vínculo del Alma",{"Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale las Memorias del Vínculo del Alma."}}
D[5466] = {"El Lich, Ras Levescarcha",{"Busca a Ras Levescarcha en Scholomance. Cuando lo hayas encontrado utiliza las Memorias del Vínculo del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Levescarcha. Lleva la cabeza al magistrado Marduke."}}
D[5481] = {"La tarea de Gordo",{"Recoge 3 hierbas luminiscentes y entrégaselas al boticario de segunda Holland en el cementerio de Rémol."}}
D[5482] = {"Apocalíseas",{"Recoge 10 apocalíseas y entrégaselas al boticario de segunda Holland."}}
D[5501] = {"Colección de kodos",{"Lleva 10 huesos de kodo del Cementerio de Kodos a Bibbly F'utzbuckle a la Cabaña de Kormek."}}
D[5502] = {"Alcaide de la Horda",{"Lleva a tu pupilo de vuelta al orfanato de Orgrimmar entregándole el silbato de huérfano orco a la supervisora de huérfanos Llantobatalla en el Valle del Honor."}}
D[5503] = {"Comisión del Alba Argenta"}
D[5504] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5505] = {"La llave de Scholomance"}
D[5507] = {"Mantos del Alba",{"Lleva 10 muestras de valor del Alba Argenta al intendente Destello de Luz en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5508] = {"Piedras de la Plaga de un corruptor"}
D[5509] = {"Piedras de la Plaga de un invasor"}
D[5510] = {"Piedras de la Plaga de un esbirro"}
D[5511] = {"La llave de Scholomance"}
D[5513] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este."}}
D[5514] = {"Molde rima con... ¿oro?",{"Lleva los Fragmentos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan."}}
D[5515] = {"Bolsa de los horrores de Krastinov",{"Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff."}}
D[5517] = {"Manto del Alba cromático",{"Lleva 25 muestras de valor de El Alba Argenta al intendente Cerrobrecha a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este."}}
D[5518] = {"El traje de orgo Gordok",{"Lleva 4 madejas de paño rúnico, 8 retales de cuero basto, 2 hebras de hilo rúnico y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre."}}
D[5519] = {"El disfraz de ogro Gordok"}
D[5521] = {"Manto del Alba cromático",{"Lleva 25 muestras de valor de El Alba Argenta al intendente Chispillo en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5522] = {"Leonid Barthalomew",{"Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este."}}
D[5524] = {"Manto del Alba cromático",{"Lleva 25 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5525] = {"¡Libera a Knot!"}
D[5526] = {"Fragmentos de gangrevid",{"Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de pureza para guardar el fragmento y llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna."}}
D[5527] = {"Un relicario de pureza",{"Ve a Silithus a buscar un relicario de pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna."}}
D[5528] = {"La cata de los Gordok"}
D[5529] = {"Crías de dragón apestadas",{"Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz."}}
D[5531] = {"Betina Bigglezink",{"Lleva los huevos congelados a Betina Bigglezink, que está fuera."}}
D[5533] = {"Scholomance",{"Habla con el alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5534] = {"El equipamiento \"perdido\" de Kim'jael",{"Encuentra una runa que los nagas guardan en las Ruinas de Eldarath y llévasela a Kim'jael en Azshara."}}
D[5535] = {"Agitación espiritual",{"Destruye 6 apariciones de Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara."}}
D[5536] = {"Una tierra llena de odio",{"Mata 6 sátiros Haldarr, 2 timadores Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno."}}
D[5537] = {"Fragmentos esqueléticos",{"Lleva 15 fragmentos esqueléticos al alquimista Arbington, en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5538] = {"Molde rima con... ¿oro?",{"Lleva los Fragmentos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan."}}
D[5541] = {"Municiones para Estruendo",{"Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh."}}
D[5542] = {"Perros demoníacos",{"Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring."}}
D[5543] = {"Cielos sangrientos",{"Mata 30 murcípestes y vuelve con Tirion Fordring."}}
D[5544] = {"Gusanos carroñeros",{"Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero."}}
D[5545] = {"El cumplimiento del plazo",{"Lleva 8 fajos de madera a Raelen al Aserradero de la Vega del Este."}}
D[5561] = {"El rodeo kodo",{"Lleva 5 kodos domados y el kombobulador kodo a Smeed Mezclatornillos, al Campamento Mezclatornillos."}}
D[5581] = {"Los portales de la Legión",{"Destruye 6 Portales en el Aquelarre Mannoroc y vuelve a la Aldea Cazasombras a hablar con Taiga Melenasabia."}}
D[5582] = {"Escama sana de dragón",{"Lleva la escama sana de dragón a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[5601] = {"Pamela, mi hermana",{"Encuentra a Pamela Rutagrana en Villa Darrow."}}
D[5621] = {"Prendas de la luna",{"Encuentra a la centinela Shaya y cura sus heridas utilizando un hechizo de Curación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo a Laurna Luzdelalba a Dolanaar."}}
D[5622] = {"Los caminos de Elune",{"Habla con Laurna Luzdelalba en Teldrassil."}}
D[5623] = {"Al servicio de la Luz",{"Ve al Bosque de Elwynn y habla con la sacerdotisa Josetta."}}
D[5624] = {"Las prendas de la Luz",{"Encuentra al guardia Roberts y cura sus heridas usando Curación inferior (Rango 2). Después, concédele la Palabra de poder: Entereza y vuelve a Villadorada a hablar con la sacerdotisa Josetta."}}
D[5625] = {"Las prendas de la Luz",{"Encuentra al montaraz Dolf y cura sus heridas usando la Curación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Kharanos a hablar con Maxan Anvol."}}
