D[5713] = {"Un tiro. Un muerto.",{"Protege a la centinela Aynasha y luego ve a Vallefresno, a la Atalaya de Maestra, y habla con Onaeya."}}
D[5721] = {"La Batalla de Villa Darrow",{"Coloca el Fardo de reliquias en la plaza de Villa Darrow.","","Impide que Davil Fuegoluz muera antes que Horgus.","","Impide que el capitán Rutagrana muera hasta que aparezca Rutagrana el Corrompido.","","Derrota a Rutagrana el Corrompido.","","Habla con el espíritu de Joseph Rutagrana cuando aparezca en la plaza y luego habla con Pamela en su casa."}}
D[5722] = {"Buscando la cartera perdida",{"Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés."}}
D[5723] = {"Midiendo fuerzas con el enemigo",{"Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno."}}
D[5724] = {"La vuelta de la cartera perdida",{"Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno."}}
D[5725] = {"Poder destructivo",{"Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas."}}
D[5726] = {"Enemigos ocultos",{"Lleva una insignia de General a Thrall a Orgrimmar."}}
D[5727] = {"Enemigos ocultos",{"Lleva la insignia de General a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar."}}
D[5728] = {"Enemigos ocultos",{"Mata a Bazzalan y a Jergosh el Invocador y ve a ver a Thrall a Orgrimmar."}}
D[5729] = {"Enemigos ocultos",{"Habla con Neeru Hojafuego en Orgrimmar."}}
D[5730] = {"Enemigos ocultos",{"Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado."}}
D[5741] = {"El Cetro de la Luz",{"Consigue el Cetro de la Luz y llévaselo a Azore Aldamort a la torre de Ethel Rethor."}}
D[5742] = {"Redención",{"Escucha lo que Tirion Fordring tiene que contarte."}}
D[5761] = {"Matar a la bestia",{"Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar."}}
D[5762] = {"Hemet Decautela",{"Llévale la caja de Kravel a Hemet Decautela, que está en Tuercespina."}}
D[5763] = {"La caza en Tuercespina",{"Lleva el cuerno kodo de Roon a Hemet Decautela a Stranglethorn."}}
D[5781] = {"De recuerdos olvidados",{"Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring."}}
D[5801] = {"La forja del Penacho en Llamas",{"Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto incompleta.","","Llévale la llave esqueleto incompleta al alquimista Arbington al Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5802] = {"La forja del Penacho en Llamas",{"Lleva el molde para llave esqueleto y 2 barras de torio a la cima de la Cresta del Penacho en Llamas en el Cráter de Un'Goro. Utiliza el molde para llave esqueleto en el lago de lava para forjar la llave esqueleto sin terminar.","","Llévale la llave esqueleto sin terminar al boticario Dithers a El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5803] = {"El escarabajo de Araj",{"Destruye a Araj el Invocador y lleva el Escarabeo de Araj al alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5804] = {"El escarabeo de Araj",{"Destruye a Araj el Invocador y lleva el Escarabeo de Araj al boticario Dithers en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5805] = {"¡Bienvenido!",{"Lleva el vale regalo de Villanorte a Merissa Fontana."}}
D[5821] = {"El guardaespaldas",{"Escolta la caravana Gizelton a través del poblado de los centauros Kolkar. Habla con Smeed en el Campamento Mezclatornillos para recibir tu recompensa."}}
D[5841] = {"¡Bienvenido!",{"Lleva el vale regalo del Valle de Crestanevada a Yori Crackhelm."}}
D[5842] = {"¡Bienvenido!",{"Lleva el vale regalo de Cañada Umbría a Orenthil Susurravientos."}}
D[5843] = {"¡Te damos la bienvenida!",{"Lleva el vale regalo del Valle de los Retos a Magga."}}
D[5844] = {"¡Bienvenido!",{"Lleva el vale regalo del Campamento Narache a Vorn Visioceleste."}}
D[5845] = {"Del honor perdido",{"Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo del Honor Perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring."}}
D[5846] = {"De amor y familia",{"Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro."}}
D[5847] = {"¡Bienvenido!",{"Lleva el vale regalo de Camposanto a Claire Sauzal, de Camposanto."}}
D[5848] = {"Del amor y la familia",{"Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.","","Devuelve la pintura a Tirion Vadín."}}
D[5861] = {"Encuentra a Myranda",{"Viaja a la Tumba de Uther, en el sur de las Tierras de la Peste. Enseña a Myranda la Fada el Regalo de Tirion."}}
D[5862] = {"La Ilusión Escarlata",{"Habla con Myranda para conseguir la Ilusión Escarlata. Bajo el poder de la Ilusión Escarlata viaja a la Vega del Amparo y entrega el Regalo de Tirion al alto señor Taelan Vadín.","","La Vega del Amparo está al Norte, Taelan seguramente estará en el interior de la Fortaleza de Mardenholde."}}
D[5863] = {"El Territorio Machacaduna",{"Andi Lynn de Gadgetzan quiere que destruyas el Territorio Machacaduna y para conseguirlo tendrás que matar 10 toscos Machacadunas, 10 déspotas Machacadunas y a Gor'marok el Devastador."}}
D[5881] = {"La sustitución",{"Maggran quiere que le entregues una carta a Grish Largocamino en El Gran Elevador, en Los Baldíos."}}
D[5882] = {"Bálsamo por caza"}
D[5883] = {"Bálsamo por minería"}
D[5884] = {"Bálsamo por recolección"}
D[5885] = {"Bálsamo por desuello"}
D[5886] = {"Bálsamo por desencantamiento"}
D[5887] = {"Bálsamo por caza"}
D[5888] = {"Bálsamo por minería"}
D[5889] = {"Bálsamo por recolección"}
D[5890] = {"Bálsamo por desuello"}
D[5891] = {"Bálsamo por desencantamiento"}
D[5892] = {"Suministros de Ferrohondo",{"Lleva 10 cajas de suministros de Ferrohondo al intendente de la Alianza en Dun Baldar."}}
D[5893] = {"Suministros de Dentefrío",{"Lleva 10 cajas de suministros de Dentefrío al intendente de la Horda en el Bastión Lobo Gélido."}}
D[5901] = {"Una Peste en la Cruzada",{"Utiliza la Jarra de termitas vacía en los Montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Mickey Levine, que está en El Baluarte, en Claros de Tirisfal."}}
D[5902] = {"Una Peste en la Cruzada",{"Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste."}}
D[5903] = {"Una Peste en la Cruzada",{"Utiliza la Jarra de termitas vacía en los Montones de termitas de las Tierras de la Peste del Este. Cuando hayas reunido 100 termitas de las Tierras de la Peste, vuelve con Nathaniel Dumah al Campamento del Orvallo en las Tierras de la Peste del Oeste."}}
D[5904] = {"Una Peste en la Cruzada",{"Encuentra un lugar adecuado en el centro del Aserradero Crestanorte, en las Tierras de la Peste del Oeste, para colocar la barrica de termitas de las Tierras de la Peste."}}
D[5921] = {"Claro de la Luna",{"Utiliza el hechizo \"teletransportarse: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrite Rafagaestelar."}}
D[5922] = {"Claro de la Luna",{"Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrite Rafagaestelar."}}
D[5923] = {"Escucha la llamada",{"Ve a Darnassus, al Enclave Cenarion y habla con Mathrengyl Garroso."}}
D[5924] = {"Escucha la llamada",{"Habla con Mathrengyl Garroso en el Enclave Cenarion, en Darnassus."}}
D[5925] = {"Atendiendo a la llamada",{"Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus."}}
D[5926] = {"Escucha la llamada",{"Habla con Turak Runatótem en el Alto de los Ancestros de Cima del Trueno."}}
D[5927] = {"Escucha la llamada",{"Habla con Turak Tótem Rúnico en Alto de los Ancestros, en Cima del Trueno."}}
D[5928] = {"Escucha la llamada",{"Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno."}}
D[5929] = {"Espíritu del gran oso",{"Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrite Rafagaestelar a Amparo de la Noche."}}
D[5930] = {"Espíritu del gran oso",{"Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrite Rafagaestelar a Amparo de la Noche."}}
D[5931] = {"El regreso a Darnassus",{"Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion."}}
D[5932] = {"Vuelve a Cima del Trueno",{"Vuelve a Cima del Trueno para hablar con Turak Tótem Rúnico en Alto de los Ancestros."}}
D[5941] = {"Vuelve con Chromie",{"Lleva el montón de reliquias a Chromie a Andorhal."}}
D[5942] = {"Tesoros ocultos",{"Lleva la llave de Joseph al cofre de Joseph."}}
D[5943] = {"La caravana Gizelton",{"Escolta la caravana Gizelton a través del Aquelarre Mannoroc. Habla con Smeed en el Campamento de los Mezclatornillos para recibir tu recompensa."}}
D[5944] = {"En sueños",{"Escolta a Taelan Fordring fuera de la Vega del Amparo."}}
D[5961] = {"Campeón de la Reina alma en pena",{"Habla con Nathanos Clamañublo en las Tierras de la Peste del Este. Se dice que ahora vive en la Hacienda de Marris.|n"}}
D[5981] = {"Gigantes arrasadores",{"Rivern Ventogélido quiere que mates 4 gigantes Machacahielo y 4 presertores Machacahielo."}}
D[6001] = {"Cuerpo y corazón",{"Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee.","","Cuando hayas acabado, vuelve a Darnassus y habla con Mathrengyl Garroso."}}
D[6002] = {"Cuerpo y corazón",{"Aplica el polvo de luna Cenarion a la piedra de lechúcico lunar que se encuentra entre Mulgore y Los Baldíos para provocar a Garraluna. Hecho esto, has de enfrentarte a Garraluna para obtener la fuerza física y de corazón que posee.","","Habla con Turak Runatótem en Cima del Trueno cuando hayas acabado."}}
D[6004] = {"Negocios inconclusos",{"Mata a 2 médicos Escarlata, 2 cazadores Escarlata, 2 magos Escarlata y 2 caballeros Escarlata antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}}
D[6021] = {"Zaeldarr el Marginado",{"Mata al infiltrador Hameya. Utiliza su llave en el Túmulo que hay detrás de La Subgranja."}}
D[6022] = {"Matar con un propósito",{"Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y la mano de mortero para convertir la putrefacción viva en putrefacción coagulada."}}
D[6023] = {"Negocios inconclusos",{"Mata al cazador Radley y al hidalgo Durgen antes de regresar con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}}
D[6024] = {"La súplica de Hameya",{"Lleva la cabeza de Zaeldarr al custodio Alen a la Capilla de la Esperanza de la Luz."}}
D[6025] = {"Negocios inconclusos",{"Entra en la Vega del Amparo y busca un punto elevado desde el que puedas ver la ciudad y calcular las fuerzas de la Cruzada Escarlata. Cuando lo hayas hecho regresa con Kirsta Sombraprofunda en las Tierras de la Peste del Oeste."}}
D[6026] = {"Eso pide mucho",{"Smokey LaRue quiere que consigas 2 barras de torio, 1 vara dorada, 8 bombas de gran carga y 8 disparadores inestables.","","Tendrás que encontrar a un herrero y a un ingeniero para conseguir esos objetos."}}
D[6027] = {"El Libro de los Ancestros",{"Consigue el Libro de los Ancestros y llévaselo a Azore Aldamort a la torre de Ethel Rethor.|n"}}
D[6028] = {"El informe Vista Eterna",{"Entrega el informe de Vista Eterna a la oficial Argenta Purocorazón en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[6029] = {"El informe Vista Eterna",{"Entrega el informe de Vista Eterna al oficial Argenta Garush en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[6030] = {"El duque Nicolas Zverenhoff",{"Entrega el libro, \"Estudios sobre la Comunicación con los Espíritus\", al duque Nicolas Zverenhoff en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[6031] = {"Paño rúnico",{"Llévale 30 retales de paño rúnico a Meilosh, que está en el Bastión de los Fauces de Madera."}}
D[6032] = {"Tela sagrada",{"Llévale 2 retales de tela lunar a Meilosh, que está en el Bastión de los Fauces de Madera."}}
D[6041] = {"Cuando Smokey canta, me pongo violento",{"Viaja al Bosque de la Peste, al noroeste de la Esperanza de la Luz. Destruye 8 estructuras de la Plaga utilizando el compuesto especial de Smokey en la marca de detonación que hay en el interior de cada edificio. Smokey ha hecho marcar los zigurats y los degolladeros.","","Cuando plantes la bomba, sal del edificio y disfruta del espectáculo.","","Por cierto, el compuesto especial de Smokey es... bastante inestable."}}
D[6042] = {"Los pequeños problemas de la no-vida",{"Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamorinfecto cuando hayas acabado."}}
D[6061] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un zancudo de llanura adulto. Practica un poco y devuélvele la fusta a Yaw Trampa en el Poblado Pezuña de Sangre."}}
D[6062] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un jabalí salvaje jaspeado. Practica un poco y devuélvele la fusta a Thotar en Cerrotajo."}}
D[6063] = {"Domesticar la bestia",{"Utiliza la fusta de domador para domar a un rondador Tejemadera. Practica tus habilidades y después devuélvele la fusta de domador a Dazalar, que está en Dolanaar."}}
D[6064] = {"Domesticar la bestia",{"Usa la fusta de doma para domar a un jabalí del risco grande. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos."}}
D[6065] = {"El camino del cazador",{"Habla con Yaw Trampa en el Poblado Pezuña de Sangre."}}
D[6066] = {"El camino del cazador",{"Habla con Yaw Crinafilada en el Poblado Pezuña de Sangre."}}
D[6067] = {"El camino del cazador",{"Habla con Yaw Trampa en el Poblado Pezuña de Sangre."}}
D[6068] = {"El camino del cazador",{"Habla con Thotar en Cerrotajo."}}
D[6069] = {"El camino del cazador",{"Habla con Thotar en Cerrotajo."}}
D[6070] = {"El camino del cazador",{"Habla con Thotar en Cerrotajo."}}
D[6071] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar."}}
D[6072] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar, en Teldrassil."}}
D[6073] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar."}}
D[6074] = {"El camino del cazador",{"Ve a hablar con Grif Corazón Salvaje en Kharanos."}}
D[6075] = {"El camino del cazador",{"Ve a hablar con Grif Corazón Salvaje en Kharanos."}}
D[6076] = {"El camino del cazador",{"Ve a hablar con Grif Corazón Salvaje en Kharanos."}}
D[6081] = {"Entrenar a la bestia",{"Habla con Ormak Tirosiniestro en Orgrimmar."}}
D[6082] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un escórpido acorazado. Practica un poco y devuélvele la fusta de domador a Thotar en Cerrotajo."}}
D[6083] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un correspuma. Practica un poco y devuélvele la fusta de domador a Thotar en Cerrotajo."}}
D[6084] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un leopardo de las nieves. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos."}}
D[6085] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un oso zarpahelada. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos."}}
D[6086] = {"Entrenar a la bestia",{"Habla con Belia Tronagranito en Forjaz."}}
D[6087] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un acechador de pradera. Practica un poco y devuélvele la fusta a Yaw Trampa en el Poblado Pezuña de Sangre."}}
D[6088] = {"Domesticar la bestia",{"Usa la fusta de domador para domar un aguilón. Practica un poco y devuélvele la fusta a Yaw Trampa en el Poblado Pezuña de Sangre."}}
D[6089] = {"Entrenar a la bestia",{"Habla con Holt Astatrueno en el Alto de los Cazadores, en Cima del Trueno."}}
D[6101] = {"Domesticar la bestia",{"Utiliza la fusta de domador para domar a un acechador sable de la noche. Practica tus habilidades y después devuélvele la fusta de domador a Dazalar, que está en Dolanaar."}}
D[6102] = {"Domesticar la bestia",{"Utiliza la fusta de domador para domar a un estridador estrígido. Practica tus habilidades y después devuélvele la fusta de domador a Dazalar, que está en Dolanaar."}}
D[6103] = {"Domesticar la bestia",{"Habla con Jocaste en el Enclave Cenarion de Darnassus."}}
D[6121] = {"Nuevas lecciones",{"Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar."}}
D[6122] = {"La fuente del envenenamiento",{"Recoge agua de Salto de Fonroca a la entrada de la cueva.","","Entrégale la muestra llena de Salto de Fonroca a Alanndarian Arrullanoche; en Auberdine, en Costa Oscura."}}
D[6123] = {"Reunir los ingredientes del remedio",{"Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo."}}
D[6124] = {"Curar la dolencia",{"Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno."}}
D[6125] = {"Poder contra el veneno",{"Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion."}}
D[6126] = {"Nuevas lecciones",{"Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrite Rafagaestelar."}}
D[6127] = {"La fuente del envenenamiento",{"Recoge agua de Cima Calígine en el estanque de la cima.","","Luego llévasela a Tonga Tótem Rúnico a El Cruce, en Los Baldíos."}}
D[6128] = {"Reunir los ingredientes del remedio",{"Llévale 5 raíces de tierra y 5 cuernos de kodo a Tonga Runatótem en El Cruce para que pueda confeccionar un bálsamo curativo."}}
D[6129] = {"Curar la dolencia",{"Usa el bálsamo animal curativo sobre las 10 gacelas enfermas que se encuentran en la parte norte de Los Baldíos; así se curarán. Hemos recibido informes según los cuales se han avistado gacelas enfermas por la carretera que va de este a oeste en El Cruce."}}
D[6130] = {"Poder contra el veneno",{"Vuelve a Cima del Trueno para hablar con Turak Tótem Rúnico en Alto de los Ancestros."}}
D[6132] = {"¡Sácame de aquí!",{"Escolta a Melizza Zumbala y luego ve a Desolace, al Cementerio de Kodos y habla con Hornizz Zumbala."}}
D[6133] = {"La orden del Señor de exploradores",{"Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien.","","También tienes que matar a 8 exploradores, 8 zancaminos y 8 Leñantros."}}
D[6134] = {"La caza de ectoplamas",{"Lleva 8 ectoplasmas y la caja de imanes fantasmales a Hornizz Zumbala a Desolace."}}
D[6135] = {"Alatardecer, cómo te odio…",{"Encuentra a Alatardecer y mátalo. Recoge un parche de piel de Alatardecer de su cadáver y llévaselo a Nathanos Clamorinfecto.","","Se dice que Alatardecer vaga por el campo, al norte de la Hacienda de Marris."}}
D[6136] = {"El corpulento",{"Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamorinfecto cuando hayas cumplido la misión."}}
D[6141] = {"Hermano Antón",{"Habla con el hermano Antón en Desolace."}}
D[6142] = {"Almejas",{"Encuentra 10 piezas de carne de almeja blanda y llévaselas a Mai'Lahii a la Aldea Cazasombras."}}
D[6143] = {"Otros pescados para freír",{"Mata a 7 mirmidones Filozante, 7 nagas Filozante y 5 hechiceras Filozante y luego ve a Cazasombras, en Desolace, a hablar con Drulzegar."}}
D[6144] = {"La llamada del teniente",{"Ve a Entrañas y habla con Varimathras."}}
D[6145] = {"El mensajero carmesí",{"Vuelve a las Tierras de la Peste del Este y encuentra al mensajero carmesí. Mata al mensajero y recupera la Orden del Gran Cruzado.","","Lleva el documento a Nathanos Clamorinfecto y espera sus instrucciones."}}
D[6146] = {"La estratagema de Nathanos",{"Viaja a Mano de Tyr, al sureste de la Hacienda de Marris. Una vez allí, da un mordisco a la manzana podrida. Entrega la Orden del Gran Cruzado al Señor Cruzado Valdemar con la protección de la forma de La Cruzada Escarlata."}}
D[6147] = {"Regresa junto a Nathanos",{"Vuelve con Nathanos Clamañublo con la nueva información.|n"}}
D[6148] = {"El Oráculo Escarlata, Demetria",{"La Cruzada Escarlata se está moviendo. En algún lugar, a lo largo del camino que va de Mano de Tyr a Stratholme, encontrarás al Oráculo, Demetria, con su escolta. Da caza a Demetria y mátala. Vuelve junto a Nathanos Clamorinfecto si tienes éxito."}}
D[6161] = {"La búsqueda del tesoro de Masatormento",{"Encuentra la Rackmore's Silver Key. Encuentra la Rackmore's Golden Key. Encuentra y abre el cofre de Masatormento."}}
D[6162] = {"La última batalla de un esposo",{"Mata al Señor Supremo Ror y lleva su zarpa a Dreka'Sur al Puesto del Veneno de Frondavil."}}
D[6163] = {"Ramstein",{"Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos."}}
D[6164] = {"Libro de entradas de Augustus",{"Lleva el libro de entradas de Augustus a Augustus el Agraciado a Valle del Terror."}}
D[6181] = {"Mensajero a toda prisa",{"Lleva la Nota de Lewis a Thor, el maestro de grifos."}}
D[6182] = {"El primero y el último",{"Habla con Mathias Shaw en el Casco Antiguo, en Ventormenta. Vive en los Cuarteles."}}
D[6183] = {"Honrar a los muertos",{"Vuelve a hablar con Mathias Shaw si quieres aceptar esta misión."}}
D[6184] = {"Flint Sombramás",{"Vete al Campamento del Orvallo en las Tierras de la Peste del Oeste y reúnete con tu contacto, Flint Sombramás."}}
D[6185] = {"Las pestes del este",{"Explora las Tierras de la Peste del Este en busca de pistas sobre el \"Clamorinfecto\" y los agentes perdidos del IS:7. Si encuentras alguna insignia del IS:7 llévasela a Flint Sombramás en el Campamento del Orvallo."}}
D[6186] = {"El regreso de Clamorinfecto",{"Regresa a Ventormenta e informa al alto señor Bolvar Fordragon sobre el destino de Nathanos Marris."}}
D[6187] = {"Restaurar el orden",{"Reúne un ejército y viaja a las Tierras de la Peste del Este. Lanza un asalto contra Nathanos Clamorinfecto y cualquier miembro de la Horda que pueda intentar protegerle.","","Tienes que permanecer alerta, <nombre>. Los de la Horda defenderán al Señor de exploradores con su vida."}}
D[6261] = {"Dungar Tragolargo",{"Lleva el Cajón de Osric a Dungar Tragolargo, el maestro de grifos."}}
D[6281] = {"Prosigue hasta Ventormenta",{"Cómprale al maestro de grifos Thor un vuelo en grifo y lleva la Nota de Lewis a Osric Strang, en la tienda Inmunidad Limitada, en el Casco Antiguo de Ventormenta."}}
D[6282] = {"La ameneza de la arpías",{"Maggran Ligaterra en el Refugio Roca del Sol quiere que mates 7 arpías Furia Sangrienta, 7 emboscadores Furia Sangrienta, 7 cazadores Furia Sangrienta y 7 Plumapícaros Furia Sangrienta."}}
D[6283] = {"El linaje Furia Sangrienta",{"Maggran, en el Refugio Roca del Sol, quiere que mates a la Destripadora Furia Sangrienta y le lleves sus restos como prueba de tu hazaña."}}
D[6284] = {"Aracnofobia",{"Mata a Besseleth y lleva el colmillo de Besseleth a Maggran en el Refugio Roca del Sol."}}
D[6285] = {"Regresa con Lewis",{"Compra un vuelo en grifo hasta la Colina del Centinela al maestro de grifos Dungar Tragolargo y lleva el Cajón de Osric a Lewis de la Colina del Centinela."}}
D[6301] = {"El ciclo del renacimiento",{"Tammra Windfield, en el Refugio Roca dle Sol, quiere que le consigas 10 semillas de Gaia."}}
D[6321] = {"Suministros para El Sepulcro",{"Lleva el pedido de Podrig a Karos Razok."}}
D[6322] = {"Michael Garrett",{"Lleva la caja de Gordon a Michael Garrett."}}
D[6323] = {"Vuela a Entrañas",{"Compra un viaje en murciélago a Entrañas al maestro de murciélagos Karos Razok. Después lleva el pedido de Podrig a Gordon Wendham en Entrañas."}}
D[6324] = {"Vuelve con Podrig",{"Compra un viaje en murciélago a El Sepulcro al maestro de murciélagos Michael Garrett. Después lleva la caja de Gordon al guardia de la muerte Podrig en El Sepulcro."}}
D[6341] = {"La prodigalidad de Teldrassil",{"Lleva la colección de Nessa a Vesprystus."}}
D[6342] = {"Vuela a Auberdine",{"Consigue un hipogrifo del maestro de hipogrifos Vesprystus, viaja a Auberdine y lleva la colección de Nessa a Laird."}}
D[6343] = {"Vuelve con Nessa",{"Lleva la respuesta de Laird a Nessa Cantosombrío."}}
D[6344] = {"Nessa Cantosombrío",{"Habla con Nessa Cantosombrío."}}
D[6361] = {"Un fardo de pieles",{"Llévale el fajo de pieles al maestro de jinetes del viento Devrak en El Cruce."}}
D[6362] = {"Un viaje a Cima del Trueno",{"Cómprale un jinete del viento para Cima del Trueno al maestro de jinetes del viento Devrak y llévale entonces el fajo de pieles a Ahanu en Cima del Trueno."}}
D[6363] = {"Tal, maestro de jinetes del viento",{"Lleva los artículos de piel de Ahanu a Tal en Cima del Trueno."}}
D[6364] = {"Volver junto a Jahan",{"Cómprale un jinete del viento para El Cruce al maestro de jinetes del viento Tal y llévale entonces los artículos de piel de Ahanu a Jahan Alalcón."}}
D[6365] = {"Entrega de carne a Orgrimmar",{"Llévale la carne de Zargh a Devrak en El Cruce."}}
D[6381] = {"Nueva vida",{"Planta 10 semillas de Gaia en los Túmulos y lleva las semillas de Gaia encantadas restantes a Tammra en el Refugio Roca del Sol."}}
D[6382] = {"La Caza de Vallefresno",{"Habla con Senani Truenozón en el Puesto del Hachazo, Vallefresno."}}
D[6383] = {"La Caza de Vallefresno"}
D[6384] = {"Un viaje a Orgrimmar",{"Cómprale un jinete del viento al maestro de jinetes del viento Devrak y llévale entonces la carne de Zargh a Gryshka en Orgrimmar."}}
D[6385] = {"Doras, maestro de jinetes del viento",{"Llévale la carta de Gryshka a Doras en Orgrimmar."}}
D[6386] = {"El regreso a El Cruce",{"Cómprale un jinete del viento para El Cruce al maestro de jinetes del viento Doras y llévale entonces la carta de Gryshka a Zargh a en El Cruce."}}
D[6387] = {"Estudiantes de honor",{"Lleva la lista de Brock a Thorgrum Borrelson a Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Lleva los picos honorarios a Gryth Thurden en Forjaz."}}
D[6389] = {"Una Peste en la Cruzada",{"Libera las termitas de las Tierras de la Peste en la Serrería Crestanorte y luego vuelve con el barril de termitas a las Tierras de la Peste del Oeste y busca a Nathaniel Dumah en el Campamento del Orvallo."}}
D[6390] = {"Una Peste en la Cruzada",{"Libera las termitas de las Tierras de la Peste en el Aserradero Crestanorte y luego vuelve con la barrica de termitas de las Tierras de la Peste a Mickey Levine en El Baluarte en los Claros de Tirisfal."}}
D[6391] = {"Vuela a Forjaz",{"Contrata un vuelo en grifo a Forjaz con el maestro de grifos Thorgrum Borrelson para llevar la lista de Brock a Golnir Dedorroca."}}
D[6392] = {"Vuelve con Brock",{"Contrata un vuelo en grifo a Thelsamar con el maestro de grifos Gryth Thurden para llevar los picos honoríficos a Brock Buscapiedras."}}
D[6393] = {"Guerra elemental",{"Lleva 10 incendritas a Tsunaman en el Refugio Roca del Sol."}}
D[6394] = {"Pico de Thazz'ril",{"Lleva el pico de Thazz'ril al supervisor Thazz'ril."}}
D[6395] = {"El último deseo de Marla",{"Lleva los restos de Samuel Fipps a la tumba de Marla y luego vuelve con la novicia Elreth."}}
D[6401] = {"Kaya está viva",{"Da las buenas noticias a Tammra Campovento en el Refugio Roca del Sol."}}
D[6402] = {"Tienes un cita en Ventormenta",{"Viaja hasta Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al alguacil Windsor sobre tu llegada."}}
D[6403] = {"La gran farsa",{"Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!"}}
D[6421] = {"Barranco del Alud",{"Explora las profundidades de la cueva del Barranco del Alud y lleva 10 cristales de resonita Mor'rogal en el Refugio Roca del Sol para que los investigue."}}
D[6441] = {"Los cuernos de sátiro",{"Reúne 16 cuernos de sátiro para Pixie en el Puesto del Hachazo."}}
D[6442] = {"Naga en la Ensenada de Zoram",{"Llévale 20 cabezas de Colafuria a Marukai en La Ensenada de Zoram."}}
D[6461] = {"Chupasangres",{"Xen'zilla, en Malaka'Jin, necesita que mates 10 trepadores musgondo y 7 escupevenenos musgondo."}}
D[6462] = {"Los talismanes trols",{"Llévale 8 talismanes trols a Mitsuwa en la Avanzada de Zoram'gar."}}
D[6481] = {"El despertar del terráneo",{"Abre el barril de resonita con el cristal de resonita encantado y, a continuación, mata a Goggeroc. Vuelve a ver a Mor'rogal para contarle lo ocurrido y entregarle el cristal de resonita encantado."}}
D[6482] = {"Liberar a Ruul",{"Escolta a Ruul y después habla con Yama Pezuñablanca en el Puesto del Hachazo."}}
D[6501] = {"El Ojo del dragón",{"Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del dragón. La única información que tienes sobre dicho ser, es que existe."}}
D[6502] = {"Amuleto Pirodraco",{"Tienes que recuperar la sangre de dragón negro campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra."}}
D[6503] = {"Avanzada de Vallefresno",{"Mata a 9 avanzados de Vallefresno y vuelve junto a Kuray'bin en el Puesto del Hachazo."}}
D[6504] = {"Las páginas perdidas",{"Encuentra las 12 páginas que faltan del manual de instrucciones de la trituradora y vuelve a componer con ellas los 3 primeros capítulos. Devuélvele las páginas a Gurda Cicafuria cerca del Puesto del Hachazo."}}
D[6521] = {"Una alianza nefasta",{"Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas."}}
D[6522] = {"Una alianza nefasta",{"Lleva el pergamino a Varimathras, que está en Entrañas."}}
D[6523] = {"Proteje a Kaya",{"Escolta a Kaya Patatleta hasta el Campamento Aparaje y ve a ver a Makaba Patatleta cerca del límite sureste de Espolón."}}
D[6541] = {"Preséntate ante Kadrak",{"Preséntate ante Kadrak en la torre de vigilancia en los Baldíos del Norte."}}
D[6542] = {"Preséntate ante Kadrak",{"Abre el fajo de informes. Lleva los informes Grito de Guerra al explorador Grito de Guerra, al corredor Grito de Guerra y al escolta Grito de Guerra. Lleva los últimos informes que ellos te den a Kadrak en la torre de vigilancia norte en los Baldíos."}}
D[6543] = {"Los informes Grito de Guerra",{"Preséntate ante Kadrak en la torre de vigilancia en los Baldíos del Norte."}}
D[6544] = {"El asalto de Torek",{"Escolta a Torek en su ataque sobre la Avanzada Ala de Plata contra Duriel Fuegolunar e informa después a Ertog Colmillorrabioso en el Puesto del Hachazo."}}
D[6545] = {"Novedades del corredor Grito de Guerra"}
D[6546] = {"Novedades del escolta Grito de Guerra"}
D[6547] = {"Novedades del explorador Grito de Guerra"}
D[6548] = {"Venga mi aldea",{"Mata 8 rufianes Tótem Siniestro y 6 mercenarios Tótem Siniestro. A continuación, ve a ver a Makaba Patatleta cerca del límite sureste de Espolón."}}
D[6561] = {"La vileza de Brazanegra",{"Llévale la cabeza del Señor Crepuscular Kelris a Bashana Runatótem en Cima del Trueno."}}
D[6562] = {"Problemas en las profundidades",{"Habla con Je'neu Sancrea en Vallefresno."}}
D[6563] = {"La esencia de Aku'Mai",{"Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno."}}
D[6564] = {"Lealtad a los dioses antiguos",{"Llévale la nota humedecida a Je'neu Sancrea en Vallefresno."}}
D[6565] = {"Lealtad a los dioses antiguos",{"Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve junto a Je'neu Sancrea en Vallefresno."}}
D[6566] = {"Lo que trae el viento",{"Escucha a Thrall."}}
D[6567] = {"El Campeón de la Horda",{"Busca a Rexxar. El jefe de guerra te ha indicado dónde encontrarlo. Recorre los caminos de Desolace, entre la Sierra Espolón y Feralas."}}
D[6568] = {"El testamento de Rexxar",{"Entrega el testamento de Rexxar a Myranda la Fada. Está en las Tierras de la Peste del Oeste."}}
D[6569] = {"Ilusiones oculares",{"Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada."}}
D[6570] = {"Brasaliza",{"Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca El Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza.|n"}}
D[6571] = {"Suministros Grito de Guerra",{"Reúne los suministros Grito de Guerra: las hojas de sierra Grito de Guerra, cabo de troncos, aceite de los Grito de Guerra y el envío de hachas de los Grito de Guerra para Locke Okarr en el Puesto del Hachazo."}}
D[6581] = {"Las hojas de sierra Grito de Guerra"}
D[6582] = {"La prueba de las calaveras, Arúspice",{"Debes encontrar a Arúspice, el campeón draco del Vuelo Azul y matarlo. Separa su calavera de su cuerpo y llévasela a Brasaliza.","","Sabes que puedes encontrar a Arúspice en Cuna del Invierno."}}
D[6583] = {"La prueba de las calaveras, Somnus",{"Destruye al campeón draco del Vuelo Verde, Somnus. Lleva su calavera a Brasaliza."}}
D[6584] = {"La prueba de los cráneos, Chronalis",{"Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su cráneo a Brasaliza."}}
D[6585] = {"La prueba de las calaveras, Axtroz",{"Viaja a Grim Batol y encuentra a Axtroz, el campeón draco del Vuelo Rojo. Destrúyelo y hazte con su calavera. Llévasela a Brasaliza."}}
D[6601] = {"El ascenso",{"Diría que se acabaron las charadas. Ya sabes que el Amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rexxar y explicarle el apuro en el que te encuentras. Enséñale el amuleto pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora."}}
D[6602] = {"La sangre de dragón negro campeón",{"Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rexxar."}}
D[6603] = {"Problemas en Cuna del Invierno",{"Encuentra a Donova Cubilnevado cerca de las fuentes termales de Cuna del Invierno."}}
D[6604] = {"Lechúcico iracundo",{"Habla con Jaron Tallapiedras en Aldea Estrella Fugaz."}}
D[6605] = {"Algo extraño",{"Habla con Winna Hazzard en Frondavil."}}
D[6606] = {"Un poco de suerte",{"Habla con la médico bruja Mau'ari en Vista Eterna."}}
D[6607] = {"Nat Pagle, pescador del extremo",{"Nat Pagle quiere que pesques los siguientes peces:","","Mahi mahi juncobruma de la Playa Juncobruma del Pantano de las Penas.","","1 artillero Sar'theris de la Playa de Sar'theris de Desolace.","","1 Ahi de Feralas del Río Verdantis de Feralas.","","Latipinia azul de La Costa Salvaje de Vega de Tuercespina.","","Cuando los tengas todos, vuelve a buscar a Nat Pagle."}}
D[6608] = {"¡Qué bueno eres!",{"Parece que Lumak piensa que ya no puede enseñarte nada más sobre la pesca. Ve a buscar a su amigo, Nat Pagle, un humano pescador que vive en una isla al sur de Theramore (o eso parece que ha dicho)."}}
D[6609] = {"¡Me has dejado seco!",{"Ve a Kalimdor, a la ciudad costera de Theramore. Busca una isla hacia el sur. ¡Nat Pagle te espera!"}}
D[6610] = {"Sorpresa de almejates",{"Dirge Hojágil quiere que le consigas lo siguiente:","","12 huevos gigantes. Pueden ser huevos de los rocs que deambulan por Tanaris o de cualquier otro pájaro de grandes dimensiones.","","10 piezas de carne de almeja sabrosa. ¡Esta la podrás obtener de las almejas, por supuesto!","","20 piezas de queso suizo de Alterac. ¡Podrás encontrarlo en cualquier quesería!","","Consigue todo lo que Dirge necesita y llévaselo."}}
D[6611] = {"Ve a Gadgetzan",{"Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias."}}
D[6612] = {"Conozco a un tío…",{"Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias."}}
D[6621] = {"El rey de los Corrupto",{"Coloca el estandarte de Karang en el túmulo del tótem corrupto. No permitas que los furbolgs destruyan el estandarte. Derrota al jefe Murgut y lleva el tótem de Murgut a Karang Amakkar en Zoram'gar."}}
D[6622] = {"Orden de gravedad",{"Salva a pacientes asignando vendas identificativas para atender sus heridas por orden de gravedad. Debes salvar a 15 pacientes antes de que 6 mueran a consecuencia de sus heridas.","","¡Ten presente el orden de prioridad! Los soldados con heridas graves mueren antes que los soldados con heridas de gravedad media. Los soldados heridos leves son los que más tardan en morir y solo hay que salvarlos DESPUÉS de identificar y atender a los soldados con heridas graves y medias."}}
D[6623] = {"Dispensario de la Horda",{"Ve a Sentencia, en las Tierras Altas de Arathi, y habla con el doctor Gregory Victor sobre tu incorporación al Dispensario de la Horda.|n"}}
D[6624] = {"Atenciones médicas",{"Salva a los pacientes utilizando vendas identificativas para ocuparte de sus heridas. Debes salvar a 15 pacientes antes de que 6 de ellos mueran a causa de sus heridas.","","¡Recuerda el orden en el que debes atender a los pacientes! Los soldados heridos graves mueren antes, seguidos de los soldados malheridos. Los soldados heridos leves tardan más en morir y deben ser salvados DESPUÉS de haber salvado a los soldados heridos graves y a los soldados malheridos."}}
D[6625] = {"El Dispensario de la Alianza",{"Ve a Theramore, en el Marjal Revolcafango, y habla con el doctor Gustaf VanHowzen sobre incorporarte al Dispensario de la Alianza."}}
D[6626] = {"Un anfitrión del mal",{"Mata a 8 guardias de batalla y 8 tejespinas Rajacieno y 8 adeptos Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno."}}
D[6627] = {"Prueba de conocimiento",{"Responde la pregunta de Braug Espiritoscuro con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés <listo/lista>."}}
D[6628] = {"Prueba de conocimiento",{"Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés <listo/lista>."}}
D[6629] = {"Mata a Grundig Nube Negra",{"Mata a Grundig Nube Negra y 6 toscos Tótem Siniestro. A continuación, ve a ver a Makaba Patatleta cerca del límite sureste de Espolón."}}
D[6641] = {"Vorsha la Azotadora",{"Mantén a salvo a Muglash en su viaje hacia el blandón. Ayúdalo a apagar el blandón y entonces protégelo frente a los nagas.","","Si sales <airoso/airosa>, vuelve a la Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora."}}
D[6642] = {"El favor de la Hermandad, mineral de hierro negro"}
D[6643] = {"El favor de la Hermandad, núcleos ardientes"}
D[6644] = {"El favor de la Hermandad, núcleo de lava"}
D[6645] = {"El favor de la Hermandad, cuero del núcleo"}
D[6646] = {"El favor de la Hermandad, gota de sangre de la montaña"}
D[6661] = {"A por las ratas del tren subterráneo",{"Captura a 5 ratas del subterráneo usando la flauta cazarratas. Guía a las ratas hasta Monty. No te olvides de devolver la flauta cuando hayas acabado."}}
D[6662] = {"Mi hermano Nipsy",{"Lleva la caja de carne misteriosa a Niblis, que está en el Depósito del Tren Subterráneo de Ventormenta."}}
D[6681] = {"Mansión Ravenholdt",{"Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas.","","Tendrás que poner a prueba tu ingenio por el camino. Ándate con ojo."}}
D[6701] = {"Emblemas de la Hermandad"}
D[6721] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar."}}
D[6722] = {"El camino del cazador",{"Habla con Dazalar en Dolanaar."}}
D[6741] = {"¡Más botines!"}
D[6761] = {"La nueva frontera",{"Ve a Darnassus, al Enclave Cenarion y habla con Mathrengyl Garroso."}}
D[6762] = {"Rabine Saturna",{"Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Rabine Saturna. Claro de la Luna se encuentra entre Frondavil y Cuna del Invierno; para llegar, tienes que seguir el camino que sale del Bastión de los Fauces de Madera."}}
D[6781] = {"Más restos de armadura"}
D[6801] = {"Lokholar, el Señor del Hielo"}
D[6804] = {"Agua envenenada",{"Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales de vínculo y el aspecto de Neptulon al duque Hydraxis a Azshara."}}
D[6805] = {"Sirocosos y reptarenas",{"Mata a 15 agitadores sirocosos y 15 estruendores del desierto y vuelve a ver al duque Hydraxis a Azshara."}}
D[6821] = {"Ojo de brasadivino",{"Lleva el ojo del Piroguardián brasadivino al duque Hydraxis a Azshara."}}
D[6822] = {"El Núcleo de Magma",{"Mata a 1 Señor del Fuego, 1 gigante fundido, 1 canino del Núcleo y 1 marea de lava y ve a ver al duque Hydraxis a Azshara."}}
D[6823] = {"Agente de Hydraxis",{"Consigue una mención de honor de los Señores del Agua y habla con el duque Hydraxis en Azshara."}}
D[6824] = {"Las manos de los enemigos",{"Lleva las manos de Lucifron, Sulfuron, Gehennas y Shazzrah al duque Hydraxis a Azshara."}}
D[6825] = {"La llamada del aire: flota de Guse"}
D[6826] = {"La llamada del aire: flota de Jeztor"}
D[6827] = {"La llamada del aire: flota de Mulverick"}
D[6844] = {"Umber, el archivista",{"Lleva el objeto recubierto de silítido a Umber, el archivista del Círculo Cenarion, en la aldea de Amparo de la Noche, en el Claro de la Luna."}}
D[6845] = {"El descubrimiento de los secretos del pasado",{"Habla con el rabino Saturna en el poblado Amparo de la Noche, en Claro de la Luna."}}
D[6846] = {"¡Al ataque!"}
D[6847] = {"El ojo que todo lo ve del maestro Ryson",{"Recupera el Ojo que todo lo ve del maestro Ryson en las cuevas de los Hacha Invernal y devuélveselo.","","Pero ándate con cuidado, al parecer el Ojo que todo lo ve del maestro Ryson ¡está maldito!"}}
D[6848] = {"El ojo que todo lo ve del maestro Ryson",{"Recupera el Ojo que todo lo ve del maestro Ryson en las cuevas de los Hacha Invernal y devuélveselo.","","Pero ándate con cuidado, al parecer el Ojo que todo lo ve del maestro Ryson ¡está maldito!"}}
D[6861] = {"La unidad trituradora portátil de Zinfizzlex",{"El maestro ingeniero Zinfizzlex quiere que le lleves lo siguiente:","","*30 barras de torio.","","*50 barras de mitril.","","*75 barras de hierro.","","*1 sierra de vapor."}}
D[6862] = {"La unidad trituradora portátil de Zinfizzlex",{"El maestro ingeniero Zinfizzlex quiere que le lleves lo siguiente:","","*30 barras de torio.","","*50 barras de mitril.","","*75 barras de hierro.","","*1 sierra de vapor.|n"}}
D[6881] = {"Ivus, el Señor del Bosque"}
D[6901] = {"Lanzar el ataque"}
D[6921] = {"Entre ruinas",{"Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."}}
D[6922] = {"Barón Aquanis",{"Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno."}}
D[6941] = {"La llamada del aire: la flota de Vipore"}
D[6942] = {"La llamada del aire: la flota de Slidore"}
D[6943] = {"La llamada del aire: la flota de Ichman"}
D[6961] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar."}}
D[6962] = {"Golosinas para el Gran Padre Invierno",{"Lleva 5 galletas de jengibre y leche fría como el hielo al Gran Padre Invierno en Orgrimmar."}}
D[6963] = {"El robo de las golosinas del Festival de Invierno",{"Encuentra al investigador de los Pastos de Bosquehumeante que ha desaparecido en las regiones nevadas de las Montañas de Alterac."}}
D[6964] = {"El espíritu de esta fiesta",{"Habla con Sagorne Zanca Cresta en el Valle de la Sabiduría de Orgrimmar sobre el festín del Festival de Invierno."}}
D[6981] = {"El fragmento brillante",{"Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento brillante.","","Entrega el fragmento como se te indique."}}
D[6982] = {"Suministros de Dentefrío",{"Lleva 10 cajas de suministros de Dentefrío al intendente de la Alianza en Dun Baldar."}}
D[6983] = {"¡Qué ruin!",{"Encuentra los regalitos robados y devuélveselos a Kaymard Cobrellizco en Orgrimmar. Se cree que están en posesión de Grinch el Abominable, que se encuentra en algún lugar de las regiones nevadas de las Montañas de Alterac."}}
D[6984] = {"Un agradecimiento de Pastos de Bosquehumeante",{"Habla con el Gran Padre Invierno en Orgrimmar."}}
D[6985] = {"Suministros de Ferrohondo",{"Lleva 10 cajas de suministros de Ferrohondo al intendente de la Horda en el Bastión Lobo Gélido."}}
D[7001] = {"Establos vacíos",{"Encuentra a un Lobo Gélido en el Valle de Alterac. Usa el collar Lobo Gélido cuando estés junto a él para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos de los Lobo Gélido. Habla con el maestro de establos para ganarte el crédito por la captura."}}
D[7002] = {"Arneses para carneros de montar"}
D[7003] = {"Gigantes reducidos",{"Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 15 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Ventipnotizador, al embarcadero de La Costa Olvidada de Feralas."}}
D[7021] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar."}}
D[7022] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno. Está cerca de la zona de comercio de los Pastos de Bosquehumeante, en Forjaz."}}
D[7023] = {"¡Papá Invierno está aquí!",{"Habla con Papá Invierno. Está cerca de la zona de comercio de los Pastos de Bosquehumeante, en Forjaz."}}
D[7024] = {"¡El Gran Padre Invierno está aquí!",{"Habla con el Gran Padre Invierno. Lo encontrarás cerca de la zona de comercio de los Pastos de Bosquehumeante, en Orgrimmar."}}
D[7025] = {"Golosinas para el Gran Padre Invierno",{"Lleva 5 galletas de jengibre y leche fría como el hielo al Gran Padre Invierno a Forjaz."}}
D[7026] = {"Arneses para carneros de montar"}
D[7027] = {"Establos vacíos",{"Encuentra un carnero de Alterac en el Valle de Alterac. Usa la collera de entrenamiento Pico Tormenta cuando estés junto al carnero de Alterac para domarlo. Cuando lo consigas, te seguirá hasta el maestro de establos. Habla con el maestro de establos para ganarte el crédito por la captura.|n"}}
D[7028] = {"Los males de Maraudón",{"Recoge 25 tallas de cristal terádrico y llévaselas a Willow a Desolace."}}
D[7029] = {"La corrupción de Lenguavil",{"Llena el vial cerúleo cubierto en el estanque naranja de Maraudon.","","Aplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico.","","Cura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras."}}
D[7041] = {"La corrupción de Lenguavil",{"Llena el vial revestido en el estanque naranja de Maraudon.","","Aplica el líquido a la hiedra tallovil para que emerja el vástago tóxico.","","Cura 8 plantas eliminando su vástago tóxico e informa a Talendria en Punta de Nijel."}}
D[7042] = {"El robo de las golosinas del Festival de Invierno",{"Encuentra al investigador de los Pastos de Bosquehumeante que ha desaparecido en las regiones nevadas de las Montañas de Alterac."}}
D[7043] = {"¡Qué ruin!",{"Recupera los dulces robados y libera a Metzen el Reno después de derrotar a Grinch el Abominable, que se esconde cerca de la Caverna Estrecha en las Laderas de Trabalomas."}}
D[7044] = {"Leyendas de Maraudón",{"Recupera las 2 partes del Cetro de Celebras: la vara y el diamante Celebrian.","","Encuentra el modo de hablar con Celebras."}}
D[7045] = {"Un agradecimiento de Pastos de Bosquehumeante",{"Habla con el Gran Padre Invierno en Forjaz."}}
D[7046] = {"El cetro de Celebras",{"Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras.","","Habla con él después del ritual."}}
D[7061] = {"El festín del Festival de Invierno",{"Lee el libro \"El festín del Festival de Invierno\" si quieres saber más sobre esta fiesta. Cuando termines, entrégaselo a Baine Pezuña de Sangre en Cima del Trueno."}}
D[7062] = {"El espíritu de esta fiesta",{"Habla con el historiador Karnik del Festival de Invierno en la Liga de Exploradores de Forjaz."}}
D[7063] = {"El festín del Festival de Invierno",{"Lee el libro \"El festín del Festival de Invierno\" si quieres saber más sobre esta fiesta. Cuando termines, entrégaselo al rey Magni Barbabronce de Forjaz."}}
D[7064] = {"Corrupción de la tierra y de la semilla",{"Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace."}}
D[7065] = {"Corrupción de la tierra y de la semilla",{"Mata a la princesa Theradras y ve a ver al guardián Marandis a Punta de Nijel, en Desolace."}}
D[7066] = {"La semilla de la vida",{"Busca a Remulos en Claro de la Luna y dale la semilla de la vida."}}
D[7067] = {"Las instrucciones del Paria",{"Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace."}}
D[7068] = {"Fragmentos Oscuros",{"Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar."}}
D[7070] = {"Fragmentos Oscuros",{"Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango."}}
D[7081] = {"Los cementerios del Valle de Alterac",{"Asalta un cementerio y vuelve con el sargento Durgen Pico Tormenta en las Montañas de Alterac."}}
D[7082] = {"Los cementerios de Alterac",{"Asalta un cementerio y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac."}}
D[7101] = {"Las torres y los búnkeres",{"Captura una torre enemiga y vuelve con el cabo Teeka Gruñido Sangriento en las Montañas de Alterac."}}
D[7102] = {"Las torres y los búnkeres",{"Destruye el estandarte de una torre enemiga o de un búnker y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac."}}
D[7121] = {"El intendente",{"Habla con el intendente de Pico Tormenta."}}
D[7122] = {"Conquistar una mina",{"Captura una mina que no esté bajo control de los Pico Tormenta y vuelve junto al sargento Durgen Pico Tormenta en las Montañas de Alterac."}}
D[7123] = {"Habla con nuestro intendente",{"Habla con el intendente de Lobo Gélido."}}
D[7124] = {"Conquistar una mina",{"Captura una mina y vuelve con el cabo Teeka Gruñidosangriento en las Montañas de Alterac."}}
D[7141] = {"La batalla de Alterac",{"Adéntrate en el Valle de Alterac, derrota al general Drek'thar de la Horda y vuelve junto a la prospectora Tallapiedra en las Montañas de Alterac."}}
D[7142] = {"La batalla por Alterac",{"Adéntrate en el Valle de Alterac y derrota al general enano Vanndar Pico Tormenta. Vuelve entonces junto a Voggah Agarre Letal en las Montañas de Alterac."}}
D[7161] = {"Terreno de pruebas",{"Viaja hasta la cueva Zarpa Salvaje ubicada al sureste del campamento base en el Valle de Alterac y encuentra el estandarte de los Lobo Gélido. Devuélvele el estandarte al maestro de guerra Laggrond."}}
D[7162] = {"Terreno de pruebas",{"Viaja hasta la cueva Ala Gélida ubicada al suroeste de Dun Baldar en el Valle de Alterac y recupera el estandarte de Pico Tormenta. Devuélveselo al teniente Haggerdin en las Montañas de Alterac."}}
D[7163] = {"Ascender y darse a conocer"}
D[7164] = {"Honorable con el clan"}
D[7165] = {"Ganarse una reverencia"}
D[7166] = {"Héroes legendarios"}
D[7167] = {"El ojo del orden"}
D[7168] = {"Ascender y darse a conocer"}
D[7169] = {"Honorable con la guardia"}
D[7170] = {"Ganarse una reverencia"}
D[7171] = {"Héroes legendarios"}
D[7172] = {"El ojo del orden"}
D[7181] = {"La leyenda de Korrak",{"Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac.","","Si Korrak se digna aparecer, destrúyelo y vuelve con el maestro de guerra Laggrond."}}
D[7201] = {"El último elemento",{"Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los golems y a los creadores de golems. Recuerdas que Vivian Latumba también murmuró entre dientes algo sobre los elementales."}}
D[7202] = {"Korrak el Sanguinario",{"Según cuenta la leyenda, el jefe de los poderosos trols Hacha Invernal parece dispuesto a sembrar el caos entre los habitantes del Valle de Alterac.","","Si Korrak se digna aparecer, destrúyelo y vuelve con el teniente Haggerdin en las Montañas de Alterac."}}
D[7221] = {"Habla con la prospectora Tallapiedra",{"Habla con la prospectora Tallapiedra en la plaza fuerte de Dun Baldar."}}
D[7222] = {"Habla con Voggah Agarre Letal",{"Habla con Voggah en el Bastión Lobo Gélido."}}
D[7223] = {"Los restos de armadura",{"Llévale 20 piezas de restos de armadura a Murgot Forjahonda en Dun Baldar."}}
D[7224] = {"Botín enemigo",{"Llévale 20 piezas de restos de armadura al herrero Regzar en Aldea Lobo Gélido."}}
D[7241] = {"En defensa de Lobo Gélido",{"Dirígete al Valle de Alterac en las Montañas de Alterac. Encuentra al maestro de guerra Laggrond y habla con él para empezar tu carrera como soldado Lobo Gélido; lo encontrarás en la entrada del túnel. El Valle de Alterac se sitúa al norte de Molino Tarren en la falda de las Montañas de Alterac."}}
D[7261] = {"El imperativo soberano",{"Dirígete al Valle de Alterac en las Laderas de Trabalomas. Delante de la entrada del túnel, encuentra al teniente Haggerdin y habla con él.","","¡Por la gloria de Barbabronce!"}}
D[7281] = {"Amor fraternal",{"Viaja hasta el territorio de los Pico Tormenta y mata al comandante Karl Filis. Vuelve con el comandante Luis Philips cuando hayas completado la tarea.|n"}}
D[7282] = {"Amor fraternal",{"Viaja hasta el territorio de los Lobo Gélido y mata al comandante Luis Philips Vuelve con el comandante Karl Filis cuando hayas completado la tarea.|n"}}
D[7301] = {"Señores del Cielo caídos",{"Viaja hasta el territorio de los Lobo Gélido y busca al comandante del aire Slidore, al comandante del aire Vipore y al comandante del aire Ichman. Vuelve con el comandante Duffy cuando hayas completado la misión."}}
D[7302] = {"Señores del Cielo caídos",{"Averigua qué fue del comandante del aire Guse, el comandante del aire Jeztor y el comandante del aire Mulverick. Vuelve con el comandante Mulfort cuando hayas completado la misión."}}
D[7321] = {"Sopa de tortuga reconfortante",{"Llévale 10 piezas de carne de tortuga y algunas especias calmantes al Christoph Jeffcoat en Molino Tarren."}}
D[7341] = {"Un trato justo"}
D[7342] = {"Las flechas no valen para nada"}
D[7361] = {"Favor entre los Lanza Negra",{"Se te asignado la tarea de matar a los jugadores elfos de la noche en el Valle de Alterac.","","Mata a un elfo de la noche y llévale su cabeza decapitada a Najak Malditor en el Bastión Lobo Gélido."}}
D[7362] = {"Aliado de los Tauren",{"Se te asignado la tarea de matar a los jugadores gnomos en el Valle de Alterac.","","Mata a un gnomo y llévale un mechón de la víctima a Ravak Tótem Siniestro en el Bastión Lobo Gélido."}}
D[7363] = {"La condición humana",{"Se te asignado la tarea de matar a los jugadores humanos en el Valle de Alterac.","","Mata a un humano y vuelve con el comandante Luis Philips (que deambula entre el frente y el Bastión Lobo Gélido) con un hueso de tu víctima.","","¡Al fin se avecina una cura para la condición humana!"}}
D[7364] = {"La recompensa de Gnomeregan",{"Se te asignado la tarea de matar a los jugadores adversarios tauren en el Valle de Alterac.","","Mata a un tauren y vuelve con Dirk Estafa a Dun'Baldar con una pezuña tauren."}}
D[7365] = {"Réquiem de Corzocelada",{"Se te asignado la tarea de matar a los jugadores trol en el Valle de Alterac.","","Mata a un trol y vuelve con Athramanis en Dun'Baldar con el mojo de un trol Lanza Negra."}}
D[7366] = {"La misericordia del arzobispo",{"Se te asignado la tarea de matar a los jugadores renegados en el Valle de Alterac.","","Mata a un renegado y vuelve con el comandante Karl Filis (que deambula entre la Serrería y la Mina) con el corazón de tu víctima."}}
D[7367] = {"Acabar con la amenaza",{"Encuentra al experto en explosivos de los Lobo Gélido y mátalo. Vuelve con el experto en explosivos de los Pico Tormenta cuando hayas acabado este trabajo."}}
D[7368] = {"Acabar con la amenaza",{"Encuentra al experto en explosivos de los Pico Tormenta y mátalo. Vuelve con el experto en explosivos de los Lobo Gélido cuando hayas acabado este trabajo."}}
D[7381] = {"El regreso de Korrak",{"Si Korrak el Sanguinario vuelve por la Tierra de Disputa, encuéntralo y acaba con él.","","Llévale la calavera de Korrak al maestro de guerra Laggrond en las Laderas de Trabalomas."}}
D[7382] = {"Korrak el Eterno",{"Si Korrak el Sanguinario vuelve por la Tierra de Disputa, encuéntralo y acaba con él.","","Llévale la calavera de Korrak al teniente Haggerdin en las Laderas de Trabalomas.|n"}}
D[7383] = {"La corona de la Tierra",{"Llena la ampolla de amatista y devuélvesela a Corithras Furia Lunar, que está en Dolanaar."}}
D[7385] = {"Un galón de sangre"}
D[7386] = {"Recogida de cristal"}
D[7401] = {"SE BUSCA: ¡enanos!",{"Se te asignado la tarea de matar a los jugadores enanos en el Valle de Alterac.","","Mata a un enano y sácale la espina dorsal. Llévasela al sargento Yazra Gruñido Sangriento en el Bastión Lobo Gélido."}}
D[7402] = {"Se buscan: ¡ORCOS!",{"Se te asignado la tarea de matar a los jugadores orcos en el Valle de Alterac.","","Mata a un orco y llévale un colmillo de la víctima al cabo Noreg Pico Tormenta en Dun Baldar."}}
D[7421] = {"Defensa de los Lanza Negra"}
D[7422] = {"Ve a por más mechones"}
D[7423] = {"Más esquirlas de huesos"}
D[7424] = {"¿Y la pezuña?"}
D[7425] = {"Colecta de mojo de Corzocelada"}
D[7426] = {"El amor de un hombre"}
D[7427] = {"Se buscan: ¡MÁS ENANOS!"}
D[7428] = {"Se buscan: ¡MÁS ORCOS!"}
D[7429] = {"¡Libera a Knot!"}
D[7441] = {"Pusillín y el ancestro Azj'Tordin",{"Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de conjuros de Azj'Tordin, por cualquier medio.","","Si consigues hacerte con el libro de conjuros, vuelve al Pabellón Lariss de Feralas y busca a Azj'Tordin."}}
D[7461] = {"Locura interior",{"Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará.","","Entra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum.","","Si consigues completar esta misión, ve al patio a buscar a la ancestro Shen'dralar."}}
D[7462] = {"El tesoro de los Shen'dralar",{"Regresa a El Athenaeum y encuentra el tesoro de Shen'dralar. ¡Reclama tu recompensa!"}}
D[7463] = {"El refresco arcano",{"Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum."}}
D[7481] = {"Leyendas élficas",{"Busca a Telmius Buscasueños en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres."}}
D[7482] = {"Leyendas élficas",{"Busca a Telmius Buscasueños en La Masacre. Vuelve al Bastión Plumaluna a informar a la erudita Runaespina de lo que hayas encontrado."}}
D[7483] = {"El Tratado de Prontitud",{"Lleva 1 Tratado de Prontitud, 1 diamante negro prístino, 2 grandes fragmentos brillantes y 2 unidades de sangre de héroes al guardián del Conocimiento Lydros a La Masacre para conseguir un arcano de prontitud."}}
D[7484] = {"El Tratado de Concentración",{"Lleva 1 Tratado de Concentración, 1 diamante negro prístino, 4 grandes fragmentos brillantes y 2 pieles de sombra al guardián del Conocimiento Lydros a La Masacre para conseguir un arcano de concentración."}}
D[7485] = {"El tratado sobre protección",{"Lleva 1 tratado sobre protección, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 1 costura desgarrada de abominación al Tradicionalista Lydros a La Masacre para conseguir un arcanum de protección."}}
D[7486] = {"Una recompensa de héroe",{"Recoge tu recompensa en el arca de Hydraxis."}}
D[7488] = {"La Membrana de Lethtendris",{"Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas."}}
D[7489] = {"La Membrana de Lethtendris",{"Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas."}}
D[7490] = {"Victoria para la Horda",{"Llévale la cabeza de Onyxia a Thrall en Orgrimmar."}}
D[7491] = {"Para que todos lo vean",{"Busca al señor supremo Runthak en el Valle de la Fuerza."}}
D[7492] = {"Campamento Mojache",{"Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida."}}
D[7493] = {"El viaje acaba de empezar"}
D[7494] = {"Bastión Plumaluna",{"Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas."}}
D[7495] = {"Victoria para la Alianza",{"Lleva la cabeza de Onyxia al Alto Señor Bolvar Fordragon, en Ventormenta."}}
D[7496] = {"Celebrar los buenos momentos",{"Busca al mayor Mattingly en el Valle de los Héroes."}}
D[7497] = {"El viaje acaba de empezar"}
D[7498] = {"Garona: un estudio acerca de la discreción y la traición",{"Devuelve el libro a sus legítimos dueños."}}
D[7499] = {"Códice de Defensa",{"Devuelve el libro a sus legítimos dueños."}}
D[7500] = {"El libro de cocina del Arcanista",{"Devuelve el libro a sus legítimos dueños."}}
D[7501] = {"La Luz y cómo alterarla",{"Devuelve el libro a sus legítimos dueños."}}
D[7502] = {"Controlar las Sombras",{"Devuelve el libro a sus legítimos dueños."}}
D[7503] = {"La mayor raza de cazadores",{"Devuelve el libro a sus legítimos dueños."}}
D[7504] = {"Sagrada Bologna: lo que la Luz nunca te dirá",{"Devuelve el libro a sus legítimos dueños."}}
D[7505] = {"El choque de Escarcha y tú",{"Devuelve el libro a sus legítimos dueños."}}
D[7506] = {"El Sueño Esmeralda",{"Devuelve el libro a sus legítimos dueños."}}
D[7507] = {"Compendio de Nostro",{"Devuelve el compendio de matar dragones de Nostro a El Athenaeum."}}
D[7508] = {"Forjar Quel'Serrar",{"Entrega la espada élfica desafilada al guardián del Conocimiento Lydros."}}
D[7509] = {"Forjar Quel'Serrar",{"Debes conseguir que Onyxia escupa fuego sobre la antigua espada sin templar. Una vez hecho, recógela: ahora su hoja está candente. Pero ten cuidado: una hoja candente no permanecerá así para siempre, no tienes tiempo que perder.","","Antes de volver a mí, tienes que terminar lo empezado: debes matar a la bestia e introducir la hoja candente en su cadáver.","","Hazlo y Quel'Serrar será tuya."}}
D[7541] = {"Un servicio para la Horda"}
D[7562] = {"Mor'zul Sangredoble",{"Habla con Mor'zul Sangredoble en las Estepas Ardientes."}}
D[7563] = {"La ira de sangre",{"Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes."}}
D[7564] = {"Ojosalvajes",{"Llévale el estuche de sangre a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7581] = {"Las selladuras de la prisión",{"Viaja a La Masacre en Feralas y consigue 15 muestras de sangre de sátiro del sátiro Mala Hierba que habita en el Barrio Alabeo. Cuando hayas acabado, ve a ver a Daio a la Escara Impía.|n"}}
D[7582] = {"El revestimiento de la prisión",{"Viaja a la Garganta Negro Rumor en Cuna del Invierno y recoge 5 Lágrimas de los Hederine de los demonios Hederine que ocupan la garganta. Cuando hayas cumplido tu tarea, ve a ver a Daio a la Escara Impía."}}
D[7583] = {"Supresión",{"Aventúrate en la Escara Impía y localiza a un comandante Guardia apocalíptico.","","Utiliza la prisión de cristal resplandeciente para atrapar al comandante Guardia apocalíptico. Prepárate para una sucesión de ataques pues el demonio intentará escapar.","","Si tienes éxito, llévale el Guardia apocalíptico encarcelado a Daio, que está en la Escara Impía."}}
D[7601] = {"La orden de Niby",{"Habla con Diblis en Frondavil."}}
D[7602] = {"Esencia de energía vil pura",{"Diblis de Frondavil te ha pedido que le lleves 3 esencias viles impecables que provengan de 3 lugares distintos. Los sátiros Legashi de Azshara tienen la esencia vil impecable de su región. Los Legionarios Jaedenar de Jaedenar tienen la esencia vil impecable de su región. Los guardias viles de Las Tierras Devastadas tienen la esencia vil impecable de su región. Reúne las esencias viles impecables y vuelve con Diblis a Frondavil."}}
D[7603] = {"El núcleo infernal de Kroshius",{"Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego inferi cerca de ellos y espera el regreso de Kroshius. Cuando el inferno se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius.","","Lleva el núcleo infernal de Kroshius a Niby el Todopoderoso a Frondavil."}}
D[7604] = {"Un contrato vinculante",{"Entrégale el contrato de La Hermandad del torio a Lokhtos Tratoscuro si quieres recibir los planes de Sulfuron."}}
D[7621] = {"Un aviso"}
D[7622] = {"Equilibrio de Luz y Sombras",{"Salva a 50 campesinos antes de que 15 sean asesinados. Habla con Eris Feleste si tienes éxito.","","Puedes ver el Poste de la muerte para ver cuántos campesinos han sido asesinados."}}
D[7623] = {"Lord Pesadilla",{"Cómprale pociones enigmáticas a Gorzeeki en las Estepas Ardientes.","","Usa las pociones para viajar por Jaedenar y habla con Lord Pesadilla."}}
D[7624] = {"Ulathek el Traidor",{"Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar."}}
D[7625] = {"Polvo estelar xorothiano",{"Cómprale polvo estelar xorothiano a Ur'dan. Llévaselo a Gorzeeki Ojovago en las Estepas Ardientes."}}
D[7626] = {"La Campana de Dethmoora",{"Llévale 10 elixires de poder de las sombras a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7627] = {"Rueda de la Marcha Negra",{"Llévale 6 grandes fragmentos brillantes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes."}}
D[7628] = {"La Vela del Apocalipsis",{"Lleva 35 escamas de dragón negro a Gorzeeki Ojosalvajes a Las Estepas Ardientes."}}
D[7629] = {"Entrega de diablillo",{"Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el pergamino llévale el tarro a Gorzeeki Ojosalvajes."}}
D[7630] = {"La arcanita",{"Lleva 3 lingotes de arcanita a Gorzeeki Ojosalvajes a Las Estepas Ardientes."}}
D[7631] = {"Terrorecus de Xoroth",{"Lee las instrucciones de Mor'zul. Invoca al Corcel de la Muerte Xorothiano, derrótalo y después vincula su espíritu al tuyo."}}
D[7632] = {"La hoja antigua",{"Encuentra al dueño de la hoja petrificada vieja. Buena suerte, <nombre>; este es un mundo enorme..."}}
D[7633] = {"Una presentación"}
D[7634] = {"Carcaj antiguo cosido con tendón",{"Hastat el Anciano te ha pedido que le lleves 1 tendón de dragón azul maduro. Si lo encuentras, llévaselo a Hastat a Frondavil."}}
D[7635] = {"La cuerda adecuada",{"Estoma el Anciano te ha pedido que le lleves 1 tendón de dragón negro maduro. Si lo encontraras, llévaselo a Estoma a Frondavil."}}
D[7636] = {"El báculo de los Ancestros",{"Debes encontrar y destruir a estos 4 corruptores demoníacos:","","Simone la Seductora.","","Klinfran el Enloquecido.","","Solenor el Destripador.","","Artorius el Fatídico.","","Destruye a estas criaturas, vuelve a Frondavil y entrega sus cabezas a Vartrus el Ancestro.","","Busca pistas de su paradero en la corteza petrificada.","","DEBES completar esta misión tú <solo/sola>."}}
D[7637] = {"Énfasis en el sacrificio",{"Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo."}}
D[7638] = {"Lord Grisillo Quiebrasombras",{"Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7639] = {"Mostrarse juicioso",{"Devuelve el incensario de exorcismos a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7640] = {"Exorcismo en Valle del Terror",{"Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7641] = {"El trabajo de Grimand Elmore",{"Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta."}}
D[7642] = {"Recopilación de artículos",{"Lleva 40 paños rúnicos, 6 lingotes de arcanita, 10 lágrimas de Arthas, 5 frascos de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta."}}
D[7643] = {"El antiguo espíritu equino",{"Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida.","","Ve a la mazmorra de La Masacre, en Feralas y mata a Tendris Madeguerra. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga."}}
D[7644] = {"La gualdrapa de arcanita bendecida",{"Devuelve la Blessed Arcanite Barding a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7645] = {"Alimento para caballos enriquecido con maná",{"Consigue 20 galletas enriquecidas con maná, ingrediente principal del alimento especial para caballos, y llévaselas a Merideth Carlson a las Laderas de Trabalomas, en Costasur. Solo El Alba Argenta fabrica esas galletas. También tienes que darle 50 piezas de oro para aplacar su orgullo herido."}}
D[7646] = {"El cristal de adivinación",{"Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta."}}
D[7647] = {"Juzgar y redimir",{"Utiliza el cristal de adivinación en el centro del sótano de El Gran Osario en Scholomance. Al hacerlo, aparecerán los espíritus que tienes que juzgar. Si derrotas a esos espíritus, aparecerá el Caballero de la Muerte Atracoscuro. Acaba con él y reclama el alma perdida del destrero caído. Entrega el alma redimida del destrero y la gualdrapa encantada bendecida al destrero caído de Atracoscuro."}}
D[7648] = {"Un trabajo bien hecho",{"Lleva la gualdrapa de arcanita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta para que la inspeccione."}}
D[7649] = {"Las mallas de placas en torio encantado: volumen I",{"Devuelve el libro a sus legítimos dueños."}}
D[7650] = {"Las mallas de placas en torio encantado: volumen II",{"Devuelve el libro a sus legítimos dueños."}}
