D[7701] = {"SE BUSCA: vigía Maltorius",{"El traidor Hierro Negro llamado vigía Maltorius está en La Fosa de la Escoria de La Caldera, en La Garganta de Fuego.","","Mátalo y lleva su cabeza al capitán de vigía Lolo Zancalarga a La Garganta de Fuego para recibir tu recompensa."}}
D[7703] = {"El aunto inacabado de Gordok",{"Encuentra el Guante del Poder de Gordok y llévaselo al capitán Kromcrush a La Masacre.","","Según Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok."}}
D[7704] = {"¡Mira el tamaño de esto!",{"Lleva la almohada de la ayudante de cámara Pilaprieta a Evonice Fumollín a La Garganta de Fuego."}}
D[7721] = {"Combustible para el Ultra-reductor",{"Reúne 10 núcleos de elemental de agua de los elementales marinos y los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Ventipnotizador, que está cerca del embarcadero."}}
D[7722] = {"La receta del fluido ardiente",{"Busca la receta de fluido ardiente robada por el vigía Maltorius en la La Fosa de la Escoria de La Caldera. Llévasela al maestro herrero Cremación a La Garganta de Fuego."}}
D[7723] = {"¡Malditos dedos gordos!",{"Hansel Manospesadas quiere que mates 20 golems de guerra pesados.","","Suelen estar cerca de La Caldera en La Garganta de Fuego. Después ve a ver a Hansel."}}
D[7724] = {"Amenaza abrasadora",{"Hansel Manospesadas quiere que mates 20 lavarañas mayores en La Garganta de Fuego. Las encontrarás en los estanques de lava.","","Después ve a ver a Hansel Manospesadas."}}
D[7725] = {"Encoge más gigantes",{"Utiliza el Ultra-reductor de Zorbin para encoger a cualquier gigante que encuentres en Feralas a un tamaño más manejable. Lleva 10 residuos de miniaturización encontrados en las versiones encogidas de los gigantes a Zorbin Ventipnotizador, al embarcadero de La Costa Olvidada de Feralas."}}
D[7726] = {"Más combustible para el Ultra-reductor",{"Reúne 6 núcleos de elemental de agua de los elementales marinos y los rocíos marinos que hay en La Costa Olvidada de Feralas, y llévaselos a Zorbin Ventipnotizador, que está cerca del embarcadero."}}
D[7727] = {"¿Incendosaurio? Loqueseasaurio más bien",{"Hansel Manospesadas quiere que mates 20 incendosaurios.","","Suelen estar en los estanques de lava de La Fosa de la Escoria. Está en La Caldera de La Garganta de Fuego.","","Después ve a ver a Hansel Manospesadas."}}
D[7728] = {"OBJETOS ROBADOS: Tobera y espejo espía",{"Encuentra la tobera y el espejo espía y llévaselos al capataz Scrange a La Garganta de Fuego.","","Lo único que sabes es que fueron robados por enanos Hierro Negro. La tobera es una herramienta de herrero y el espejo es un instrumento muy valioso para los vigías."}}
D[7729] = {"OPORTUNIDAD LABORAL: Acabar con la competencia",{"Mata a 15 capataces y 15 esclavistas Hierro Negro y ve a ver al capataz Scrange a La Garganta de Fuego."}}
D[7730] = {"Infestación de Zukk'ash",{"Lleva 20 caparazones de Zukk'ash a Hadoken Zancoveloz al Campamento Mojache de Feralas."}}
D[7731] = {"Aguijolatigador",{"Derrota a Aguijolatigador en Las Entrañas Retorcidas y lleva sus glándulas a Hadoken Zancoveloz al Campamento Mojache de Feralas."}}
D[7732] = {"El informe Zukk'ash",{"Entrega a Zilzibin Tambor Sabio el informe del campamento Mojache Zukk'ash. Reside en La Calle Mayor de Orgrimmar."}}
D[7733] = {"Calidad mejorada",{"Lleva 10 pellejos gruesos de yeti Cicatriz Feral a Pratt McGrubben al Bastión Plumaluna."}}
D[7734] = {"Calidad mejorada",{"Lleva 10 pellejos gruesos de yeti Cicatriz Feral a Jangdor Zancoveloz al Campamento Mojache de Feralas."}}
D[7735] = {"Pellejo de yeti prístino",{"Lleva el pellejo de yeti prístino a Pratt McGrubben al Bastión Plumaluna de Feralas."}}
D[7736] = {"Fabricar fluido ardiente con sangrerregia"}
D[7737] = {"Ganarse el respeto"}
D[7738] = {"Pellejo de yeti perfecto",{"Lleva los pellejos de yeti perfecto a Jangdor Zanco Veloz al Campamento Mojache de Feralas."}}
D[7761] = {"La orden de Puño Negro",{"¡Será estúpido ese orco! Al parecer, tienes que encontrar esta señal y ganar la marca de Drakkisath para poder acceder al orbe de orden.","","Según la carta, el general Drakkisath guarda la señal. Quizás deberías investigarlo."}}
D[7781] = {"Señor de Roca Negra",{"Llévale la cabeza de Nefarian al alto señor Bolvar Fordragón en Ventormenta."}}
D[7782] = {"Señor de Roca Negra",{"Vete al Valle de los Héroes, en la Ciudad de Ventormenta, y habla con el mariscal de campo Afrasiabi."}}
D[7783] = {"Señor de Roca Negra",{"Lleva la cabeza de Nefarian a Thrall a Orgrimmar."}}
D[7784] = {"Señor de Roca Negra",{"Habla con el Señor Supremo Colmilloturbio en Orgrimmar. Te espera en el Valle de la Fuerza."}}
D[7785] = {"Examina la vasija",{"Examina la vasija de renacer y devuélvesela al alto señor Demitrian."}}
D[7786] = {"Thunderaan el Hijo del Viento",{"Para liberar a Thunderaan el Hijo del Viento de su cárcel, debes entregarle al alto señor Demitrian en Silithus la mitad izquierda y la derecha de las ataduras del Hijo del Viento, 10 barras de elementium y la esencia del Señor del Fuego."}}
D[7787] = {"¡Arriba, Trueno Furioso!",{"Lleva la hoja besada por el viento durmiente al alto señor Demitrian."}}
D[7788] = {"¡Expulsa al invasor!",{"Entra en la Garganta Grito de Guerra y derrota a la Horda, obtén una marca de honor de Grito de Guerra y vuelve con la centinela Cantolongo en el Claro Ala de la Plata."}}
D[7789] = {"Acaba con los usurpadores Ala de Plata",{"Entra en la Garganta Grito de Guerra y derrota a la Alianza, obtén una marca de honor de Grito de Guerra y llévasela al capitán Trizacráneo en el Campamento de Mor'shan."}}
