D[8277] = {"Veneno mortal del desierto",{"Beetix Castaneo en el Fuerte Cenarion, en Silithus, quiere que consigas 8 aguijoneros escórpidos Latigosólido y 8 colmillos de arácnidos de arena. Vuelve a verla cuando hayas cumplido tu misión."}}
D[8278] = {"La última esperanza de Noggle",{"Beetix Castañeta en el Fuerte Cenarion, en Silithus quiere que consigas 3 aguijoneros de tenazario Latipiedra, 3 aguijoneros de despellejador Latipiedra y 3 colmillos de acecharrocas."}}
D[8279] = {"El Lexicón del Crepúsculo",{"Lleva los tres capítulos del Lexicón del Crepúsculo a Hermit Ortell en Silithus."}}
D[8280] = {"Asegurar las rutas de suministros",{"Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus, quiere que mates a 15 golpeadores deslizantes."}}
D[8281] = {"Intensificar la seguridad",{"Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus, quiere que mates a 20 trituradores deslizantes."}}
D[8282] = {"La cartera perdida de Noggle",{"Recupera la Cartera de Noggle en las montañas al sur de Silithus y devuélvesela en el Fuerte Cenarion."}}
D[8283] = {"Se busca: Pinzamorten el Terror de las arenas",{"Lleva la pinza de Pinzamorten a Vish Kozus, Capitán de la guardia."}}
D[8284] = {"El misterio del Crepúsculo",{"La Geóloga Trotuina en el Fuerte Cenarion, en Silithus, quiere que consigas 8 fragmentos de tablilla Crepuscular."}}
D[8285] = {"El desertor",{"Lleva la tablilla restaurada al ermitaño Ortell en Silithus.|n"}}
D[8286] = {"Lo que nos depara el futuro",{"Ve a las Cavernas del Tiempo en Tanaris y encuentra a Anacronos, del Linaje de Nozdormu."}}
D[8287] = {"Un propósito terrible",{"Lleva la trascripción de tablilla decodificada al comandante Mar'alith."}}
D[8288] = {"Solo uno puede alzarse",{"Lleva la cabeza del Señor de linaje Capazote a Baristolth del Mar de Dunas al Fuerte Cenarion en Silithus."}}
