D[8301] = {"El buen camino",{"Lleva 200 fragmentos de caparazón de silítido a Baristolth."}}
D[8302] = {"Una buena mano",{"Lleva 200 fragmentos de caparazón de silítido a Baristolth."}}
D[8303] = {"Anacronos",{"Busca a Anacronos en las Cavernas del Tiempo de Tanaris."}}
D[8304] = {"Queridísima Natalia",{"El comandante Mar'alith del Fuerte Cenarion de Silithus quiere que interrogues a los habitantes del campamento Barbabronce, que está al sur del fuerte.","","Cuando consigas la información ve a ver al comandante Mar'alith."}}
D[8305] = {"Recuerdos olvidados",{"Encuentra la lágrima cristalina en Silithus y mira en sus profundidades."}}
D[8306] = {"En las fauces de la locura",{"El comandante Mar'alith del Fuerte Cenarion de Silithus quiere que encuentres a su amada Natalia. Parece que podría estar en Colmen'Regal, hacia el sur.","","No olvides ir a ver a los enanos del campamento Barbabronce antes de ir a la colmena; puede que tengan otras tareas o consejos que darte.","","Y recuerda lo que dijo el comandante: \"Haz lo que tengas que hacer.\""}}
D[8307] = {"Receta del desierto",{"Busca información sobre cómo cocinar carne de gusano de arena en el Campamento del Martillo Crepuscular, al oeste del Fuerte Cenarion."}}
D[8308] = {"La carta perdida de Brann Barbabronce",{"Lleva la carta de Brann Barbabronce al campamento Barbabronce al sur de Silithus."}}
D[8309] = {"Los grabados de los glifos",{"Rutgar Glifoforma del campamento Barbabronce en Silithus quiere que vayas a Colmen'Ashi, Colmen'Regal y Colmen'Zora y calques cristales en cada colmena.","","Usa el juego de calco para copiar los glifos antiguos. Vuelve a ver a Rutgar cuando hayas terminado la tarea."}}
D[8310] = {"Descifrar el código",{"Frankal Petraponte del campamento Barbabronce en Silithus quiere que le lleves 1 cerebro de silítido de Colmen'Zora, 1 de Colmen'Ashi y 1 de Colmen'Regal. Vuelve a ver a Frankal cuando hayas terminado la tarea."}}
D[8311] = {"Golosinas de Halloween para Jesper",{"Habla con los taberneros de Ventormenta, Forjaz y Darnassus, así como con Talvash del Kissel en Forjaz. Realiza los trucos que te pidan a cambio de tratos.","","Vuelve a ver a Jesper en el orfanato de Ventormenta con un mazapán de Darnassus, una gominola de Gnomeregan un almendrado de Ventormenta y una menta de Forjaz."}}
D[8312] = {"Golosinas de Halloween para Pupas",{"Habla con los taberneros de Orgrimmar, Entrañas y Cima del Trueno, y también con Kali Remik en Poblado Sen'jin. Realiza los trucos que te piden a cambio de las golosinas que ofrecen. Vuelve a ver a Pupas en el Orfanato de Orgrimar con un mazapán de Cima del Trueno, una gominola Lanza Negra, un almendrado de Orgrimmar y una menta de Entrañas."}}
D[8313] = {"Compartir el conocimiento",{"Lleva la Página de receta rasgada a Calandrath en la taberna del Fuerte Cenarion."}}
D[8314] = {"Desentrañar el misterio",{"Rutgar Glifoforma del campamento Barbabronce quiere que lleves el prisma cristalino con glifos a la geóloga Trotuina al Fuerte Cenarion de Silithus."}}
D[8315] = {"La llamada",{"La Geóloga Trotuina del Fuerte Cenarion de Silithus quiere que consigas el mecanismo de desbloqueo de los cristales del emisario Qiraji.","","Tienes que llevar los glifos a Huesos de Grakkarond, al sur del Fuerte Cenarion, y dibujarlos en la arena. Si aparece el emisario Qiraji, mátalo y coge el mecanismo de desbloqueo de los cristales. Si lo consigues, ve a ver a la geóloga Trotuina.","","¡Lleva un ejército contigo, <nombre>!"}}
