D[8460] = {"Aliado a los Fauces de Madera",{"Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda."}}
D[8461] = {"Los Muertobosque del Norte",{"Nafien quiere que mates a 6 vigilantes del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión de los Fauces de Madera."}}
D[8462] = {"Habla con Nafien",{"Viaja hacia el norte por el camino principal de Frondavil y habla con el fúrbolg Nafien. Está haciendo guardia en la entrada del Bastión de los Fauces de Madera."}}
D[8464] = {"Actividad de los Nevada",{"Salfa quiere que mates 8 chamanes Nevada, 8 Vigilantes del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión de los Fauces de Madera en Cuna del Invierno."}}
D[8465] = {"Habla con Salfa",{"Viaja por el Bastión de los Fauces de Madera y sal a Cuna del Invierno. Habla con Salfa, que está haciendo guardia en la entrada del Bastión de los Fauces de Madera."}}
D[8466] = {"Plumas para Grazle"}
D[8467] = {"Plumas para Nafien"}
D[8469] = {"Cuentas para Salfa"}
D[8470] = {"El tótem ritual de los Muertobosque",{"Lleva el tótem ritual Muertobosque al interior del Bastión de los Fauces de Madera. A ver si alguno de los furbolgs que hay en él sabe dar uso al objeto. Los Fauces de Madera no hablarán contigo si no tienes un nivel de reputación neutral o superior con ellos."}}
D[8471] = {"Tótem ritual Nevada",{"Lleva el tótem ritual Nevada al Bastión de los Fauces de Madera y averigua si alguno de los furbolgs sabe de su utilidad. Los Fauces de Madera no hablarán contigo si tu reputación con ellos no es como mínimo de neutral."}}
D[8481] = {"La raíz de todos los males",{"Clava la antorcha de invocación del Demonio en la entrada de la cueva del Gran Jefe Nevada en el Poblado Nevada de los furbolgs. Derrota al demonio y consigue la esencia de Xandivious para Gorn Monóculo del Bastión de los Fauces de Madera."}}
D[8484] = {"Negociar la paz",{"Llévale la ofrenda de paz de los Fauces de Madera al rey Magni Barbabronce de Forjaz."}}
D[8485] = {"Negociar la paz",{"Llévale la ofrenda de paz de los Fauces de Madera a Thrall, que está en Orgrimmar."}}
D[8492] = {"¡La Alianza necesita lingotes de cobre!",{"Llévale 20 lingotes de cobre al alférez Petrocejas en La Sala Militar de Forjaz."}}
D[8493] = {"¡La Alianza necesita más lingotes de cobre!",{"Llévale 20 lingotes de cobre al sargento Petrocejas en la base aérea de Dun Morogh."}}
D[8494] = {"¡La Alianza necesita lingotes de hierro!",{"Llévale 20 lingotes de hierro al cabo Carnes en La Sala Militar de Forjaz."}}
D[8495] = {"¡La Alianza necesita más lingotes de hierro!",{"Llévale 20 lingotes de hierro al cabo Carnes en la base aérea de Dun Morogh."}}
D[8496] = {"Vendas para el campo de batalla",{"Lleva 30 vendas de paño rúnico gruesas, 30 vendas de seda gruesas y 30 vendas de tejido mágico gruesas a Clamavientos Cuerno Digno en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas logísticas X para poder completar la misión."}}
D[8497] = {"Material de supervivencia en el desierto"}
D[8498] = {"Órdenes de batalla de Crepusculares",{"Consigue las órdenes de batalla de Crepusculares y llévaselas al comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas tácticas X para poder completar la misión."}}
D[8499] = {"¡La Alianza necesita lingotes de torio!",{"Llévale 20 lingotes de torio a Dama Trenzado en La Sala Militar de Forjaz."}}
D[8500] = {"¡La Alianza necesita más lingotes de torio!",{"Llévale 20 lingotes de torio a Dama Trenzado en la base aérea de Dun Morogh."}}
D[8501] = {"Objetivo: los aguijoneros de Colmen'Ashi",{"Mata 30 aguijoneros Colmen'Ashi y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate XII para poder completar la misión."}}
D[8502] = {"Objetivo: los trabajadores de Colmen'Ashi",{"Mata 30 trabajadores Colmen'Ashi y preséntate ante la comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate III para poder completar la misión."}}
D[8503] = {"¡La Alianza necesita algas estranguladoras!",{"Llévale 20 algas estranguladoras al soldado Draxlegauge en La Sala Militar de Forjaz."}}
D[8504] = {"¡La Alianza necesita más algas estranguladoras!",{"Llévale 20 algas estranguladoras al soldado Draxlegauge en la base aérea de Dun Morogh."}}
D[8505] = {"¡La Alianza necesita lotos cárdenos!",{"Llévale 20 lotos cárdenos al maestro Arrullanoche en La Sala Militar de Forjaz."}}
D[8506] = {"¡La Alianza necesita más lotos cárdenos!",{"Llévale 20 lotos cárdenos al maestro Arrullanoche en la base aérea de Dun Morogh."}}
D[8507] = {"Servicio de campo",{"Preséntate en el puesto de la Brigada de Forjaz cerca de Colmen'Zora. Prepara tu documentación de instrucción de campo sin firmar y consigue la documentación de instrucción de campo firmada del capitán Yunquenegro. A continuación, reúnete con Clamavientos Kaldon en el Fuerte Cenarion, en Silithus.","","Nota: curar o lanzar hechizos benéficos a un miembro de la Brigada de Forjaz, te marcará como JcJ."}}
D[8508] = {"Documentación de instrucción de campo"}
D[8509] = {"¡La Alianza necesita lágrimas de Arthas!",{"Llévale 20 lágrimas de Arthas al alférez Germaine en La Sala Militar de Forjaz."}}
D[8510] = {"¡La Alianza necesita más lágrimas de Arthas!",{"Llévale 20 lágrimas de Arthas al Sargento Mayor Germaine en la base aérea de Dun Morogh."}}
