D[8533] = {"¡La Horda necesita más lingotes de cobre!",{"Llévale 20 lingotes de cobre al minero Cromaljibe en Durotar."}}
D[8534] = {"Informe de exploración de Colmen'Zora",{"Contacta con la exploradora Cenarion Azenel en Colmen'Zora y entrega el informe de exploración de Colmen'Zora a Astaorgullo Clamavientos en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VI para poder completar la misión."}}
D[8535] = {"Templario vetusto",{"Invoca y mata a un Templario vetusto y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas IV para poder completar la misión."}}
D[8536] = {"Templario de tierra",{"Invoca y mata a un Templario de tierra y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas III para poder completar la misión."}}
D[8537] = {"Templario carmesí",{"Invoca y mata a un Templario carmesí y preséntate ante Bor Bravacrín en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas II para poder completar la misión."}}
D[8538] = {"Los cuatro Duques",{"Invoca y mata al Duque de las Brasas, al Duque de las Profundidades, al Duque de los Céfiros y al Duque de las Esquirlas y preséntate ante la comandante Mar'alith en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas V para poder completar la misión."}}
D[8539] = {"Objetivo: las hermanas de la colmena de Colmen'Zora",{"Mata 30 hermanas de la colmena de Colmen'Zora y preséntate ante el comandante Mar'alith en el Fuerte Cenarion, en Silithus. También debes llevar el Informe de tareas de combate V para poder completar la misión."}}
D[8540] = {"Botas para la guardia",{"Lleva 3 botas de mitril ornamentado a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas II para poder completar la misión."}}
D[8541] = {"Piedra de pulir para la guardia",{"Lleva 10 piedras de pulir densas, 10 piedras de pulir sólidas y 10 piedras de pulir pesadas a Vish Kozus, Capitán de la guardia del Fuerte Cenarion en Silithus. También debes llevar el Informe de tareas logísticas III para poder completar la misión."}}
D[8542] = {"¡La Horda necesita lingotes de estaño!",{"Llévale 20 lingotes de estaño a Bruto Maug en el Valle de los Espíritus de Orgrimmar."}}
