D[8546] = {"¡La Horda necesita más lingotes de mitril!"}
D[8548] = {"Equipamiento de Voluntario",{"Lleva 5 distintivos de combate Cenarion, 3 distintivos de logística Cenarion y 7 distintivos de táctica Cenarion a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación amistoso con el Círculo Cenarion para poder completar esta misión."}}
D[8549] = {"¡La Horda necesita flores de paz!",{"Llévale 20 flores de paz al herborista Plumorgullo en el Valle de los Espíritus de Orgrimmar."}}
D[8550] = {"¡La Horda necesita más flores de paz!"}
D[8551] = {"El cofre del capitán",{"Lleva el cofre de Smotts a Hecklebury Smotts en la Bahía del Botín."}}
D[8552] = {"La banda con monograma",{"Devuelve la banda con monograma a su propietario."}}
D[8553] = {"El aflanje del capitán",{"Habla con Sprogger."}}
D[8554] = {"Enfréntate a Negolash",{"Lleva 10 Alas de águila ratonera a la parrilla y 5 botellas de vino de vid de jungla al barco salvavidas del capitán Smotts.","","Mata a Negolash y lleva el alfanje de Smotts al capitán Smotts en Tuercespina."}}
D[8555] = {"Encomienda a los Vuelos"}
D[8556] = {"El anillo con sello de fuerza implacable",{"Llévale 1 anillo de magistrado qiraji, 2 ídolos luminiscentes, 5 escarabajos de bronce y 5 escarabajos de marfil a Clamavientos Yessendra en Silithus. También debes alcanzar la reputación de honrado ante el Círculo Cenarion para completar esta misión."}}
D[8557] = {"El mantón de fuerza implacable",{"Llévale 1 mantón marcial qiraji, 2 ídolos de ónice, 5 escarabajos de plata y 5 escarabajos de hueso a Keyl Patacerce en Silithus. También debes alcanzar la reputación de venerado ante el Círculo Cenarion para completar esta misión."}}
D[8558] = {"La hoz de fuerza implacable",{"Llévale 1 empuñadura con púas qiraji, 2 ídolos de porcelana, 5 escarabajos de cristal y 5 escarabajos de piedra al alcaide Haro en Silithus. También debes alcanzar la reputación de exaltado ante el Círculo Cenarion para completar esta misión."}}
D[8559] = {"Las grebas de conquistador",{"Llévale las ataduras de mando qiraji, 2 ídolos de la guerra, 5 escarabajos de marfil y 5 escarabajos de oro a Kandrostrasz en Ahn'Qiraj. Esta misión requiere la reputación neutral con la facción Linaje de Nozdormu."}}
D[8560] = {"Los leotardos de conquistador",{"Llévale la piel intacta de Ouro, 2 ídolos de muerte, 5 escarabajos de bronce y 5 escarabajos de marfil a Kandrostrasz en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
D[8561] = {"La corona de conquistador",{"Llévale el aro de Vek'lor, 2 ídolos del sol, 5 escarabajos de piedra y 5 escarabajos de cristal a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación de amistoso ante el Linaje de Nozdormu para completar esta misión."}}
D[8562] = {"La coraza de conquistador",{"Llévale el caparazón del dios antiguo, 2 ídolos de la guerra, 5 escarabajos de plata y 5 escarabajos de hueso a Vethsera en Ahn'Qiraj. También debes alcanzar la reputación de honorable ante el Linaje de Nozdormu para completar esta misión."}}
