D[8728] = {"Buenas y malas noticias",{"Narain Sabelotodo de Tanaris quiere que le lleves 20 barras de arcanita, 10 menas de elementium, 10 diamantes de Azeroth y 10 zafiros azules."}}
D[8729] = {"La cólera de Neptulon",{"Utiliza la boya de arcanita en La Vorágine espiral de la Bahía de la Tempestad de Azshara."}}
D[8730] = {"La corrupción de Nefarius",{"Mata a Nefarian y recupera del fragmento de cetro rojo. Llévaselo a Anacronos a las Cavernas del Tiempo, en Tanaris. Tienes 5 horas para completar esta tarea."}}
D[8731] = {"Servicio de campo",{"Preséntate ante Krug Machacacráneos en la Avanzada de la Legión de Orgrimmar delante de Colmen'Regal. Prepara tu documentación de instrucción de campo sin firmar, consigue la documentación de instrucción de campo firmada y llévaselas a Clamavientos Kaldon en el Fuerte Cenarion. Nota: curar o lanzar hechizos benéficos a un miembro de la Legión de Orgrimmar, te marcará como JcJ."}}
D[8732] = {"Documentación de instrucción de campo"}
D[8733] = {"Eranikus, el Tirano del Sueño",{"Viaja al continente de Teldrassil y busca al agente de Malfurion. Lo encontrarás a lo largo de los muros de Darnassus.|n"}}
D[8734] = {"Tyrande y Rémulos",{"Ve a Claro de la Luna y habla con el guardián Remulos."}}
D[8735] = {"Corrupción de Pesadilla",{"Ve a los 4 Portales del Sueño Esmeralda de Azeroth y recoge un fragmento de la corrupción de la Pesadilla en cada uno. Habla otra vez con el guardián Remulos en Claro de la Luna cuando hayas completado la tarea."}}
D[8736] = {"La Pesadilla se manifiesta",{"Defiende Amparo de la Noche de Eranikus. No dejes morir al guardián Remulos. No mates a Eranikus. Defiéndete. Espera a Tyrande.|n"}}
D[8737] = {"Templario azur"}
D[8738] = {"Informe de exploración de Colmen'Regal",{"Contacta con el explorador Cenarion Landion en Colmen'Regal y entrega el informe de exploración de Colmen'Regal a Clamavientos Cuerno Digno en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VII para poder completar la misión."}}
D[8739] = {"Informe de exploración de Colmen'Ashi",{"Contacta con la exploradora Cenarion Jalia en Colmen'Ashi y entrega el informe de exploración de Colmen'Ashi a Astaorgullo Clamavientos en el Fuerte Cenarion. También debes llevar el Informe de tareas tácticas VIII para poder completar la misión."}}
D[8740] = {"Los merodeadores Crepusculares",{"Mata a la Maleante Crepuscular Morna y a 5 Maleantes Crepusculares. Cuando termines tu tarea, entrégale el informe al Clamavientos Cuerno Digno. También debes llevar las Instrucciones de la misión táctica IX para poder completar la misión."}}
D[8741] = {"El regreso del Campeón",{"Lleva el fragmento de cetro verde a Anacronos a las Cavernas del Tiempo, en Tanaris.|n"}}
