D[9201] = {"Libranza del artesano: poción de Protección contra lo Arcano superior",{"Entrega 15 pociones de Protección contra lo Arcano superior y la libranza del artesano: poción de Protección contra lo Arcano superior al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.|n"}}
D[9202] = {"Libranza del artesano: poción sublime de curación",{"Entrega 20 pociones de curación sublime y la libranza del artesano –poción de curación sublime– al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9203] = {"Libranza del artesano: frasco de petrificación",{"Entrega 1 frasco de petrificación y la libranza del artesano –frasco de petrificación– al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9204] = {"Libranza del artesano: anguila Escama Tormentosa",{"Entrega 40 anguilas Escama Tormentosa y la libranza del artesano –anguila Escama Tormentosa– al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9205] = {"Libranza del artesano: pez coraza plateado",{"Entrega 30 peces coraza plateados y la libranza del artesano –pez coraza plateado– al maestro de manada Mazadura que está en la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
