D[9230] = {"La garra helada de Ramaladni",{"Korfax, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere que le lleves 1 runa helada, 1 zafiro azul y 1 barra de arcanita.|n"}}
D[9232] = {"La única canción que conozco",{"El artesano Wilhelm, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere que le lleves 2 runas heladas, 2 esencias de agua, 2 zafiros azules y 30 piezas de oro."}}
D[9233] = {"Vademécum de Omarion",{"Lleva el vademécum de Omarion al artesano Wilhelm a la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este.|n"}}
D[9234] = {"Los guanteletes Deliriohelado",{"El artesano Wilhelm de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 5 runas heladas, 12 barras de torio, 2 barras de arcanita, 2 esencias de agua y 200 piezas de oro."}}
