D[9664] = {"Nuevas avanzadas",{"Captura la Torre de la Guardia de la Corona, la Torre de la Muralla del Este, la Torre del Paso Norte y la Torre del Bosque de la Peste en las Tierras de la Peste del Este. Tras hacerlo, regresa y habla con el Emisario Barbablanca en la Capilla de la Esperanza de la Luz."}}
D[9665] = {"Fortalecimiento de nuestras defensas",{"Captura la Torre de la Guardia de la Corona, la Torre de la Muralla del Este, la Torre del Paso Norte y la Torre del Bosque de la Peste en las Tierras de la Peste del Este. Tras hacerlo, regresa y habla con el Emisario Gormok en la Capilla de la Esperanza de la Luz."}}
D[65593] = {"Los corazones de los amantes",{"Llévale los corazones de Avelina Lilly e Isaac Pearson a Carendin Halgar, que está en el Templo de los Condenados."}}
D[65597] = {"El vínculo",{"Utilizando los corazones de los amantes, invoca y domina a un íncubo, y después devuélvele los corazones de amantes a Carendin Halgar, que está en el Barrio de la Magia de Entrañas."}}
D[65601] = {"El amor duele",{"Habla con Magar en Orgrimmar."}}
D[65602] = {"¿Qué es el amor?",{"Recupera la figurilla de madera y llévasela a Gakin el Presotenebra en el Barrio de los Magos de Ventormenta."}}
D[65603] = {"El vínculo",{"Utilizando la figurilla de madera, invoca y somete a un íncubo. Después devuelve la figurilla de madera a Gakin el Presotenebra en El Cordero Degollado."}}
D[65604] = {"El vínculo",{"Usa el pañuelo deshilachado para invocar y dominar a un íncubo y después lleva el pañuelo a Gan'rul Ojosangre en Orgrimmar."}}
D[65610] = {"Ojalá estuvieras aquí",{"Investiga el Lago Cielo Estrellado de Vallefresno e informa de tus hallazgos a Gan'rul Ojosangre, que está en Orgrimmar."}}
