D[2] = {"La griffe de Serres-tranchantes",{"Apporter la griffe de Serres-tranchantes à Senani Thunderheart, au poste de Bois-brisé, en Ashenvale."}}
D[5] = {"L'estomac qui gargouille",{"Parler au chef Grual."}}
D[6] = {"La prime pour Garrick Padfoot",{"Tuer Garrick Padfoot et rapporter sa tête à l'Adjoint Willem de l'Abbaye du Northshire."}}
D[7] = {"Nettoyer le camp des kobolds",{"Tuer 10 Vermines kobold, puis revenir voir le maréchal McBride."}}
D[8] = {"Un marché de voleur",{"Livrer une Lettre à Renée dans les Clairières de Tirisfal."}}
D[9] = {"Les champs de mort",{"Le Fermier Saldean veut que vous tuiez 20 Gardiens des moissons."}}
D[10] = {"La rédemption de Scrimshank",{"Découvrir ce qu'est devenu le géomètre Scrimshank, et rapporter son équipement topographique au grand géomètre Fizzledowser à Gadgetzan."}}
D[11] = {"Prime pour les gnolls Rivepatte",{"Apporter 8 Brassards peints de gnolls à l'Adjoint Rainer à la Caserne."}}
D[12] = {"La milice du peuple",{"Tuer 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles."}}
D[13] = {"La milice du peuple",{"Tuer 15 Pilleurs défias et 15 Pillards défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles."}}
D[14] = {"La milice du peuple",{"Tuer 15 Malandrins défias, 5 Eclaireurs défias et 5 Truands défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles."}}
D[15] = {"Enquête sur la crête aux échos",{"Tuer 10 Ouvriers kobolds, puis revenir faire son rapport au maréchal McBride."}}
D[16] = {"Procurer de l'eau à Gerard"}
D[17] = {"Rechercher les composants à Uldaman",{"Apporter 12 Champignons magenta à Ghak Healtouch à Thelsamar."}}
D[18] = {"La confrérie des voleurs",{"Apporter 12 Masques rouges à l’Adjoint Willem à l’extérieur de l’Abbaye de Northshire."}}
D[19] = {"Tharil'zun",{"Rapporter la Tête de Tharil'zun au maréchal Marris, dans les Carmines."}}
D[20] = {"La menace des Blackrock",{"Rapporter 10 Haches détériorées au maréchal Marris de Lakeshire."}}
D[21] = {"La bataille de la Crête aux échos",{"Tuer 12 Travailleurs kobold, puis revenir voir le maréchal McBride, à l’Abbaye de Northshire."}}
D[22] = {"La tourte au foie de Broche-tripes",{"Salma Saldean a besoin de 8 Foies de Broche-tripes pour faire une Tourte au foie de Broche-tripes."}}
D[23] = {"La patte d'Ursangous",{"Apporter la Patte d'Ursangous à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale."}}
D[24] = {"La tête de Shadumbra",{"Apporter la Tête de Shadumbra à Senani Thunderheart, au Poste de Bois-brisé, dans Ashenvale."}}
D[25] = {"Impasse aux Serres-Rocheuses",{"Tuer 12 Elémentaires d’eau corrompus au lac Mystral, à l’est de la Perce des Serres, et au sud-ouest du poste de Bois-brisé.","","Faire une reconnaissance sur le kiosque du lac Mystral ; celui qui a vue sur l’avant-poste de l’Alliance.","","Retourner voir Mastok Wrilehiss, au poste de Bois-brisé, dans Ashenvale."}}
D[26] = {"Une leçon à apprendre",{"Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune."}}
D[27] = {"Une leçon à apprendre",{"Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune."}}
D[28] = {"L'épreuve du lac",{"Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.","","Vous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve."}}
D[29] = {"L'épreuve du lac",{"Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.","","Vous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve."}}
D[30] = {"L'épreuve du lion de mer",{"Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.","","Reformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.","","Apporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune."}}
D[31] = {"Forme aquatique",{"Retourner à Thunder Bluff et montrer le Pendentif du lion de mer à Turak Runetotem."}}
D[32] = {"L'ascension des silithides",{"Apporter le rapport à Zilzibin Drumlore à Orgrimmar."}}
D[33] = {"Les loups derrière la frontière",{"Apporter 8 pièces de Viande de loup coriace à Eagan Peltskinner, à l’extérieur de l’Abbaye de Northshire."}}
