D[35] = {"Inquiétudes supplémentaires",{"Le maréchal Dughan veut que vous parliez au garde Thomas."}}
D[36] = {"Le ragoût de la marche de l'Ouest",{"Verna Furlbrow veut que vous apportiez la Recette du ragoût de la marche de l'Ouest à Salma Saldean."}}
D[37] = {"Trouver les gardes disparus",{"Le garde Thomas veut que vous alliez vers le nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai."}}
