D[3821] = {"Le Rocher des Cognepeurs",{"S'aventurer dans les Steppes ardentes et découvrir ce qu'il est advenu de Sha'ni Proudtusk."}}
D[3822] = {"Krom'Grul",{"Récupérer l’Anneau de nez de Sha'ni sur Krom'Grul, et le rapporter à Thal'trak, à Kargath. Fouiller les différentes grottes et mines du Rocher des Cognepeurs."}}
D[3823] = {"Exterminer les Brûlentrailles",{"Tuer 15 Ogres-mages Brûlentrailles, 7 Ogres Brûlentrailles et 7 Brutes Brûlentrailles, puis retourner voir Oralius."}}
D[3824] = {"Le seigneur-brute Gor'tesh",{"Trouver Gor'tesh, quelque part à l’ouest du rocher des Cognepeurs. Le tuer et rapporter la Tête coupée de Gor'tesh à Oralius, dans les Steppes ardentes."}}
D[3825] = {"Une tête d'ogre au bout d'une pique = une fête",{"Prendre la Tête coupée de Gor'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique."}}
D[3841] = {"Un orphelin à la recherche d'un foyer",{"Parler à Quentin aux Mille pointes."}}
D[3842] = {"Une courte incubation",{"Apporter 2 Elixirs de Robustesse à Quentin, aux Mille pointes."}}
D[3843] = {"Un tout nouveau membre dans la famille",{"Emmenez votre Oeuf fragile de Fée fléchetteuse dans les Hinterlands et parlez à Agnar Beastamer. Dépêchez-vous, vous n’avez qu’une heure pour le trouver avant que le petit ne meure dans l’oeuf."}}
D[3844] = {"C'est un Secret pour tout le monde",{"Rechercher dans l'étang un indice sur l'identité du propriétaire du radeau brisé."}}
D[3845] = {"C'est un secret pour tout le monde",{"Examiner les objets du paquet et les apporter à leur propriétaire."}}
D[3861] = {"COT-COT-CODEC !",{"Trouver de la Nourriture spéciale pour poulet et l'apporter à la poule que vous voulez aider. Lorsque vous l'aurez trouvée, encouragez-la (/acclame) avant d'essayer de lui donner la Nourriture spéciale pour poulet."}}
D[3881] = {"Le sauvetage de l'expédition",{"Apporter une Caisse de nourriture et de l'Equipement de recherche à Williden Marshal dans le Cratère d'Un'Goro."}}
D[3882] = {"Faites rouler les os",{"Apporter 8 Os de dinosaure à Spark Nilminer, au cratère d'Un'Goro."}}
D[3883] = {"Ecologie étrangère",{"Utiliser la Fiole de raclement pour récolter un Echantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l’intérieur du cratère d'Un'Goro. Chercher les chambres qui contiennent des larves suspendues.","","Apporter l’Echantillon de paroi de la ruche à Hol'anyee Marshal dans le cratère d'Un'Goro."}}
D[3884] = {"Le journal de Williden",{"Rapporter le Journal à Williden Marshal quelque part dans le Cratère d'Un'Goro."}}
D[3901] = {"Faites cliqueter les thorax !",{"Tuez 12 Squelettes Cliquethorax, puis retournez voir le prêtre des ombres Sarvis au Glas."}}
D[3902] = {"La chasse aux trésors",{"Fouiller Le Glas et ses alentours pour trouver 6 pièces de fournitures de récupération, et les ramener au Garde noir Saltain."}}
D[3903] = {"Milly Osworth",{"Parler à Milly Osworth."}}
D[3904] = {"Les vendanges de Milly",{"Apporter 8 seaux de la récolte de Milly à Milly Osworth à l'Abbaye de Northshire."}}
D[3905] = {"Manifeste des vendanges",{"Apporter le Manifeste des vendanges à Frère Neals dans l'Abbaye de Northshire."}}
D[3906] = {"Discordance des flammes",{"Partir pour la carrière dans le mont Blackrock et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie."}}
D[3907] = {"Discordance des flammes",{"Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart."}}
