D[3909] = {"L'élixir de Videre",{"Rechercher Gregan Brewspewer au nord de Feralas. Apprendre de lui comment vous pouvez acquérir l'élixir de Videre, puis retourner voir Donova Snowden, au Berceau-de-l'Hiver."}}
D[3912] = {"Rendez-vous à la tombe",{"Se rendre au cimetière au-dehors de Gadgetzan et boire l'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan."}}
D[3913] = {"Une situation grave",{"Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver."}}
D[3914] = {"L'épée de Linken",{"Remettre l'Epée excellente de Linken à Linken dans le cratère d'Un'Goro."}}
D[3921] = {"Wenikee Boltbucket",{"Apporter le Samophlange cassé à Wenikee Boltbucket."}}
