D[4124] = {"Le messager disparu",{"Parler à Ginro Hearthkindle dans le bastion de Feathermoon."}}
D[4125] = {"Le messager disparu",{"Localiser le bateau du messager quelque part le long de la côte de Feralas."}}
D[4126] = {"Hurley Blackbreath",{"Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos."}}
D[4127] = {"Débris de bateau",{"Retourner au bastion de Feathermoon et montrer à Ginro Hearthkindle le Couteau perdu que vous avez découvert."}}
D[4128] = {"Ragnar Thunderbrew",{"Parler à Ragnar Thunderbrew."}}
D[4129] = {"Le couteau révélé",{"Apporter le Couteau perdu à Quintis Jonespyre au bastion de Feathermoon."}}
D[4130] = {"La lecture psychométrique",{"Parler à Ginro Hearthkindle dans le bastion de Feathermoon."}}
D[4131] = {"Les gnolls Griffebois",{"Fouiller les Camps des gnolls Griffebois dans la partie sud de Feralas pour trouver des indices sur les possessions du messager ou sur le messager lui-même."}}
D[4132] = {"Opération : Mort à Forgehargne",{"Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth."}}
D[4133] = {"Vivian Lagrave",{"Parler à la maîtresse des ombres Vivian Lagrave à Kargath."}}
D[4134] = {"La recette perdue de Thunderbrew",{"Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath."}}
D[4135] = {"Le Gouffre grouillant",{"À présent que la dernière destination connue de Raschal est découverte, continuez à le rechercher, lui ou ses restes, dans le Gouffre grouillant. D'après le message, il se trouve au sud des camps des gnolls Griffebois."}}
D[4136] = {"Ribbly Screwspigot",{"Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes."}}
D[4141] = {"Muigin et Larion",{"Récolter 15 Pétales-de-sang et retourner voir Muigin."}}
D[4142] = {"Visite à Gregan",{"Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas."}}
D[4143] = {"Brouillard maléfique",{"Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro."}}
D[4144] = {"Les pousses de Pétales-de-sang"}
D[4145] = {"Larion et Muigin",{"Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal."}}
