D[4181] = {"Ingénierie des gobelins",{"Apporter le Manuel d'ingénierie à Nixx Sprocketspring à Gadgetzan si vous souhaitez en apprendre davantage sur l'ingénierie gobeline."}}
D[4182] = {"La menace des draconiens",{"Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie."}}
D[4183] = {"Les véritables maîtres",{"Voyager jusqu'au Lakeshire et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon."}}
D[4184] = {"Les véritables maîtres",{"Voyager vers Stormwind et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon.","","Bolvar demeure dans le Donjon de Stormwind."}}
D[4185] = {"Les véritables maîtres",{"Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor."}}
D[4186] = {"Les véritables maîtres",{"Apporter le Décret de Bolvar au Magistrat Solomon au Lakeshire."}}
D[4201] = {"Le philtre d'amour",{"Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Blackrock."}}
