D[4224] = {"Les véritables maîtres",{"Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche.","","Vous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord."}}
D[4241] = {"Maréchal Windsor",{"Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor.","","Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison."}}
D[4242] = {"Espoir abandonné",{"Donner les mauvaises nouvelles au maréchal Maxwell."}}
D[4243] = {"À la poursuite d'A-mi 01",{"Trouver A-mi 01 dans le Cratère d'Un'Goro."}}
D[4244] = {"À la poursuite d'A-mi 01",{"Trouver une Caisse en mithril et retourner près de A-mi 01 dans le Cratère d'Un'Goro."}}
D[4245] = {"À la poursuite d'A-mi 01",{"Escorter A-mi 01 sur le chemin du retour jusqu'à Karna Remtravel dans le Cratère d'Un'Goro."}}
D[4261] = {"Esprit d'un ancien",{"Escorter Arei jusqu’à un lieu sûr, puis parler à Kayneth Stillwind au Chant des forêts, dans l’est d'Ashenvale."}}
D[4262] = {"Grand seigneur Pyron",{"Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig.","","Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?"}}
D[4263] = {"Incendius !",{"Trouver le Seigneur Incendius dans les Profondeurs de Blackrock et le détruire !"}}
D[4264] = {"Une Note chiffonnée",{"Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…"}}
D[4265] = {"L'évasion de la ruche",{"Libérer Raschal de la ruche de Zukk'ash.","","Revenir voir Ginro Hearthkindle au bastion de Feathermoon et lui dire que Raschal est sain et sauf."}}
D[4266] = {"Accueil d'un héros",{"Parler à Shandris Feathermoon dans le bastion de Feathermoon."}}
D[4267] = {"L'ascension des silithides",{"Apporter le Rapport de Raschal à Gracina Spiritmight à Darnassus."}}
D[4281] = {"La livraison à Thalanaar",{"Apporter le Vieux colis à Falfindel Waywarder, à Thalanaar."}}
D[4282] = {"Un espoir en lambeaux",{"Rapporter les Renseignements perdus du maréchal Windsor.","","Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne."}}
D[4283] = {"CINQUANTE ! OUI !",{"Oralius veut 50 Médaillons de Blackrock. Il y a de fortes chances de trouver ces médaillons sur les orcs des Steppes ardentes."}}
D[4284] = {"Cristaux de puissance",{"Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal."}}
D[4285] = {"Le Pylône nord",{"Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro."}}
D[4286] = {"Du beau matériel",{"Se rendre dans les Profondeurs de Blackrock et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Blackrock."}}
D[4287] = {"Le Pylône est",{"Trouver l'emplacement du Pylône de cristal est dans le Cratère d'Un'Goro."}}
D[4288] = {"Le Pylône ouest",{"Découvrir l'emplacement du Pylône de cristal ouest."}}
D[4289] = {"Les gorilles d'Un'Goro",{"Apporter 2 Peaux de gorille d'Un'Goro, 2 Peaux de marteleur d'Un'Goro et 2 Peaux de foudroyeur d'Un'Goro à Torwa Pathfinder à l'entrée du cratère d'Un'Goro."}}
D[4290] = {"La nourriture de Lar'korwi",{"Trouver la dernière victime de Lar'korwi et voler un Morceau de carcasse d'un battrodon, puis retourner voir Torwa Pathfinder au Cratère d'Un'Goro."}}
D[4291] = {"Un parfum pour Lar'korwi",{"Apporter 2 Glandes de phéromone de ravasaure à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro."}}
D[4292] = {"Un appât pour Lar'korwi",{"En utilisant le contenu de la Sacoche de Torwa, appeler Lar'korwi et le vaincre. Puis apporter la Tête de Lar'korwi à Torwa Pathfinder près de l'entrée du Cratère d'Un'Goro."}}
D[4293] = {"Un échantillon de Limon...",{"Ramasser des Echantillons de Gelée de Gangrebois sur les gelées de Gangrebois. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Undercity, déceler l'échantillon le plus corrompu. Apporter 5 Echantillons corrompus de Gangrebois au Chimiste Fuely."}}
D[4294] = {"... et un échantillon de Limon",{"Ramasser des Echantillons de Gelée d'Un'Goro sur les gelées du Cratère d'Un'Goro. Puis, en utilisant le Matériel d'expérience qui se trouve à côté du Chimiste Fuely à Undercity, déceler l'échantillon le plus pur. Apporter 5 Echantillons purs d'Un'Goro au Chimiste Fuely."}}
D[4295] = {"La bière de Rocknot"}
D[4296] = {"Tablette des Sept",{"Apporter la Transcription de la tablette à Maxwort Uberglint dans les Steppes ardentes."}}
D[4297] = {"Nourriture pour bébé",{"Apporter 5 Flancs de Traqueur Crins-d'argent à Angar Beastamer dans les Hinterlands."}}
D[4298] = {"L'amour d'un parent",{"Parler à Agnar Beastamer dans les Hinterlands."}}
D[4300] = {"Les armes aux lames d'os",{"Apporter 8 Griffes blanches de ravasaure à Jes'rimon à Orgrimmar."}}
D[4301] = {"Le puissant U'cha",{"Apporter la Peau d'U'cha à Torwa Pathfinder à l'entrée du Cratère d'Un'Goro."}}
