D[4864] = {"Les Indomptables enragés",{"Ramasser les Fournitures de Jaron dans la neige, puis trouver l'Indomptable qui a volé l'amulette dont Jaron a parlé.","","Rapporter les fournitures de Jaron et l'Amulette de la plume bleue à Jaron Stoneshaper au pavillon, dans le Berceau-de-l'Hiver."}}
D[4865] = {"Serpent sauvage",{"Faire un rapport de vos trouvailles à Motega Firemane."}}
D[4866] = {"Le lait matriarcal",{"Vous trouverez la Matriarche Couveuse au coeur du pic Blackrock. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois <empoisonné/empoisonnée>, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon."}}
D[4867] = {"Urok Hurleruine",{"Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh."}}
D[4881] = {"Complot d'assassinat",{"Prévenir Kanati Greycloud au Poste de Blanc-relais qu'un complot le menace."}}
D[4882] = {"Secrets gardés",{"Apporter le Collier de plumes bleues à Trull Failbane au Poste de la Vénéneuse."}}
D[4883] = {"Secrets gardés",{"Apporter le Collier de plumes bleues à Nara Wildmane."}}
D[4901] = {"Les gardiens de l'autel",{"Protéger Ranshalla pendant qu’elle s’efforce de réactiver l’Autel d’Elune. Faire un rapport de vos découvertes à Erelas Ambersky, au village de Rut'theran."}}
D[4902] = {"Les Indomptables d'Elune",{"Parler à l’archidruide Fandral Staghelm, à Darnassus."}}
D[4903] = {"Ordre du chef de guerre",{"Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Blackrock. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie."}}
D[4904] = {"Libre, enfin !",{"Escorter Lakota Windsong hors de la Cime de Noir-nuage, puis parler à Thalia Amberhide au Poste de Librevent."}}
D[4906] = {"Plus de corruption",{"Eridan Bluewind de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu, et Xavaric. Revenir auprès d’Eridan quand la tâche est accomplie."}}
D[4907] = {"Tinkee Steamboil",{"Parler à Tinkee Steamboil."}}
D[4921] = {"Disparition au combat",{"Trouver la femme de Mankrik puis retourner le voir à la Croisée."}}
D[4941] = {"Sagesse d'Eitrigg",{"Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.","","Vous avez déjà vu Eitrigg dans les Appartements de Thrall."}}
D[4961] = {"Purifie l'Orbe d'Orahil",{"Tuer le Démon de l’Orbe, puis parler à Tabetha."}}
D[4962] = {"Un éclat de gangrechien",{"Prendre le Rubis de Felhas et l’utiliser sur l’un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l’Esprit de gangrechien emprisonné à Menara Voidrender, dans les Tarides."}}
D[4963] = {"Eclat d'Infernal",{"Prendre l’Emeraude d'Infus et l’utiliser sur les Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l’Emeraude d'Infus et l’Esprit d'Infernal emprisonné à Menara Voidrender, dans les Tarides."}}
D[4964] = {"L'Orbe complet de Dar'Orahil",{"Attendre que Menara Voidrender termine l’Orbe de Dar'Orahil, puis lui reparler."}}
D[4965] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Voidrender dans les Tarides."}}
D[4966] = {"Protéger Kanati Greycloud",{"Protéger Kanati Greycloud contre l’attaque centaure."}}
D[4967] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Voidrender dans les Tarides."}}
D[4968] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Voidrender dans les Tarides."}}
D[4969] = {"Connaissance de l'Orbe d'Orahil",{"Parler à Menara Voidrender dans les Tarides."}}
D[4970] = {"Provisions de sabres-de-givre",{"Récolter 5 Viandes de Croc acéré et 5 Viandes de Noroît pour Rivern Frostwind du Berceau-de-l'Hiver."}}
D[4971] = {"Une question de temps",{"Utiliser le Déplaceur temporel à côté de l’un des silos d’Andorhal pour révéler des Parasites temporels.","","Tuer 15 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l’auberge d’Andorhal, dans les Maleterres de l’ouest."}}
D[4972] = {"Arrêt du temps",{"Trouver 5 Montres d'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la cité, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’ouest."}}
D[4973] = {"Arrêt du temps",{"Trouver 5 Montres d'Andorhal parmi les décombres de la cité, et les rapporter à Chromie à l’Auberge d’Andorhal, dans les Maleterres de l’ouest."}}
D[4974] = {"Pour la Horde !",{"Aller au Pic Blackrock et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar."}}
D[4975] = {"L'Orbe complet de Noh'Orahil",{"Attendre que Menara Voidrender ait terminé l’Orbe de Noh'Orahil, puis lui reparler."}}
D[4976] = {"Rapporter l'Orbe purifié",{"Rapporter l’Orbe infernal purifié à Menara Voidrender, dans les Tarides."}}
D[4981] = {"Agent Bijou",{"Aller au Pic Blackrock et découvrir ce qui est arrivé à Bijou."}}
D[4982] = {"Les effets de Bijou",{"Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville."}}
D[4983] = {"Rapport de reconnaissance de Bijou",{"Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath."}}
D[4984] = {"La faune et la flore souffrent aussi",{"Détruire 8 Loups malades, puis retourner voir Mulgris Deepriver, au Repaire putride dans les Maleterres de l’ouest."}}
D[4985] = {"La faune et la flore en souffrent aussi",{"Détruire 8 Grizzlis malades, puis retourner voir Mulgris Deepriver au Repaire putride, dans les Maleterres de l’ouest."}}
D[4986] = {"La branche de chêne à glyphes",{"D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l’assistance de l’un des druides, là-bas."}}
D[4987] = {"La branche de chêne à glyphes",{"D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Thunder Bluff. Aller solliciter l’assistance de l’un des druides, là-bas."}}
D[5001] = {"Les effets de Bijou",{"Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !"}}
D[5002] = {"Message à Maxwell",{"Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell."}}
D[5021] = {"Mieux vaut tard que jamais",{"Le discours incohérent de la femme fantomatique indique qu’elle a besoin qu’on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu’il s’agit de préciser où se trouve son cheval ou l’endroit où le paquet doit être livré."}}
D[5022] = {"Mieux vaut tard que jamais",{"Rendre visite aux Facteurs royaux de Stormwind pour apprendre l’adresse d’une certaine Emma Felstone. En général, il y a un officier du recensement à l’Hôtel de ville."}}
D[5023] = {"Mieux vaut tard que jamais",{"Se renseigner auprès des Surveillants royaux d’Undercity pour apprendre l’adresse d’un certain Jeremiah Felstone. En général, il y a un officier du recensement près du bureau d’inscription des guildes et tabards."}}
D[5041] = {"Ravitaillement pour la Croisée",{"Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides."}}
D[5042] = {"La force d’Agammagan"}
D[5043] = {"L'agilité d'Agammagan"}
D[5044] = {"La sagesse d'Agammagan"}
D[5045] = {"L'essor de l'esprit"}
D[5046] = {"Peau tranchante"}
D[5047] = {"Pépin Preste-Jugeote, à votre service !",{"Parler à Malyfous Darkhammer à Long-guet."}}
D[5048] = {"Emma la bonne pâte",{"Trouver la vieille Emma à Stormwind, et découvrir si elle est en fait Emma Felstone. Si c’est le cas, elle appréciera peut-être le colis que Janice Felstone lui a préparé."}}
D[5049] = {"Le blues de Jeremiah",{"Trouver Jeremiah Payson dans Undercity et découvrir s’il est en fait Jeremiah Felstone. Si c’est le cas, il appréciera peut-être le colis que Janice Felstone lui a préparé."}}
D[5050] = {"Charme porte-bonheur",{"Rapporter son Demi-charme porte-bonheur à Janice Felstone dans les Maleterres de l’ouest."}}
D[5051] = {"Deux moitiés deviennent Une",{"Trouver l’autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Felstone dans les Maleterres de l’ouest et le recoller.","","Donner le Charme porte-bonheur à Janice Felstone à la Ferme Felstone, dans les Maleterres de l’ouest."}}
D[5052] = {"Joyaux de sang d'Agammagan",{"Apporter un Joyau de sang à Mangletooth, à Camp Taurajo, dans les Tarides.","","Collectez plus de Joyaux de sang, si vous souhaitez qu’il vous gratifie de la puissance d’Agamaggan."}}
D[5054] = {"Ursius des Crocs acérés",{"Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Ursius."}}
D[5055] = {"Brumeran des Noroît",{"Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Brumeran."}}
D[5056] = {"Shy-Rotam",{"Storm Shadowhoof, à Long-guet au Berceau-de-l'Hiver, veut que vous triomphiez de Shy-Rotam."}}
D[5057] = {"Essais passés",{"Apporter le Marqueur de Storm Shadowhoof à Melor Stonehoof à Thunder Bluff."}}
D[5058] = {"Journal de Mme Dalson"}
D[5059] = {"Enfermé"}
D[5060] = {"Enfermé"}
D[5061] = {"Forme aquatique",{"Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Bearwalker."}}
D[5062] = {"Feu sacré",{"Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Grimtotem sur la Cime des Anciens dans Thunderbluff."}}
D[5063] = {"La coiffe du savant écarlate",{"Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés.","","Il faudra aussi payer 50 pièces d’or pour le travail de fabrication."}}
D[5064] = {"Espionner le Totem sinistre",{"Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage."}}
D[5065] = {"Les tablettes perdues de Mosh'aru",{"Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris."}}
D[5066] = {"Un appel aux armes : les Maleterres",{"Trouver le commandant Ashlam Valorfist. Son camp de base est situé au camp du Noroît, au nord des montagnes d'Alterac."}}
D[5067] = {"Jambières d'Arcana",{"Pour fabriquer les Jambières d'Arcana, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Fluides d'embaumement de Murmegivre.","","Il faudra également payer 50 pièces d’or pour le travail de fabrication."}}
D[5068] = {"La cuirasse carnassière",{"Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Darkhammer : 1 Peau de la Bête en parfait état ; 10 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Peaux des ombres.","","Il faudra également payer 50 pièces d’or pour le travail de fabrication."}}
D[5081] = {"Mission de Maxwell",{"Se rendre au Pic Blackrock et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie."}}
D[5082] = {"La menace des Tombe-hiver",{"Donova Snowden du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver."}}
D[5083] = {"L'eau de feu de Tombe-hiver",{"Apporter le Flacon d'eau de feu vide à Donova Snowden du Berceau-de-l'Hiver."}}
D[5084] = {"Corrompu",{"Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois."}}
D[5085] = {"Gelée mystère",{"Aller faire un rapport de vos trouvailles à Donova Snowden."}}
D[5086] = {"Horreurs toxiques",{"Récolter 3 Gouttelettes d'Horreur toxique pour Donova Snowden au Berceau-de-l'Hiver."}}
D[5087] = {"Les messagers des Tombe-hiver",{"Trouver les Messagers Tombe-hiver et les empêcher de livrer leur cargaison au village Tombe-hiver."}}
D[5088] = {"Arikara",{"Tuer Arikara. Rapporter sa dépouille et de la poudre d’incendia à Motega Firemane au Poste de Blanc-relais comme preuve de votre acte."}}
D[5089] = {"Ordres du général Drakkisath",{"Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes."}}
D[5090] = {"Un appel aux armes : les Maleterres",{"Trouver le commandant Ashlam Valorfist. Son camp de base est le Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5091] = {"Un appel aux armes : les Maleterres",{"Trouver le commandant Ashlam Valorfist. Il s'est établi au Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5092] = {"Nettoyer le passage",{"Tuer 10 Ecorcheurs Squelettes et 10 Goules écumantes sur la Colline des chagrins.","","Retourner auprès du commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5093] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et d’Undercity."}}
D[5094] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et d’Undercity."}}
D[5095] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l’est des Clairières de Tirisfal et d’Undercity."}}
D[5096] = {"Diversions écarlates",{"Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Felstone et les Larmes de Dalson et détruire leur tente d’état-major.","","Placer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest."}}
D[5097] = {"Tout au long des tours de guet",{"À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.","","Quand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Valorfist au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5098] = {"Tout au long des tours de guet",{"À l’aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l’embrasure de la porte de la tour pour pouvoir la marquer.","","Quand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l’ouest."}}
D[5102] = {"La reddition du général Drakkisath",{"Rendez-vous au Pic Blackrock et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell."}}
D[5103] = {"Mort brûlante",{"Quelqu’un dans ce monde doit bien savoir à quoi servent ces gantelets. Bonne chance !"}}
D[5121] = {"Le grand chef Tombe-hiver",{"Donova Snowden du Berceau-de-l'Hiver veut que vous triomphiez du Grand chef Tombe-hiver."}}
D[5122] = {"Le médaillon de foi"}
D[5123] = {"Le dernier morceau",{"Apporter le Journal mal écrit à Donova Snowden au Berceau-de-l'Hiver."}}
D[5124] = {"Gantelets en plaque de feu",{"Apporter à Malyfous Darkhammer 6 Barres de thorium enchanté, 2 Essences de feu, et 4 Rubis stellaires. Lui remettre également vos Gantelets en plaques inachevés."}}
D[5125] = {"L'estimation d'Aurius"}
D[5126] = {"L'histoire de Lorax",{"Parler à Lorax. Écouter ce qu’il a à dire."}}
D[5127] = {"La forge démoniaque",{"Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.","","Trouver aussi la Cuirasse couverte de runes inachevée.","","Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver."}}
D[5128] = {"Paroles du Grand Chef",{"Rapporter le Journal mal écrit à Kelek Skykeeper dans le sud de Gangrebois."}}
D[5141] = {"Travail du cuir de dragon",{"Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Peter Galen, à Azshara.","","Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.","","Terminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision."}}
D[5142] = {"La petite Pamela",{"Retrouver Pamela Redpath."}}
D[5143] = {"Travail du cuir tribal",{"Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Caryssia Moonhunter en Feralas.","","L’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.","","L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix."}}
D[5144] = {"Travail du cuir élémentaire",{"Apporter 2 Coeurs de feu, 2 Globes d’eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants.","","L’accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire.","","L’accomplissement de cette quête vous empêchera d’apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix."}}
D[5145] = {"Travail du cuir de dragon",{"Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Thorkaf Dragoneye, dans les Terres ingrates.","","Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.","","Terminer cette quête avec succès vous interdira l’apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision."}}
D[5146] = {"Travail du cuir élémentaire",{"Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Winterhoof dans les montagnes d’Arathi.","","L’accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.","","L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix."}}
D[5147] = {"On recherche : Arnak Grimtotem",{"Tuer Arnak Grimtotem et apporter une preuve de votre acte au garde-falaise Longhorn au Poste de Librevent."}}
D[5148] = {"Travail du cuir tribal",{"Apporter un Gilet en cuir sauvage et un Casque en cuir sauvage à Se'Jib dans la vallée de Strangleronce.","","L’accomplissement de cette quête donne accès aux arts du travail du cuir tribal.","","L’accomplissement de cette quête vous empêchera d’apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l’on veut suivre avant de faire ce choix."}}
D[5149] = {"Poupée de Pamela",{"Trouver la poupée de Pamela."}}
D[5150] = {"Dadanga a faim !"}
D[5151] = {"Hypercapaciteur bidulotron",{"Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthèse à Wizlo Bearingshiner."}}
D[5152] = {"Tante Marlene",{"Parler à Marlene, au sud des ruines d'Andorhal."}}
D[5153] = {"Un étrange historien",{"Apporter l’Alliance de Joseph à Chromie."}}
D[5154] = {"Les annales de Darrowshire",{"Apporter les Annales de Darrowshire à Chromie, à Andorhal."}}
D[5155] = {"Les forces de Jaedenar",{"Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Mosshoof dans Gangrebois."}}
D[5156] = {"Enquête sur la corruption",{"Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d’eau corrompue, retourner auprès de Taronn Redfeather dans Gangrebois."}}
D[5157] = {"Recueillir de l'eau souillée",{"Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Mosshoof dans Gangrebois."}}
D[5158] = {"À la recherche de soutien spirituel",{"Apporter l’Eau de Puits de lune corrompue à Islen Waterseer dans les Tarides."}}
D[5159] = {"L'eau purifiée retourne à Gangrebois",{"Apporter l’Eau de Puits de lune purifiée à Greta Mosshoof dans Gangrebois."}}
D[5160] = {"Le Protectorat de la matrone",{"Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee."}}
D[5161] = {"La colère du vol bleu",{"Si vous souhaitez continuer, parlez à Haleh."}}
D[5162] = {"La colère du vol bleu",{"Parler à Jeziba dans les Maleterres. Il vit à Andorhal."}}
D[5163] = {"Yéti ? Y es-tu ?",{"Prendre le yéti mécanique d'Umi et effrayer ses amis avec :","","Legacki, à Long-guet (Berceau-de-l'Hiver)","Sprinkle, à Gadgetzan (Tanaris)","Quixxil, au refuge des Marshal (Cratère d'Un'Goro)","","Quand vous aurez terminé, rapporter le yéti mécanique à Umi."}}
D[5164] = {"Guide de l'Indocile",{"Lire le Guide de l'Indocile."}}
D[5165] = {"En calmant les flammes de protection",{"Avec de l’Eau de Puits de lune purifiée, éteindre les flammes des quatre braseros de protection à l’intérieur du Fort des ombres dans Gangrebois."}}
D[5166] = {"La cuirasse du vol chromatique",{"Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' :","","1 Carapace chromatique.","","10 Ecailles chromatiques brillantes.","","10 Sangs de héros.","","10 Coutures d'Abomination effilochées."}}
D[5167] = {"Cuissardes des duellistes chromatiques",{"Pour forger les Cuissardes des duellistes chromatiques, il faut apporter les éléments suivants à Jeziba le 'Sculpteur' :","","1 Carapace chromatique.","","10 Ecailles chromatiques brillantes.","","10 Sangs de héros.","","5 Peaux des ombres."}}
D[5168] = {"Héros du Darrowshire",{"Apporter le Libram de Davil et le Bouclier Redpath à Carlin Redpath."}}
D[5181] = {"Vilains de Darrowshire",{"Rapporter le Crâne d'Horgus et l’Epée brisée de Marduk à Carlin Redpath à la chapelle de l'Espoir de Lumière."}}
D[5201] = {"L'incursion des Tombe-hiver",{"Rivern Frostwind veut que vous tuiez 5 Chamans Tombe-hiver et 5 Ursas Tombe-hiver."}}
D[5202] = {"Une étrange clé rouge",{"Chercher dans Jaedenar à quoi sert la Clé rouge sang."}}
D[5203] = {"Sauvetage à Jaedenar",{"Escorter Arko'narin à l’endroit où Lightforge et son équipement sont détenus, puis la protéger lors de l’évasion du Fort des ombres. Ensuite, aller trouver Jessir Moonbow dans Gangrebois pour lui apprendre ce qui est arrivé à ses amis."}}
D[5204] = {"Le châtiment de la Lumière",{"Revenir à Jaedenar et tuer la succube Rakaiah avant de trouver le Cadavre de Trey Lightforge."}}
D[5206] = {"Les maraudeurs du Darrowshire",{"Apporter 5 Crânes résonants et le Cristal mystique à Carlin Redpath, dans les Maleterres de l’est."}}
D[5210] = {"Frère Carlin",{"Apporter les Annales complètes de Darrowshire à Carlin Redpath dans les Maleterres de l’est."}}
D[5211] = {"Défenseurs de Darrowshire",{"Libérer 15 Esprits de Darrowshire et retourner auprès de Carlin Redpath."}}
D[5212] = {"La chair ne ment pas",{"Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair."}}
D[5213] = {"L'agent actif",{"Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink."}}
D[5214] = {"Le grand Ezra Grimm",{"Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait."}}
D[5215] = {"Les chaudrons du Fléau",{"Parler à la grande prêtresse MacDonnell à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5216] = {"Cible : le Champ de Felstone",{"Se rendre au Champ de Felstone dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron."}}
D[5217] = {"Retour au camp du Noroît",{"Apporter une Bouteille du Champ de Felstone remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5218] = {"Le Chaudron du champ de Felstone"}
D[5219] = {"Cible : les Larmes de Dalson",{"Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron."}}
D[5220] = {"Retour au camp du Noroît",{"Apporter la Bouteille des Larmes de Dalson remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5221] = {"Chaudron des Larmes de Dalson"}
D[5222] = {"Cible : le Repaire putride",{"Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron."}}
D[5223] = {"Retour au camp du Noroît",{"Apporter la Bouteille du Repaire putride remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5224] = {"Le Chaudron du Repaire putride"}
D[5225] = {"Cible : la Flétrissure de Gahrron",{"Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron."}}
D[5226] = {"Retour au camp du Noroît",{"Apporter la Bouteille de la Flétrissure de Gahrron remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5227] = {"Chaudron de la Flétrissure de Gahrron"}
D[5228] = {"Les chaudrons du Fléau",{"Parler à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5229] = {"Cible : le Champ de Felstone",{"Se rendre au Champ de Felstone, dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve. Il aura peut-être une clé qui permet d’accéder au chaudron. Il faut se munir de la Bouteille d'échantillon du Champ de Felstone vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron."}}
D[5230] = {"Retour à la Barricade",{"Apporter la Bouteille du Champ de Felstone remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5231] = {"Cible : les Larmes de Dalson",{"Se rendre aux Larmes de Dalson dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron."}}
D[5232] = {"Retour à la Barricade",{"Apporter la Bouteille des Larmes de Dalson remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5233] = {"Cible : le Repaire putride",{"Se rendre au Repaire putride dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide du Repaire putride pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron."}}
D[5234] = {"Retour à la Barricade",{"Ramener la Bouteille du Repaire putride remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5235] = {"Cible : la Flétrissure de Gahrron",{"Se rendre à la Flétrissure de Gahrron dans les Maleterres de l’ouest pour trouver et vaincre le Seigneur du Chaudron qui s’y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille vide de la Flétrissure de Gahrron pour pouvoir récupérer un échantillon des poisons à l’intérieur du chaudron."}}
D[5236] = {"Retour à la Barricade",{"Apporter la Bouteille de la Flétrissure de Gahrron remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l’ouest."}}
D[5237] = {"Mission accomplie !"}
D[5238] = {"Mission accomplie !"}
D[5241] = {"Oncle Carlin",{"Trouver Carlin Redpath."}}
D[5242] = {"Un coup final",{"Tuer Moora et Salia, et rapporter la Tête du Seigneur des ténèbres Fel'dan à Greta Mosshoof dans Gangrebois."}}
D[5243] = {"Les demeures du Sacré",{"Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni."}}
D[5244] = {"Les ruines de Kel'Theril",{"Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles"}}
D[5245] = {"Les Esprits troublés de Kel'Theril",{"Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est."}}
D[5246] = {"Fragments du passé",{"Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est."}}
D[5247] = {"Fragments du passé",{"Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est."}}
D[5248] = {"Tourmentée par le passé",{"Amener le Cristal de Zin-Malor au lac Kel'Theril dans le Berceau-de-l'Hiver et trouver un esprit Bien-né qui veuille bien vous parler."}}
D[5249] = {"Au Berceau-de-l'Hiver",{"Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver, et parler à Wynd Nightchaser."}}
D[5250] = {"Pluie-d'Etoiles",{"Trouver le village de Pluie-d'Etoiles dans le Berceau-de-l'Hiver et parler à Wynd Nightchaser."}}
D[5251] = {"L'archiviste",{"Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates."}}
D[5252] = {"Une Bien-née pleine de remords",{"Parler à Wynd Nightchaser au village de Pluie-d'Etoiles et lui demander quel est le bon endroit pour le Cristal de Zin-Malor."}}
D[5253] = {"Le Cristal de Zin-Malor",{"Apporter le Cristal de Zin-Malor à l’archidruide Fandral Staghelm à Darnassus."}}
D[5261] = {"Eagan le tanneur",{"Parler à Eagan Peltskinner."}}
D[5262] = {"La vérité vient du ciel",{"Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est."}}
D[5263] = {"Au-dessus et au-delà",{"S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff."}}
D[5264] = {"Seigneur Maxwell Tyrosus",{"Parler au seigneur Maxwell Tyrosus. Il est à l’intérieur de l’église."}}
D[5265] = {"Siège de l’Aube d'argent",{"Ouvrir le Coffre prendre votre récompense."}}
D[5281] = {"Âmes tourmentées",{"Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme."}}
D[5282] = {"Âmes tourmentées",{"Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres !","","Libérer 15 Esprits sans repos puis retourner auprès d’Egan."}}
D[5283] = {"L'art de l'armurier",{"Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants et les rapporter à Grumnus : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril."}}
D[5284] = {"La voie du Forgeron d'armes",{"Pour devenir un Fabricant d'armes, il faut fabriquer les éléments suivants et les rapporter à Ironus : 4 Epées d'acier lunaire, 4 Gigantesques haches en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires."}}
D[5301] = {"L'art de l'armurier",{"Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants puis les apporter à Okothos : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril."}}
D[5302] = {"La voie du Forgeron d'armes",{"Pour devenir un Fabricant d'armes, vous devez fabriquer les éléments suivants et les rapporter à Borgosh : 4 Epées d'acier lunaire, 4 Gigantesques haches en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires."}}
D[5305] = {"Douce sérénité",{"Aller jusqu’à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le ramener à Lilith."}}
D[5306] = {"Pierre du serpent de la chasseresse des ombres",{"Aller jusqu’au Pic Blackrock et abattre la chasseresse des ombres Vosh'gajin. Récupérer la Pierre du serpent de Vosh'gajin et la ramener à Kilram."}}
D[5307] = {"Corruption",{"Trouver le Fabricant d'épées de la Garde noire à Stratholme et le tuer. Récupérer l’Insigne de la Garde noire et retourner auprès de Seril Scourgebane."}}
D[5321] = {"Le dormeur s'est éveillé",{"Escorter Kerlonian Evershade jusqu’à Liladris Moonriver au Poste de Maestra à Ashenvale."}}
D[5341] = {"Fortune de la famille Barov",{"S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d’Alexi Barov quand la tâche est accomplie."}}
D[5342] = {"Le dernier Barov",{"Voyagez jusqu’au Camp du Noroît, dans le territoire de l’Alliance, et y assassiner Weldon Barov. Prenez sa tête et revenez auprès d’Alexi Barov.","","Attention : Weldon sera probablement bien protégé par la racaille de l’Alliance."}}
D[5343] = {"Fortune de la famille Barov",{"S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès de Weldon Barov quand la tâche est accomplie."}}
D[5344] = {"Le dernier Barov",{"Voyager jusqu’à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.","","Attention : Alexi sera probablement bien protégé par les vandales de la Horde."}}
D[5361] = {"Arbre familial",{"Apporter le Rapport du garde-falaise Longhorn à Nataka Longhorn au poste de Rôdeur-fantôme en Désolace."}}
D[5381] = {"La Main d'Iruxos",{"Récupérer la Boîte démoniaque dans la forteresse de Hache-Tonnerre, puis la rapporter à Taiga Wisemane, à Proie-de-l'Ombre."}}
D[5382] = {"Docteur Theolen Krastinov, le boucher",{"Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie."}}
D[5384] = {"Kirtonos le héraut",{"Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.","","Combattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff."}}
D[5385] = {"Les restes de Trey Lightforge",{"Rapporter le Cadavre de Trey Lightforge à Jessir Moonbow dans Gangrebois."}}
D[5386] = {"La prise du jour",{"Parler à Jinar'Zillen à Proie-de-l'Ombre, puis amener 2 poissons Ventre-rouge à Nataka Longhorn."}}
D[5401] = {"Brevet de l'Aube d'argent"}
D[5402] = {"Pierres du Fléau des serviteurs"}
D[5403] = {"Pierres du Fléau des envahisseurs"}
D[5404] = {"Pierres du Fléau des corrupteurs"}
D[5405] = {"Brevet de l'Aube d'argent"}
D[5406] = {"Pierres du Fléau des corrupteurs"}
D[5407] = {"Pierres du Fléau des envahisseurs"}
D[5408] = {"Pierres du Fléau des serviteurs"}
D[5421] = {"Poisson dans un seau"}
D[5441] = {"Les péons paresseux",{"Utiliser la Masse du contremaître sur les Péons paresseux, lorsqu’ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Masse du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves."}}
D[5461] = {"L'humain, Ras Murmegivre",{"Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke."}}
D[5462] = {"Le moribond, Ras Murmegivre",{"Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert."}}
D[5463] = {"Le cadeau de Menethil",{"Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie."}}
D[5464] = {"Le cadeau de Menethil",{"Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est."}}
D[5465] = {"Souvenir lié",{"Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié."}}
D[5466] = {"La Liche, Ras Murmegivre",{"Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke."}}
D[5481] = {"La tâche de Gordo",{"Récolter 3 herbes des ténèbres et les apporter à l’Apprenti Apothicaire Holland au cimetière de Brill."}}
D[5482] = {"Herbe maléfique",{"Récolter 10 Herbes maléfiques et les apporter à l’apprenti apothicaire Holland."}}
D[5501] = {"Collectionneur d'os",{"Apporter à Bibbly F'utzbuckle à la Hutte de Kormek 10 Os de kodo provenant du Cimetière des kodos."}}
D[5502] = {"Un surveillant de la Horde",{"Ramenez votre protégé à l'orphelinat d'Orgrimmar, en rendant le sifflet d'orphelin orc à la gouvernante de l'orphelinat, Battlewail, dans la Vallée de l'Honneur."}}
D[5503] = {"Brevet de l'Aube d'argent"}
D[5504] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l’Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l’ouest"}}
D[5505] = {"La clé de Scholomance"}
D[5507] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l’Aube d'argent au quartier-maître Lightspark au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5508] = {"Pierres du Fléau des corrupteurs"}
D[5509] = {"Pierres du Fléau des envahisseurs"}
D[5510] = {"Pierres du Fléau des serviteurs"}
D[5511] = {"La clé de Scholomance"}
D[5513] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l’Aube d'argent à l'intendante Breechlock, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l’est."}}
D[5514] = {"Moisissure rime avec…",{"Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan."}}
D[5515] = {"Sac des horreurs de Krastinov",{"Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff."}}
D[5517] = {"Le mantelet de l'aube Chromatique",{"Apporter 25 Marques de valeur de l’Aube d'argent à l'intendante Breechlock, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l’est."}}
D[5518] = {"La tenue d'ogre gordok",{"Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Knot Thimblejack. Il est actuellement enchaîné dans l’aile Gordok de Hache-tripes."}}
D[5519] = {"La tenue d'ogre gordok"}
D[5521] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l’Aube d'argent au quartier-maître Lightspark au camp du Noroît, dans les Maleterres de l’ouest."}}
D[5522] = {"Leonid Barthalomew",{"Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l’est."}}
D[5524] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l’Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l’ouest."}}
D[5525] = {"Libérez Knot !"}
D[5526] = {"Fragment de la Gangrevigne",{"Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit."}}
D[5527] = {"Un reliquaire de pureté",{"Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune."}}
D[5528] = {"La dégustation gordok"}
D[5529] = {"Portée contaminée",{"Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière."}}
D[5531] = {"Betina Bigglezink",{"Apporter les Oeufs congelés à Betina Bigglezink."}}
D[5533] = {"Scholomance",{"Parler à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5534] = {"L'équipement \"manquant\" de Kim'jael",{"Trouver \"une rune\" détenue par les nagas dans les ruines d’Eldarath et la rapporter à Kim'jael à Azshara."}}
D[5535] = {"Agitation spirituelle",{"Détruire 6 Apparitions de Bien-nés et 6 Jeunes liches bien-nées avant de retourner auprès de Loh'atu à Azshara."}}
D[5536] = {"Un pays plein de haine",{"Tuer 6 satyres Haldarr, 2 Entourloupeurs Haldarr, 2 Lige de la corruption Haldarr puis revenir auprès de Loh'atu à la frontière d’Ashenvale."}}
D[5537] = {"Fragments de squelette",{"Apporter 15 Fragments de squelette à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5538] = {"Moisissure rime avec…",{"Apporter les Fragments de squelette imprégnés et 15 pièces d’or à Krinkle Goodsteel à Gadgetzan."}}
D[5541] = {"Munitions pour Rumbleshot",{"Apporter les Munitions de Rumbleshot à Hegnar Rumbleshot à Dun Morogh."}}
D[5542] = {"Chiens-démons",{"Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring, quand la mission sera terminée."}}
D[5543] = {"Ciel couleur de sang",{"Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring."}}
D[5544] = {"Larve putride",{"Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées."}}
D[5545] = {"Un sac d'embrouilles",{"Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est."}}
D[5561] = {"Le rassemblement des kodos",{"Ramener cinq Kodos domptés et le Kombobulateur kodo à Smeed Scrabblescrew au camp de Scrabblescrew."}}
D[5581] = {"Les portails de la Légion",{"Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Wisemane, à Proie-de-l'Ombre."}}
D[5582] = {"L'écaille de dragon luisante",{"Apporter l’Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l’Espoir de Lumière dans les Maleterres de l’est."}}
D[5601] = {"Pamela, ma sœur",{"Trouver Pamela Redpath dans le Darrowshire."}}
D[5621] = {"Vêtements de la lune",{"Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Morninglight, à Dolanaar."}}
D[5622] = {"Au service d'Elune",{"Parler à Laurna Morninglight à Teldrassil."}}
D[5623] = {"Au service de la Lumière",{"Parler à la prêtresse Josetta dans la Forêt d’Elwynn."}}
D[5624] = {"Vêtements de la Lumière",{"Trouver le garde Roberts et soigner ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir la prêtresse Josetta, à Goldshire."}}
D[5625] = {"Vêtements de la Lumière",{"Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos."}}
D[5626] = {"Au service de la Lumière",{"Parler à Maxan Anvol à Dun Morogh."}}
