D[5713] = {"Un tir. Un tué",{"Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Ashenvale."}}
D[5721] = {"La bataille du Darrowshire",{"Placer la Liasse de reliques sur la place centrale de Darrowshire.","","Empêcher la mort de Davil Lightfire, jusqu’à la mort de Horgus.","","Empêcher la mort du capitaine Redpath, jusqu’à ce que Redpath le Corrompu apparaisse.","","Vaincre Redpath le Corrompu.","","Parler à l’esprit de Joseph Redpath, quand il apparaît sur la place centrale, puis parler à Pamela, dans sa maison."}}
D[5722] = {"À la recherche de la sacoche perdue",{"Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant."}}
D[5723] = {"Tester la force de l'ennemi",{"Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff."}}
D[5724] = {"Rapporter la sacoche perdue",{"Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff."}}
D[5725] = {"Le pouvoir de détruire...",{"Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Undercity."}}
D[5726] = {"Ennemis cachés",{"Apporter un Insigne de lieutenant à Thrall à Orgrimmar."}}
D[5727] = {"Ennemis cachés",{"Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar."}}
D[5728] = {"Ennemis cachés",{"Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar."}}
D[5729] = {"Ennemis cachés",{"Parler à Neeru Fireblade à Orgrimmar."}}
D[5730] = {"Ennemis cachés",{"Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris."}}
D[5741] = {"Sceptre de lumière",{"Prendre le Sceptre de lumière et le rapporter à Azore Aldamort, dans la tour d’Ethel Rethor."}}
D[5742] = {"Rédemption",{"Écouter ce que Tirion Fordring a à dire."}}
D[5761] = {"Tuer la bête",{"Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar."}}
D[5762] = {"Hemet Nesingwary",{"Apporter la Caisse de Kravel à Hemet Nesingwary, à Strangleronce."}}
D[5763] = {"Chasse à Strangleronce",{"Apporter la Corne de kodo de Roon à Hemet Nesingwary à Strangleronce."}}
D[5781] = {"Aux mémoires perdues",{"Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission."}}
D[5801] = {"Forgée dans la Fournaise",{"Emporter le Moule de Clé squelette et 2 Barres de thorium au sommet de la crête de la Fournaise dans le cratère d’Un'Goro. Utiliser le Moule de Clé squelette au lac de lave pour forger la Clé squelette inachevée.","","Apporter la Clé squelette inachevée à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5802] = {"Forgée dans la Fournaise",{"Prendre le moule de la Clé squelette et deux barres de thorium au sommet de la crête de la Fournaise dans le cratère d'Un'Goro. Se servir du moule de la Clé squelette pour forger la Clé squelette inachevée.","","Apporter la Clé squelette inachevée à l'Apothicaire Dithers à la Barricade, Maleterres de l'Ouest."}}
D[5803] = {"Le Scarabée d'Araj",{"Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."}}
D[5804] = {"Le Scarabée d'Araj",{"Vaincre Araj l'Invocateur et apporter le Scarabée d'Araj à l’apothicaire Dithers à la Barricade, dans les Maleterres de l’ouest."}}
D[5805] = {"Bienvenue !",{"Apporter le Bon-cadeau (Northshire) à Merissa Stilwell."}}
D[5821] = {"Garde du corps à recruter",{"Escorter la Caravane de Gizelton et l’aider à passer le village des centaures Kolkar. Parler à Smeed, au camp de Scrabblescrew, pour toucher la récompense."}}
D[5841] = {"Bienvenue !",{"Apporter le Bon-cadeau (Vallée des Frigères) à Yori Crackhelm."}}
D[5842] = {"Bienvenue !",{"Apporter le Bon-cadeau (Sombrevallon) à Orenthil Whisperwind."}}
D[5843] = {"Bienvenue !",{"Apporter le Bon-cadeau (Vallée des Epreuves) à Magga."}}
D[5844] = {"Bienvenue !",{"Apporter le Bon-cadeau (Camp Narache) à Vorn Skyseer."}}
D[5845] = {"De l'honneur perdu",{"Se rendre à Valnord, dans la région nord-est des Maleterres de l’est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie."}}
D[5846] = {"L'amour et la famille",{"Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau."}}
D[5847] = {"Bienvenue !",{"Apporter le Bon-cadeau (Le Glas) à Claire Willower, au Glas."}}
D[5848] = {"De l'amour et de la famille",{"Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles.","","Rapporter le tableau à Tirion Fordring."}}
D[5861] = {"Trouver Myranda",{"Se rendre au tombeau d’Uther, au sud des Maleterres. Montrer à Myranda la Mégère le Don de Tirion."}}
D[5862] = {"Le subterfuge écarlate",{"Parler à Myranda pour obtenir l’Illusion écarlate. Aller à Hearthglen pendant que vous êtes sous l’effet de l’Illusion écarlate, et apporter le Don de Tirion au généralissime Taelan Fordring.","","Hearthglen se trouve au nord, et Taelan devrait se trouver à l’intérieur du Donjon de Mardenholde."}}
D[5863] = {"La base des Cognedunes",{"Andi Lynn de Gadgetzan veut que vous détruisiez la Base des Cognedunes en tuant 10 Brutes Cognedunes, 10 Massacreurs Cognedunes, et Gor'marok le Ravageur."}}
D[5881] = {"Puiser dans les réserves",{"Maggran voudrait que vous apportiez une lettre à Grish Longrunner, à la Grande élévation, dans les Tarides."}}
