D[5929] = {"L'esprit du Grand ours",{"Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune."}}
D[5930] = {"Esprit du Grand ours",{"Aller voir l'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu'il peut vous enseigner sur la nature de l'ours. Quand cela est fait, retourner voir Dendrite Starblaze, à Havrenuit, dans Reflet-de-Lune."}}
D[5931] = {"Retour à Darnassus",{"Retourner à Darnassus et parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne."}}
D[5932] = {"Retour vers Thunder Bluff",{"Retourner à Thunder Bluff, et parler à Turak Runetotem, sur la Cime des Anciens."}}
D[5941] = {"Retourner voir Chromie",{"Apporter la Liasse de reliques à Chromie, à Andorhal."}}
D[5942] = {"Trésors cachés",{"Utiliser la Clé de Joseph sur le Coffre de Joseph."}}
D[5943] = {"La caravane de Gizelton",{"Escorter la caravane de Gizelton à travers le convent de Mannoroc. Parler à Smeed, au camp de Scrabblescrew, pour toucher la récompense."}}
D[5944] = {"En rêves",{"Escortez Taelan Fordring jusqu'à la sortie des Hearthglen."}}
D[5961] = {"Le champion de la reine banshee",{"Parler à Nathanos le Flétrisseur, dans les Maleterres de l’est. Il se trouve actuellement à la ferme des Marris."}}
D[5981] = {"Géants déchaînés",{"Rivern Frostwind voudrait que vous tuiez 4 Géants Cognegivre et 4 Protecteurs Cognegivre."}}
D[6001] = {"Corps et cœur",{"Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d’Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.","","Quand cela est fait, parler à Mathrengyl Bearwalker, à Darnassus."}}
D[6002] = {"Corps et cœur",{"Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu’il possède.","","Quand cela est fait, parler à Turak Runetotem, à Thunder Bluff."}}
D[6004] = {"Un travail inachevé",{"Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Krista Deepshadow dans les Maleterres de l'ouest."}}
D[6021] = {"Zaeldarr le Banni",{"Apporter la Tête de Zaeldarr au Conservateur Alen, à la chapelle de l'Espoir de Lumière."}}
D[6022] = {"Tuer utile",{"Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée."}}
D[6023] = {"Un travail inachevé",{"Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest."}}
D[6024] = {"L'appel d'Hameya",{"Tuer l’Infiltrateur Hameya. Utiliser sa clé sur le Monticule de poussière, derrière le caveau de Zaeldarr."}}
D[6025] = {"Un travail inachevé",{"Aller dans Hearthglen, et trouver un poste d’observation élevé d’où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Deepshadow, dans les Maleterres de l’ouest."}}
D[6026] = {"Cela demande beaucoup",{"Smokey LaRue veut que vous lui apportiez 2 Barres de thorium, 1 Bâtonnet doré, 8 Bombes explosives et 8 Déclencheurs instables.","","Vous devrez trouver un forgeron et un ingénieur pour obtenir ces objets."}}
D[6027] = {"Le Livre des Anciens",{"Obtenir le Livre des Anciens, puis le rapporter à Azore Aldamort, dans la tour d’Ethel Rethor."}}
D[6028] = {"Le rapport de Long-guet",{"Apportez le Rapport de Long-guet à l'officier de l'Aube d'argent Pureheart au Camp du Noroît, dans les Maleterres de l'ouest."}}
D[6029] = {"Le rapport de Long-guet",{"Livrer le Rapport de Long-guet à l’officier Garush de l'Aube d'argent, à la Barricade, dans les Maleterres de l’ouest."}}
D[6030] = {"Le duc Nicholas Zverenhoff",{"Apportez le livre \" Etudes sur la langue des Esprits \" au duc Nicholas Zverenhoff, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."}}
D[6031] = {"L'étoffe runique",{"Apportez 30 pièces d'étoffe runique à Meilosh au Repaire des Grumegueules."}}
D[6032] = {"Le vêtement sacré",{"Apporter 2 pièces d’Etoffe lunaire à Meilosh, au Repaire des Grumegueules."}}
D[6041] = {"Quand Smokey chante, je deviens violent",{"Aller à Pestebois, au nord-ouest de la chapelle de l'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.","","Une fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.","","Garder en tête que le Mélange spécial de Smokey est très... instable."}}
D[6042] = {"Les petits soucis de la non-vie",{"Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait."}}
D[6061] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, au village Bloodhoof."}}
D[6062] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline."}}
D[6063] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar."}}
D[6064] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Wildheart, à Kharanos."}}
D[6065] = {"La voie du chasseur",{"Parler à Yaw Sharpmane, au village Bloodhoof."}}
D[6066] = {"La voie du chasseur",{"Parler à Yaw Sharpmane, au village Bloodhoof."}}
