D[6087] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Traqueur des prairies. S'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, au village Bloodhoof."}}
D[6088] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Rapace. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Sharpmane, au village Bloodhoof."}}
D[6089] = {"Entraîner la bête",{"Parler à Holt Thunderhorn, sur la Cime des Chasseurs, à Thunder Bluff."}}
D[6101] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Rôdeur sabre-de-nuit. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar."}}
D[6102] = {"Dompter la bête",{"Utiliser le Bâtonnet de domptage pour dompter un Hurleur Strigid. S’entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar."}}
D[6103] = {"Entraîner la bête",{"Parler à Jocaste, à l'enclave cénarienne de Darnassus."}}
D[6121] = {"Nouvelles leçons",{"Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit."}}
D[6122] = {"Le principe originel",{"Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d’eau, à l’entrée de la grotte, à proximité des Chutes.","","Apporter la Fiole d'échantillon des Chutes de la Bondissante remplie à Alanndarian Nightsong, à Auberdine, dans Sombrivage."}}
D[6123] = {"Rassembler les ingrédients du remède",{"Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Nightsong, à Auberdine ; elle pourra ainsi commencer à préparer son remède."}}
D[6124] = {"Soigner la maladie",{"Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d’abord entre le sud de la rivière Bondissante et le nord d’Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d’Ashenvale."}}
D[6125] = {"Pouvoir contre le poison",{"Retourner voir Mathrengyl Bearwalker, dans l’Enclave cénarienne, à Darnassus."}}
D[6126] = {"Nouvelles leçons",{"Aller à Reflet-de-Lune, et parler à Dendrite Starblaze, au village de Havrenuit."}}
D[6127] = {"Le principe originel",{"Utiliser la Fiole d'échantillon vide du Pic de Brume-funeste pour collecter un échantillon de l’eau d’un bassin, au sommet du Pic de Brume-funeste.","","Apporter ensuite la Fiole d'échantillon remplie à Tonga Runetotem, à la Croisée, dans les Tarides."}}
D[6128] = {"Rassembler les ingrédients du remède",{"Apporter 5 Terrestrines et 5 Cornes de kodo à Tonga Runetotem, à la Croisée, pour qu'il puisse préparer un baume curatif."}}
D[6129] = {"Soigner la maladie",{"Utiliser le Remède pour animaux sur 10 Gazelles malades qui se trouvent dans la partie nord des Tarides ; ceci les soignera. Les Gazelles malades ont été vues au nord de la route orientée est-ouest qui traverse la Croisée."}}
D[6130] = {"Pouvoir contre le poison",{"Retourner voir Turak Runetotem, sur la Cime des Anciens, à Thunder Bluff."}}
D[6132] = {"Faites-moi sortir de là !",{"Escorter Melizza Brimbuzzle, puis parler à Hornizz Brimbuzzle au cimetière des Kodos en Désolace."}}
D[6133] = {"L'ordre du seigneur forestier",{"Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien.","","Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons."}}
D[6134] = {"Chasse à l'ectoplasme",{"Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace."}}
D[6135] = {"Crépuscaile, oh comme je te hais !",{"Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur.","","Il paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris."}}
D[6136] = {"Le corpulent",{"Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée."}}
D[6141] = {"Frère Anton",{"Adressez-vous au frère Anton, en Désolace."}}
D[6142] = {"Des praires comme appât",{"Trouver 10 morceaux de Chair de praire et les apporter à Mai'Lahii, à Proie-de-l'Ombre."}}
D[6143] = {"D'autres poissons à frire",{"Tuer 7 Myrmidons Ondulame, 7 Nagas Ondulame et 5 Sorcières Ondulame, puis parler à Drulzegar, à Proie-de-l'Ombre, en Désolace."}}
D[6144] = {"L'appel du commandement",{"Aller à Undercity et parler à Varimathras."}}
D[6145] = {"Le messager cramoisi",{"Retourner dans les Maleterres de l’est et traquer le Messager cramoisi, le tuer et récupérer les Ordres du Grand Croisé.","","Apporter les Ordres à Nathanos le Flétrisseur pour obtenir des instructions supplémentaires."}}
D[6146] = {"La ruse de Nathanos",{"Aller à la Main de Tyr, au sud-est de la ferme des Marris. Une fois sur place, mordre dans la Pomme pourrie. Profiter d’avoir revêtu l’apparence d’un membre de la Croisade écarlate pour apporter les Ordres du Grand Croisé au Grand maître Valdelmar."}}
D[6147] = {"Retourner voir Nathanos",{"Retourner voir Nathanos le Flétrisseur avec la nouvelle information."}}
D[6148] = {"L'Oracle écarlate, Demetria",{"La Croisade écarlate fait mouvement. Quelque part le long de la route, entre la Main de Tyr et Stratholm, vous trouverez l’Oracle Demetria et sa fratrie. La tuer et retourner voir Nathanos le Flétrisseur."}}
D[6161] = {"Revendiquer le trésor de Rackmore !",{"Trouver la Clé d'argent de Rackmore. Trouver la Clé d'or de Rackmore. Trouver et ouvrir le Coffre de Rackmore."}}
D[6162] = {"La dernière bataille d'un mari",{"Tuer le Seigneur Ror et apporter sa Griffe à Dreka'Sur, au Poste de la Vénéneuse, en Gangrebois."}}
D[6163] = {"Ramstein",{"Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos."}}
D[6164] = {"Le livre de compte d'Augustus",{"Apporter le Livre de compte d'Augustus à Augustus le Touché à Val-Terreur."}}
D[6181] = {"Un message rapide",{"Apporter la Note de Lewis à Thor, le Maître des gryphons."}}
D[6182] = {"Le premier et le dernier",{"Parler à Mathias Shaw, dans la vieille ville de Stormwind. Il se trouve dans la caserne."}}
D[6183] = {"Honorer la mort",{"Reparlez à Mathias Shaw, quand vous aurez décidé d’accepter son travail."}}
D[6184] = {"Flint Shadowmore",{"Allez au camp du Noroît, dans les Maleterres de l’ouest, et rencontrez votre contact, Flint Shadowmore."}}
D[6185] = {"Les Maleterres de l'Est",{"Fouillez les Maleterres de l’est pour trouver des indices relatifs au \"Flétrisseur\" et aux agents du SI:7 portés disparus. Si vous trouvez un quelconque Insigne du SI:7, rapportez-le à Flint Shadowmore, au camp du Noroît."}}
D[6186] = {"La venue du Flétrisseur",{"Retourner à Stormwind et informer le généralissime Bolvar Fordragon du destin de Nathanos Marris."}}
D[6187] = {"L'ordre doit être rétabli",{"Montez une armée et portez-vous vers les Maleterres de l’est. Lancez un assaut total sur Nathanos le Flétrisseur et détruisez tout misérable élément de la Horde qui tenterait de le défendre.","","Gardez votre présence d’esprit, <nom> : la Horde le défendra jusqu’à la mort."}}
D[6261] = {"Dungar Longdrink",{"Apportez la Caisse d'Osric à Dungar Longdrink, le Maître des gryphons."}}
D[6281] = {"Continuer vers Stormwind",{"Achetez un voyage en gryphon à Thor, Maître des gryphons, puis apportez la Note de Lewis à Osric Strang au magasin “Immunité limitée”, dans la vieille ville de Stormwind."}}
D[6282] = {"La menace des harpies",{"Maggran Earthbinder de la retraite de Roche-Soleil veut que vous anéantissiez sept Harpies, sept Embusquées, sept Tueuses et sept Volplumes Rougefuries."}}
D[6283] = {"La lignée Rougefurie",{"Maggran, à la Retraite de Roche-Soleil, vous demande de détruire la Déchiqueteuse Rougefurie et de rapporter son corps comme preuve de votre exploit."}}
D[6284] = {"Arachnophobie",{"Tuer Besseleth, et apporter le Croc de Besseleth à Maggran, dans la Retraite de Roche-Soleil."}}
D[6285] = {"Aller voir Lewis",{"Achetez un voyage en gryphon pour la Colline des sentinelles à Dungar Longdrink, Maître des gryphons, puis apportez la Caisse d'Olric à Lewis à la Colline des sentinelles."}}
D[6301] = {"Cycle de la renaissance",{"Tammra Windfield, de la retraite de Roche-Soleil, vous demande de rassembler 10 Graines de Gaea."}}
D[6321] = {"Approvisionner le Sépulcre",{"Apporter l’Ordre de Podrig à Karos Razok."}}
D[6322] = {"Michael Garret",{"Apporter la Caisse de Gordon à Michael Garret."}}
D[6323] = {"Voyage vers Undercity",{"Acheter un voyage en chauve-souris pour Undercity, auprès du Maître des chauves-souris, Karos Razok, puis apporter l’Ordre de Podrig à Gordon Wendham, à Undercity."}}
D[6324] = {"Retour vers Podrig",{"Acheter un voyage en chauve-souris pour le Sépulcre, auprès du Maître des chauves-souris Michael Garret, puis apporter la Caisse de Gordon au Garde noir Podrig, au Sépulcre."}}
D[6341] = {"Le don de Teldrassil",{"Apporter la Collection de Nessa à Vesprystus."}}
D[6342] = {"Vol vers Auberdine",{"Prenez un hippogryphe vers Auberdine chez le maître des hippogryphes Vesprystus, puis apportez la Collection de Nessa à Laird."}}
D[6343] = {"Retourner à Nessa",{"Réponse de Laird à Nessa Shadowsong."}}
D[6344] = {"Nessa Shadowsong",{"Parler à Nessa Shadowsong."}}
D[6361] = {"Un Tas de peaux",{"Apporter le Tas de peaux au Maître des Cavaliers célestes, Devrak, à la Croisée."}}
D[6362] = {"Voyage vers Thunder Bluff",{"Acheter un voyage pour Thunder Bluff, auprès du Maître des Cavaliers célestes, Devrak, puis apporter le Tas de peaux à Ahanu, à Thunder Bluff."}}
D[6363] = {"Tal le Maître des Cavaliers célestes",{"Apporter les Marchandises en cuir d'Ahanu à Tal, à Thunder Bluff."}}
D[6364] = {"Retourner vers Jahan",{"Acheter un voyage pour la Croisée auprès du Maître des Cavaliers célestes Tal, puis apporter les Marchandises en cuir d’Ahanu à Jahan Hawkwing."}}
D[6365] = {"Viandes vers Orgrimmar",{"Apporter la Chair de Zargh à Devrak, à la Croisée."}}
D[6381] = {"Nouvelle vie",{"Planter 10 Graines de Gaea sur les Monticules de Gaea, puis parler à Tammra, à la Retraite de Roche-Soleil."}}
D[6382] = {"La Chasse d'Ashenvale",{"Parler à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale."}}
D[6383] = {"La Chasse d'Ashenvale"}
D[6384] = {"Trajet vers Orgrimmar",{"Acheter un voyage pour Orgrimmar, auprès du Maître des Cavaliers célestes, Devrak, puis apporter la Chair de Zargh à Gryshka, à Orgrimmar."}}
D[6385] = {"Doras le Maître des Cavaliers célestes",{"Apporter la Lettre de Gryshka à Doras, à Orgrimmar."}}
D[6386] = {"Retour à la Croisée",{"Acheter un voyage pour la Croisée auprès du Maître des Cavalier célestes, Doras, puis apporter la Lettre de Gryshka à Zargh, à la Croisée."}}
D[6387] = {"L'honneur des étudiants",{"Apportez la Liste de Brock à Thorgrum Borrelson à Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Apportez les Pioches d'honneur à Gryth Thurden à Ironforge."}}
D[6389] = {"Une Plaie sur la Croisade",{"Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l'ouest, avec le Tonneau de Termites des Maleterres."}}
D[6390] = {"Une Plaie sur la Croisade",{"Libérez les Termites des Maleterres dans la scierie de la Crête du nord, puis retournez voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal, avec le Tonneau de Termites des Maleterres."}}
D[6391] = {"Voyage vers Ironforge",{"Acheter un billet de gryphon pour Ironforge, auprès du Maître des gryphons, Thorgrum Borrelson, puis apporter la Liste de Brock à Golnir Bouldertoe, à Ironforge."}}
D[6392] = {"Retourner vers Brock",{"Acheter un billet de gryphon pour Thelsamar, auprès du Maître des gyphons Gryth Thurden, puis apporter les Pioches d'honneur à Brock Stoneseeker, à Thelsamar."}}
D[6393] = {"Guerre élémentaire",{"Apporter 10 Incendrites à Tsunaman, dans la Retraite de Roche-Soleil."}}
D[6394] = {"La pioche de Thazz'ril",{"Apportez la Pioche de Thazz'rill au contremaître Thazz'rill."}}
D[6395] = {"La dernière volonté de Marla",{"Apporter le Cadavre de Samuel Fipps sur la Tombe de Marla, puis retourner voir la novice Elreth."}}
D[6401] = {"Kaya est en vie",{"Apprendre la bonne nouvelle à Tammra Windfield, dans la Retraite de Roche-Soleil."}}
D[6402] = {"Le rendez-vous à Stormwind",{"Aller à la Cité de Stormwind et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée."}}
D[6403] = {"La grande mascarade",{"Suivre Reginald Windsor dans Stormwind. Le protéger contre toute menace !"}}
D[6421] = {"Le ravin des Eboulis",{"Explorer la grotte du ravin des Eboulis, et apporter 10 Cristaux de résonite à Mor'rogal, dans la Retraite de Roche-Soleil."}}
D[6441] = {"Cornes de satyre",{"Collecter 16 Cornes de satyre pour Pixel, au Poste de Bois-brisé."}}
D[6442] = {"Des nagas sur la grève de Zoram",{"Apporter 20 Têtes d'Irequeue à Marukai, le long de la grève de Zoram."}}
D[6461] = {"Suceurs de sang",{"Xen'zilla, à Malaka'Jin, voudrait que vous tuiez 10 Rampants des mousses profondes et 7 Venimeux des mousses profondes."}}
D[6462] = {"Charme troll",{"Apporter 8 Charmes trolls à Mitsuwa, à l’Avant-poste de Zoram'gar."}}
D[6481] = {"Un Terrestre se lève",{"Ouvrir la Gangue de résonite avec le Cristal de résonite enchanté, puis tuer Goggeroc. Retourner voir Mor'rogal pour l'informer et lui rapporter le Cristal de résonite enchanté."}}
D[6482] = {"Liberté pour Ruul",{"Escorter Ruul, puis parler à Yama Snowhoof, au Poste de Bois-brisé."}}
D[6501] = {"L'Œil de dragon",{"Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe."}}
D[6502] = {"Amulette drakefeu",{"Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Blackrock."}}
D[6503] = {"Les estafettes d'Ashenvale",{"Tuer 9 Estafettes d'Ashenvale, puis retourner voir Kuray'bin, à l’avant-poste de Bois-brisé."}}
D[6504] = {"Les pages perdues",{"Trouver les 12 pages manquantes du Manuel d'utilisation du Déchiqueteur, puis les rassembler pour constituer les Chapitres 1, 2, et 3. Ramener les pages à Gurda Ragescar près du poste de Bois-brisé."}}
D[6521] = {"Une alliance impie",{"Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Undercity."}}
D[6522] = {"Une alliance impie",{"Apporter le Petit parchemin à Varimathras, à Undercity."}}
D[6523] = {"Protéger Kaya",{"Escorter Kaya Flathoof au Camp Aparaje, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres-Rocheuses."}}
D[6541] = {"Rapport à Kadrak",{"Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides."}}
D[6542] = {"Rapport à Kadrak",{"Faire un rapport à Kadrak, dans la tour de guet, dans le nord des Tarides."}}
D[6543] = {"Les rapports Warsong",{"Apporter les Rapports du clan Warsong à l’Eclaireur Warsong, au Messager Warsong et au Voltigeur Warsong. Rapporter leurs comptes rendus mis à jour à Kadrak, dans la tour de guet nord, dans les Tarides."}}
D[6544] = {"L'assaut de Torek",{"Escorter Torek lors de son attaque contre l’Avant-poste d'Aile-argent et Duriel Moonfire, puis faire un rapport à Ertog Ragetusk, au Poste de Bois-brisé."}}
D[6545] = {"Mise à jour du Messager Warsong"}
D[6546] = {"Mise à jour du voltigeur Warsong"}
D[6547] = {"Mise à jour de l'Eclaireur Warsong"}
D[6548] = {"Vengez mon village !",{"Tuez 8 Forbans du Totem sinistre et 6 Mercenaires du Totem sinistre, puis retournez voir Makaba Flathoof, près de la lisière sud-est des Serres-Rocheuses."}}
D[6561] = {"L'infamie de Brassenoire",{"Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff."}}
D[6562] = {"Problèmes dans les profondeurs",{"Parler à Je'neu Sancrea, à Ashenvale."}}
D[6563] = {"L'Essence d'Aku'Mai",{"Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale."}}
D[6564] = {"Allégeance aux Dieux très anciens",{"Apporter la Note humide à Je'neu Sancrea, à Ashenvale."}}
D[6565] = {"Allégeance aux Dieux très anciens",{"Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale."}}
D[6566] = {"Ce que le vent apporte",{"Écouter Thrall."}}
D[6567] = {"Le Champion de la Horde",{"Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas."}}
D[6568] = {"Le testament de Rexxar",{"Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest."}}
D[6569] = {"Illusions d'Occulus",{"Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée."}}
D[6570] = {"Brandeguerre",{"Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre."}}
D[6571] = {"Fournitures Warsong",{"Collecter les Fournitures Warsong : Lames du clan Warsong, Huile Warsong, et la Cargaison de Haches Warsong ayant pour destinataire Locke Okarr, au Poste de Bois-brisé."}}
D[6581] = {"Lames du clan Warsong"}
D[6582] = {"L'épreuve des crânes, Clairvoyant",{"Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre.","","Clairvoyant se trouve au Berceau-de-l'Hiver."}}
D[6583] = {"L'épreuve des crânes, Somnus",{"Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre."}}
D[6584] = {"L'épreuve des crânes, Chronalis",{"Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre."}}
D[6585] = {"L'épreuve des crânes, Axtroz",{"Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre."}}
D[6601] = {"Ascension...",{"Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire."}}
D[6602] = {"Le sang du champion des dragons noirs",{"Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar."}}
D[6603] = {"Troubles au Berceau-de-l'Hiver",{"Trouver Donova Snowden, à côté des sources chaudes du Berceau-de-l'Hiver."}}
D[6604] = {"Les Indomptables enragés",{"Parler à Jaron Stoneshaper, au village de Pluie-d'Etoiles."}}
D[6605] = {"Une étrange personne",{"Parler à Winna Hazzard, à Gangrebois."}}
D[6606] = {"Un peu de chance",{"Parler à la Mau'ari, à Long-guet."}}
D[6607] = {"Nat Pagle, pêcheur de l'extrême",{"Nat Pagle voudrait que vous attrapiez les poissons suivants :","","Le Mahi Mahi de Brumejonc, de la grève de Brumejonc, dans le marais des Chagrins.","","Un Frappeur Sar'theris, de la grève de Sar'theris en Désolace.","","L'Ahi de Feralas, de la rivière Verdantis de Feralas.","","Le Sailfin bleu de la Côte sauvage, de la Côte sauvage de la vallée de Strangleronce.","","Retournez voir Nat Pagle quand la collecte sera terminée."}}
D[6608] = {"Vous êtes trop bon",{"Vous pensez que Lumak essaie de vous dire qu’il ne peut plus vous aider à améliorer votre compétence de pêche. Vous devriez essayer de vous adresser maintenant à son ami, Nat Pagle, un pêcheur humain des îles au sud de Theramore (c’est du moins ce que vous croyez comprendre du discours de Lumak)."}}
D[6609] = {"Il ne me reste rien !",{"Aller à Kalimdor, dans la ville côtière de Theramore. À partir de là, chercher une île au sud de la ville principale. Nat Pagle vous attend !"}}
D[6610] = {"Surprise de palourdes",{"Dirge Quikcleave voudrait que vous lui apportiez les objets suivants :","","12 Oeufs géants. Vous les trouverez sur les Rocs qui hantent Tanaris ou sur toute autre espèce de grand oiseau.","","10 morceaux de Chair de palourde piquante. Vous pouvez trouver la chair de palourde sur... les palourdes, naturellement !","","20 Emmentals d'Alterac. Vous les trouverez dans une fromagerie !","","Collectez tous ces objets, puis retournez voir Dirge."}}
D[6611] = {"Vers Gadgetzan vous allez !",{"Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Quikcleave."}}
D[6612] = {"Je connais un gars...",{"Aller à Gadgetzan, dans le Désert de Tanaris, et parler de votre carrière de cuisinier à Dirge Quikcleave."}}
D[6621] = {"Le roi des Vile-sylve",{"Placer la Bannière de Karang sur le Monticule du totem Vile-sylve. Ne pas laisser les furbolgs détruire la Bannière. Tuer le chef Murgut, et apporter le Totem de Murgut à Karang Amakkar, à Zoram'gar."}}
D[6622] = {"Triage",{"Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.","","Rappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait."}}
D[6623] = {"Service de traumatologie de la Horde",{"Aller au Trépas-d'Orgrim, dans les hautes-terres d'Arathi, et évoquer avec le docteur Gregory Victor la possibilité de rejoindre les rangs des médecins de la Horde."}}
D[6624] = {"Triage",{"Sauver des patients en utilisant des Bandages de Triage, afin de panser leurs blessures. Vous devez sauver 15 patients avant que 6 d’entre eux ne meurent de leurs blessures.","","Rappelez-vous l’ordre du triage ! Les Soldats agonisants meurent les premiers, suivis des Soldats grièvement blessés. Les Soldats blessés sont ceux qui meurent les derniers, et ils doivent être soignés APRES ceux qui agonisent et ceux qui sont grièvement blessés ; selon le tri que vous avez fait."}}
D[6625] = {"Service de traumatologie de l'Alliance",{"Aller à Theramore, dans le marécage d'Âprefange, et parler au docteur Gustaf VanHowzen de la possibilité de rejoindre les rangs des médecins de l’Alliance."}}
D[6626] = {"L'hôte du mal",{"Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge."}}
D[6627] = {"L'épreuve de la Connaissance",{"Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses."}}
D[6628] = {"L'épreuve de la Connaissance",{"Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Undercity."}}
D[6629] = {"Tuer Grundig Darkcloud",{"Tuer Grundig Darkcloud et 6 Brutes du Totem sinistre, puis retourner voir Makaba Flathoof, à côté de la frontière sud-est des Serres Rocheuses."}}
D[6641] = {"Vorsha la Flagellante",{"Garantir la sécurité de Muglash tandis qu’il voyage vers le brasero. L’aider à éteindre le brasero, puis le protéger, en combattant les nagas.","","En cas de réussite, retourner à l’avant-poste de Zoram'gar et informer le messager Warsong de la mort de Vorsha la Flagellante."}}
D[6642] = {"Faveur auprès de la Confrérie, Minerai de sombre fer"}
D[6643] = {"Faveur auprès de la Confrérie, Noyau de feu"}
D[6644] = {"Faveur auprès de la Confrérie, Noyau de lave"}
D[6645] = {"Faveur auprès de la Confrérie, Cuir du Magma"}
D[6646] = {"Faveur auprès de la Confrérie, Sang de la montagne"}
D[6661] = {"Chasse au rat dans les profondeurs",{"Capturer 5 Rats des profondeurs en utilisant le Pipeau du dératiseur. Conduire les Rats vers Monty. N’oubliez pas de rendre le Pipeau quand vous aurez terminé."}}
D[6662] = {"Mon frère, Nipsy",{"Apporter le Carton de viande mystère à Nipsy, au Dépôt du Tram des profondeurs de Stormwind."}}
D[6681] = {"Ravenholdt, le manoir",{"Apporter le Sceau de Ravenholdt à Fahrad, au Manoir de Ravenholdt, dans les collines d'Hillsbrad.","","Votre sagacité sera mise à l’épreuve tout au long de la route. Préparez-vous."}}
D[6701] = {"Emblèmes du Syndicat"}
D[6721] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6722] = {"La voie du chasseur",{"Parler à Dazalar, à Dolanaar."}}
D[6741] = {"Plus de butin !"}
D[6761] = {"La nouvelle frontière",{"Parler à Mathrengyl Bearwalker, dans l’Enclave cénarienne de Darnassus."}}
D[6762] = {"Rabine Saturna",{"Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules."}}
D[6781] = {"Plus de morceaux d'armure !"}
D[6801] = {"Lokholar le Seigneur des Glaces"}
D[6804] = {"Eau empoisonnée",{"Utiliser l’Aspect de Neptulon sur les élémentaires empoisonnés des Maleterres de l’est. Apporter 12 Bracelets discordants et l’Aspect de Neptulon au duc Hydraxis, en Azshara."}}
D[6805] = {"Tempêtes",{"Tuer 15 Tempétueux de poussière et 15 Grondeurs du désert, puis retourner voir le duc Hydraxis, en Azshara."}}
D[6821] = {"Oeil du Prophète ardent",{"Apporter l’Oeil du Prophète ardent au duc Hydraxis, en Azshara."}}
D[6822] = {"Le Cœur du Magma",{"Tuer 1 Seigneur du feu, 1 Géant de lave, 1 Chien antique du Magma et 1 Surgisseur de lave, puis retourner voir le duc Hydraxis, à Azshara."}}
D[6823] = {"Agent de Hydraxis",{"Parvenir au niveau de réputation Honoré auprès des Hydraxiens, puis parler au duc Hydraxis, en Azshara."}}
D[6824] = {"Les mains de l'ennemi",{"Apporter les Mains de Lucifron, de Sulfuron, de Gehennas et de Shazzrah au duc Hydraxis, en Azshara."}}
D[6825] = {"L'appel des airs - l'escadrille de Guse"}
D[6826] = {"L'appel des airs - l'escadrille de Jeztor"}
D[6827] = {"L'appel des airs - l'escadrille de Mulverick"}
D[6844] = {"Umber, Archiviste",{"Apporter l’Objet silithide incrusté à Umber, l’archiviste du Cercle cénarien, au village de Havrenuit, à Reflet-de-Lune."}}
D[6845] = {"Les secrets du passé",{"Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune."}}
D[6846] = {"Que l'attaque commence !"}
D[6847] = {"L'Œil qui-voit-tout de Maître Ryson",{"Récupérer l’Oeil qui-voit-tout de Maître Ryson dans les Grottes Haches-d’hiver, puis le rapporter à Maître Ryson.","","Sachez que l’on dit de l’Oeil qui-voit-tout de Maître Ryson qu’il contient une terrible malédiction !"}}
D[6848] = {"L'Œil qui voit tout de maître Ryson",{"Récupérer l’Oeil-qui-voit-tout de Maître Ryson dans les Grottes Winterax, puis le rapporter à Maître Ryson.","","Sachez que l’on dit de l’Oeil-qui-voit-tout de Maître Ryson qu’il contient une terrible malédiction !"}}
D[6861] = {"Le Déchiqueteur portable de Zinfizzlex",{"Le Maître Ingénieur Zinfizzlex veut que vous lui apportiez les matériaux suivants :","","*30 Barres de thorium.","","*50 Barres de Mithril.","","*75 Barres de fer.","","*1 Scie mécanique."}}
D[6862] = {"Le Déchiqueteur portable de Zinfizzlex",{"Le Maître Ingénieur Zinfizzlex veut que vous lui apportiez les matériaux suivants :","","*30 Barres de thorium.","","*50 Barres de Mithril.","","*75 Barres de fer.","","*1 Scie mécanique."}}
D[6881] = {"Ivus le Seigneur des forêts"}
D[6901] = {"Lancez l'attaque !"}
D[6921] = {"Parmi les ruines",{"Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale."}}
D[6922] = {"Baron Aquanis",{"Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale."}}
D[6941] = {"L'appel des airs - l'escadrille de Vipore"}
D[6942] = {"L'appel des airs - l'escadrille de Slidore"}
D[6943] = {"L'appel des airs - l'escadrille d'Ichman"}
D[6961] = {"Grand-père Hiver est ici !",{"Allez voir Grand-père Hiver. Il se trouve près des Gourmandises Fumebois à Orgrimmar."}}
D[6962] = {"Des friandises pour Grand-père Hiver",{"Apporter 5 Biscuits au pain d'épices et un Verre de lait glacé au Grand-père Hiver, à Orgrimmar."}}
D[6963] = {"Friandises volées de la fête du Voile d'hiver",{"Trouver l'enquêteur des Gourmandises Fumebois qui est porté disparu dans les montagnes d'Alterac."}}
D[6964] = {"L'esprit de cette fête",{"Parler à Sagorne Crestrider, dans la Vallée de la Sagesse d'Orgrimmar, au sujet de la fête du Voile d'hiver."}}
D[6981] = {"L'Eclat luminescent",{"Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent.","","Puis livrez l'Eclat, selon les instructions."}}
D[6982] = {"Fournitures de Froide-dent",{"Apporter 10 Fournitures de Froide-dent à l'intendant de l’Alliance, à Dun Baldar."}}
D[6983] = {"La méchanceté vous habite...",{"Localiser les friandises, et les ramener à Kaymard Copperpinch, à Orgrimmar. C'est l'abominable Grinche, vivant quelque part dans les régions enneigées des montagnes d'Alterac, qui les détiendrait."}}
D[6984] = {"Un grand merci des Gourmandises Fumebois !",{"Parler à Grand-père Hiver à Orgrimmar."}}
D[6985] = {"Fournitures de Gouffrefer",{"Apporter 5 Fournitures de Gouffrefer à l'Intendant de la Horde, au donjon Frostwolf."}}
D[7001] = {"Ecuries vides",{"Trouvez un Loup des glaces dans la vallée d’Alterac. Servez-vous de la Muselière de loup des glaces pour « dompter » la bête. Lorsque ce sera fait, le loup des glaces vous suivra jusqu’au Maître des écuries Frostwolf. Parlez au Maître des écuries Frostwolf pour être crédité de cette capture."}}
D[7002] = {"Harnais en cuir de bélier"}
D[7003] = {"Géants rétrécis",{"Utilisez l'Ultra-réducteur de Zorbin sur des géants de n'importe quel type en Feralas afin les rendre plus faciles à gérer. Apportez 15 Résidus de miniaturisation que vous trouverez sur les versions rétrécies des géants à Zorbin Fandazzle aux docks de la Côte oubliée en Feralas."}}
D[7021] = {"Grand-père Hiver est ici !",{"Parler à Grand-père Hiver ; il se trouve près des Gourmandises Fumebois, à Orgrimmar."}}
D[7022] = {"Grandpère Hiver est ici !",{"Parler à Grandpère Hiver ; il se trouve près des Gourmandises Fumebois, à Ironforge."}}
D[7023] = {"Grandpère Hiver est ici !",{"Parler à Grandpère Hiver ; il se trouve près des Gourmandises Fumebois, à Ironforge."}}
D[7024] = {"Grand-père Hiver est ici !",{"Allez voir Grand-père Hiver. Il se trouve près des Gourmandises Fumebois à Orgrimmar."}}
D[7025] = {"Des friandises pour Grandpère Hiver",{"Apporter 5 Biscuits au pain d'épices et un verre de Lait glacé au Grandpère Hiver à Ironforge."}}
D[7026] = {"Harnais pour béliers"}
D[7027] = {"Écuries vides",{"Trouvez un Bélier d'Alterac dans la vallée d'Alterac. Lorsque vous serez à proximité, servez-vous du Collier d'entraînement Stormpike pour le \"dompter\". Une fois dompté, le Bélier d'Alterac vous suivra jusqu'au Maître des écuries. Parlez au Maître des écuries pour être crédité de cette capture."}}
D[7028] = {"Forces maléfiques retorses",{"Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace."}}
D[7029] = {"La corruption de Vylelangue",{"Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon.","","En faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.","","Soigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre."}}
D[7041] = {"La corruption de Vylelangue",{"Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon.","","En faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir.","","Soigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel."}}
D[7042] = {"Friandises volées de la fête du Voile d'hiver",{"Localiser l'enquêteur des Gourmandises Fumebois qui a été porté disparu dans les montagnes d'Alterac."}}
D[7043] = {"La méchanceté vous habite…",{"Trouver les Friandises volées, et les ramener à Wumort Jinglepocket, à Ironforge. C'est l'Abominable Grinche qui aurait le chargement en sa possession, il résiderait dans les régions neigeuses des montagnes d'Alterac."}}
D[7044] = {"Légendes de Maraudon",{"Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras.","","Trouvez un moyen de parler à Celebras."}}
D[7045] = {"Un grand merci des Gourmandises Fumebois !",{"Parler à Grandpère Hiver à Ironforge."}}
D[7046] = {"Le sceptre de Celebras",{"Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras.","","Parlez-lui après la réussite du rituel."}}
D[7061] = {"La fête du Voile d'hiver",{"Prenez le temps de lire ce livre, \"La fête du Voile d'hiver\", pour en apprendre plus sur cette période de fête. Quand vous en aurez fini avec le livre, apportez-le à Cairne Bloodhoof, dans la ville de Thunder Bluff."}}
D[7062] = {"L'esprit de cette fête",{"Parlez à l'historien Karnik de la fête du Voile d'hiver, en vous rendant à la Ligue des Explorateurs d'Ironforge."}}
D[7063] = {"La fête du Voile d'hiver",{"Prenez le temps de lire le livre « La fête du Voile d'hiver » pour en apprendre plus sur cette période sainte. Quand vous en aurez fini avec le livre, apportez-le à Muradin Barbe-de-Bronze, à Forgefer."}}
D[7064] = {"Corruption de la terre et de la graine",{"Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace."}}
D[7065] = {"Corruption de la terre et de la Graine",{"Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace."}}
D[7066] = {"Graine de vie",{"Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie."}}
D[7067] = {"Les instructions du paria",{"Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace."}}
D[7068] = {"Fragments d'Ombréclat",{"Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar."}}
D[7070] = {"Fragments d'Ombréclat",{"Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange."}}
D[7081] = {"Les cimetières de la vallée d'Alterac",{"Attaquez un cimetière, puis présentez-vous au caporal Noreg Stormpike à Dun Baldar."}}
D[7082] = {"Les cimetières d'Alterac",{"Attaquez un cimetière, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac."}}
D[7101] = {"Tours et fortins",{"Prenez une tour ennemie, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac."}}
D[7102] = {"Tours et fortins",{"Détruisez la bannière d'une tour ou d'un fortin ennemi, puis présentez-vous au sergent Durgen Stormpike à Dun Baldar."}}
D[7121] = {"L'intendant",{"Parlez à l’Intendant Stormpike."}}
D[7122] = {"Prendre une mine",{"Prenez une mine que les Stormpike ne contrôlent pas, puis présentez-vous à l’intendant Stormpike à Dun Baldar."}}
D[7123] = {"Parlez à notre Intendant",{"Parlez à l’Intendant Frostwolf."}}
D[7124] = {"Prendre une mine",{"Prenez une mine, puis présentez-vous au caporal Teeka Bloodsnarl dans les montagnes d'Alterac."}}
D[7141] = {"La bataille d'Alterac",{"Entrez dans la vallée d'Alterac, tuez Drek'thar, le général de la Horde, puis retournez voir la Prospectrice Stonehewer dans les montagnes d'Alterac."}}
D[7142] = {"La bataille pour Alterac",{"Entrez dans la vallée d'Alterac, tuez Vanndar Stormpike, le général nain, puis retournez voir Voggah Deathgrip dans les montagnes d'Alterac"}}
D[7161] = {"Montrer sa valeur",{"Rendez-vous dans les cavernes des Follepattes, au sud-est de la base principale, et récupérez la Bannière Frostwolf qui s’y trouve. Ramenez-la au Maître de guerre Laggrond."}}
D[7162] = {"Montrer sa valeur",{"Rendez-vous dans les cavernes de l'Aile de glace, au sud-ouest de la base principale, et récupérez la Bannière Stormpike qui s’y trouve. Ramenez-la au lieutenant Haggerdin."}}
D[7163] = {"Ascension et reconnaissance"}
D[7164] = {"Honoré au sein du clan"}
D[7165] = {"Montée en grade"}
D[7166] = {"Héros de légende"}
D[7167] = {"L'Œil du commandement"}
D[7168] = {"Ascension et reconnaissance"}
D[7169] = {"Honoré au sein de la Garde"}
D[7170] = {"Montée en grade"}
D[7171] = {"Héros de légende"}
D[7172] = {"L'Œil du commandement"}
D[7181] = {"La légende de Korrak",{"Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers.","","Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Maître de guerre Laggrond."}}
D[7201] = {"Le dernier élément",{"Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires."}}
D[7202] = {"Korrak le Ragesang",{"Korrak le Ragesang se cache dans les profondeurs des cavernes Winterax. D’après la légende, le chef des puissants trolls Winterax ne se montre qu’après la mort de 500 de ses guerriers.","","Rendez-vous aux cavernes Winterax et massacrez tout ce qui vous fait obstacle jusqu’à ce que Korrak se montre. Tuez-le et présentez-vous au Lieutenant Haggerdin."}}
D[7221] = {"Discuter avec la prospectrice Stonehewer",{"Discutez avec la Prospectrice Stonehewer à la Garnison de Dun Baldar."}}
D[7222] = {"Discuter avec Voggah Deathgrip",{"Parlez à Voggah au donjon Frostwolf."}}
D[7223] = {"Morceaux d'armures",{"Apportez 20 Morceaux d’armure à Murgot Deepforge à Dun Baldar."}}
D[7224] = {"Pris à l'ennemi",{"Apportez 20 Morceaux d’armure au forgeron Regzar au village Frostwolf."}}
D[7241] = {"La défense des Frostwolf",{"Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Trouvez le maître de guerre Laggrond, parlez-lui et commencez votre carrière comme soldat Frostwolf."}}
D[7261] = {"L'impératif souverain",{"Rendez-vous dans la vallée d'Alterac, dans les contreforts d'Hillsbrad. Présentez-vous au lieutenant Haggerdin.","","Pour la gloire de Bronzebeard !"}}
D[7281] = {"Amour fraternel",{"Pénétrez en territoire Stormpike et tuez le commandant Karl Philips. Lorsque ce sera fait, présentez-vous au commandant Louis Philips."}}
D[7282] = {"Amour fraternel",{"Pénétrez en territoire Frostwolf et tuez le commandant Louis Philips. Lorsque ce sera fait, présentez-vous au commandant Karl Philips."}}
D[7301] = {"Les ailes brisées",{"Enfoncez-vous en territoire Frostwolf à la recherche des chefs d’escadrille Slidor, Vipore et Ichman. Si vous les retrouvez, présentez-vous au commandant Duffy."}}
D[7302] = {"Les ailes brisées",{"Découvrez ce qui est arrivé aux chefs d’escadrille Guse, Jetzor et Mulverick. Lorsque vous les aurez retrouvés, présentez-vous au commandant Mulfort."}}
D[7321] = {"Bisque de tortue apaisante",{"Apporter 10 morceaux de Viande de tortue et des Epices apaisantes à Christoph Jeffcoat au Moulin-de-Tarren."}}
D[7341] = {"Un marché honnête"}
D[7342] = {"Les flèches, c'est pour les mauviettes"}
D[7361] = {"En faveur auprès des Sombrelances",{"Vous avez été <chargé/chargée> de tuer les personnages Elfes de la nuit présents dans la vallée d’Alterac.","","Tuez un Elfe de la nuit et présentez-vous à Najak Maléficas avec une Tête coupée d’Elfe de la nuit."}}
D[7362] = {"Allié des Taurens",{"Vous avez été <chargé/chargée> de tuer les personnages gnomes présents dans la vallée d’Alterac.","","Tuez un Gnome et présentez-vous à Ravak Totem-Sinistre au donjon Loup-de-givre avec une Touffe de cheveux de Gnome."}}
D[7363] = {"La condition humaine",{"Vous avez été <chargé/chargée> de tuer les personnages humains présents dans la vallée d’Alterac.","","Tuez un humain et présentez-vous au commandant Louis Philips (qui fait la navette entre le front et le donjon Loup-de-givre) avec un Bout d’os humain.","","Un remède à la condition humaine est à portée de main !"}}
D[7364] = {"Au service de Gnomeregan",{"Vous avez été <chargé/chargée> de tuer les personnages taurens présents dans la vallée d’Alterac.","","Tuez un Tauren et présentez-vous à Dirk Lembrouille à Dun Baldar avec un Sabot de Tauren."}}
D[7365] = {"Le requiem de Forteramure",{"Vous avez été <chargé/chargée> de tuer les personnages trolls présents dans la vallée d’Alterac.","","Tuez un Troll et présentez-vous à Athramanis à Dun Baldar avec un Mojo de Troll sombrelance."}}
D[7366] = {"La pitié de l'archevêque",{"Vous avez été <chargé/chargée> de tuer les personnages Réprouvés présents dans la vallée d’Alterac.","","Tuez un Réprouvé et présentez-vous au commandant Karl Philips (qui fait la navette entre le scierie et la mine) avec un Cœur de Réprouvé."}}
D[7367] = {"Désarmer les mines",{"Trouvez l’Expert en explosifs Frostwolf et tuez-le. Lorsque ce sera fait, présentez-vous à l’Expert en explosifs Stormpike."}}
D[7368] = {"Désarmer les mines",{"Trouvez l’Expert en explosifs Stormpike et tuez-le. Lorsque ce sera fait, présentez-vous à l’Expert en explosifs Frostwolf."}}
D[7381] = {"Le retour de Korrak",{"Si Korrak le Ragesang devait réapparaître dans le Champ sanglant, traquez-le et tuez-le.","","Apportez le Crâne de Korrak au Maître de guerre Laggrond dans les contreforts de Hautebrande."}}
D[7382] = {"Korrak l'Indestructible",{"Si Korrak le Ragesang réapparaît dans le Champ sanglant, traquez-le et tuez-le.","","Apportez le Crâne de Korrak au lieutenant Haggerdin dans les Contreforts de Hautebrande."}}
D[7383] = {"La couronne de la Terre",{"Remplir la Fiole d'améthyste et la rapporter à Corithras Moonrage à Dolanaar."}}
D[7385] = {"Quelques litres de sang"}
D[7386] = {"Grappes de cristaux"}
D[7401] = {"ON RECHERCHE : des Nains !",{"Vous avez été <chargé/chargée> de tuer les personnages nains présents dans la vallée d’Alterac.","","Tuez des Nains et arrachez-leur la colonne vertébrale. Apportez les Colonnes vertébrales de Nains au sergent Yazra Gronde-Sang au donjon Loup-de-givre."}}
D[7402] = {"On recherche : ORCS !",{"Vous avez été chargé de tuer les personnages orcs présents dans la Vallée d’Alterac.","","Tuez un orc et remettez les Dents d’orc au caporal Noreg Foudrepique à Dun Baldar."}}
D[7421] = {"La défense des Sombrelances"}
D[7422] = {"Pour une poignée de cheveux"}
D[7423] = {"Toujours plus de bouts d'os !"}
D[7424] = {"Chasse aux sabots !"}
D[7425] = {"La collection de mojos de Forteramure"}
D[7426] = {"L'amour d'un homme"}
D[7427] = {"On recherche : PLUS DE NAINS !"}
D[7428] = {"On recherche : PLUS D'ORCS !"}
D[7429] = {"Libérez Knot !"}
D[7441] = {"Pusillin et l'Ancien Azj'Tordin",{"Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin.","","Si vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas."}}
D[7461] = {"Folie intérieure",{"Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera.","","Entrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum.","","Lorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour."}}
D[7462] = {"Le trésor des Shen'dralar",{"Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !"}}
D[7463] = {"Rafraîchissement arcanique",{"Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos."}}
D[7481] = {"Légendes elfiques",{"Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache."}}
D[7482] = {"Légendes elfiques",{"Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon."}}
D[7483] = {"Libram de Rapidité",{"Apportez un Libram de rapidité, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 2 doses de Sang des héros au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de rapidité."}}
D[7484] = {"Libram de focalisation",{"Apportez un Libram de focalisation, 1 Diamant noir en parfait état, 4 Grands éclats brillants et 2 Peaux des ombres au Gardien du savoir Lydros à Hache-tripes pour recevoir un arcanum de focalisation."}}
D[7485] = {"Libram de Protection",{"Apportez un Libram de protection, 1 Diamant noir en parfait état, 2 Grands éclats brillants et 1 Couture d'abomination effilochée au Gardien du savoir Lydros à Hache-tripes pour recevoir un Arcanum de protection."}}
D[7486] = {"La récompense du héros",{"Allez chercher votre récompense dans le Coffre d’Hydraxis."}}
D[7488] = {"Le filet de Lethtendris",{"Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas."}}
D[7489] = {"Le filet de Lethtendris",{"Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas."}}
D[7490] = {"Victoire pour la Horde !",{"Apportez la Tête d’Onyxia à Thrall à Orgrimmar."}}
D[7491] = {"Pour que tous voient",{"Allez voir le seigneur Runthak dans la vallée de la Force."}}
D[7492] = {"Camp Mojache",{"Parlez à Talo Thornhoof au Camp Mojache, en Feralas."}}
D[7493] = {"Le voyage commence à peine"}
D[7494] = {"Le bastion de Feathermoon",{"Parlez à Latronicus Moonspear au bastion de Feathermoon en Feralas."}}
D[7495] = {"Victoire pour l'Alliance !",{"Apportez la Tête d’Onyxia au généralissime Bolvar Fordragon à Stormwind."}}
D[7496] = {"Célébrer le triomphe",{"Allez voir le major Mattingly dans la vallée des Héros."}}
D[7497] = {"Le voyage commence à peine"}
D[7498] = {"Garona : une étude en discrétion et en trahison",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7499] = {"Le codex de défense",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7500] = {"Les recettes de l’arcaniste",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7501] = {"La lumière et comment l'altérer",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7502] = {"Contrôler les ombres",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7503] = {"La plus grande race de chasseurs",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7504] = {"Sainte Bolognaise : Ce que la lumière ne vous dit pas",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7505] = {"Le Horion de givre et vous",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7506] = {"Le Rêve d'Emeraude…",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7507] = {"Le guide de Dagharn",{"Rapporter « Le guide de Nostro du tueur de dragons » à l’Athenaeum."}}
D[7508] = {"Forger Quel'Serrar",{"Donnez la Lame elfique inachevée au Gardien du savoir Lydros."}}
D[7509] = {"Forger Quel'Serrar",{"Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important.","","Avant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre.","","Si vous y parvenez, Quel’Serrar sera à vous."}}
D[7541] = {"Un service pour la Horde"}
D[7562] = {"Mor'zul Bloodbringer",{"Parler à Mor'zul Bloodbringer dans les Steppes ardentes."}}
D[7563] = {"Rage de sang",{"Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes."}}
D[7564] = {"Gorzeeki Wildeyes",{"Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes."}}
D[7581] = {"Les ancrages de la prison",{"Rendez-vous à Hache-tripes en Feralas et récupérez 15 doses de Sang de satyre sur les satyres Follengeance qui habitent le quartier de Crochebois. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure."}}
D[7582] = {"Les parois de la prison",{"Rendez-vous à la gorge du Sombre murmure, dans le Berceau-de-l'Hiver, et récupérez 5 Larmes de l’Hederine sur les démons Hederine qui occupent la gorge. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure."}}
D[7583] = {"Suppression",{"Pénétrez dans la Balafre impure et localisez un Commandant de la garde funeste.","","Servez-vous de la Prison de cristal luminescente sur lui. Attendez-vous à être sauvagement <attaqué/attaquée>, car le démon fera l’impossible pour éviter d’être capturé.","","Si vous réussissez, amenez le garde funeste emprisonné à Levadre à la Balafre impure."}}
D[7601] = {"Les Commandements de Niby",{"Parlez à Démonet à Gangrebois."}}
D[7602] = {"La gangressence parfaite",{"Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes.","","Les satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région.","","Récupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois."}}
D[7603] = {"Le noyau infernal de Kroshius",{"Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.","","Rapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois."}}
D[7604] = {"Un contrat contraignant",{"Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron."}}
D[7621] = {"Un avertissement"}
D[7622] = {"L’équilibre de la Lumière et de l’Ombre",{"Sauvez 50 Paysans avant que 15 d'entre eux aient été tués. Si vous y parvenez, allez parler à Eris Havenfire.","","Consultez le Panneau des morts pour voir combien de paysans ont été tués."}}
D[7623] = {"Le seigneur Banehollow",{"Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes.","","Servez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow."}}
D[7624] = {"Ulathek le traître",{"Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar."}}
D[7625] = {"Poussière d'étoile xorothienne",{"Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes."}}
D[7626] = {"La Cloche de Dethmoora",{"Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes."}}
D[7627] = {"La Roue de la Marche noire",{"Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes."}}
D[7628] = {"La Chandelle de l'apocalypse",{"Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes."}}
D[7629] = {"Livraison de diablotin",{"Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes."}}
D[7630] = {"L'arcanite",{"Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes."}}
D[7631] = {"Le destrier de l'effroi de Xoroth",{"Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit."}}
D[7632] = {"La feuille ancienne",{"Trouvez le propriétaire de la Feuille ancienne pétrifiée. Bonne chance, <nom>, le monde est vaste."}}
D[7633] = {"Une rencontre"}
D[7634] = {"Feuille d'Ancien cousue de tendons",{"L'Ancien Hasat vous demande de lui ramener un Tendon de dragon bleu adulte. Si vous en trouvez un, ramenez-le-lui à Gangrebois"}}
D[7635] = {"La bonne corde",{"L’Ancien Stoma vous demande de lui ramener un Tendon de dragon noir adulte. Si vous en trouvez un, ramenez-le à Stoma à Gangrebois."}}
D[7636] = {"Le bâton des Anciens",{"Vous devez trouver et tuer quatre corrupteurs démoniaques :","","Simona la Séductrice.","","Klinfran l’Enragé.","","Solenor le Tueur.","","Artorius le Néfaste.","","Détruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois.","","Vous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire.","","Vous DEVEZ agir seul."}}
D[7637] = {"L'accent sur le sacrifice",{"Rendez-vous à Ironforge et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or."}}
D[7638] = {"Le seigneur Grayson Shadowbreaker",{"Parler au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind."}}
D[7639] = {"Des preuves de jugement",{"Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Stormwind."}}
D[7640] = {"Exorciser Val-Terreur",{"Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind."}}
D[7641] = {"L'œuvre de Grimand Elmore",{"Parlez à Grimand Elmore dans le Quartier des nains de Stormwind."}}
D[7642] = {"Une ribambelle d'objets",{"Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Stormwind."}}
D[7643] = {"L'ancien esprit équin",{"Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer.","","Ensuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse."}}
D[7644] = {"Le caparaçon en arcanite béni",{"Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker."}}
D[7645] = {"Fourrage enrichi en manne",{"Récupérer 20 Biscuits enrichis en manne, l’ingrédient vital qui permet de préparer du Fourrage enrichi en manne, pour le compte de Merideth Carlson de Southore dans les contreforts d’Hillsbrad. L’Aube d’argent est la seule à fabriquer ces biscuits.","","Vous devrez également lui donner 50 pièces d’or pour apaiser sa susceptibilité."}}
D[7646] = {"Le Clairvoyant",{"Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind."}}
D[7647] = {"Jugement et rédemption",{"Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu.","","Ensuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre."}}
D[7648] = {"Le chef d'œuvre de Grimand",{"Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind, pour inspection."}}
D[7649] = {"Les plates en thorium enchanté - Volume I",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7650] = {"Les plates en thorium enchanté - Volume II",{"Rendez ce livre à ses légitimes propriétaires."}}
D[7651] = {"Les plates en thorium enchanté - Volume III",{"Rendez ce livre à ses légitimes propriétaires."}}
