D[7654] = {"Les bottes impériales en plaques"}
D[7655] = {"Les bracelets impériaux en plaques"}
D[7656] = {"La pansière impériale"}
D[7657] = {"Le heaume impérial en plaques"}
D[7658] = {"Les jambières impériales en plaques"}
D[7659] = {"Les épaulières impériales en plaques"}
