D[8275] = {"La reconquête de Silithus",{"Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus."}}
D[8276] = {"La reconquête de Silithus",{"Parler à l'imploratrice céleste Proudhorn au Fort cénarien, en Silithus."}}
D[8277] = {"Venin mortel du désert",{"Beetix Ficklespragg au Fort cénarien en Silithus veut que vous ramassiez 8 Dards de scorpide Cinglepierre et 8 Crocs de Glisseuse du sable. Retournez la voir quand vous aurez terminé."}}
D[8278] = {"Le dernier espoir de Noggle",{"Beetix Ficklespragg, du Fort cénarien en Silithus, veut que vous ramassiez 3 Dards de pinceurs Cinglepierre, 3 Dards d'écorcheur Cinglepierre et 3 Crocs de traqueuse des rochers."}}
D[8279] = {"Le lexique du Crépuscule",{"Apportez les trois chapitres du Lexique du Crépuscule à l'ermite Ortell, en Silithus."}}
D[8280] = {"Sécuriser les lignes d'approvisionnement",{"L'Imploratrice céleste Proudhorn au Fort cénarien en Silithus veut que vous tuiez 15 Frappeurs térébrants."}}
D[8281] = {"Améliorer la sécurité",{"L'Imploratrice céleste Corne-fière au Fort cénarien en Silithus veut que vous tuiez 20 Écraseurs térébrants."}}
D[8282] = {"La sacoche perdue de Noggle",{"Récupérez la Sacoche de Noggle dans les montagnes au sud de Silithus et rapportez-la-lui au Fort cénarien."}}
D[8283] = {"On recherche : Poigne-de-mort, Terreur des sables",{"Apporter la Pince de Poigne-de-mort à Vish Kozus, capitaine de la garde."}}
D[8284] = {"Le mystère du Crépuscule",{"La géologue Larksbane du Fort cénarien en Silithus veut que vous rassembliez 8 Fragments de Tablette du crépuscule."}}
D[8285] = {"Le déserteur",{"Apportez la Tablette réparée à l'ermite Ortell en Silithus."}}
D[8286] = {"Ce que demain apportera",{"Rendez vous dans les grottes du Temps en Tanaris et trouvez Anachronos, la progéniture de Nozdormu."}}
D[8287] = {"Un terrible but",{"Remettez la Transcirption décodée de la tablette au commandant Mar'alith."}}
D[8288] = {"Il ne peut y en avoir qu'un",{"Rapportez la Tête du seigneur des couvées Lanistaire à Baristolth des Sables changeants, au Fort cénarien en Silithus."}}
D[8289] = {"Les talismans de vaillance"}
D[8290] = {"Triomphez des envahisseurs !",{"Entrez dans le goulet des Warsong, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Warsong. Puis revenez voir la sentinelle Farsong au bosquet d'Aile-argent."}}
D[8291] = {"Triomphez des envahisseurs !",{"Entrez dans le goulet des Warsong, triomphez de la Horde et gagnez une Marque d'honneur du goulet des Warsong. Puis revenez voir la sentinelle Farsong au bosquet d'Aile-argent."}}
