D[8293] = {"La marque d'honneur"}
D[8294] = {"Écrasez les usurpateurs d'Aile-argent",{"Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan."}}
D[8295] = {"Écrasez les usurpateurs d'Aile-argent",{"Entrez dans le goulet des Warsong, triomphez de l'Alliance et obtenez une Marque d'honneur du goulet des Warsong. Puis revenez voir le capitaine Shatterskull au campement de Mor'shan."}}
