D[8301] = {"Le Chemin des Justes",{"Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth."}}
D[8302] = {"La Main des Justes",{"Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth."}}
D[8303] = {"Anachronos",{"Chercher Anachronos dans les Grottes du temps à Tanaris."}}
D[8304] = {"Chère Natalia",{"Le commandant Mar’alith, du Fort cénarien en Silithus, veut que vous interrogiez les habitants du Campement de Bronzebeard, qui se trouve au sud du Fort cénarien.","","Lorsque vous aurez réuni les informations demandées, retournez voir le commandant Mar’alith."}}
D[8305] = {"Des souvenirs oubliés depuis longtemps",{"Trouvez la Larme cristalline, en Silithus, et contemplez ses profondeurs."}}
D[8306] = {"L'antre de la folie",{"Le commandant Mar'alith au Fort cénarien en Silithus veut que vous retrouviez sa bien-aimée, Natalia. Selon les informations que vous avez réunies, la Ruche'Regal au sud serait l'endroit où vous pourriez trouver dame Natalia Mar'alith.","","N'oubliez pas de rendre visite aux nains au camp de Bronzebeard avant de vous aventurer dans la ruche. Ils ont peut-être d'autres tâches à vous confier et des conseils pour vous.","","Et <nom>, souvenez-vous des mots du commandant : \"Faites votre devoir...\""}}
D[8307] = {"Recette du désert",{"Cherchez des informations sur la façon de cuisiner la Chair de ver de sable, au camp du Marteau du crépuscule à l'ouest du Fort cénarien."}}
D[8308] = {"La lettre perdue de Brann Bronzebeard",{"Apporter la Lettre de Brann Bronzebeard au Campement de Bronzebeard dans le sud de Silithus."}}
D[8309] = {"À la poursuite des glyphes",{"Rutgar Glyphshaper, du campement de Bronzebeard en Silithus, veut que vous entriez dans Ruche’Ashi, Ruche’Zora et Ruche’Regal et que vous récupériez des reproductions des Cristaux ornés de glyphes dans chaque ruche.","","Utilisez la Trousse de transcription du géologue pour obtenir une copie correcte de ces glyphes antiques. Lorsque vous aurez terminé, retournez voir Rutgar Glyphshaper."}}
D[8310] = {"Déchiffrer le code",{"Obtenez un Cerveau de silithide intact provenant de la Ruche’Regal. N’importe quel silithide de cette ruche fera l’affaire."}}
D[8311] = {"Des bonbons de la Sanssaint pour Jesper !",{"Parler aux aubergistes de Stormwind, d'Ironforge, de Darnassus, et à Talvash del Kissel à Ironforge. Accomplissez les blagues qu'ils vous demanderont de faire en échange de bonbons.","","Retournez voir Jesper à l'orphelinat de Stormwind avec un Massepain de Darnassus, une Boule de gomme de Gnomeregan, du Nougat de Stormwind et un Bonbon à la menthe d'Ironforge."}}
D[8312] = {"Des bonbons de la Sanssaint pour Spoops !",{"Parler aux aubergistes d'Orgrimmar, d'Undercity, de Thunder Bluff, et à Kali Remik au village de Sen'jin. Accomplissez les blagues qu'ils vous demanderont de faire en échange de bonbons.","","Retournez voir Spoops à l'orphelinat d'Orgrimmar avec un Massepain de Thunder Bluff, une Boule de gomme de Darkspear, du Nougat d'Orgrimmar et un Bonbon à la menthe d'Undercity."}}
D[8313] = {"Partager la connaissance",{"Apportez la Page de recette déchirée à Calandrath, à l’auberge du Fort cénarien."}}
D[8314] = {"Dévoiler le mystère",{"Rutgar Glyphshaper, du campement de Bronzebeard, veut que vous remettiez le Prisme cristallin orné de glyphes à la géologue Larksbane, au Fort cénarien en Silithus."}}
D[8315] = {"L'appel",{"La géologue Larksbane, au Fort cénarien en Silithus, veut que vous récupériez le Mécanisme de déverrouillage du cristal sur le Maître des clés.","","Elle vous a demandé de vous rendre près des Restes de Grakkarond, au sud du Fort cénarien, et d’y dessiner les glyphes d'appel dans le sable. Si le Maître des clés apparaît, tuez-le et récupérez le Mécanisme de déverrouillage du cristal. Ensuite, si vous avez réussi, retournez voir la géologue Larksbane.","","Elle vous a conseillé d’emmener une armée, <nom>."}}
D[8316] = {"Armes de guerre"}
D[8317] = {"Un coup de main à la cuisine",{"Calandrath, du Fort cénarien, a besoin d’une fournée de 10 Boulettes du desert fumées."}}
D[8318] = {"Communications secrètes",{"Apporter 10 Textes du crépuscule cryptés à Bor Wildmane au Fort cénarien."}}
D[8319] = {"Les textes du crépuscule cryptés"}
D[8320] = {"Les géoseigneurs du crépuscule",{"Tuer 10 Géoseigneurs du crépuscule, puis retourner voir Huum Wildmane au Fort cénarien."}}
D[8321] = {"Vyral le Vil",{"Remettre la Chevalière de Vyral à Huum Wildmane au Fort cénarien."}}
D[8322] = {"Les œufs pourris",{"Placez les Oeufs pourris dans le tonneau de bière principal de l’auberge de Southshore."}}
D[8323] = {"Les vrais croyants",{"L'ermite Ortell veut que vous lui apportiez 10 Textes du crépuscule cryptés."}}
D[8324] = {"Je crois encore…"}
D[8331] = {"Aurel Feuilledor",{"Parlez à Aurel Feuilledor au Fort cénarien."}}
D[8332] = {"Les ducs du Conseil",{"Apportez 1 Grand éclat brillant et 3 Blasons abyssaux à Aurel Goldleaf, au Fort cénarien."}}
D[8333] = {"Le médaillon de statut"}
D[8341] = {"Les seigneurs du conseil",{"Apportez 5 Grands éclats brillants et 3 Chevalières abyssales à Aurel Feuilledor, au Fort cénarien."}}
D[8342] = {"L'anneau d'autorité du crépuscule"}
D[8343] = {"La découverte de Feuilledor",{"Parlez à Aurel Feuilledor au Fort cénarien."}}
D[8348] = {"La chevalière des ducs",{"Apportez la Chevalière abyssale à Bor Crin-sauvage, au Fort cénarien."}}
D[8349] = {"Bor Crin-sauvage",{"Parlez à Bor Crin-sauvage au Fort cénarien."}}
D[8351] = {"Bor souhaite vous parler",{"Parlez à Bor Crin-sauvage au Fort cénarien."}}
D[8352] = {"Le sceptre du Conseil",{"Apportez un Sceptre abyssal à Bor Crin-sauvage, au Fort cénarien."}}
D[8353] = {"Caqueter pour un bonbon à la menthe",{"Utilisez l'emote /poulet devant l'aubergiste Firebrew, et vous recevrez en échange un bonbon à la menthe d'Ironforge !"}}
D[8354] = {"Caqueter pour un bonbon à la menthe",{"Utilisez l'emote /poulet devant l'aubergiste Norman, et vous recevrez en échange un bonbon à la menthe d'Undercity !"}}
D[8355] = {"Boule de gomme en approche",{"Utilisez l'emote /tchou devant Talvash del Kissel, et vous recevrez en échange une boule de gomme de Gnomeregan !"}}
D[8356] = {"Montrer ses muscles pour du nougat",{"Utilisez l'emote /frime devant l'aubergiste Allison, et vous recevrez en échange du nougat de Stormwind !"}}
D[8357] = {"Danser pour du massepain",{"Utilisez l'emote /danser devant l'aubergiste Saelienne, et vous recevrez en échange du massepain de Darnassus !"}}
D[8358] = {"Boule de gomme en approche",{"Utilisez l'emote /tchou devant Kali Remik, et vous recevrez en échange une boule de gomme de Darkspear !"}}
D[8359] = {"Montrer ses muscles pour du nougat",{"Utilisez l'emote /frime devant l'aubergiste Gryshka, et vous recevrez en échange du nougat d'Orgrimmar !"}}
D[8360] = {"Danser pour du massepain",{"Utilisez l'emote /danser devant l'aubergiste Pala, et vous recevrez en échange du massepain de Thunder Bluff !"}}
D[8361] = {"Des contacts abyssaux",{"Bor Wildmane, du Fort cénarien en Silithus, veut que vous détruisiez un Templier abyssal et que vous lui rameniez un Blason abyssal comme preuve de votre exploit."}}
D[8362] = {"Les blasons abyssaux"}
D[8363] = {"Les chevalières abyssales"}
D[8364] = {"Les sceptres abyssaux"}
D[8365] = {"Ohé, des chapeaux de pirate !",{"La Modiste arrogante veut que vous lui rapportiez 20 Chapeaux de pirate des Mers du sud au port Gentepression, en Tanaris."}}
D[8366] = {"Le racket des Mers du sud",{"Le chef de la sécurité Bilgewhizzle du port Gentepression, en Tanaris, veut que vous tuiez 10 Pirates des Mers du sud, 10 Flibustiers des Mers du sud, 10 Portefaix des Mers du sud et 10 Bretteurs des Mers du sud."}}
D[8367] = {"Pour un grand honneur",{"Apportez 3 Marques d’honneur de la vallée d’Alterac, 3 Marques d’honneur du bassin d’Arathi et 3 Marques d’honneur du goulet des Warsong à l’un des porteguerre de la Horde, devant les champs de bataille."}}
D[8368] = {"La bataille du goulet des Warsong",{"Apportez 3 Marques d’honneur Warsong à l’un des porteguerres de la Horde, devant les champs de bataille."}}
D[8369] = {"Les envahisseurs de la vallée d'Alterac",{"Apportez 3 Marques d’honneur de la vallée d’Alterac à l’un des porteguerres de la Horde, devant les champs de bataille."}}
D[8370] = {"La conquête du bassin d'Arathi",{"Apportez 3 Marques d’honneur du bassin d’Arathi à l’un des porteguerres de la Horde, devant les champs de bataille."}}
D[8371] = {"Des efforts concertés",{"Apportez 3 Marques d'honneur de la vallée d'Alterac, 3 Marques d'honneur du bassin d'Arathi et 3 Marques d'honneur du goulet des Warsong à un général de brigade de l'Alliance, devant les champs de bataille."}}
D[8372] = {"La lutte pour le goulet des Warsong",{"Apportez 3 Marques d'honneur du goulet des Warsong à un général de brigade de l'Alliance, devant les champs de bataille."}}
D[8373] = {"La puissance du pin",{"Utilisez le Nettoyeur de boules puantes pour retirer les Boules puantes que les Réprouvés ont lancées sur Southshore. Retournez voir le sergent Hartman à Southshore quand vous aurez terminé."}}
D[8374] = {"La revendication du bassin d'Arathi",{"Apportez 3 Marques d'honneur du bassin d'Arathi à un général de brigade de l'Alliance, devant les champs de bataille."}}
D[8375] = {"Souvenez-vous de la vallée d'Alterac !",{"Apportez 3 Marques d'honneur de la vallée d'Alterac à un général de brigade de l'Alliance, devant les champs de bataille."}}
