D[8409] = {"Des tonneaux gâtés",{"Retournez voir la sombre imploratrice Yanka à la Fête de l'homme d'osier dans les clairières de Tirisfal."}}
D[8410] = {"La maîtrise des éléments",{"Rassembler un échantillon d'air, de feu, de terre et d'eau pour Bath'rah la Vigie des Vents."}}
D[8411] = {"Maîtriser les éléments",{"Apportez les éléments terre, air, feu et eau à Bath'rah la Vigie des vents."}}
D[8412] = {"Le totem des esprits",{"Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents."}}
D[8413] = {"Vaudou !",{"Apporter les Plumes vaudou à Bath'rah la Vigie des vents."}}
D[8414] = {"La dissipation du mal",{"Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel'danis dans les Maleterres de l'ouest."}}
D[8415] = {"La pointe du Noroît",{"Parler au commandant Ashlam Vaillepoing au Camp du Noroît."}}
D[8416] = {"Pierres du Fléau inertes",{"Apportez la Pierre du Fléau inerte au commandant Ashlam Vaillepoing à la pointe du Noroît."}}
D[8417] = {"Un esprit troublé",{"Parlez au Héros de la Horde tombé au combat, à l'entrée des Terres Foudroyées."}}
D[8418] = {"Forger la pierre de pouvoir",{"Apportez des Plumes vaudou ambres, bleues et vertes."}}
D[8419] = {"La demande d'un diablotin",{"Apportez un morceau de Gangrétoffe à Démonet à Gangrebois."}}
D[8420] = {"Chaud et piquant",{"Apportez un morceau de gangrétoffe à Démonet à Gangrebois."}}
D[8421] = {"L'anti-étoffe des héros",{"Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois."}}
D[8422] = {"Les trolls d'un même plumage…",{"Apporter 6 Plumes vaudou des trolls du Temple englouti."}}
D[8423] = {"Fraternité entre guerriers",{"Tuez 7 Sangliers infernaux dans les Terres Foudroyées, et revenez voir le Héros de la Horde tombé au combat."}}
D[8424] = {"La guerre contre les liges d'ombre",{"Tuez les Liges d'ombre dans les Terres Foudroyées et revenez voir le Héros de la Horde tombé au combat."}}
D[8425] = {"Plumes vaudou",{"Apportez les Plumes vaudou des trolls du Temple englouti au Héros de la Horde tombé au combat."}}
D[8426] = {"La bataille du goulet des Warsong",{"Apportez 3 Marques d’honneur du goulet des Warsong à l’un des porteguerres de la Horde, devant les champs de bataille."}}
