D[8446] = {"Voilé par le cauchemar",{"Trouver quelqu’un capable de comprendre la signification de l’Objet noyé dans les cauchemars.","","Peut-être qu’un druide de grande puissance pourra vous aider."}}
D[8447] = {"L'éveil des légendes",{"Attendre que le gardien Remulos de Reflet-de-Lune ait purifié l’Objet noyé dans les cauchemars."}}
D[8460] = {"Allié des Grumegueules",{"Grifleur veut que vous prouviez votre valeur en tuant 6 Guerriers Mort-bois, 6 Guides Mort-bois et 6 Jardiniers Mort-bois. Lorsque ce sera fait, retournez le voir dans le sud de Gangrebois, près du Sanctuaire d'émeraude."}}
D[8461] = {"Les Mort-bois du nord",{"Nafien veut que vous tuiez 6 Protecteurs Mort-bois, 6 Vengeurs Mort-bois et 6 Chamans Mort-bois. Ensuite, retournez le voir dans le nord de Gangrebois, près de l'entrée du repaire des Grumegueules."}}
D[8462] = {"Parler à Nafien",{"Suivre la route principale de Gangrebois vers le nord et parler à Nafien le furbolg. Il monte la garde à côté de l’entrée du repaire des Grumegueules."}}
D[8464] = {"Les Tombe-hiver s'agitent",{"Salfa voudrait que vous tuiez 8 Chamans Tombe-hiver, 8 Protecteurs Tombe-hiver et 8 Ursas Tombe-hiver. Salfa se trouve juste à l'extérieur de l'entrée du repaire des Grumegueules, au Berceau-de-l'hiver."}}
D[8465] = {"Parler à Salfa",{"Traverser le repaire des Grumegueules et sortir au Berceau-de-l’Hiver. Parlez à Salfa, qui monte la garde à l’extérieur du repaire des Grumegueules."}}
D[8466] = {"Des plumes pour Grifleur"}
D[8467] = {"Des plumes pour Nafien"}
D[8469] = {"Des perles pour Salfa"}
D[8470] = {"Le totem rituel des Mort-bois",{"Amener le Totem rituel mort-bois à l’intérieur du repaire des Grumegueules et voir si l’un des furbolgs qui s’y trouvent est capable d’en faire quelque chose. Les Grumegueules ne vous adresseront pas la parole s’ils ne sont pas Neutres à votre égard, au minimum."}}
D[8471] = {"Le totem rituel des Tombe-hiver",{"Emportez le totem rituel Tombe-hiver au Repaire des Grumegueules et voyez si l’un des furbolgs lui trouve une utilisation. Les Grumegueules ne vous parleront pas si vous n’avez pas à leur égard une réputation Neutre au minimum."}}
D[8481] = {"La racine du mal",{"Plantez la Torche d'invocation de démon à l’entrée de la caverne du grand chef Tombe-hiver, dans le village des furbolgs Tombe-hiver. Triomphez du démon et récupérez l’Essence de Xandivious pour Gorn le Borgne du Repaire des Grumegueules."}}
D[8484] = {"Négocier la paix",{"Apporter l’Offrande de paix grumegueule au roi Magni Bronzebeard, à Ironforge."}}
D[8485] = {"Négocier la paix",{"Apporter l’Offrande de paix grumegueule à Thrall, à Orgrimmar."}}
D[8492] = {"L'Alliance a besoin de barres de cuivre !",{"Ramener 20 barres de cuivre au sergent Stonebrow dans la Garde militaire d'Ironforge."}}
D[8493] = {"L'Alliance a besoin de plus de barres de cuivre !",{"Ramener 20 Barres de cuivre au sergent Front-de-Pierre à l’aérodrome de Dun Morogh."}}
D[8494] = {"L'Alliance a besoin de barres de fer !",{"Ramener 20 barres de fer au caporal Carnes dans la Garde militaire d'Ironforge."}}
D[8495] = {"L'Alliance a besoin de plus de barres de fer !",{"Ramener 20 barres de fer au caporal Carnes à l’aérodrome de Dun Morogh."}}
D[8496] = {"Des bandages pour la campagne",{"Apportez 30 Bandages épais en étoffe runique, 30 Bandages épais en soie et 30 Bandages épais en tisse-mage à l’imploratrice céleste Proudhorn. Vous devez aussi apporter le Briefing logistique X pour terminer cette quête."}}
D[8497] = {"Survivre dans le désert"}
D[8498] = {"Les ordres de batailles du Crépuscule",{"Vous procurer les Ordres de bataille du Crépuscule et les ramener au commandant Mar’alith, au Fort cénarien de Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique X."}}
D[8499] = {"L'Alliance a besoin de barres de thorium !",{"Ramener 20 Barres de thorium à dame Twinbraid dans la Garde militaire d'Ironforge."}}
D[8500] = {"L'Alliance a besoin de plus de barres de thorium !",{"Apportez 20 Barres de thorium à Dame Doublenattes à l'aérodrome de Dun Morogh."}}
D[8501] = {"Objectif : les aiguillonneurs de la Ruche'Ashi",{"Tuez 30 Aiguillonneurs de la Ruche’Ashi, puis présentez-vous au rapport devant le commandant Mar’alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat XII."}}
D[8502] = {"Objectif : les ouvrières de la Ruche'Ashi",{"Tuez 30 Ouvrières de la Ruche’Ashi, et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat III pour terminer cette quête."}}
D[8503] = {"L'Alliance a besoin d'étouffante !",{"Ramener 20 Etouffantes au soldat Draxlegauge dans la Garde militaire d'Ironforge."}}
D[8504] = {"L'Alliance a besoin de plus d'étouffante !",{"Rapportez 20 Étouffantes au Soldat Draunessieu, à l’aérodrome en Dun Morogh."}}
D[8505] = {"L'Alliance a besoin de lotus pourpre !",{"Ramener 20 lotus pourpres à maître Nightsong, dans la Garde militaire d'Ironforge."}}
D[8506] = {"L'Alliance a besoin de plus de lotus pourpre !",{"Rapportez 20 Lotus pourpres à Maître Chantenuit, à l’aérodrome de Dun Morogh."}}
D[8507] = {"Votre affectation",{"Présentez-vous au poste de la brigade d’Ironforge devant la Ruche’Zora. Préparez votre Ordre de mission et obtenez un Ordre de mission signé du capitaine Blackanvil. Ensuite, retournez voir l'Implorateur céleste Kaldon au Fort cénarien, en Silithus.","","Note : lancer un sort de soin, ou tout autre sort bénéfique, sur un membre de la brigade d’Ironforge vous infligera un marqueur JcJ."}}
D[8508] = {"La liste des affectations"}
D[8509] = {"L'Alliance a besoin de larmes d'Arthas !",{"Ramener 20 larmes d’Arthas au sergent-major Germaine dans la Garde militaire d'Ironforge."}}
D[8510] = {"L'Alliance a besoin de plus de larmes d'Arthas !",{"Ramener 20 larmes d’Arthas au sergent-major Germain à l’aérodrome de Dun Morogh."}}
D[8511] = {"L'Alliance a besoin de cuir léger !",{"Ramenez 10 Cuirs légers à Bonnie Stoneflayer dans la Garde militaire d'Ironforge."}}
D[8512] = {"L'Alliance a besoin de plus de cuir léger !",{"Apportez 10 Cuirs légers à Bonnie Ecorchepierre à l'aérodrome de Dun Morogh."}}
D[8513] = {"L'Alliance a besoin de cuir moyen !",{"Ramener 10 cuirs moyens au soldat Porter dans la Garde militaire d'Ironforge."}}
D[8514] = {"L'Alliance a besoin de plus de cuir moyen !",{"Ramener 10 cuirs moyens au soldat Porter, à l’aérodrome de Dun Morogh."}}
D[8515] = {"L'Alliance a besoin de cuir épais !",{"Ramener 10 Cuirs épais à Marta Finespindle dans la Garde militaire d'Ironforge."}}
D[8516] = {"L'Alliance a besoin de plus de cuir épais !",{"Ramener 10 cuirs légers à Marta Finespindle à l’aérodrome de Dun Morogh."}}
D[8517] = {"L'Alliance a besoin de bandages en lin !",{"Ramener 20 bandages en lin à la Sentinelle Silversky, dans la Garde militaire d'Ironforge."}}
D[8518] = {"L'Alliance a besoin de plus de bandages en lin !",{"Apportez 20 Bandages en lin à la Sentinelle Silversky à l'aérodrome de Dun Morogh."}}
D[8519] = {"Un pion sur l'Echiquier éternel",{"Apprenez tout ce que vous pouvez au sujet du passé, puis parlez à Anachronos dans les Grottes du temps à Tanaris."}}
D[8520] = {"L'Alliance a besoin de bandages en soie !",{"Ramener 20 bandages en soie à l’infirmière Stonefield, dans la Garde militaire d'Ironforge."}}
D[8521] = {"L'Alliance a besoin de plus de bandages en soie !",{"Apportez 20 Bandages en soie à l'infirmière Champierreux à l'aérodrome de Dun Morogh."}}
D[8522] = {"L'Alliance a besoin de bandages en étoffe runique !",{"Ramener 20 Bandages en étoffe runique au Gardien Moonshade dans la Garde militaire d'Ironforge."}}
D[8523] = {"L'Alliance a besoin de plus de bandages en étoffe runique !",{"Ramener 20 bandages en étoffe runique au gardien Lunombrage à l’aérodrome de Dun Morogh."}}
D[8524] = {"L'Alliance a besoin de thon arc-en-ciel !",{"Ramener 20 Thons arc-en-ciel à Khirry le Gastronome dans la Garde militaire d'Ironforge."}}
D[8525] = {"L'Alliance a besoin de plus de thon arc-en-ciel !",{"Rapportez 20 thons arc-en-ciel à Khirry le Gastrognome à l’aéroport de Dun Morogh."}}
D[8526] = {"L'Alliance a besoin de rôtis de raptor !",{"Ramener 20 Rôtis de raptor à Sarah Sadwhistle dans la Garde militaire d'Ironforge."}}
D[8527] = {"L'Alliance a besoin de plus de rôti de raptor !",{"Rapportez 20 Rôtis de raptor à Sarah Tristesifflet, à l’aérodrome de Dun Morogh."}}
D[8528] = {"L'Alliance a besoin de jaune-queue tacheté !",{"Ramener 20 jaunes-queues tachetés à la chasseresse Swiftriver dans la Garde militaire d'Ironforge."}}
D[8529] = {"L'Alliance a besoin de plus de jaune-queue tacheté !",{"Rapportez 20 Jaunes-queues tachetés à la chasseresse Ondevive, à l’aérodrome de Dun Morogh."}}
D[8532] = {"La Horde a besoin de barres de cuivre !",{"Ramener 20 barres de cuivre au mineur Cromwell dans la Vallée des esprits d'Orgrimmar."}}
D[8533] = {"La Horde a besoin de plus de barres de cuivre !",{"Rapportez 20 Barres de cuivre au Mineur Cromwell, en Durotar."}}
D[8534] = {"Rapport de reconnaissance de la Ruche'Zora",{"Trouver l’Eclaireur cénarien Azenel dans la Ruche’Zora et ramener le Rapport de reconnaissance de la Ruche’Zora à l’Imploratrice céleste Proudhorn, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique VI."}}
D[8535] = {"Le templier chenu",{"Invoquez et tuez un Templier chenu, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique IV."}}
D[8536] = {"Le templier terrestre",{"Invoquez et tuez un Templier terrestre, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique III."}}
D[8537] = {"Le templier cramoisi",{"Invoquez et tuez un Templier cramoisi, puis allez faire votre rapport à Bor Wildmane, au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique II."}}
D[8538] = {"Les quatre ducs",{"Trouver un moyen d’invoquer et de tuer les duc des Cendres, le duc des Profondeurs, le duc des Zéphyrs et le duc des Éclats, puis revenir voir le commandant Mar'alith au Fort cénarien. Pour terminer cette quête, vous devez aussi apporter le Briefing tactique V."}}
D[8539] = {"Objectif : les sœurs de Ruche'Zora",{"Tuez 30 Soeurs de la Ruche’Zora et revenez faire votre rapport au commandant Mar'alith au Fort cénarien, en Silithus. Vous devez aussi apporter le Briefing de combat V pour terminer cette quête."}}
D[8540] = {"Des bottes pour la Garde",{"Remettre 3 Bottes ornées en mithril à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique II pour terminer cette quête."}}
D[8541] = {"Des silex à aiguiser pour la Garde",{"Apporter 10 Silex à aiguiser denses, 10 Silex à aiguiser solides et 10 Silex à aiguiser lourds à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Vous devez aussi apporter le Briefing logistique III pour terminer cette quête."}}
D[8542] = {"La Horde a besoin de barres d'étain !",{"Apportez 20 Barres d'étain au grunt Maug dans la Vallée des esprits d'Orgrimmar."}}
D[8543] = {"La Horde a besoin de plus de barres d'étain !",{"Apportez 20 Barres d’étain au Grunt Maug en Durotar."}}
D[8544] = {"Les spallières de conquérant",{"Apportez des Manchettes de commandement qiraji, 2 Idoles de la nuit, 5 Scarabées de pierre et 5 Scarabées d’argile à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, la Progéniture de Nozdormu doit au moins être Neutre à votre égard."}}
D[8545] = {"La Horde a besoin de barres de mithril !",{"Ramener 20 barres de mithril au sergent-chef T’kelah dans la Vallée des esprits d'Orgrimmar."}}
D[8546] = {"La Horde a besoin de plus de barres de mithril !"}
D[8548] = {"L'équipement de guerre des volontaires",{"Apportez 5 Badges cénariens de combat, 3 Badges cénariens de logistique et 7 Badges cénariens de tactique à Vargus, au Fort cénarien en Silithus. Pour terminer cette quête, il faut aussi que le Cercle cénarien soit au moins Amical à votre égard."}}
D[8549] = {"La Horde a besoin de pacifique !",{"Ramener 20 pacifiques à l’herboriste Proudfeather dans la Vallée des esprits d'Orgrimmar."}}
D[8550] = {"La Horde a besoin de plus de pacifique !"}
D[8551] = {"Le coffre du capitaine",{"Apporter le coffre au capitaine Hecklebury Smotts à Baie-du-Butin."}}
D[8552] = {"L'écharpe à monogramme",{"Rendre l'Echarpe à monogramme à son propriétaire."}}
D[8553] = {"Le sabre du capitaine Smott",{"Parler à Sprogger."}}
D[8554] = {"Face à Negolash",{"Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevine dans le Canot de sauvetage du capitaine Smott.","","Tuer Negolash, et apporter le Coutelas de Smotts au capitaine Smotts, à Strangleronce."}}
D[8555] = {"Le fardeau des Vols draconiques"}
D[8556] = {"Chevalière de force inflexible",{"Apporter 1 Anneau de magistrat qiraji, 2 Idoles brillantes, 5 Scarabées en bronze et 5 Scarabées d'ivoire à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8557] = {"Drapé de force inflexible",{"Apporter 1 Drapé martial qiraji, 2 Idoles d'onyx, 5 Scarabées d'argent et 5 Scarabées d'os à Keyl Swiftclaw, en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête."}}
D[8558] = {"La faucille de force inflexible",{"Apporter 1 Manche à pointes qiraji, 2 Idoles d'albâtre, 5 Scarabées de cristal et 5 Scarabées de pierre au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8559] = {"Les grèves de conquérant",{"Apportez des Manchettes de commandement qiraji, 2 Idoles de la guerre, 5 Scarabées d’ivoire et 5 Scarabées d’or à Kandrostrasz, à Ahn'Qiraj. Il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard."}}
D[8560] = {"Les garde-jambes de conquérant",{"Ramener la Peau intacte d’Ouro, 2 Idoles de la mort, 5 Scarabées en bronze et 5 Scarabées d’ivoire à Kandrostrasz, à l’intérieur d’Ahn'Qiraj. Pour terminer cette quête, il faut également que la Progéniture de Nozdormu soit au moins Amicale à votre égard."}}
D[8561] = {"La couronne de conquérant",{"Apportez le Diadème de Vek’nilash, 2 Idoles du soleil, 5 Scarabées de pierre et 5 Scarabées de cristal à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, il faut également que la Progéniture de Nozdormu soit au moins Amicale à votre égard."}}
D[8562] = {"La cuirasse de conquérant",{"Apportez la Carapace du Dieu très ancien, 2 Idoles de la guerre, 5 Scarabées d’argent et 5 Scarabées d’os à Vethsera, à l’intérieur d’Ahn’Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu."}}
D[8565] = {"Victoires passées en Arathi"}
D[8566] = {"Victoires passées en Arathi"}
D[8567] = {"Victoires passées dans le goulet des Warsong"}
D[8568] = {"Victoires passées dans le goulet des Warsong"}
