D[8570] = {"Efforts passés dans le goulet des Warsong"}
D[8572] = {"La tenue de combat de vétéran",{"Ramener 7 Badges cénariens de combat, 4 Badges cénariens de logistique et 4 Badges cénariens de tactique à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8573] = {"Equipement de guerre de champion",{"Ramener 15 Badges cénariens de combat, 20 Badges cénariens de logistique, 20 Badges cénariens de tactique et 1 Marque de Cénarius à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8574] = {"L’équipement de guerre de fidèle",{"Ramener 15 Badges cénariens de combat, 20 Badges cénariens de logistique, 17 Badges cénariens de tactique et 1 Marque de Remulos à Vargus, au Fort cénarien en Silithus. Vous devrez aussi être <Révéré/Révérée> par le Cercle cénarien pour terminer cette quête."}}
D[8575] = {"Le grand livre magique d'Azuregos",{"Apporter le Grand livre magique d'Azuregos à Narain Divinambolesque, en Tanaris."}}
D[8576] = {"La traduction du grand livre"}
D[8577] = {"Stewvul, ex-M.A.P.V.",{"Narain Divinambolesque veut que vous retrouviez son ex-meilleur ami pour la vie (M.A.P.V.), Stewvul, et que vous repreniez les lunettes de divination que Stewvul lui a volé."}}
D[8578] = {"Des lunettes d'observation ? Aucun problème !",{"Retrouver les Lunettes de divination de Narain et les rapporter à Narain Divinambolesque en Tanaris."}}
D[8579] = {"Champions mortels"}
D[8580] = {"La Horde a besoin de fleur de feu !",{"Ramener 20 fleurs de feu au chevaucheur de chauve-souris Pele’keiki dans la Vallée des esprits d'Orgrimmar."}}
D[8581] = {"La Horde a besoin de plus de fleur de feu !"}
D[8582] = {"La Horde a besoin de lotus pourpre !",{"Ramener 20 lotus pourpres à l’apothicaire Jezel dans la Vallée des esprits d'Orgrimmar."}}
D[8583] = {"La Horde a besoin de plus de lotus pourpre !"}
D[8584] = {"On ne parle jamais de mon boulot",{"Narain Divinambolesque de Tanaris veut que vous parliez à Dirge Hachillico à Gadgetzan."}}
D[8585] = {"L'île de l'effroi !",{"Récupérer la Carcasse de Lakmaeran et 20 Filets de chimaerok pour Dirge Quickcleave, en Tanaris."}}
D[8586] = {"Pyro-côtelettes de chimaerok à la Dirge",{"Dirge Quickcleave, de Gadgetzan, veut que vous lui rameniez 20 doses de Carburant de fusée des gobelins et 20 doses de Sel de Fonderoc."}}
D[8587] = {"Retour vers Narain",{"Remettre le Poulet de 500 livres à Narain Divinambolesque à Tanaris."}}
D[8588] = {"La Horde a besoin de cuir lourd !",{"Ramener 10 cuirs lourds à l’Ecorcheuse Jamani dans la Vallée des esprits d'Orgrimmar."}}
D[8589] = {"La Horde a besoin de plus de cuir lourd !"}
D[8590] = {"La Horde a besoin de cuir épais !",{"Ramener 10 morceaux de cuir épais au sergent Umala dans la Vallée des esprits d'Orgrimmar."}}
D[8591] = {"La Horde a besoin de plus de cuir épais !"}
D[8592] = {"La tiare de l’oracle",{"Apportez le Diadème de Vek’Nilash, 2 Idoles du sage, 5 Scarabées d'argent et 5 Scarabées d'os à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, il faut également que la Progéniture de Nozdormu soit au moins Amicale à votre égard."}}
D[8593] = {"Le pantalon de l'Oracle",{"Ramener la Peau du grand ver des sables, 2 Idoles de la renaissance, 5 Scarabées d'or et 5 Scarabées d'argile à Kandrostrasz, à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard."}}
D[8594] = {"Le mantelet de l’oracle",{"Apportez des Manchettes de commandement qiraji, 2 Idoles de la renaissance, 5 Scarabées d'argent et 5 Scarabées d'ivoire à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard."}}
D[8595] = {"Champions mortels"}
D[8596] = {"Les bottillons de l’oracle",{"Apportez des Manchettes de commandement qiraji, 2 Idoles de la mort, 5 Scarabées en bronze et 5 Scarabées d’or à Kandrostrasz, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard."}}
D[8597] = {"Le draconique pour les nuls",{"Retrouver le livre de Narain Divinambolesque, enfoui sur une île des mers du Sud."}}
D[8598] = {"rANçOn !",{"Ramener la Demande de rançon a Narain Divinambolesque, en Tanaris."}}
D[8599] = {"Une chanson d'amour pour Narain",{"Transmettre la Lettre d’amour de Meredith à Narain Divinambolesque, en Tanaris."}}
D[8600] = {"La Horde a besoin de cuir robuste !",{"Ramener 10 morceaux de cuir robuste au docteur Serratus dans la Vallée des esprits d'Orgrimmar."}}
D[8601] = {"La Horde a besoin de plus de cuir robuste !"}
D[8602] = {"Les espauliers de l'implorateur des tempêtes",{"Rapporter des Manchettes de domination qiraji, 2 Idoles de la vie, 5 Scarabées d'or et 5 Scarabées de cristal à Andorgos, à Ahn'Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Neutre à votre égard."}}
D[8603] = {"Les habits de l'Oracle",{"Ramemer la Carcasse du Dieu très ancien, 2 Idoles de la mort, 5 Scarabées de pierre et 5 Scarabées de cristal à Vethsera, à l'intérieur d'Ahn'Qiraj. Pour terminer cette quête, vous devez être <Honoré/Honorée> par la Progéniture de Nozdormu."}}
D[8604] = {"La Horde a besoin de bandages en laine !",{"Ramenez 20 bandages en laine au guérisseur Longrunner dans la Vallée des esprits d'Orgrimmar."}}
D[8605] = {"La Horde a besoin de plus de bandages en laine !"}
D[8606] = {"Un leurre !",{"Narain Divinambolesque, en Tanaris, veut que vous vous rendiez au Berceau-de-l’Hiver et que vous posiez le Sac d'or à l’endroit indiqué par les voleurs de livres."}}
D[8607] = {"La Horde a besoin de bandages en tisse-mage !",{"Ramenez 20 bandages en tisse-mage à dame Callow dans la Vallée des esprits d'Orgrimmar."}}
D[8608] = {"La Horde a besoin de plus de bandages en tisse-mage !"}
D[8609] = {"La Horde a besoin de bandages en étoffe runique !",{"Ramener 20 bandages en étoffe runique à la Garde de pierre Clayhoof dans la Vallée des esprits d'Orgrimmar."}}
D[8610] = {"La Horde a besoin de plus de bandages en étoffe runique !"}
D[8611] = {"La Horde a besoin de steaks de loup !",{"Ramener 20 steaks de loup à la garde de sang Rawtar dans la Vallée des esprits d'Orgrimmar."}}
D[8612] = {"La Horde a besoin de plus de steaks de loup !"}
D[8613] = {"La Horde a besoin de jaunes-queues tachetés !",{"Ramener 20 jaunes-queues tachetés au pêcheur Lin’do dans la Vallée des esprits d'Orgrimmar."}}
D[8614] = {"La Horde a besoin de plus de jaunes-queues tachetés !"}
D[8615] = {"La Horde a besoin de pains de saumon !",{"Ramener 20 pains de saumon au chef Sharpclaw dans la Vallée des esprits d'Orgrimmar."}}
D[8616] = {"La Horde a besoin de plus de pains de saumon !"}
D[8619] = {"L'Ancien Morndeep"}
D[8620] = {"Le seul remède",{"Retrouver les 8 chapitres perdus du « Draconique pour les nuls » et les combiner avec la Reliure magique, puis ramener l’exemplaire réparé du « Draconique pour les nuls, volume II » à Narain Divinambolesque, en Tanaris."}}
