D[8698] = {"L'anneau de la tempête imminente",{"Apporter 1 Anneau de magistrat qiraji, 2 Idoles vermillon, 5 Scarabées d’argent et 5 Scarabées d'os à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8699] = {"L'anneau des secrets scellés",{"Apporter 1 Anneau de magistrat qiraji, 2 Idoles azur, 5 Scarabées d’or et 5 Scarabées d’argile à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8700] = {"L'anneau de vie interminable",{"Apporter 1 Anneau de magistrat qiraji, 2 Idoles d’albâtre, 5 Scarabées en bronze et 5 Scarabées d'ivoire à l’imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8701] = {"L'anneau des ombres voilées",{"Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d’onyx, 5 Scarabées de pierre et 5 Scarabées de cristal à l’imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8702] = {"L'anneau des noms inexprimés",{"Apporter 1 Anneau de cérémonie qiraji, 2 Idoles de jaspe, 5 Scarabées de pierre et 5 Scarabées de cristal à l’imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8703] = {"L'anneau de justice éternelle",{"Apporter 1 Anneau de magistrat qiraji, 2 Idoles vermillon, 5 Scarabées d'argent et 5 Scarabées d'os à l’imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8704] = {"La chevalière du sentier invisible",{"Apporter 1 Anneau de cérémonie qiraji, 2 Idoles d’ambre, 5 Scarabées d’or et 5 Scarabées d'argile à l’imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."}}
D[8705] = {"Le marteau de sagesse infinie",{"Apporter 1 Manche orné qiraji, 2 Idoles brillantes, 5 Scarabées en bronze et 5 Scarabées d'ivoire au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8706] = {"Le marteau de la tempête imminente",{"Apporter 1 Manche à pointes qiraji, 2 Idoles d’ambre, 5 Scarabées d’ivoire et 5 Scarabées en bronze au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8707] = {"La lame des secrets scellés",{"Apporter 1 Manche orné qiraji, 2 Idoles d’obsidienne, 5 Scarabées d’argent et 5 Scarabées d’os au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8708] = {"La masse de vie interminable",{"Apporter 1 Manche orné qiraji, 2 Idoles de jaspe, 5 Scarabées de cristal et 5 Scarabées de pierre au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8709] = {"La dague des ombres voilées",{"Apporter 1 Manche à pointes qiraji, 2 Idoles vermillon, 5 Scarabées d’or et 5 Scarabées d’argile au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
D[8710] = {"Le kriss des noms inexprimés",{"Apporter 1 Manche orné qiraji, 2 Idoles d'onyx, 5 Scarabées d’or et 5 Scarabées d’argile au Gardien Haro, en Silithus. Vous devrez aussi être <Exalté/Exaltée> par le Cercle cénarien pour terminer cette quête."}}
