D[9022] = {"Les adieux d'Anthion",{"Retournez voir Mokvar à Orgrimmar avec des Bottes de vaillance, des Jambières de vaillance et des Spallières de vaillance."}}
D[9023] = {"Le poison parfait",{"Dirk Thunderwood, du Fort cénarien en Silithus, veut que vous lui rameniez la Glande à venin de Venoxis et la Glande à venin de Kurinaxx."}}
D[9024] = {"L'intuition d'Aristan",{"Remettez 1 bouteille d’Eau de Cologne et 1 Flacon de parfum à Morgan Pestle, dans le Quartier commerçant de Stormwind."}}
D[9025] = {"La découverte de Morgan",{"Retourner voir Aristan Mottar, à côté de la banque, dans le Quartier commerçant de Stormwind."}}
D[9026] = {"Remonter à la source",{"Parler à l’aubergiste Allison à la Rose dorée, dans le Quartier commerçant de Stormwind."}}
D[9027] = {"Remonter à la source",{"Parler à Evert Sorisam, au Fil le plus fin, au bord des canaux de Stormwind."}}
D[9028] = {"La source est découverte !",{"Trouver l’apothicaire Staffron Lerent dans les contreforts de Hautebrande, derrière le manoir de Ravenholdt."}}
D[9029] = {"Un chaudron bouillonnant"}
D[9032] = {"Le triste destin de Bodley",{"Rendez-vous au mont Rochenoire, près du pic Rochenoire, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley."}}
D[9033] = {"Les échos de la guerre",{"Le commandant Eligor Portelaube, de la chapelle de l’Espoir de Lumière dans les Maleterres de l'Est, veut que vous tuiez 5 Monstruosités vivantes, 5 Gargouilles peau de pierre, 8 Capitaines des chevaliers de la mort et 3 Traque-venin."}}
D[9034] = {"Cuirasse de cuirassier",{"Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une cuirasse de cuirassier si vous lui apportez les choses suivantes : 1 Cuirasse désacralisée, 25 Débris d’armure en plaques, 4 Barres d’arcanite et 2 Cristaux de nexus."}}
