D[9331] = {"Voler la flamme d'Ironforge",{"Rapportez la flamme d'Ironforge au Conteur de la fête."}}
D[9332] = {"Voler la flamme de Darnassus",{"Rapportez la flamme de Darnassus au Conteur de la fête."}}
D[9333] = {"Les gants de l'Aube d'argent"}
D[9334] = {"Huile de sorcier bénie"}
D[9335] = {"Pierre à aiguiser consacrée"}
D[9336] = {"Potion de soins majeure"}
D[9337] = {"Potion de mana majeure"}
D[9338] = {"Allégeance au Cercle cénarien"}
D[9339] = {"La récompense d'un voleur"}
D[9341] = {"Tabard de l'Aube d'argent"}
D[9343] = {"Tabard de l'Aube d'argent"}
D[9362] = {"Le seigneur de guerre Krellian",{"Récupérez la Coquille prismatique pour l'archimage Xylem. L'archimage réside dans une tour au sommet des falaises d'Azshara."}}
D[9364] = {"Magie morcelée",{"Métamorphosez les Fouette-bile d’Azshara, puis tuez les clones qui apparaissent quelques instants plus tard. Quand vous aurez tué 50 clones de métamorphose, retournez voir l’archimage Xylem en Azshara."}}
D[9365] = {"La récompense d'un voleur"}
D[9367] = {"La fête du Feu",{"Touchez les feux de joie à l'intérieur de Stormwind, Ironforge et Darnassus, puis parlez à n'importe quel Maître des traditions de la fête dans une des capitales."}}
D[9368] = {"La fête du Feu",{"Touchez les feux de joie à l'intérieur d'Orgrimmar, Thunder Bluff et Undercity, puis parlez à n'importe quel Maître des traditions de la fête dans une des capitales."}}
D[9386] = {"Une Lumière au sein des ombres",{"Trouvez et touchez les feux de joie situés au pic Rochenoire, à Hache-Tripes, dans la Scholomance et à Stratholme, puis parlez au gardien des flammes de la fête."}}
D[9388] = {"Flammes vacillantes en Kalimdor",{"Rendez-vous aux feux de joie d’Ashenvale, des Tarides, de Sombrivage et des Serres-Rocheuses, puis parlez au Gardien des flammes de la fête."}}
D[9389] = {"Flammes vacillantes dans les Royaumes de l'est",{"Rendez-vous aux feux de joie des contreforts d’Hillsbrad, de la forêt des Pins argentés, de la Marche de l’ouest et des Paluns, puis parlez au Gardien des flammes de la fête."}}
D[9415] = {"Se présenter au maréchal Bluewall",{"Parlez au maréchal Bluewall au campement de l’Alliance, près de Ruche’Zora."}}
D[9416] = {"Se présenter au général Kirika",{"Parlez au général Kirika au campement de la Horde, près de Ruche’Regal."}}
D[9419] = {"Passer le désert au peigne fin",{"Trouver de la Silithyste et la livrer à l’ Extracteur de silithyste, puis parler au maréchal Bluewall au campement de l'Alliance près de Ruche'Zora."}}
D[9422] = {"Passer le désert au peigne fin",{"Trouver de la Silithyste et la livrer à un Extracteur de silithyste, puis parler au général Kirika au campement de la Horde près de Ruche’Regal."}}
D[9664] = {"Fonder de nouveaux avant-postes",{"Capturez la Tour de la garde de la couronne, la Tour du Mur d’est, la Tour du Col du nord et la Tour de Pestebois dans les Maleterres de l’est. Revenez ensuite voir l’émissaire Whitebeard à la Chapelle de l’Espoir de Lumière."}}
D[9665] = {"Renforcer nos défenses",{"Capturez la Tour de la garde de la couronne, la Tour du Mur d’est, la Tour du Col du nord et la Tour de Pestebois dans les Maleterres de l’est. Revenez ensuite voir l’émissaire Gormok à la Chapelle de l’Espoir de Lumière."}}
D[65593] = {"Les cœurs des amoureux",{"Apportez les Cœurs d’Avelina Lilly et d’Isaac Pearson à Carendin Halgar dans le Temple des Damnés."}}
D[65597] = {"Le lien",{"Utilisez les Cœurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Cœurs des amoureux à Carendin Halgar, dans le Quartier de la magie d’Undercity."}}
D[65601] = {"Les affres de l’amour",{"Parlez à Magar, à Orgrimmar."}}
D[65602] = {"Qu’est-ce que l’amour ?",{"Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Stormwind."}}
D[65603] = {"Le lien",{"Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l’objet à Gakin le Tisse-noir à l’Agneau assassiné."}}
D[65604] = {"Le lien",{"Utilisez l’Écharpe flétrie pour invoquer et asservir un Incube, puis rapportez-la à Gan’rul Bloodeye, à Orgrimmar."}}
D[65610] = {"Comme tu me manques",{"Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan’rul Bloodeye, à Orgrimmar."}}
end)();
