D[93] = {"Темные пирожки с крабами",{"Добудьте 6 липких паучьих лапок и принесите их шеф-повару Груалю в Темнолесье."}}
D[94] = {"Недремлющее Око",{"Отнесите амулет Азоры к статуе льва, стоящей рядом с башней Илгалара в Красногорье."}}
