D[2361] = {"Восстановление ожерелья"}
D[2378] = {"Поиски Изувеченной Длани",{"Отправляйтесь в Оргриммар и поговорите с Шентулом в Расселине Теней."}}
D[2379] = {"Зандо'зан",{"Поговорите с Зандо'заном в расселине Теней."}}
D[2380] = {"В Оргриммар!",{"Поговорите с Шентулом в расселине Теней в Оргриммаре."}}
D[2381] = {"Грабь награбленное",{"Принесите Рениксу Презренному из Кабестана сокровище Южного моря. Не забудьте взять из гизмотронного аппарата Реникса ХОЧУ и отмычки. Они понадобятся для выполнения задания.","","Если на вас нападут необычайно враждебные попугаи, воспользуйтесь ХОЧУ!"}}
D[2382] = {"Реникс из Кабестана",{"Поговорите с Рениксом Презренным в Кабестане."}}
D[2383] = {"Записка на пергаменте",{"Прочтите пергамент и поговорите с Франгом в долине Испытаний."}}
D[2398] = {"Потерянные дворфы",{"Найдите Бейлога в Ульдамане."}}
D[2399] = {"Росток папоротника"}
D[2418] = {"Камни Силы",{"Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли."}}
D[2438] = {"Изумрудный ловец снов",{"Принесите изумрудного ловца снов Таллонкаю Гибкому Корню в Доланаар."}}
D[2439] = {"Платиновые диски",{"Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна."}}
D[2440] = {"Платиновые диски",{"Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес."}}
D[2458] = {"Надежное прикрытие",{"Отыщите башню Торговой компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.","","Возле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и продемонстрируйте приветствие Изувеченной Длани (команда /честь).","","Все нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным."}}
D[2459] = {"Фероситас Пожиратель Снов",{"Таллонкай Гибкий Корень из Доланаара хочет, чтобы вы убили 7 мистиков из племени Кривой Сосны и нашли пропавший самоцвет."}}
D[2460] = {"Приветствие Изувеченной Длани",{"Повторите приветствие Раздробленной Руки вслед за Шентулом."}}
D[2478] = {"Миссия: выполнима, но с трудом",{"Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой компании, двух патрульных Торговой компании и двух смотрителей Торговой компании.","","Ликвидируйте старшего мастера Галливикса, взломайте замок на его ящике и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания."}}
D[2479] = {"Помощь Хинотта",{"Пойдите на Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.","","Сядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками."}}
D[2480] = {"Помощь Хинотта",{"Дождитесь, пока Серж Хинотт доделает лекарство."}}
D[2498] = {"Возвращение к Деналану",{"Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль'Амет."}}
D[2499] = {"Дубохмур",{"Деналан с озера Аль'Амет хочет, чтобы вы сняли гигантскую опухоль с Дубохмура."}}
D[2500] = {"За реактивами в Бесплодные земли",{"Добудьте в Бесплодных землях реактивы для Гхака Целителя и отнесите их ему в Телcамар."}}
D[2501] = {"За реактивами в Бесплодные земли II",{"Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар."}}
D[2518] = {"Слезы Луны",{"Жрица А'моора из дарнасского храма Луны хочет, чтобы вы принесли ей серебряные паутинные железы леди Сатры."}}
D[2519] = {"Храм Луны",{"Сестра Аквинна хочет, чтобы вы поговорили со жрицей А'моорой из Храма Луны."}}
D[2520] = {"Жертвоприношение Сатры",{"Жрица А'моора просит вас положить серебряные паутинные железы леди Сатры у фонтана в храме и затем вернуться к ней."}}
D[2521] = {"Служба для Кум'иша",{"Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренейского аметиста, отнесите ее Кум'ише Коллекционеру.","","Будьте внимательны – этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренейского аметиста.","","Вы будете вознаграждены за каждую безупречную сферу из дренейского аметиста, которую доставите Кум-ише."}}
D[2522] = {"Попытки Кум'иша",{"Найдите безупречную сферу из дренейского аметиста и верните ее Кум'ише Коллекционеру."}}
