D[3373] = {"Сущность Эраникуса",{"Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме."}}
D[3374] = {"Сущность Эраникуса",{"Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет."}}
D[3375] = {"Запасной фиал",{"Принесите зелье маны, уголь и сладкий нектар Талвашу де Кисселю в Стальгорн. Получите запасной фиал виденья Талваша."}}
D[3376] = {"Сразить Остроклыка!",{"Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака."}}
D[3377] = {"Молитва Элуне",{"Выслушайте Зимаэля."}}
D[3378] = {"Молитва Элуне",{"Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнасс."}}
D[3379] = {"Мастер Тени",{"Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания."}}
