D[3504] = {"Предательница",{"Отнесите запечатанное письмо Аг'тору Кровопалу в Азшару."}}
D[3505] = {"Предательница",{"Убейте 10 эльфов крови-землемеров и 10 эльфов крови-геодезистов, потом разыщите лагерь волхва Римтори. В лагере найдите что-нибудь важное для мага, из-за чего она могла бы ринуться в бой."}}
D[3506] = {"Предательница",{"Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг'тору Кроволапу в Азшаре."}}
D[3507] = {"Предательница",{"Поговорите с Белгромом Каменной Буловой в Оргриммаре."}}
D[3508] = {"Минуя охрану",{"Подождите, пока Лорамус завершит заклинание просветления."}}
D[3509] = {"Имя Зверя",{"Поговорите в Азшаре с лордом Арккоросом. Начните поиски у кромки воды, чтобы найти Храм Арккоран."}}
D[3510] = {"Имя Зверя",{"Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Аккоросу."}}
D[3511] = {"Имя Зверя",{"Отнесите состав для закалки Лорамусу Многоногу."}}
D[3512] = {"Судя по словам Эраникуса...",{"Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов."}}
D[3513] = {"Свиток с рунами",{"Отнесите свиток с рунами в северную сторожевую башню Степей."}}
D[3514] = {"Мощь Орды",{"Убейте предводительницу Пещеры Когтей, Ринтариэль Хранительницу Ключей."}}
D[3517] = {"Тайненькое знаньице",{"Найдите таблички Бет'Амары, Джин'яэль, Маркри и Саэль'Хай и принесите их Джедиге в Азшару."}}
D[3518] = {"Доставка Магате",{"Отнесите табличку Бет'Амары Магате в Громовой Утес."}}
D[3519] = {"Друг в беде",{"Поговорите с Диранией Серебряным Сиянием в Тенистой долине."}}
D[3520] = {"Духи крикунов",{"Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля."}}
D[3521] = {"Противоядие для Иверрона",{"Соберите 7 гиацинтовых грибов, 4 лунные лилии и 1 порцию лимфы чащобного тенетника и принесите Дирании Серебряное Сияние в Тенистую долину."}}
D[3522] = {"Противоядие для Иверрона",{"Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда."}}
D[3523] = {"Плеть в холмах",{"Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам."}}
D[3524] = {"Останки на берегу",{"Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай'Леггонд в Аубердин."}}
D[3525] = {"Уничтожить идола",{"Сопроводите Белнистраза к идолу свинобразов на Курганах Иглошкурых.","","Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола."}}
D[3526] = {"Гоблинское инженерное дело",{"Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск."}}
