D[3528] = {"Бог Хаккар",{"Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис."}}
D[3541] = {"Доставка Джес'римону",{"Отнесите табличку Джин'яэль Джес'римону в Оргриммар."}}
