D[3821] = {"Скала Молота Ужаса",{"Отправляйтесь в Пылающие степи и выясните, что сталось с Ша'ни Гордым Клыком."}}
D[3822] = {"Кром'Грул",{"Заберите ноздревое кольцо Ша'ни у Кром'Грула и верните его Тал'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса."}}
D[3823] = {"Угасание Огненного Чрева",{"Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева. По выполнении задания вернитесь к Орелиусу."}}
D[3824] = {"Гор'теш Жестокий",{"Найдите Гор'теша на западе от скалы Молота Ужаса. Убейте Гор'теша и отнесите его голову Орелиусу в Пылающие степи."}}
D[3825] = {"Голова огра на палочке = вечеринка",{"Отнесите голову Гор'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику."}}
D[3841] = {"Бездомный сиротка",{"Поговорите с Квентином в Тысяче Игл."}}
D[3842] = {"Инкубатор",{"Принесите 2 эликсира стойкости Квентину в Тысячу Игл."}}
D[3843] = {"Новый член семьи",{"Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет."}}
D[3844] = {"Тайна, покрытая мраком",{"Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот."}}
D[3845] = {"Тайна, покрытая мраком",{"Изучите найденное в сумке и верните владельцу."}}
D[3861] = {"Куд-кудаааа!",{"Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете ее, /поклонитесь ей прежде, чем накормить ее специальным цыплячьим кормом."}}
D[3881] = {"Спасение экспедиции",{"Принесите ящик с провизией и исследовательское оборудование Виллидену Маршалу в Кратер Ун'Горо."}}
D[3882] = {"Игра в кости",{"Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун'Горо."}}
D[3883] = {"Экология чужих",{"Воспользуйтесь фиалом для образцов, чтобы взять образец материала стены улья из одного из инкубаторов Гориши в Кратере Ун'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок.","","Принесите образец материала стены улья Холании Маршал в Кратер Ун'Горо."}}
D[3884] = {"Дневник Вилидена",{"Верните дневник Виллидену Маршалу, который находится где-то в Кратере Ун'Горо."}}
D[3901] = {"Игрушки-погремушки",{"Убейте 12 скелетов-костетрясов, а затем вернитесь к жрецу Тьмы Сарвису в Могильник."}}
D[3902] = {"Поиски старой одежды",{"Обыщите Могильник и его окрестности и найдите 6 ящиков с добычей и передайте их стражу смерти Салтену."}}
D[3903] = {"Милли Осворт",{"Поговорите с Милли Осворт."}}
D[3904] = {"Урожай Милли",{"Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья."}}
D[3905] = {"Уведомление о поставке винограда",{"Отнесите уведомление о поставке винограда брату Нилзу в Аббатство Североземья."}}
D[3906] = {"Дисгармония пламени",{"Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду."}}
D[3907] = {"Дисгармония пламени",{"Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию."}}
D[3908] = {"Тайна, покрытая мраком",{"Отнесите меч Линкена Донове Снегоноре."}}
D[3909] = {"Эликсир Видере",{"Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре."}}
D[3912] = {"Встречаемся на кладбище",{"Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана."}}
D[3913] = {"Замогильная история",{"Воскресните, найдите могильный камень, о котором говорил Гаэриан."}}
D[3914] = {"Меч Линкена",{"Доставьте превосходный меч Линкена Линкену в Кратер Ун'Горо."}}
D[3921] = {"Венаки Бенике",{"Отнесите сломанный самофланж Венаки Бенике."}}
D[3922] = {"Металлические заготовки",{"Принесите 15 металлических заготовок для деталей Венаки Бенике в Степи."}}
D[3923] = {"Рилли Грязегоб",{"Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар."}}
D[3924] = {"Руководство по самофланжу",{"Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар."}}
D[3941] = {"Помощь гномов",{"Найдите Джей Ди Колли в Укрытии Маршалла."}}
