D[4681] = {"Останки на берегу",{"Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай'Леггонд в Аубердине."}}
D[4701] = {"Устранение опасности",{"Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами."}}
D[4721] = {"Одичавшие стражи",{"Убейте для Трулла Баловня Судьбы из Оскверненного леса 10 яростных совухов в Зимних Ключах."}}
D[4722] = {"Останки морской черепахи",{"Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин."}}
D[4723] = {"Останки морской твари",{"Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин."}}
D[4724] = {"Праматерь стаи",{"Убейте Халикон, праматерь стаи воргов Кровавого Топора."}}
D[4725] = {"Останки морской черепахи",{"Отнесите ящик со странными пометками Гвеннид Блай'Леггонд в Аубердин."}}
D[4726] = {"Сущность детеныша дракона",{"Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях."}}
D[4727] = {"Останки морской черепахи",{"Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин."}}
D[4728] = {"Останки морской твари",{"Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин."}}
D[4729] = {"Редкие звери Киблера",{"Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру."}}
D[4730] = {"Останки морской твари",{"Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин."}}
