D[5513] = {"Оплечья Рассвета",{"Принесите 10 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли."}}
D[5514] = {"Форма денег стоит",{"Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет."}}
D[5515] = {"Мешок ужасов Крастинова",{"Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф."}}
D[5517] = {"Многоцветное оплечье Рассвета",{"Принесите 25 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли."}}
D[5518] = {"Броня огров Гордока",{"Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе."}}
D[5519] = {"Броня огров Гордока"}
D[5521] = {"Многоцветное оплечье Рассвета",{"Принесите 25 знаков доблести Серебряного Рассвета интенданту Искре Света в Лагерь Промозглого Ветра."}}
D[5522] = {"Леонид Барталомей",{"Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли."}}
D[5524] = {"Многоцветное оплечье Рассвета",{"Принесите 25 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях."}}
D[5525] = {"Освободите Нотта!"}
D[5526] = {"Осколки сквернита",{"Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне."}}
D[5527] = {"Реликварий Чистоты",{"Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне."}}
D[5528] = {"Лучшее пойло Гордока"}
D[5529] = {"Зачумленные детеныши дракона",{"Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды."}}
D[5531] = {"Бетина Биггльцинк",{"Принесите охлажденные яйца Бетине Биггльцинк."}}
D[5533] = {"Некроситет",{"Поговорите с алхимиком Арбингтоном с вершины Холодной Скалы, что в Западных Чумных землях."}}
D[5534] = {"\"Пропавшее\"оборудование Ким'джаеля",{"Найдите некую руну, которую хранят наги в руинах Эльдарата и принесите ее Ким'джаелю в Азшару."}}
D[5535] = {"Духовное беспокойство",{"Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло'хату в Азшару."}}
D[5536] = {"Земли, полные ненависти",{"Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло'хату к границе Ясеневого леса."}}
D[5537] = {"Фрагменты скелетов",{"Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях."}}
D[5538] = {"Форма денег стоит",{"Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет."}}
D[5541] = {"Боеприпасы для Громострела",{"Доставьте боеприпасы Хегнару Громострелу в Дун Мороге."}}
D[5542] = {"Псы-демоны",{"Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу."}}
D[5543] = {"Окровавленные небеса",{"Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу."}}
D[5544] = {"Мясо личинок-трупоедов",{"Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов."}}
D[5545] = {"Тридцать три несчастья",{"Принесите 8 вязанок дров Раэлен на Лесопилку Восточной долины."}}
D[5561] = {"Отлов кодо",{"Приведите пять прирученных кодо Смиду Заржавеню в Лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор."}}
D[5581] = {"Порталы Легиона",{"Уничтожьте 6 порталов на Поле Маннорок, а затем вернитесь к Тайге Мудрой Гриве в Деревню Ночных Охотников."}}
D[5582] = {"Здоровая чешуя дракона",{"Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли."}}
