D[8730] = {"Порча Нефария",{"Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов."}}
D[8731] = {"Рутинное задание",{"Поступите в распоряжение легиона Оргриммара возле улья Регал. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях, отнесите их Зовущему Калдону в крепость Кенария.","","Внимание: исцеление или наложение благоприятных заклинаний на бойцов легиона Оргриммара переводит в режим PvP."}}
D[8732] = {"Бумаги о полевых обязанностях"}
D[8733] = {"Эраникус, Тиран Сна",{"Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнасса."}}
D[8734] = {"Тиранда и Ремулос",{"Отправляйтесь в Лунную поляну и поговорите с хранителем Ремулосом."}}
D[8735] = {"Порча Кошмара",{"Отправьтесь к четырем порталам сна Азерота и добудьте фрагменты порчи Кошмара из каждого из них. Вернитесь к хранителю Ремулосу на Лунную поляну по завершении задания."}}
D[8736] = {"Явление Кошмара",{"Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулосу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды."}}
D[8737] = {"Лазурный храмовник",{"Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу I."}}
D[8738] = {"Донесение разведчика из Улья Регал",{"Свяжитесь с разведчиком Кенария Ландионом в улье Регал и отнесите донесение разведчика из улья Регал Зовущей из клана Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VII."}}
D[8739] = {"Донесение разведчика из Улья Аши",{"Свяжитесь с разведчиком Кенария Джалией в улье Аши и отнесите донесение разведчика Зовущей из клана Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VIII."}}
D[8740] = {"Сумеречные мародеры",{"Убейте сумеречного мародера Морну и 5 сумеречных мародеров. Доложите о выполнении задания Зовущей из клана Гордый Рог. Кроме того, сдайте тактическую задачу IX."}}
