D[8770] = {"Цель: защитники из Улья Аши",{"Убейте 30 защитников из улья Аши и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I."}}
D[8771] = {"Цель: пескоходы из Улья Аши",{"Убейте 30 пескоходов из улья Аши и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II."}}
D[8772] = {"Цель: стражи дорог из Улья Зора",{"Убейте 30 стражей дорог из улья Зора и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VI."}}
D[8773] = {"Цель: разрушители из Улья Зора",{"Убейте 30 разрушителей из улья Зора и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи IV."}}
D[8774] = {"Цель: стерегущие из Улья Регал",{"Убейте 30 стерегущих из улья Регал и доложите об этом командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи VIII."}}
D[8775] = {"Цель: злюки из Улья Регал",{"Убейте 30 злюк из улья Регал и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу IX."}}
D[8776] = {"Цель: поработители из Улья Регал",{"Убейте 30 поработителей из улья Регал и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу X."}}
D[8777] = {"Цель: землерои из Улья Регал",{"Убейте 30 землероев из улья Регал и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XI."}}
D[8778] = {"Взрывчатка для дружины Стальгорна",{"Принесите 6 бутылок воспламеняющей смеси, 5 бочонков гоблинского ракетного топлива и 10 порций концентрированного взрывчатого вещества чародею Пружине Форсунки возле Улья Зора в Силитусе. Кроме того, принесите тыловое задание IV."}}
D[8779] = {"Материалы для гадания",{"Принесите 1 большой сияющий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в крепости Кенария в Силитусе. Также принесите тыловое задание V."}}
D[8780] = {"Комплекты брони",{"Принесите 8 комплектов грубой брони и 8 накладок из толстой кожи Джанеле Твердомолот на заставу дружины Стальгорна возле улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VII."}}
D[8781] = {"Нехватка оружия",{"Принесите 2 палаша лунной стали Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VI."}}
D[8782] = {"Поставки формы",{"Принесите 1 кусок луноткани, 2 рулона рунной ткани и 1 железношелковую паутину Зовущей из клана Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII."}}
D[8783] = {"Необычные материалы",{"Принесите Варгусу из крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX."}}
D[8784] = {"Секреты Кираи",{"Принесите древний киражский артефакт драконам, которые укрылись в храме, недалеко от входа."}}
D[8785] = {"Амулеты для легиона Оргриммара",{"Принесите 6 мощных амулетов, 6 бутылей большого колдунства и 8 бутылок воспламеняющей смеси жрице Тьмы Шаи к улью Регал в Силитус. Кроме того, принесите тыловое задание IV."}}
D[8786] = {"Нехватка оружия",{"Принесите 3 массивных железных топора Мероку Долгому Шагу в лагерь легиона Оргриммара рядом с Ульем Регал. Кроме того, сдайте тыловую задачу VI."}}
D[8787] = {"Комплекты брони",{"Принесите 8 комплектов грубой брони и 8 накладок из толстой кожи Мероку Долгому Шагу к улью Регал. Кроме того, сдайте тыловую задачу VII."}}
D[8788] = {"Слегка растрясенный дар"}
D[8789] = {"Киражское императорское оружие",{"Аригос в Храме Ан'Киража создаст для вас усиленное элементием оружие, если вы принесете ему киражское имперское оружие и 3 куска элементиевой руды."}}
D[8790] = {"Киражские императорские регалии",{"Меритра из Сна в Храме Ан'Киража может создать для вас усиленное элементием оружие, если вы принесете ей киражские имперские регалии и 3 куска элементиевой руды."}}
D[8791] = {"Повергнутый Оссириан",{"Принесите голову Оссириана Неуязвимого командиру Мар'алиту в крепость Кенария."}}
