D[8804] = {"Неприкосновенный запас",{"Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрат в таверну в крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I."}}
D[8805] = {"Сапоги для стражей",{"Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II."}}
D[8806] = {"Шлифовальные камни",{"Принесите 10 массивных шлифовальных камней, 10 твердых шлифовальных камней и 10 тяжелых точильных камней Вишу Коцусу, капитану стражи в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III."}}
D[8807] = {"Материалы для гадания",{"Принесите 1 большой сияющий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в крепости Кенария в Силитусе. Также принесите тыловое задание V."}}
D[8808] = {"Поставки формы",{"Принесите 1 кусок луноткани, 2 рулона рунной ткани и 1 железношелковую паутину Зовущей из клана Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII."}}
D[8809] = {"Необычные материалы",{"Принесите Варгусу из крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX."}}
D[8810] = {"Запас бинтов",{"Принесите 30 плотных бинтов из рунной ткани, 30 плотных шелковых бинтов и 30 бинтов из магической ткани Зовущей из клана Гордый Рог в крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу X."}}
