D[9242] = {"Снежные перчатки",{"Принесите 5 морозных рун, 12 кусков зачарованной кожи, 3 субстанции Воды, 3 обработанных грубых шкуры и 200 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9243] = {"Снежный мундир",{"Принесите 8 морозных рун, 16 кусков зачарованной кожи, 5 субстанций Воды, 5 обработанных грубых шкур и 300 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли. Кроме того, вас должны превозносить в ордене Серебряного Рассвета."}}
D[9244] = {"Наручи из ледяной чешуи",{"Принесите 4 морозные руны, 16 толстых чешуй скорпида, 5 субстанций Воды, 3 обработанные грубые шкуры и 200 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9245] = {"Рукавицы из ледяной чешуи",{"Принесите 5 морозных рун, 16 толстых чешуй скорпида, 5 субстанций Воды, 3 обработанные грубые шкуры и 200 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9246] = {"Кираса из ледяной чешуи",{"Принесите 8 морозных рун, 24 толстые чешуи скорпида, 7 субстанций Воды, 5 обработанных грубых шкур и 300 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли. Кроме того, вас должны превозносить в ордене Серебряного Рассвета."}}
D[9247] = {"Зов Хранителя",{"Отнесите письмо хранителя свитков самому хранителю в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9248] = {"Скромный подарок",{"Принесите 1 скипетр Бездны Аурели Золотой Лист из Крепости Кенария в Силитусе. Кроме того, вы должны добиться уважительного отношения Круга Кенария."}}
D[9250] = {"Основа Атиеша",{"Найдите того, кто поможет отыскать недостающие части посоха и изгнать из него злого духа."}}
D[9251] = {"Атиеш, оскверненный великий посох",{"Анахронос из пещер Времени, что в Танарисе, просит вас принести ему навершие и основание Атиеша."}}
D[9257] = {"Атиеш, большой посох Стража",{"Анахронос из Пещер Времени, что в Танарисе, просит вас отнести Атиеш, большой посох Стража, в Стратхольм и установить его на освященную землю. Одолейте силу, которая исторгнется из посоха, и вернитесь к Анахроносу."}}
D[9259] = {"Предатель Кровавого Паруса"}
D[9260] = {"Что делает Плеть в Штормграде?",{"Соберите три тусклых некротических камня, которые носит при себе нежить, окружившая Оргриммар, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[9261] = {"Что делает Плеть в Стальгорне?",{"Соберите три тусклых некротических камня, которые носит при себе нежить, окружившая Стальгорн, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[9262] = {"Что делает Плеть в Дарнассе?",{"Соберите три тусклых некротических камня, которые носит при себе нежить, окружившая Дарнасс, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[9263] = {"Что делает Плеть в Оргриммаре?",{"Соберите три тусклых некротических камня, которые носит при себе нежить, окружившая Оргриммар, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[9264] = {"Что делает Плеть в Громовом Утесе?",{"Соберите три тусклых некротических камня, которые носит при себе нежить, окружившая Громовой утес, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[9265] = {"Что делает Плеть в Подгороде?",{"Соберите три тусклых некротических камня, которые носит при себе нежить, окружившая Подгород, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[9266] = {"Восстановление добрых отношений"}
D[9267] = {"Исцеление старых ран"}
D[9268] = {"Морской бой"}
D[9272] = {"Костюм пирата"}
D[9292] = {"Треснутый некротический кристалл",{"Отнесите треснутый некротический кристалл лейтенанту Оррину, находящемуся за воротами Штормграда."}}
D[9295] = {"Письмо с фронта",{"Отнесите порванное письмо хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9299] = {"Записка с фронта",{"Отнесите потертую записку хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9300] = {"Страничка с фронта",{"Отнесите разорванную страницу хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9301] = {"Конверт с фронта",{"Отнесите конверт, запятнанный кровью, хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9302] = {"Послание с фронта",{"Отнесите смятое послание хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9304] = {"Документ с фронта",{"Отнесите испачканный документ хранителю свитков в Часовню Последней Надежды в Восточные Чумные земли."}}
D[9310] = {"Тусклый некротический кристалл",{"Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода."}}
D[9317] = {"Освященное точило"}
D[9318] = {"Благословенное волшебное масло"}
D[9319] = {"Свет в темных местах",{"Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени."}}
D[9320] = {"Сильнейшее зелье маны"}
D[9321] = {"Хорошее лечебное зелье"}
D[9322] = {"Костры Калимдора",{"Посетите лагеря праздника Огненного солнцеворота, размещенные в Азшаре, Силитусе, Кратере Ун'Горо и Зимних Ключах, затем вернитесь к хранителю праздничного пламени."}}
D[9323] = {"Костры Восточных Королевств",{"Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени."}}
D[9324] = {"Похищение пламени Оргриммара",{"Верните Пламя Оргриммара хранителю мудрости Праздника."}}
D[9325] = {"Похищение пламени Громового Утеса",{"Верните Пламя Громового Утеса хранителю мудрости Праздника."}}
D[9326] = {"Похищение пламени Подгорода",{"Верните Пламя Подгорода хранителю мудрости Праздника."}}
D[9330] = {"Похищение пламени Штормграда",{"Верните Пламя Штормграда Праздничному Сказителю."}}
D[9331] = {"Похищение пламени Стальгорна",{"Верните Пламя Стальгорна Праздничному Сказителю."}}
D[9332] = {"Похищение пламени Дарнасса",{"Верните пламя Дарнасса праздничному сказителю."}}
