D[9362] = {"Полководец Креллиан",{"Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары."}}
D[9364] = {"Частицы магии",{"Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару."}}
D[9365] = {"Награда вора"}
D[9367] = {"Праздник Огня",{"Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнассе, затем поговорите с хранителем мудрости праздника в столичных городах."}}
D[9368] = {"Праздник Огня",{"Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах."}}
D[9386] = {"Свет в темных местах",{"Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени."}}
D[9388] = {"Мерцающие огни Калимдора",{"Посетите праздничные костры в Ясеневом лесу, Степях, на Темном Берегу и в Когтистых горах, затем поговорите с хранителем праздничного пламени."}}
D[9389] = {"Мерцающие огни Восточных Королевств",{"Посетите праздничные костры в предгорьях Хиллсбрада, в Серебряном бору, Западном Крае и Болотине, затем поговорите с хранителем праздничного пламени."}}
D[9415] = {"Маршал Синяя Синестен",{"Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора."}}
D[9416] = {"Генерал Кирика",{"Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал."}}
D[9419] = {"Истощение пустыни",{"Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора."}}
D[9422] = {"Истощение пустыни",{"Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал."}}
D[9664] = {"Новые форпосты",{"Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды."}}
D[9665] = {"Укрепим оборону",{"Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и башню Проклятого леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды."}}
D[65593] = {"Сердца влюбленных",{"Принесите сердца Авелины Лилли и Исаака Пирсона Карнедину Халгару в Храм Проклятых."}}
D[65597] = {"Связывание",{"С помощью сердец влюбленных призовите и подчините инкуба, затем верните сердца Карендину Халгару в Квартал Магов Подгорода."}}
D[65601] = {"Несчастная любовь",{"Поговорите с Магаром в Оргриммаре."}}
D[65602] = {"Лучшие друзья",{"Добудьте деревянную статуэтку и принесите ее Гакину Темнопряду в квартал магов Штормграда."}}
D[65603] = {"Связывание",{"Воспользуйтесь деревянной статуэткой, чтобы призвать и подчинить инкуба, затем верните статуэтку Гакину Темнопряду. Он будет ждать в \"Забитом ягненке\"."}}
D[65604] = {"Связывание",{"С помощью истлевшего платка призовите и подчините своей воле инкуба, затем верните его Ган'рулу Кровавому Глазу в Оргриммаре."}}
D[65610] = {"Если бы мы были вместе...",{"Осмотрите озеро Зеркало Небес в Ясеневом лесу и расскажите о находках Ган'рулу Кровавый Глаз в Оргриммаре."}}
end)();
